(window.__LIB=window.__LIB||{}).numani={"k":"numani","chs":[["المقدمة",1],["باب ما ورد في كتمان أمر آل محمد (ص)",12],["باب التمسك بحبل الله",2],["باب الإمامة والوصية",7],["باب أن الأئمة اثنا عشر بتعيين الله",40],["باب المدّعين للإمامة",13],["باب ما رواه أهل السنة في الأئمة الاثني عشر",25],["باب الشك في أحد الأئمة الاثني عشر",19],["باب أن الله لا يخلي العالم من حجة",10],["باب أنه لا بد من ظهور الحجة",5],["باب غيبة الإمام المنتظر",89],["باب الصبر في انتظار الفرج",17],["باب اختلاف الشيعة في زمن الغيبة",19],["باب صفات القائم (ع) وأفعاله",45],["باب العلامات التي تسبق الظهور",68],["باب الشدائد قبل ظهور القائم (ع)",7],["باب النهي عن التوقيت والتسمية",15],["باب ما يلقاه القائم (ع) من الناس",6],["باب خروج السفياني",18],["باب راية النبي (ص)",5],["باب جيش الغضب",12],["باب حال الشيعة عند ظهور القائم (ع)",10],["باب: بدأ الإسلام غريباً وسيعود غريباً",5],["باب عمر القائم (ع)",4],["باب إسماعيل ابن الإمام الصادق (ع)",9],["باب معرفة الإمام",5]],"items":[[1,0,"الحمد لله رب العالمين، الهادي من يشاء إلى صراط مستقيم، المستحق الشكر من عباده بإخراجه إياهم من العدم إلى الوجود، وتصويره إياهم في أحسن الصور، وإسباغه عليهم النعم ظاهرة وباطنة لا يحصيها العدد على طول الأمد، كما قال عز وجل: (وإن تعدوا نعمت الله لا تحصوها) ((2))، وبما دلهم عليه وأرشدهم إليه من العلم بربوبيته، والإقرار بوحدانيته، بالعقول الزكية، والحكمة البالغة، والصنعة المتقنة، والفطرة الصحيحة، والصبغة الحسنة، والآيات الباهرة، والبراهين الظاهرة، وشفعه ذلك ببعثه إليهم الخيرة من خلقه رسلا مصطفين، مبشرين ومنذرين، دالين هادين، مذكرين ومحذرين، ومبلغين مؤدين، بالعلم ناطقين، وبروح القدس مؤيدين، وبالحجج غالبين، وبالآيات لأهل الباطل قاهرين، وبالمعجزات لعقول ذوي الألباب باهرين، أبانهم من خلقه بما أولاهم من كرامته، وأطلعهم على غيبه، ومكنهم فيه من قدرته، كما قال عز وجل: (عالم الغيب فلا يظهر على غيبه أحدا * إلا من ارتضى من رسول فإنه يسلك من بين يديه ومن خلفه رصدا) ((1)) ترفعا لأقدارهم، وتعظيما لشأنهم، لئلا يكون للناس على الله حجة بعد الرسل، ولتكون حجة الله عليهم تامة غير ناقصة. والحمد لله الذي من علينا بمحمد سابق بريته إلى الإقرار بربوبيته، وخاتم أصفيائه، إنذارا برسالته، وأحب أحبائه إليه، وأكرم أنبيائه عليه، وأعلاهم رتبة لديه، وأخصهم منزلة منه، أعطاه جميع ما أعطاهم، وزاده أضعافا على ما أتاهم، وأحله المنزلة التي أظهر بها فضله عليهم، فصيره إماما لهم، إذ صلى في سمائه بجماعتهم، وشرف مقامه على كافتهم، وأعطاه الشفاعة دونهم، ورفعه مستسيرا إلى علو ملكوته ((2)) حتى كلمه في محل جبروته بحيث جاز مراتب الملائكة المقربين، ومقامات الكروبيين والحافين. وأنزل عليه كتابا جعله مهيمنا على كتبه المتقدمة، ومشتملا على ما حوته من العلوم الجمة وفاضلا عليها بأن جعله كما قال تعالى: (تبيانا لكل شئ) ((3)) لم يفرط فيه من شئ، فهدانا الله عز وجل بمحمد (صلى الله عليه وآله) من الضلالة والعمى، وأنقذنا به من الجهالة والردى، وأغنانا به وبما جاء به من الكتاب المبين، وما أكمله لنا من الدين، ودلنا عليه من ولاية الأئمة الطاهرين الهادين - عن الآراء والاجتهاد، ووفقنا ((1)) به وبهم إلى سبيل الرشاد. صلى الله عليه وعلى أخيه أمير المؤمنين تاليه في الفضل، ومؤازره في اللأواء والأزل ((2))، وسيف الله على أهل الكفر والجهل، ويده المبسوطة بالإحسان والعدل، والسالك نهجه في كل حال، والزائل مع الحق حيث ما زال، والخازن علمه، والمستودع سره، الظاهر على مكنون أمره، وعلى الأئمة من آله الطاهرين، الأخيار الطيبين الأبرار. معادن الرحمة، ومحل النعمة، وبدور الظلام، ونور الأنام، وبحور العلم، وباب السلام الذي ندب الله عز وجل خلقه إلى دخوله، وحذرهم النكوب عن سبيله حيث قال: (يا أيها الذين آمنوا ادخلوا في السلم كافة ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين) ((3)) أفضل صلواته وأشرفها، وأزكاها وأنماها، وأتمها وأعلاها وأسناها، وسلم تسليما كثيرا كما هو أهله وكما محمد وآله (عليهم السلام) أهله منه. أما بعد: فإنا رأينا طوائف من العصابة المنسوبة إلى التشيع، المنتمية إلى نبيها محمد وآله صلى الله عليهم - ممن يقول بالإمامة التي جعلها الله برحمته دين الحق، ولسان الصدق، وزينا لمن دخل فيها، ونجاة وجمالا لمن كان من أهلها، وفاز بذمتها، وتمسك بعقدتها، ووفى لها بشروطها، من المواظبة على الصلوات، وإيتاء الزكوات، والمسابقة إلى الخيرات، واجتناب الفواحش والمنكرات، والتنزه عن سائر المحظورات، ومراقبة الله تقدس ذكره في الملأ والخلوات، وتشغل القلوب وإتعاب الأنفس والأبدان في حيازة القربات -، قد تفرقت كلمها، وتشعبت مذاهبها، واستهانت بفرائض الله عز وجل، وخفت ((1)) إلى محارم الله تعالى، فطال بعضها علوا، وانخفض بعضها تقصيرا، وشكوا جميعا إلا القليل في إمام زمانهم، وولي أمرهم، وحجة ربهم التي اختارها بعلمه، كما قال جل وعز: (وربك يخلق ما يشاء ويختار ما كان لهم الخيرة) ((2)) من أمرهم للمحنة الواقعة بهذه الغيبة التي سبق من رسول الله (صلى الله عليه وآله) ذكرها، وتقدم من أمير المؤمنين (عليه السلام) خبرها، ونطق في المأثور من خطبه والمروي عنه من كلامه وحديثه، بالتحذير من فتنتها، وحمل أهل العلم والرواية عن الأئمة من ولده (عليهم السلام) واحدا بعد واحد أخبارها حتى ما منهم أحد إلا وقدم القول فيها، وحقق كونها، ووصف امتحان الله تبارك وتعالى اسمه خلقه بها بما أوجبته قبائح الأفعال ومساوئ الأعمال، والشح المطاع، والعاجل الفاني المؤثر على الدائم الباقي، والشهوات المتبعة، والحقوق المضيعة التي اكتسبت سخط الله عز وتقدس، فلم يزل الشك والارتياب قادحين في قلوبهم - كما قال أمير المؤمنين (عليه السلام) في كلامه لكميل بن زياد في صفة طالبي العلم وحملته: \" أو منقادا لأهل الحق لا بصيرة له، ينقدح الشك في قلبه ((3)) لأول عارض من شبهة - حتى أداهم ذلك إلى التيه والحيرة والعمى والضلالة، ولم يبق منهم إلا القليل النزر الذين ثبتوا على دين الله، وتمسكوا بحبل الله، ولم يحيدوا عن صراط الله المستقيم \"، وتحقق فيهم وصف الفرقة الثابتة على الحق التي لا تزعزعها الرياح، ولا يضرها الفتن، ولا يغرها لمع السراب، ولم تدخل في دين الله بالرجال فتخرج منه بهم. كما روينا عن أبي عبد الله جعفر بن محمد (عليهما السلام) أنه قال: من دخل في هذا الدين بالرجال أخرجه منه الرجال كما أدخلوه فيه، ومن دخل فيه بالكتاب والسنة زالت الجبال قبل أن يزول ((1)). ولعمري ما أتي من تاه وتحير وافتتن وانتقل عن الحق وتعلق بمذاهب أهل الزخرف والباطل إلا من قلة الرواية والعلم وعدم الدراية والفهم، فإنهم الأشقياء، لم يهتموا بطلب العلم ولم يتعبوا أنفسهم في اقتنائه وروايته من معادنه الصافية على أنهم لو رووا ثم لم يدروا لكانوا بمنزلة من لم يرووا. وقد قال جعفر بن محمد الصادق (عليه السلام): اعرفوا منازل شيعتنا عندنا على قدر روايتهم عنا وفهمهم منا ((2)). فإن الرواية تحتاج إلى الدراية، وخبر تدريه خير من ألف خبر ترويه. وأكثر من دخل في هذه المذاهب إنما دخل على أحوال: فمنهم من دخله بغير روية ولا علم، فلما اعترضه يسير الشبهة تاه. ومنهم من أراده طلبا للدنيا وحطامها، فلما أماله الغواة والدنيويون إليها مال مؤثرا لها على الدين، مغترا مع ذلك بزخرف القول غرورا من الشياطين الذين وصفهم الله عز وجل في كتابه، فقال: (شياطين الإنس والجن يوحي بعضهم إلى بعض زخرف القول غرورا) ((3)). والمغتر به فهو كصاحب السراب الذي يحسبه الظمآن ماء يلمعه عند ظمئه لمعة ماء، فإذا جاءه لم يجده شيئا، كما قال عز وجل ((4)). ومنهم من تحلى بهذا الأمر للرياء والتحسن بظاهره، وطلبا للرئاسة، وشهوة لها وشغفا بها من غير اعتقاد للحق، ولا إخلاص فيه، فسلب الله جماله وغير حاله، وأعد له نكاله. ومنهم من دان به على ضعف من إيمانه، ووهن من نفسه بصحة ما نطق به منه، فلما وقعت هذه المحنة التي آذننا أولياء الله صلى الله عليهم بها مذ ثلاثمائة سنة تحير ووقف، كما قال الله عز وجل من قائل: (كمثل الذي استوقد نارا فلما أضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمات لا يبصرون) ((1))، وكما قال: (كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا) ((2))، ووجدنا الرواية قد أتت عن الصادقين (عليهم السلام) بما أمروا به من وهب الله عز وجل له حظا من العلم، وأوصله منه إلى ما لم يوصل إليه غيره من تبيين ما اشتبه على إخوانهم في الدين، وإرشادهم في الحيرة إلى سواء السبيل، وإخراجهم عن منزلة الشك إلى نور اليقين. فقصدت القربة إلى الله عز وجل بذكر ما جاء عن الأئمة الصادقين الطاهرين (عليهم السلام) من لدن أمير المؤمنين (عليه السلام) إلى آخر من روي عنه منهم في هذه الغيبة التي عمي عن حقيقتها ونورها من أبعده الله عن العلم بها، والهداية إلى ما أوتي عنهم (عليهم السلام) فيها ما يصحح لأهل الحق حقيقة ما رووه ودانوا به وتؤكد حجتهم بوقوعها، ويصدق ما آذنوا به منها. وإذا تأمل من وهب الله تعالى له حسن الصورة، وفتح مسامع قلبه، ومنحه جودة القريحة، وأتحفه بالفهم وصحة الرواية بما جاء عن الهداة الطاهرين صلوات الله عليهم على قديم الأيام وحديثها من الروايات المتصلة فيها، الموجبة لحدوثها، المقتضية لكونها مما قد أوردناه في هذا الكتاب حديثا حديثا، وروي فيه، وفكر فكرا ممعنا ((1))، ولم يجعل قراءته ونظره فيه صفحا دون شافي التأمل ولم يطمح ببصره عن حديث منها يشبه ما تقدمه دون إمعان النظر فيه والتبيين له، ولما يحوي من زيادة المعاني بلفظة من كلام الإمام (عليه السلام) بحسب ما حمله واحد من الرواة عنه علم أن هذه الغيبة لو لم تكن ولم تحدث مع ذلك ومع ما روي على مر الدهور فيها لكان مذهب الإمامة باطلا، لكن الله تبارك وتعالى صدق إنذار الأئمة (عليهم السلام) بها، وصحح قولهم فيها في عصر بعد عصر، وألزم الشيعة التسليم والتصديق والتمسك بما هم عليه، وقوي اليقين في قلوبهم بصحة ما نقلوه، وقد حذر أولياء الله صلوات الله عليهم شيعتهم من أن تميل بهم الأهواء، أو تزيغ بهم وبقلوبهم الفتن واللأواء في أيامها، ووصفوا ما يشمل الله خلقه به من الابتلاء عند وقوعها بتراخي مدتها، وطول الأمد فيها (ليهلك من هلك عن بينة ويحيى من حي عن بينة) ((2)). فإنه روي عنهم (عليهم السلام) ما حدثنا به محمد بن همام، قال: حدثنا حميد بن زياد الكوفي، قال: حدثنا الحسن بن محمد بن سماعة، قال: حدثنا أحمد بن الحسن الميثمي، عن رجل من أصحاب أبي عبد الله جعفر بن محمد (عليهما السلام) أنه قال: سمعته يقول: نزلت هذه الآية التي في سورة الحديد (ولا يكونوا كالذين أوتوا الكتاب من قبل فطال عليهم الأمد فقست قلوبهم وكثير منهم فاسقون) ((3)) في أهل زمان الغيبة، ثم قال عز وجل: (أن الله يحيي الأرض بعد موتها قد بينا لكم الآيات لعلكم تعقلون) ((4)) وقال: إنما الأمد أمد الغيبة، فإنه أراد عز وجل: يا أمة محمد، أو يا معشر الشيعة، لا تكونوا كالذين أوتوا الكتاب من قبل فطال عليهم الأمد، فتأويل هذه الآية جاء في أهل زمان الغيبة وأيامها دون غيرهم من أهل الأزمنة، وإن الله تعالى نهى الشيعة عن الشك في حجة الله تعالى، أو أن يظنوا أن الله تعالى يخلي أرضه منها طرفة عين، كما قال أمير المؤمنين (عليه السلام) في كلامه لكميل بن زياد: بلى اللهم لا تخلو الأرض من حجة لله إما ظاهر معلوم، أو ((1)) خائف مغمور، لئلا تبطل حجج الله وبيناته، وحذرهم من أن يشكوا أو يرتابوا فيطول عليهم الأمد فتقسوا قلوبهم. ثم قال (عليه السلام): ألا تسمع قوله تعالى في الآية التالية لهذه الآية: (اعلموا أن الله يحيي الأرض بعد موتها قد بينا لكم الآيات لعلكم تعقلون) أي يحييها الله بعدل القائم عند ظهوره بعد موتها بجور أئمة الضلال ((2)). وتأويل كل آية منها مصدق للآخر وعلى أن قولهم صلوات الله عليهم لا بد أن يصح في شذوذ من يشذ، وفتنة من يفتتن، ونكوص من ينكص على عقبيه من الشيعة بالبلبلة ((3)) والتمحيص والغربلة التي قد أوردنا ما ذكروه (عليهم السلام) منه بأسانيد في باب ما يلحق الشيعة من التمحيص والتفرق والفتنة، إلا أنا نذكر في هذا الموضع حديثا أو حديثين من جملة ما أوردنا في ذلك الباب لئلا ينكر منكر ما حدث من هذه الفرق العاملة بالأهواء، المؤثرة للدنيا. وهو ما أخبرنا به أحمد بن محمد بن سعيد بن عقدة الكوفي، - وهذا الرجل ممن لا يطعن عليه في الثقة ولا في العلم بالحديث والرجال الناقلين له -: قال: حدثنا علي بن الحسن التيملي من تيم الله، قال: حدثني أخواي أحمد ومحمد ابنا الحسن بن علي بن فضال، عن أبيهما، عن ثعلبة بن ميمون، عن أبي كهمس، عن عمران بن ميثم، عن مالك بن ضمرة، قال: قال أمير المؤمنين (عليه السلام) لشيعته: كونوا في الناس كالنحل في الطير، ليس شئ من الطير إلا وهو يستضعفها، ولو يعلم ما في أجوافها لم يفعل بها كما يفعل، خالطوا الناس بأبدانكم، وزايلوهم بقلوبكم وأعمالكم، فإن لكل امرئ ما اكتسب وهو يوم القيامة مع من أحب، أما إنكم لن تروا ما تحبون وما تأملون - يا معشر الشيعة - حتى يتفل بعضكم في وجوه بعض، وحتى يسمي بعضكم بعضا كذابين، وحتى لا يبقى منكم على هذا الأمر إلا كالكحل في العين، أو كالملح في الطعام، وهو أقل الزاد ((1)). وسأضرب لكم في ذلك مثلا: وهو كمثل رجل كان له طعام قد ذراه وغربله ونقاه وجعله في بيت وأغلق عليه الباب ما شاء الله، ثم فتح الباب عنه فإذا السوس قد وقع فيه، ثم أخرجه ونقاه وذراه، ثم جعله في البيت وأغلق عليه الباب ما شاء الله، ثم فتح الباب عنه فإذا السوس قد وقع فيه، وأخرجه ونقاه وذراه، ثم جعله في البيت وأغلق عليه الباب، ثم أخرجه بعد حين فوجده قد وقع فيه السوس، ففعل به كما فعل مرارا حتى بقيت منه رزمة كرزمة الأندر ((2)) الذي لا يضره السوس شيئا، وكذلك أنتم تمحصكم الفتن حتى لا يبقى إلا عصابة لا تضرها الفتن شيئا ((3)). وروي عن أبي عبد الله (عليه السلام) أنه قال: والله لتمحصن والله لتطيرن يمينا وشمالا حتى لا يبقى منكم إلا كل امرئ أخذ الله ميثاقه، وكتب الإيمان في قلبه وأيده بروح منه. وفي رواية أخرى، عنهم (عليهم السلام): حتى لا يبقى منكم على هذا الأمر إلا الأندر فالأندر ((1)). وهذه العصابة التي تبقى على هذا الأمر وتثبت وتقيم على الحق هي التي أمرت بالصبر في حال الغيبة. فمن ذلك، ما أخبرنا به علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي العباسي، عن هارون بن مسلم، عن القاسم بن عروة، عن بريد بن معاوية العجلي، عن أبي جعفر محمد بن علي الباقر (عليه السلام) في معنى قوله تعالى: (يا أيها الذين آمنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون) ((2)) قال: اصبروا على أداء الفرائض، وصابروا عدوكم، ورابطوا إمامكم المنتظر ((3)). وهذه العصابة القليلة هي التي قال أمير المؤمنين (عليه السلام) لها: لا تستوحشوا في طريق الهدى لقلة من يسلكه ((4)) فيما أخبرنا أبو العباس أحمد بن محمد بن سعيد بن عقدة الكوفي، قال: حدثنا أبو عبد الله جعفر بن عبد الله المحمدي من كتابه في المحرم سنة ثمان وستين ومائتين، قال: حدثني يزيد بن إسحاق الأرحبي - ويعرف بشعر -، قال: حدثنا مخول، عن فرات بن أحنف، عن الأصبغ بن نباتة، قال: سمعت أمير المؤمنين (عليه السلام) على منبر الكوفة يقول: أيها الناس، أنا أنف الإيمان، أنا أنف الهدى وعيناه. أيها الناس، لا تستوحشوا في طريق الهدى لقلة من يسلكه إن الناس اجتمعوا على مائدة قليل شبعها، كثير جوعها، والله المستعان، وإنما يجمع الناس الرضا والغضب. أيها الناس، إنما عقر ناقة صالح واحد فأصابهم الله بعذابه بالرضا لفعله، وآية ذلك قوله عز وجل: (فنادوا صاحبهم فتعاطى فعقر * فكيف كان عذابي ونذر) ((1))، وقال: (فعقروها فدمدم عليهم ربهم بذنبهم فسواها * ولا يخاف عقباها) ((2)) ألا ومن سئل عن قاتلي فزعم أنه مؤمن فقد قتلني. أيها الناس، من سلك الطريق ورد الماء، ومن حاد عنه وقع في التيه، ثم نزل. ورواه لنا محمد بن همام ومحمد بن الحسن بن محمد بن جمهور، جميعا، عن الحسن بن محمد بن جمهور، عن أحمد بن نوح، عن ابن عليم، عن رجل، عن فرات ابن أحنف، قال: أخبرني من سمع أمير المؤمنين (عليه السلام)، وذكر مثله، إلا أنه قال: لا تستوحشوا في طريق الهدى لقلة أهله ((3)). وفي قول أمير المؤمنين (عليه السلام): \" من سلك الطريق ورد الماء، ومن حاد عنه وقع في التيه \" ((4))، بيان شاف لمن تأمله، ودليل على التمسك بنظام الأئمة، وتحذير من الوقوع في التيه بالعدول عنها والانقطاع عن سبيلها، ومن الشذوذ يمينا وشمالا، والإصغاء إلى ما يزخرفه المفترون المفتونون في دينهم من القول الذي هو كالهباء المنثور وكالسراب المضمحل، كما قال الله عز وجل: (ألم * أحسب الناس أن يتركوا أن يقولوا آمنا وهم لا يفتنون * ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين) ((1)). وكما روي عن النبي (صلى الله عليه وآله) أنه قال: إياكم وجدال كل مفتون فإنه ملقن حجته ((2)) إلى انقضاء مدته، فإذا انقضت مدته ألهبته خطيئته وأحرقته ((3)). أخبرنا بذلك عبد الواحد بن عبد الله بن يونس، قال: حدثنا محمد بن جعفر القرشي، قال: حدثني محمد بن الحسين بن أبي الخطاب، قال: حدثنا محمد بن سنان، عن أبي محمد الغفاري ((4))، عن أبي عبد الله، عن آبائه (عليهم السلام)، قال: قال رسول الله (صلى الله عليه وآله)، وذكر الحديث ((5)). وقد جمعت في هذا الكتاب ما وفق الله لجمعه من الأحاديث التي رواها الشيوخ عن أمير المؤمنين والأئمة الصادقين عليهم السلام أجمعين في الغيبة وغيرها مما سبيله أن يضاف إلى ما روي فيها بحسب ما حضر في الوقت، إذ لم يحضرني جميع ما رويته في ذلك لبعده عني وأن حفظي لم يشمل عليه، والذي رواه الناس من ذلك أكثر وأعظم مما رويته ويصغر ويقل عنه ما عندي وجعلته أبوابا صدرتها بذكر ما روي في صون سر آل محمد (عليهم السلام) عمن ليس من أهله، والتأدب بآداب أولياء الله في ستر ما أمروا بستره عن أعداء الدين والنصاب والمخالفين وسائر الفرق من المبتدعين والشاكين والمعتزلة الدافعين لفضل أمير المؤمنين صلوات الله عليه وآله أجمعين المجيزين تقديم المأموم على الإمام، والناقص على التام، خلافا على الله عز وجل حيث يقول: (أفمن يهدي إلى الحق أحق أن يتبع أم من لا يهدي إلا أن يهدى فما لكم كيف تحكمون) ((1)) وإعجابا بآرائهم المضلة وقلوبهم العمية، كما قال الله جل من قائل: (فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور) ((2))، وكما قال تبارك وتعالى: (قل هل ننبئكم بالأخسرين أعمالا * الذين ضل سعيهم في الحياة الدنيا وهم يحسبون أنهم يحسنون صنعا) ((3)) الجاحدين فضل الأئمة الطاهرين وإمامتهم (عليهم السلام) المحلول في صدورهم لشقائهم ما قد تمكن فيها من العناد لهم بعد وجوب الحجة عليهم من الله بقوله عز وجل: (واعتصموا بحبل الله جميعا ولا تفرقوا) ((4)) ومن رسوله (صلى الله عليه وآله) بقوله في عترته: إنهم الهداة وسفينة النجاة، وإنهم أحد الثقلين اللذين أعلمنا تخليفه إياهما علينا والتمسك بهما بقوله: إني مخلف فيكم الثقلين: كتاب الله، وعترتي أهل بيتي حبل ممدود بينكم وبين الله، طرف بيد الله، وطرف بأيديكم، ما إن تمسكتم به لن تضلوا. خذلانا من الله شملهم به استخفافهم ذلك وبما كسبت أيديهم، وبإيثارهم العمى على الهدى، كما قال الله عز وجل: (وأما ثمود فهديناهم فاستحبوا العمى على الهدى) ((5))، وكما قال: (أفرأيت من اتخذ إلهه هواه وأضله الله على علم) ((6)) يريد عز وجل على علم لعناده للحق، واسترخائه إياه، ورده له، واستمرائه الباطل، وحلوله في قلبه وقبوله له، والله لا يظلم الناس شيئا ولكن الناس أنفسهم يظلمون ((7)). وهم المعاندون لشيعة الحق ومحبي أهل الصدق، والمنكرون لما رواه الثقات من المؤمنين عن أهل بيت رسول الله صلى الله عليه وعليهم، الرادون العايبون لهم بجهلهم وشقوتهم، القائلون بما رواه أعداؤهم، العاملون به، الجاعلون أئمتهم أهوائهم وعقولهم وآرائهم دون من اختاره الله بعلمه، حيث يقول: (ولقد اخترناهم على علم على العالمين) ((1))، ونصبه واصطفاه وانتجبه وارتضاه، المؤثرون الملح الأجاج على العذب النمير الفرات، فإن صون دين الله وطي علم خيرة الله سبحانه عن أعدائهم المستهزئين به أولى ما قدم، وأمرهم بذلك أحق ما امتثل. ثم ابتدأنا بعد ذلك بذكر حبل الله الذي أمرنا بالاعتصام به وترك التفرق عنه بقوله: (واعتصموا بحبل الله جميعا ولا تفرقوا) ((2)). وما روي في ذلك وأردفناه بذكر ما روي في الإمامة وأنها من الله عز وجل وباختياره، كما قال تبارك وتعالى: (وربك يخلق ما يشاء ويختار ما كان لهم الخيرة) ((3)) من أمرهم، وأنها عهد من الله وأمانة يؤديها الإمام إلى الذي بعده. ثم ما روي في أن الأئمة (عليهم السلام) اثنا عشر إماما وذكر ما يدل عليه من القرآن والتوراة والإنجيل من ذلك، بعد نقل ما روي من طريق العامة في ذكر الأئمة الاثني عشر. ثم ما روي فيمن ادعى الإمامة، ومن زعم أنه إمام وليس ((4)) بإمام، وأن كل راية ترفع قبل قيام القائم فصاحبها طاغوت. ثم الحديث المروي من طرق العامة. ثم ما روي فيمن شك في واحد من الأئمة صلى الله عليهم، أو بات ليلة لا يعرف فيها إمامه، أو دان الله بغير إمام منه. ثم ما روي في أن الله لا يخلي أرضه من حجة. ثم ما روي في أنه لو لم يبق في الأرض إلا اثنان لكان أحدهما الحجة. ثم ما روي في غيبة الإمام (عليه السلام)، وذكر أمير المؤمنين والأئمة صلوات الله عليهم أجمعين بعده لها، وإنذارهم بها. ثم ما روي في ما أمر به الشيعة من الصبر والكف والانتظار في حال الغيبة. ثم ما روي فيما يلحق الشيعة من التمحيص والتفرق والتشتت عند الغيبة حتى لا يبقى على حقيقة الأمر إلا الأقل. ثم ما روي في الشدة التي تكون قبل قيام القائم (عليه السلام). ثم ما روي في صفته (عليه السلام) وسيرته. ثم ما نزل من القرآن فيه (عليه السلام). ثم ما روي من العلامات التي تكون قبل ظهوره تدل على قيامه وقرب أمره. ثم ما جاء من المنع في التوقيت والتسمية لصاحب الأمر (عليه السلام). ثم ما جاء في ما يلقى القائم منذ قيامه (عليه السلام) فيبتلى من جاهلية الناس. ثم ما جاء في ذكر جيش الغضب وهم أصحاب القائم (عليه السلام) وعدتهم. ثم ما جاء في ذكر السفياني، وأن أمره من المحتوم الكائن قبل قيام القائم (عليه السلام). ثم ما جاء في ذكر راية رسول الله (صلى الله عليه وآله)، وأنه لا ينشرها بعد يوم الجمل إلا القائم (عليه السلام)، وصفتها. ثم ما جاء في ذكر أحوال الشيعة عند خروج القائم (عليه السلام) وقبله وبعده. ثم ما روي في أن القائم (عليه السلام) يستأنف دعاء جديدا، وأن الإسلام بدأ غريبا وسيعود غريبا كما بدأ. ثم ما روي في مدة ملك القائم (عليه السلام) بعد ظهوره. ثم ما روي في ذكر إسماعيل بن أبي عبد الله (عليه السلام)، وبطلان ما يدعيه المبطلون الذين هم عن السمع والعلم معزولون. ثم ما روي في أن من عرف إمامه لم يضره تقدم هذا الأمر أم تأخر. ونحن نسأل الله بوجهه الكريم وشأنه العظيم أن يصلي على الصفوة المنتجبة ((1)) من خلقه، والخيرة من بريته، وحبله المتين، وعروته الوثقى التي لا انفصام لها، محمد وآله الطاهرين، وأن يثبتنا بالقول الثابت في الحياة الدنيا وفي الآخرة، وأن يجعل محيانا ومماتنا وبعثنا على ما أنعم به علينا من دين الحق وموالاة أهله الذين خصهم بكرامته، وجعلهم السفراء بينه وبين خلقه، والحجة على بريته، وأن يوفقنا للتسليم لهم والعمل بما أمروا به، والانتهاء عما نهوا عنه، ولا يجعلنا من الشاكين في شئ من قولهم، ولا المرتابين بصدقهم، وأن يجعلنا من أنصار دينه مع وليه، والصادقين في جهاد عدوه حتى يجعلنا بذلك معهم، ويكرمنا بمجاورتهم في جنات النعيم، ولا يفرق بيننا وبينهم طرفة عين أبدا، ولا أقل من ذلك ولا أكثر، إنه جواد كريم.","22/1/1/1",""],[1,1,"أخبرنا أبو العباس أحمد بن محمد بن سعيد ابن عقدة الكوفي قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال حدثنا عبيس بن هشام الناشري، قال: حدثنا عبدالله بن جبلة، عن سلام بن أبي عمرة، عن معروف بن خربوذ، عن أبي الطفيل عامر بن وائلة قال: قال أمير المؤمنين: أتحِبّونَ أن يُكذَّبَ اللهُ وَرسُولُه؟ حَدّثوا النّاسَ بما يَعِرفون، وأمْسِكوا عمّا يُنكِرونَ.","22/2/1/1",""],[2,1,"وحدثني أبو القاسم الحسين بن محمد الباوري قال: حدثنا يوسف بن يعقوب المقرئ السقطي بواسط، قال: حدثني خلف البزار، عن يزيد بن هارون، عن حميد الطويل قال: سمعت أنس بن مالك قال: سمعت رسول الله يقول: لا تحَدّثوا النّاسَ بما لا يَعرِفونَ، أتحِبُّونَ أنْ يُكَذَّبَ اللهُ وَرَسولُهُ؟","22/2/1/2",""],[3,1,"وحدثنا أحمد بن محمد بن سعيد ابن عقدة قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي أبو الحسن قال: حدثنا إسماعيل بن مهران قال: حدثنا الحسن بن علي بن أبي حمزة، عن عبد الأعلى بن أعين قال: قال لي أبو عبد الله جعفر بن محمد: يا عَبدَ الأعلى، إنّ احتِمالَ أمْرِنا لَيسَ مَعرِفَتَه وَقبولَه. إنّ احتمالَ أمرِنا هُو صَونُه وسِتْرُه عَمَّن لَيسَ مِن أهْلِه، فَأقْرِئهُم السّلام وَرحمَةَ اللهِ - يَعني الشّيعَةَ - وقُل: قَال لَكم: رَحِمَ اللهُ عَبداً استَجرَّ مودَّةَ النّاسِ إلى نفسِه وإلَينا بأنْ يُظهِرَ لهم ما يَعرفونَ ويكُفّ عَنهم ما يُنكرِون. (ثمّ قال) ما النّاصِب لنا حَربا بأشَدَّ مَؤونةً مِن النّاطق عَلينا بما نَكرَهُه.","22/2/1/3",""],[4,1,"وحدثنا أحمد بن محمد بن سعيد، قال: حدثنا أبو عبد الله جعفر بن عبد الله من كتابه في رجب سنة ثمان ومائتين قال: حدثنا الحسن بن علي بن فضال قال: حدثني صفوان بن يحيى، عن إسحاق بن عمار الصيرفي، عن عبد الأعلى بن أعين عن أبي عبد الله جعفر بن محمد أنه قال: لَيسَ هذا الأمرُ مَعرِفتَهُ وَولايتَهُ فقَط حَتىّ تَستُرَه عمّن ليسَ مِن أهلِه، وبِحَسبِكم أن تقولوا ما قُلنا وتَصمِتوا عمّا صَمتْنا، فإنّكم إذا قُلتم ما نَقول وسَلّمتُم لنا فيما سَكَتنا عنهُ فقَد آمنتُم بمِثلِ ما آمنّا بهِ. قالَ اللهُ تعالى: فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنْتُمْ بِهِ فَقَدِ اهْتَدَوْا ۖ وَإِنْ تَوَلَّوْا فَإِنَّمَا هُمْ فِي شِقَاقٍ ۖ فَسَيَكْفِيكَهُمُ اللَّهُ ۚ وَهُوَ السَّمِيعُ الْعَلِيمُ قالَ علِيّ بن الحُسينِ: حدِّثوا النّاسَ بما يَعرفونَ، ولا تُحَمِّلوهُم ما لا يُطيقونَ فتُغرونهُم بنا.","22/2/1/4",""],[5,1,"وأخبرنا عبد الواحد بن عبد الله بن يونس الموصلي قال: حدثنا محمد بن جعفر القرشي قال: حدثني محمد بن الحسين بن أبي الخطاب قال: حدثنا محمد بن غياث عن عبد الأعلى بن أعين قال: قال أبو عبد الله جعفر بن محمد: إنَّ احتِمالَ أمرِنا ليسَ هو التّصديقَ بهِ والقَبولَ له فقَط، إنّ مِن احتِمالِ أمرِنا سِترَهُ وصِيانَتَه عَن غيرِ أهلِه، فأقرئْهُم السّلامَ ورَحمةَ اللهِ - يعنى الشيعة - وقُل لهُم: يَقولُ لكُم: رحِمَ اللهُ عَبداً اجتَرَّ مَودَّةَ النّاسِ إلَيَّ وإلى نَفسِه، يُحدّثُهم بما يعرِفون ويستُرُ عنهُم ما يُنكِرون. ثم قال لي: واللهِ ما النّاصِبُ لنا حَرباً أشَدُّ مَؤونَةً علَينا مِن النّاطقِ عَلينا بما نَكرَهُه - وذكر الحديث بطوله -.","22/2/1/5",""],[6,1,"وأخبرنا عبد الواحد بن عبد الله قال: أخبرنا أحمد بن محمد بن رباح الزهري عن محمد بن العباس الحسني عن الحسن بن علي بن أبي حمزة البطائني عن محمد الخزاز قال: قال أبو عبد الله: مَن أذاعَ علينا حَديثنا هو بِمنُزِلةِ مَن جَحدنا حقَّنا.","22/2/1/6",""],[7,1,"وبهذا الإسناد، عن الحسن بن علي بن أبي حمزة، عن الحسن بن السري قال: قال أبو عبد الله: إنيّ لأُحدّث الرجُلّ الحديثَ فينطَلقُ فيُحدّثُ به عَني كما سمعَهُ فأَستَحلُّ به لَعنَهُ والبراءَةَ منه.","22/2/1/7",""],[8,1,"وبه عن الحسن بن علي بن أبي حمزة، عن القاسم الصيرفي، ابن مسكان قال: سمعت أبا عبد الله يقول: قومٌ يزعُمون إنيّ إمامُهم. واللهِ ما أنا لهم بإمامٍ! لَعنهُمُ اللهُ كلَّما سَترتُ سِتراً هَتكوهُ. أقولُ كذا وكذا، فَيقولونَ إنمّا يعني كذا وكذا. إنمّا أنا إمامُ مَن أطاعَني.","22/2/1/8",""],[9,1,"وبه عن الحسن، عن كرام الخثعمي قال: قال أبو عبد الله: أما واللهِ لو كانتْ على أفواهِكم أوكِيَةً لحدَّثتُ كُلَّ امرئٍ منكُم بما لهُ، واللهِ لَو وَجَدتُ أتقِياءَ لتَكَلّمتُ، واللهُ المُستَعانُ.","22/2/1/9",""],[10,1,"وبه عن الحسن، عن أبيه، عن أبى بصير قال: سمعت أبا جعفر يقول: سِرٌّ أسَرَّهُ اللهُ إلى جِبرَئيلَ وأسَرَّهُ جِبرئيلُ إلى محَمَّدٍ وأسَرَّه محَمّدٌ إلى عَليٍّ وأَسَرّهُ عَليٌّ إلى مَن شاءَ اللهُ واحِداً بَعدَ واحِدٍ، وأنتُم تَتكلّمونَ بِه في الطّرُقِ!","22/2/1/10",""],[11,1,"وحدثنا محمد بن همام بن سهيل قال حدثنا عبد الله بن العلاء المذاري قال حدثنا إدريس بن زياد الكوفي قال: حدثنا بعض شيوخنا قال: قال المفضل: أخذت بيدك كما أخذ أبو عبد الله بيدي وقال لي: يا مُفَضّلُ! إنّ هذا الأمر ليسَ بالقَولِ فقَط، لا واللهِ حتىّ يَصونَهُ كَما صانهُ اللهُ ويُشَرّفهُ كما شَرّفهُ اللهُ ويُؤدّي حقَّه كمَا أمرَ اللهُ.","22/2/1/11",""],[12,1,"وأخبرنا عبد الواحد بإسناده، عن الحسن، عن حفص بن نسيب فرعان قال: دخلتُ على أبي عبد الله أيام قتْلِ المعلّي بن خُنيس مولاه فقال لي: يا حَفصُ! حدَّثتُ المُعلّى بأشياءَ فأذاعَها فابتُلِيَ بِالحَديدِ. إنيّ قُلتُ لهُ: إنّ لنا حديثاً مَن حَفِظَهُ عَلينا حَفِظهُ اللهُ وحَفِظَ عَليه دينَهُ ودُنياهُ، وَمَن أذاعَهُ عَلينا سَلبَهُ اللهُ دينَهُ ودُنياهُ. يا مُعَلّى! إنّهُ مَن كتَم الصَّعبَ مِن حديثِنا جَعلَهُ اللهُ نوراً بَينَ عَينَيهِ ورَزقَهُ العِزَّ في النّاسِ، وَمَن أذاعَ الصّعبَ مِن حديثِنا لم يمُتْ حَتىّ يعضَّهُ السّلاحُ أو يموتَ متَحَيّراً.","22/2/1/12",""],[1,2,"حدثنا محمد بن عبد الله بن المعمر الطبراني بطبرية سنة ثلاث وثلاثين وثلاثمائة - وكان هذا الرجل من موالي يزيد بن معاوية ومن النصاب - قال: حدثني أبي، قال: حدثني علي بن هاشم والحسين بن السكن معا قالا: حدثنا عبد الرزاق بن همام قال: أخبرني أبي، عن مينا مولى عبد الرحمن بن عوف، عن جابر بن عبد الله الأنصاري قال: وفد على رسول الله أهل اليمن فقال النبي: جاءَكُم أهلُ اليمَنِ يبُسّونَ بَسيساً. فلما دخلوا على رسول الله قال: قَومٌ رقيقَةٌ قلوبُهُم، راسِخٌ إيمانُهُم. وَمِنهُم المَنصورُ؛ يخرُجُ في سَبعينَ ألفاً يَنصُر خَلَفي وَخَلَف وَصِيّي. حمَائِلُ سُيوفِهمُ المِسكُ. فقالوا: يا رسول الله ومن وصيك؟ فقال: هُو الّذي أمَرَكمُ اللهُ بالاعتِصامِ به فقَالَ: وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا ۚ فقالوا: يا رسول الله بيّن لنا ما هذا الحبل. فقال: هوَ قولُ اللهِ: ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ أَيْنَ مَا ثُقِفُوا إِلَّا بِحَبْلٍ مِنَ اللَّهِ وَحَبْلٍ مِنَ النَّاسِ وَبَاءُوا بِغَضَبٍ مِنَ اللَّهِ وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ الْأَنْبِيَاءَ بِغَيْرِ حَقٍّ ۚ ذَٰلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ فالحَبلُ مِن اللهِ كِتابُه، والحَبلُ مِن النّاسِ وَصِيّي. فقالوا: يا رسول الله من وصيك؟ فقال: هُو الّذي أنزَلَ اللهُ فيهِ: أَنْ تَقُولَ نَفْسٌ يَا حَسْرَتَا عَلَىٰ مَا فَرَّطْتُ فِي جَنْبِ اللَّهِ وَإِنْ كُنْتُ لَمِنَ السَّاخِرِينَ فقالوا: يا رسول الله وما جنب الله هذا؟ فقال: هوَ الّذي يقولُ اللهُ فيه: ﴿وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا( هو وصِيّي والسّبيلُ إليَّ مِن بَعدي. فقالوا: يا رسول الله بالذي بعثك بالحق نبياً أرناه فقد اشتقنا إليه. فقال: هو الّذي جَعلَهُ اللهُ آيَةً لِلمؤمِنين المُتوسّمينَ، فإنْ نَظرتُم إلَيه نَظَرَ مَن كانَ لهُ قَلبٌ أو ألْقَى السّمعَ وهوَ شَهيدٌ عَرفتُم أنّه وصِيّي كمَا عرفتُم أنيّ نَبيُّكم، فَتخلّلوا الصّفوفَ وتَصَفّحوا الوجوهَ فمَن أهوَتْ إليهِ قُلوبُكم فإنّه هوَ، لأنَّ الله يَقول في كِتابِه: رَبَّنَا إِنِّي أَسْكَنْتُ مِنْ ذُرِّيَّتِي بِوَادٍ غَيْرِ ذِي زَرْعٍ عِنْدَ بَيْتِكَ الْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا الصَّلَاةَ فَاجْعَلْ أَفْئِدَةً مِنَ النَّاسِ تَهْوِي إِلَيْهِمْ وَارْزُقْهُمْ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ أي إلَيه وإلى ذُرّيّتهِ. ثم قال: فقام أبو عامر الاشعري في الاشعريين، وأبو غرة الخولاني في الخولانيين، وظبيان، وعثمان بن قيس في بني قيس، وعرنة الدوسي في الدوسيين، ولاحق بن علاقة، فتخللوا الصفوف وتصفحوا الوجوه وأخذوا بيد الأنزع الأصلع البطين وقالوا: إلى هذا أهوت أفئدتنا يا رسول الله. فقال النبي: أنتُم نجَبَةُ اللهِ حينَ عرفتُم وصِيَّ رَسولِ اللهِ قَبلَ أن تَعرفوهُ، فَبِمَ عَرفتُم أنّهُ هوَ؟ فرفعوا أصواتهم يبكون ويقولون: يا رسول الله نظرنا إلى القوم فلم تحن لهم قلوبنا ولما رأيناه رجفت قلوبنا ثم اطمأنت نفوسنا، وانجاشت أكبادنا، وهملت أعيننا، وانثلجت صدورنا حتى كأنه لنا أب ونحن له بنون. فقال النبي: )هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ ۖ فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ ۗ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِنْ عِنْدِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ( أنتُم منهُم بالمَنْزلَةِ الّتي سبَقتْ لكُم بها الحُسنى، وأنتُم عَن النّار مُبعَدونَ. قال: فبقي هؤلاء القوم المسمون حتى شهدوا مع أمير المؤمنين الجمل وصفين فقتلوا بصفين رحمهم الله، وكان النبي بشرهم بالجنة وأخبرهم أنهم يستشهدون مع علي بن أبي طالب .","22/2/2/1",""],[2,2,"أخبرنا محمد بن همام بن سهيل قال: حدثنا أبو عبد الله جعفر بن محمد الحسني قال: حدثنا أبو إسحاق إبراهيم بن إسحاق الحميري، قال: حدثنا محمد بن يزيد بن عبد الرحمن التيمي، عن الحسن بن الحسين الأنصاري، عن محمد بن الحسين، عن أبيه، عن جده قال: قال علي بن الحسين: كانَ رسولُ اللهِ ذاتَ يَومٍ جالِساً ومعَهُ أصحابُه في المَسجِدِ فقالَ: يَطلُعُ عَليكُم مِن هذا البابِ رجُلٌ مِن أهلِ الجنَّةِ يسألُ عمّا يَعنيهِ. فطَلعَ رجُلٌ طَويلٌ يٌشبِهُ برِجالِ مُضرَ. فتقَدّمَ فسَلَّمَ عَلى رسولِ الله وجلَس، فقالَ: يا رسولَ الله إنيّ سَمِعتُ اللهَ يقولُ فيما أنزَلَ: )وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا ﴾ فَما هذا الحَبلُ الّذي أمرَنا اللهُ بالاعتِصامِ بهِ وألاّ نتَفَرَّقَ عنهُ؟ فأطْرقَ رسولُ الله مَليّاً، ثمّ رفعَ رأسَه وأشارَ بيدِه إلى عَليّ بنِ أبي طالبٍ وقالَ: هذا حَبلُ اللهِ الّذي مَن تمَسّكَ به عُصِمَ بهِ في دُنياهُ ولم يَضِلَّ بهِ في آخِرتِه. فوَثبَ الرّجلُ إلى عَليٍّ فاحتَضَنهُ مِن وَراءِ ظَهرِه وهو يقولُ: اِعتَصَمْتُ بحَبلِ اللهِ وَحبلِ رسولِه، ثمّ قامَ فَولىّ وخَرجَ، فقامَ رجُلٌ مِن النّاسِ فقالَ: يا رسولَ اللهِ، ألحَقُهُ فأسألُه أن يَستغفِرَ لي؟ فقالَ رسولُ اللهِ: إذاً تجِدُه مُوفّقاً. فقال: فلحِقَه الرّجلُ فسأله أن يَستغفِر اللهُ لهُ. فقالَ له: أفهِمتَ ما قالَ لي رسولُ الله وما قلتُ لهُ؟ قال: نعم. قال: فإن كُنتَ مُتمسّكاً بذلِك الحبلِ يغفرِ اللهُ لكَ وإلاّ فلا يَغفرِ اللهُ لكَ. إنيّ فَرطُكم وإنّكم وارِدونَ عليَّ الحوضَ، حَوضاً عرضُه ما بَين بُصرى إلى صَنعاء، فيهِ قِدحان عدَدَ نجُومِ السّماء. ألا وإنيّ مُخَلّفٌ فيكُم الثّقَلينِ، الثّقلُ الأكبرُ القُرآنُ، والثّقلُ الأصغَرُ عِترتي أهلَ بَيتي، هما حَبلُ اللهِ ممَدودٌ بينَكم وبينَ الله ، ما إنْ تمسّكتُم به لنْ تضِلوا، سَببٌ مِنه بِيدِ اللهِ وسَببٌ بأيديكُم. إنّ اللّطيفَ الخبيرَ قَد نبّأني أنهّما لَن يفترِقا حتىّ يرِدا عليَّ الحوضَ كإصبِعَيَّ هاتَين -وجمَع بين سبّابَتيهِ- ولا أقولُ كَهاتَينِ - وجمَع بَين سبّابتِه والوُسطى- فَتفضُلَ هذِه على هَذه. مَثَلُ أهلِ بَيتي فيكُم كَمثَلِ سَفينَةِ نوحٍ مَن رَكِبها نجَا ومَن تخَلّفَ عَنها غَرِقَ. مَثَلُ أهلِ بَيتي فيكُم كَمثَلِ بابِ حِطّة في بَني إسرائِيلَ الّذي مَن دخَلهُ غُفرَت ذُنوبُه واستَحَقّ الرّحمةَ والزّيادَة مِن خالِقِه. وَإِذْ قُلْنَا ادْخُلُوا هَٰذِهِ الْقَرْيَةَ فَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَادْخُلُوا الْبَابَ سُجَّدًا وَقُولُوا حِطَّةٌ نَغْفِرْ لَكُمْ خَطَايَاكُمْ ۚ وَسَنَزِيدُ الْمُحْسِنِينَ ألا إنّ العِلمَ الّذي هَبطَ بهِ آدَمُ مِن السّماءِ إلى الأرضِ وجمِيع ما فُضّلَت بهِ النّبيّونَ إلى خَاتم النَّبِيّينَ في عِترَة خاتمِ النّبِيّينَ. فأينَ يُتاهُ بِكم؟ بَل أينَ تَذهَبونَ؟ يا مَن نَسخَ مِن أصلابِ أصْحابِ السّفينَةِ هذا مِثلها فِيكُم. فَكما نجَا في هاتَيكَ مَن نجَا فَكذلِكَ يَنجو مِن هذِه مَن يَنجو. وَيلٌ لمَِن تخَلّف عَنهُم. إنّ مَثلَنا فيكُم كَمَثلِ الكَهفِ لأصحابِ الكَهفِ، وَكبابِ حِطّة وهُو بابُ السِّلْم، فادخُلوا في السّلمِ كافّةً. ولَقَد علِمَ المُستَحفَظونَ مِن أصْحابِ محَمَّدٍ أنّه قالَ: إنيّ وأهْلَ بَيتي مُطَهّرون؛ فلا تَسبِقوهُم فَتضِلّوا، ولا تَخَلّفوا عَنهُم فَتزِلّوا، ولا تُخالِفوهُم فَتجهَلوا، ولا تُعَلّموهُم فإنهُم أعلَمُ مِنكُم. هُم أعلَمُ النّاسِ صِغاراً، وَأعلَمُ النّاسِ كِباراً، فاتّبِعوا الحَقَّ وأهْلَه حَيثُما كانَ، وزايِلوا الباطِلَ وأهْلَهُ حَيثُما كانَ. وَمَا أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ ۖ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ ۖ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا قُلْ هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا وَيَوْمَ يَعَضُّ الظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا يَا وَيْلَتَىٰ لَيْتَنِي لَمْ أَتَّخِذْ فُلَانًا خَلِيلًا لَقَدْ أَضَلَّنِي عَنِ الذِّكْرِ بَعْدَ إِذْ جَاءَنِي ۗ وَكَانَ الشَّيْطَانُ لِلْإِنْسَانِ خَذُولًا أَعَدَّ اللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ فَاتَّقُوا اللَّهَ يَا أُولِي الْأَلْبَابِ الَّذِينَ آمَنُوا ۚ قَدْ أَنْزَلَ اللَّهُ إِلَيْكُمْ ذِكْرًا رَسُولًا يَتْلُو عَلَيْكُمْ آيَاتِ اللَّهِ مُبَيِّنَاتٍ لِيُخْرِجَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ مِنَ الظُّلُمَاتِ إِلَى النُّورِ ۚ وَمَنْ يُؤْمِنْ بِاللَّهِ وَيَعْمَلْ صَالِحًا يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ۖ قَدْ أَحْسَنَ اللَّهُ لَهُ رِزْقًا وَمَا أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ ۖ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ ۚ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ لَقَدْ أَضَلَّنِي عَنِ الذِّكْرِ بَعْدَ إِذْ جَاءَنِي ۗ وَكَانَ الشَّيْطَانُ لِلْإِنْسَانِ خَذُولًا وَقَالَ الرَّسُولُ يَا رَبِّ إِنَّ قَوْمِي اتَّخَذُوا هَٰذَا الْقُرْآنَ مَهْجُورًا إنّ قَوماً مِن أصْحابي يختَلِجونَ دوني يَومَ القيامَة مِن ذاتِ اليَمينِ إلى ذاتِ الشّمالِ فأقولُ: يا ربِّ أُصَيحابي أصَيحابي - وفي بعضِ الحديثِ أصحابي أصحابي - فيُقالُ: يا محَمّدُ إنّكَ لا تَدري ما أحدَثوا بعدَكَ. فأقولُ: بُعداً بُعداً، سُحقاً سُحقاً. وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ ۚ أَفَإِنْ مَاتَ أَوْ قُتِلَ انْقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ ۚ وَمَنْ يَنْقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَنْ يَضُرَّ اللَّهَ شَيْئًا ۗ وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ {144} لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا ۚ قَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنْكُمْ لِوَاذًا ۚ فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ ذَٰلِكَ الَّذِي يُبَشِّرُ اللَّهُ عِبَادَهُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ ۗ قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَىٰ ۗ وَمَنْ يَقْتَرِفْ حَسَنَةً نَزِدْ لَهُ فِيهَا حُسْنًا ۚ إِنَّ اللَّهَ غَفُورٌ شَكُورٌ قُلْ هَلْ مِنْ شُرَكَائِكُمْ مَنْ يَهْدِي إِلَى الْحَقِّ ۚ قُلِ اللَّهُ يَهْدِي لِلْحَقِّ ۗ أَفَمَنْ يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَنْ يُتَّبَعَ أَمَّنْ لَا يَهِدِّي إِلَّا أَنْ يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ أَفَلَمْ يَسِيرُوا فِي الْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌ يَعْقِلُونَ بِهَا أَوْ آذَانٌ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى الْأَبْصَارُ وَلَٰكِنْ تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ لَقَدْ كُنْتَ فِي غَفْلَةٍ مِنْ هَٰذَا فَكَشَفْنَا عَنْكَ غِطَاءَكَ فَبَصَرُكَ الْيَوْمَ حَدِيدٌ {22} يَوْمَ لَا يَنْفَعُ الظَّالِمِينَ مَعْذِرَتُهُمْ ۖ وَلَهُمُ اللَّعْنَةُ وَلَهُمْ سُوءُ الدَّارِ {52} وَيَوْمَ نَبْعَثُ فِي كُلِّ أُمَّةٍ شَهِيدًا عَلَيْهِمْ مِنْ أَنْفُسِهِمْ ۖ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰؤُلَاءِ ۚ وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ وَهُدًى وَرَحْمَةً وَبُشْرَىٰ لِلْمُسْلِمِينَ وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُمْ ۚ مَا فَرَّطْنَا فِي الْكِتَابِ مِنْ شَيْءٍ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ إِنَّا نَحْنُ نُحْيِي الْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ ۚ وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ كِتَابًا قُلْ لَا أَقُولُ لَكُمْ عِنْدِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ لَكُمْ إِنِّي مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰ إِلَيَّ ۚ قُلْ هَلْ يَسْتَوِي الْأَعْمَىٰ وَالْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ وَأَنِ احْكُمْ بَيْنَهُمْ بِمَا أَنْزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ وَاحْذَرْهُمْ أَنْ يَفْتِنُوكَ عَنْ بَعْضِ مَا أَنْزَلَ اللَّهُ إِلَيْكَ ۖ فَإِنْ تَوَلَّوْا فَاعْلَمْ أَنَّمَا يُرِيدُ اللَّهُ أَنْ يُصِيبَهُمْ بِبَعْضِ ذُنُوبِهِمْ ۗ وَإِنَّ كَثِيرًا مِنَ النَّاسِ لَفَاسِقُونَ وَإِذَا جَاءَهُمْ أَمْرٌ مِنَ الْأَمْنِ أَوِ الْخَوْفِ أَذَاعُوا بِهِ ۖ وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ وَإِلَىٰ أُولِي الْأَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ ۗ وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ لَاتَّبَعْتُمُ الشَّيْطَانَ إِلَّا قَلِيلًا وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ ۚ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ وَمَا أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًا نُوحِي إِلَيْهِمْ ۖ فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ ۚ وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ ۚ وَأُولَٰئِكَ لَهُمْ عَذَابٌ عَظِيمٌ وَاعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلَا تَفَرَّقُوا ۚ وَاذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ كُنْتُمْ أَعْدَاءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُمْ بِنِعْمَتِهِ إِخْوَانًا وَكُنْتُمْ عَلَىٰ شَفَا حُفْرَةٍ مِنَ النَّارِ فَأَنْقَذَكُمْ مِنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَهْتَدُونَ وَلَا تَكُونُوا كَالَّذِينَ تَفَرَّقُوا وَاخْتَلَفُوا مِنْ بَعْدِ مَا جَاءَهُمُ الْبَيِّنَاتُ ۚ وَأُولَٰئِكَ لَهُمْ عَذَابٌ عَظِيمٌ","22/2/2/2",""],[1,3,"أخبرنا أبو العباس أحمد بن محمد بن سعيد بن عقدة الكوفي، قال: حدثنا أبو محمد عبد الله بن أحمد بن مستورد الأشجعي من كتابه في صفر سنة ست وستين ومائتين، قال: حدثنا أبو جعفر محمد بن عبيد الله الحلبي، قال: حدثنا عبد الله بن بكير، عن عمرو بن الاشعث قال: سمعت أبا عبد الله جعفر بن محمد يقول - ونحن عنده في البيت نحواً من عشرين رجلاً - فأقبل علينا وقال: لعلَّكُم ترَونَ أن هذا الأمرَ في الإمامة إلى الرجل منّا يضعُه حيثُ يشاءُ؛ واللهِ إنّه لَعَهدٌ مِن الله نزَلَ على رَسولِ الله إلى رِجالٍ مُسَمَّينَ رجلٌ فَرجُلٌ حتىّ تنتهى إلى صاحبِها.","22/2/3/1",""],[2,3,"وأخبرني أبو العباس أحمد بن محمد بن سعيد، قال: حدثني أحمد بن يوسف بن يعقوب الجعفي من كتابه، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب بن حفص جميعاً، عن أبي بصير، عن أبي عبد الله في قول الله: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُمْ بَيْنَ النَّاسِ أَنْ تَحْكُمُوا بِالْعَدْلِ ۚ إِنَّ اللَّهَ نِعِمَّا يَعِظُكُمْ بِهِ ۗ إِنَّ اللَّهَ كَانَ سَمِيعًا بَصِيرًا قال: هيَ الوَصيَّةُ يدفعُها الرَّجُل منّا إلى الرّجلِ.","22/2/3/2",""],[3,3,"وأخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي قال: حدثنا علي بن الحسن عن اسماعيل بن مهران، عن المفضل بن صالح، عن معاذ بن كثير، عن أبي عبد الله جعفر بن محمد أنه قال: الوصِيّةُ نزَلتْ من السماء على رسولِ الله كتاباً مختوماً، ولم ينْزِل على رسولِ الله كتابٌ مختومٌ إلاّ الوصيّة، فقال جبرئيل: يا مُحمَّدُ هذه وصيَّتُك في أمّتِك إلى أهل بَيتِك. فقال رسول الله: أيّ أهلِ بيتي يا جبرئيل؟ فقال: نجيبُ اللهِ منهُم وذُرّيَّتُه ليورثَكَ عِلم النّبوّة قبل إبراهيم. وكان عليها خواتيمُ، ففتح عليٌّ الخاتمَ الأوّل ومضى لِما أُمرَ فيه، ثمَّ فتحَ الحسنُ الخاتمَ الثاني ومضى لما أُمر به، ثم فتح الحُسين الخاتمَ الثّالث فوجد فيه أنْ قاتِلْ وأقتُل وتُقتَلُ واخرجْ بقَومٍ للشّهادة؛ لا شهادةَ لهم إلاّ معكَ، ففعَلَ، وثمَّ دفَعَها إلى عليّ بن الحسين ومضى، ففتح عليُّ بن الحسين الخاتمَ الرابعَ فوجد فيه أن أطرِقْ واصمُت لمّا حُجبَ العلمُ، ثمّ دفعها إلى محمّد بن علي ففتح الخاتمَ الخامس فوجد فيه أن فسِّرْ كتابَ اللهِ تعالى وصدِّق أباكَ وورِّث ابنَك العِلمَ واصطَنع الأمَّةَ وقُل الحقَّ في الخوف والأمنِ ولا تخشَ إلاّ اللهَ، ففعل، ثمّ دفعها إلى الذي يليه. فقال معاذ بن كثير: فقلت له: وأنت هو؟ فقال: ما بكَ في هذا إلا أن تذهبَ، يا معاذُ، فترويه عنيّ. نعم، أنا هوَ… حتىّ عدّد على إثني عشرَ اسماً ثم سكت، فقلت: ثم مَن؟ فقال: حسبُك.","22/2/3/3",""],[4,3,"أخبرنا علي بن أحمد البندنيجى، عن عبيد الله بن موسى، قال: حدثنا محمد بن أحمد القلانسي قال: حدثنا محمد بن الوليد عن يونس بن يعقوب عن أبي عبد الله قال: دفع رسول الله إلى علي صحيفة مختومة باثني عشر خاتماً، وقال: فُضَّ الأوّلَ واعمل به وادفعْها إلى الحسن يفُضّ الثاني ويعمل به ويدفعْها إلى الحسين يفضّ الثالث ويعمل بما فيه، ثم إلى واحدٍ واحدٍ من ولد الحسين","22/2/3/4",""],[5,3,"وأخبرنا علي بن أحمد، عن عبيد الله بن موسى، عن علي بن إبراهيم بن هاشم، عن أبيه، عن حماد بن عيسى، عن حريز، عن زرارة، عن أبي جعفر محمد بن علي قال: سألته عن قول الله: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُمْ بَيْنَ النَّاسِ أَنْ تَحْكُمُوا بِالْعَدْلِ ۚ إِنَّ اللَّهَ نِعِمَّا يَعِظُكُمْ بِهِ ۗ إِنَّ اللَّهَ كَانَ سَمِيعًا بَصِيرًا قال: أمرَ اللهُ الإمامَ منّا أن يُؤدّيَ الإمامةَ إلى الإمام بعده، ليس له أن يزويَها عنه. ألا تسمعُ إلى قوله هم الحُكّام. أولا ترى أنه خاطب بها الحكامَ؟","22/2/3/5",""],[6,3,"وأخبرنا أحمد بن محمد بن سعيد بن عقدة الكوفي قال: حدثني أحمد بن يوسف بن يعقوب، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه، عن يعقوب بن شعيب قال: سمعت أبا عبد الله يقول: لا واللهِ! لا يدَع الله هذا الأمرَ إلاّ وله مَن يقوم به إلى يوم تقوم الساعةُ.","22/2/3/6",""],[7,3,"وأخبرنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن علي بن إبراهيم، عن أحمد بن محمد بن خالد البرقي، عن إسماعيل بن مهران، قال: حدثني المفضل بن صالح أبو جميلة عن أبي عبد الله عبد الرحمن، عن أبي عبد الله قال: إنَّ الله جلَّ اسمُه أنزلَ من السماء إلى كلِّ إمامٍ عهدَه وما يَعمل به، وعليه خاتمٌ فيَفُضُّه ويعمل بما فيه. يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ ۖ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ ۖ وَمَنْ تَوَلَّىٰ فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا {80} إنيّ مُخلّفٌ فيكم الثّقَلينِ كتابَ اللهِ وعِترتي أهلَ بيتي: حَبلٌ ممدودٌ بَينَكم وبَين اللهِ. ما إنْ تمَسّكتُم به لَن تضِلّوا. لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا ۚ قَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنْكُمْ لِوَاذًا ۚ فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ فَأَعْقَبَهُمْ نِفَاقًا فِي قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُ بِمَا أَخْلَفُوا اللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا يَكْذِبُونَ إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ۖ فَمِنْهُمْ مَنْ قَضَىٰ نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ ۖ وَمَا بَدَّلُوا تَبْدِيلًا","22/2/3/7",""],[1,4,"أخبرنا أبو سليمان أحمد بن هوذة أبي هراسة الباهلي، قال: حدثنا إبراهيم بن إسحاق النهاوندي سنة ثلاث وسبعين ومائتين، قال: حدثنا أبو محمد عبد الله بن حماد الأنصاري سنة تسع وعشرين ومائتين، قال: حدثنا عمرو بن شمر، عن المبارك بن فضالة، عن الحسن بن أبي الحسن البصري يرفعه قال: أتى جبرئيلُ النبيَّ فقال: يا محمدُ إن الله يأمرُك أن تزوّجَ فاطمةَ من عليٍّ أخيكَ. فأرسَلَ رسولُ الله إلى عليّ فقال له: يا عليُّ، إنّي مُزوّجُك فاطمةَ ابنتي سيدَةَ نساءِ العالمين وأحبَّهُن إلى بعدَك، وكائنٌ منكما سيّدا شبابِ أهل الجنة والشّهداء المضرّجونَ المقهورون في الأرض مِن بعدي والنجباءُ الزّهرُ الذين يطفئُ الله بهم الظلمَ ويُحيى بهم الحقَ ويُميتُ بهم الباطل؛ عِدَّتُهم عدّة أشهُر السنةِ، آخرُهم يصلّي عيسى بن مريم خلفه.","22/2/4/1",""],[2,4,"أخبرنا عبد الواحد بن عبد الله بن يونس الموصلي قال: حدثنا محمد بن جعفر قال: حدثنا أحمد بن محمد بن خالد، قال: حدثنا أبو هاشم داود بن القاسم الجعفري، عن أبي جعفر محمد بن علي عن آبائه قال: أقبل أمير المؤمنين ذات يوم ومعه الحسن بن علي وسلمان الفارسي، وأمير المؤمنين متكئ على يد سلمان  فدخل المسجد الحرام فجلس، إذ أقبل رجلٌ حسن الهيئة واللباس فسلّم على أمير المؤمنين وجلس بين يديه وقال: يا أمير المؤمنين أسألك عن ثلاث مسائل. قال أمير المؤمنين: سلني عمّا بدا لك. فقال الرجل: أخبرني عن الإنسان إذا نام أين تذهب روحه؟ عن الرجل كيف يذكر وينسى؟ وعن الرجل كيف يشبه ولده الأعمام والأخوال؟ فالتفت أمير المؤمنين إلى الحسن وقال: أجِبه يا أبا محمد. فقال أبو محمد للرجل: أمّا ما سألتَ عنه عن أمر الرجل إذا نام أين تذهب روحه، فإنّ روحَه معلّقة بالريح، والريح بالهواء معلقة إلى وقت ما يتحرك صاحبها باليقظة، فإنْ أذِن الله تعالى بردِّ تلك الروحِ على ذلك البدَن جذبت تلك الروح الريح، وجذبت الريح الهواء فاستكنت في بدن صاحبها، وإنْ لم يأذن الله بردِّ تلك الروح على ذلك البدن جذب الهواء الريح، وجذبت الريح الروح فلا ترد على صاحبها إلى وقت ما يبعث. وأما ما ذكرت من أمر الذّكر والنسيان، فإن قلبَ الانسانِ في حُقّ وعلى الحق طبق، فإذا هو صلّى على محمّد وآل محمد صلاةً تامّة انكشف ذلك الطبق عن ذلك الحق فأضاء القلبَ وذكّر الرجل ما نسيَ، وإن هو لم يصلِّ على محمد وآل محمد أو انتقصَ من الصلاة عليهم وأغضى عن بعضها انطبق ذلك الطبقُ على الحق فأظلم القلب وسهى الرجل ونسيَ ما كان يذكره. وأما ما ذكرتَ من أمر المولود يشبه الأعمامَ والأخوالَ، فإن الرجل إذا أتى أهله فجامعها بقلب ساكن وعروق هادئة وبدن غير مضطرب استكنت تلك النطفةُ في جوف الرحم فخرج المولود يشبه أباه وامه، وإن هو أتى زوجته بقلب غير ساكن وعروق غير هادئة وبدن مضطرب اضطربت تلك النطفة فوقعت في حال اضطرابها على بعض العروق؛ فإنْ وقعت على عِرقٍ من عروق الأعمام أشبهَ المولودُ أعمامه، وإن وقعت على عرق من عروق الأخوالِ أشبه الولدُ أخوالَه. فقال الرجل: أشهد أن لا إله إلا الله، ولم أزل أشهد بها، وأشهد أن محمداً رسول الله ، ولم أزل أشهد بها وأقولها، وأشهد أنك وصيُّ رسول الله والقائمُ بحجته، ولم أزل أشهد بها وأقولها. وأشار بيده إلى أمير المؤمنين وقال: أشهد أنّك وصيُّه والقائم بحجّته ولم أزلْ أقولها. وأشار بيده إلى الحسن وقال: وأشهد على الحسين بن عليّ أنه وصيّه والقائمُ بحجته ولم أزل أقولها. وأشهد على عليّ بن الحسين أنه القائم بأمر الحسين، وأشهد على محمّد بن على أنه القائم بأمر علي، وأشهد على جعفر أنه القائم بأمر محمد، وأشهد على موسى أنّه القائم بأمر جعفر، وأشهد على عليّ أنه وليُّ موسى، وأشهد على محمد أنه القائم بأمر علي، وأشهد على عليٍّ أنه القائم بأمر محمد، وأشهد على الحسن أنه القائم بأمر عليٍّ، وأشهد على رجلٍ من ولد الحسَين لا يُسمّى ولا يُكنى حتى يُظهرَ الله أمرَه، يملأُ الأرضَ عدلاً وقسطاً كما مُلئت جوراً وظُلماً، والسلام عليك يا أمير المؤمنين ورحمة الله وبركاته. ثم قام فمضى. فقال أمير المؤمنين للحسين: يا أبا محمد، اتّبِعه فانظر أين يقصد، قال: فخرجتُ في أثره فما كان إلا أن وضع رجلُه خارج المسجد حتى ما درَيت أين أخذ من الأرض، فرجعت إلى أمير المؤمنين فأعلمتُه، فقال: يا أبا محمد تعرفه؟ قلت: لا، واللهُ ورسوله وأمير المؤمنين أعلم، فقال: هو الخضر .","22/2/4/2",""],[3,4,"وأخبرنا محمد بن يعقوب الكليني، عن عدة من رجاله، عن أحمد بن أبي - عبد الله محمد بن خالد البرقي، عن الحسن بن العباس بن الحريش، عن أبي جعفر محمد ابن علي ، عن آبائه أن أمير المؤمنين قال لابن عباس: إنّ ليلةَ القدرِ في كلّ سنة وإنّه ينْزِلُ في تلك الليلة أمرُ السّنة وما قُضي فيها، ولذلك الأمرِ ولاةٌ بعدَ رسول الله . فقال ابن عباس: مَن هم يا أمير المؤمنين؟ فقال: أنا وأحدَ عشرَ مِن صلبى أئمةٌ محدّثون.","22/2/4/3",""],[4,4,"وأخبرنا محمد بن يعقوب، قال: حدثنا علي بن محمد، عن عبد الله بن محمد بن خالد قال: حدثني نصر بن محمد بن قابوس، عن منصور بن السندي، عن أبى داود المسترق، عن ثعلبة بن ميمون، عن مالك الجهني، عن الحارث بن المغيرة، عن الأصبغ بن نباتة، قال: أتيت أمير المؤمنين علياً ذات يوم فوجدته مفكراً ينكت في الأرض، فقلت: يا أمير المؤمنين تنكت في الأرض أرغبةً منك فيها؟ فقال: لا واللهِ، ما رغبتُ فيها ولا في الدّنيا ساعةً قط، ولكنّ فكري في مولودٍ يكون مِن ظهري هو المهدي الذي يملأها قسطاً وعدلاً كما مُلئتْ ظلماً وجوراً، تكون له حَيرةٌ وغيبة، يضلّ فيها أقوام ويهتدي فيها آخرون. فقلت: يا أمير المؤمنين فكم تكون تلك الحيرة والغيبة؟ فقال: سبتٌ من الدهر. فقلت: إنّ هذا لكائنٌ فقال: نعم! كما أنه مخلوق. قلت: أدرك ذلك الزمان؟ فقال: أنّى لك يا أصبغ بهذا الأمرِ؟ أولئك خيارُ هذه الأمّةِ مع أبرارِ هذه العترة. فقلت: ثمّ ما ذا يكون بعد ذلك ؟ قال: يفعلُ الله ما يشاءُ، فإنّ له إراداتٍ وغايات ونهايات.","22/2/4/4",""],[5,4,"وحدثني موسى بن محمد القمي أبو القاسم بشيراز سنة ثلاث عشرة وثلاثمائة، قال: حدثنا سعد بن عبد الله الأشعري، عن بكر بن صالح، عن عبد الرحمن بن سالم، عن أبى بصير، عن أبي عبد الله جعفر بن محمد قال: قال أبي لجابر بن عبد الله الأنصاري إنّ لي إليك حاجةً فمتى يخفُّ عليك أن أخلوَ بك فيها فأسألك عنها. قال جابر: في أيّ الأوقات أحببت. فخلا به أبي يوماً فقال له: يا جابرُ أخبرني عن اللّوح الذي رأيتَه بيدِ فاطمةَ بنت رسول الله وعمّا أخبرتْكَ أمّي فاطمةُ به ممّا في ذلك اللوح مكتوبٌ. فقال جابر: أشهِدُ اللهَ الذي لا شريك له إني دخلت على أمّك فاطمةَ في حياةِ رسول الله فهنّيتُها بولادة الحسين ورأيتُ في يدها لوحاً أخضرَ ظنَنتُ أنّه من زمرّد، ورأيتُ فيه كتابةً بيضاءَ شبيهةً بنورِ الشّمس، فقلتُ لها: بأبى أنتِ وأمّي ما هذا اللوحُ؟ فقالت: هذا لوحٌ أهداه الله إلى رسوله فيه اسمُ أبي واسمُ بَعلي واسمُ ولْدي واسمُ الأوصياء من ولدي، أعطانيه أبي ليبَشّرَني بذلك. قال جابر: فدفعَتهُ إليَّ أمُّك فاطمةُ فقرأتُه ونسختُه. فقال له أبي: يا جابرُ فهل لك أن تعرضَه عليَّ؟ قال: نعَم. فمَشى معه أبي إلى منْزله فأخرجَ أبي صحيفةٌ مِن رقّ فقال: يا جابرُ انظر في كتابك حتى أقرأ أنا عليك، فقرأه أبي عليه فما خالف حرفٌ حرفاً. فقال جابر: فأُشهد الله أني هكذا رأيتُه في اللوح مكتوبا: بسم الله الرحمن الرحيم، هذا كتاب من الله العزيز الحكيم لمحمّد نبيّه ونورِه وحجابِه وسفيرِه ودليله، نزل به الروح الأمين مِن عند رب العالمين، يا محمد عظّم أسمائي، واشكر نعمائي، ولا تجحد آلائي، إني أنا الله لا إله إلا أنا، قاصمُ الجبارين، ومديل المظلومين، وديّان يوم الدين، وإني أنا الله لا إله إلا أنا، فمَن رجا غير فضلي أو خاف غير عدلي عذبتُه عذاباً لا أعذبه أحداً من العالمين، فإيّاي فاعبد، وعليَّ فتوكّل. إني لم أبعث نبيّاً فأكملتُ أيامه وأنقضت مدته إلاّ جعلتُ له وصياً، وإني فضّلتُك على الأنبياء، وفضّلت وصيَّك على الأوصياء، وأكرمتك بشبلَيك وسبطَيك الحسن والحسين، فجعلت الحسن معدنَ علمي بعد انقضاء مدة أبيه، وجعلت حُسيناً معدنَ وحيي فأكرمتُه بالشهادة وختمتُ له بالسعادة، فهو أفضل مَن استُشهد فيَّ، وأرفعُ الشهداء درجة عندي، جعلت كلمتي التامةَ معه وحجتي البالغةَ عنده، بعترته أُثيب وأُعاقب. أوّلُهم عليٌّ سيد العابدين وزين أوليائي الماضين وابنه سميّ جده المحمود محمد الباقر لعلمي والمعدن لحكمتي، سيهلك المرتابون في جعفر، الرادُّ عليه كالراد عليَّ، حقَّ القولُ مني لأكرمنَّ مثوى جعفر ولأسرنَّهُ في أشياعه وأنصاره وأوليائه، أتيحت بعده فتنة عمياء حندس لأنَّ خيط فرضي لا ينقطع وحجتي لا تخفى وأن أوليائي بالكأس الأوفى يُسقَون، أبدال الأرض، ألا ومَن جحد واحداً منهم فقد جحدني نعمتي، ومَن غيَّر آيةً من كتابي فقد افترى عليَّ. ويلٌ للمفترين الجاحدين عند انقضاء مدة عبدي موسى وحبيبي وخيرتي، إن المكذبَّ به كالمكذِّب بكل أوليائي، وهو وليّي وناصري ومَن أضع عليه أعباءَ النبوة وأمتحنه بالاضطلاع بها، وبعده خليفتي عليُّ بن موسى الرضا يقتله عفريتٌ مستكبر، يُدفن في المدينة التي بناها العبد الصالح ذو القرنين، خيرُ خلقي يُدفن إلى جنب شرّ خَلقي، حقَّ القولُ مني لأ قرَّنَّ عينه بابنه محمدٍ وخليفته من بعده ووراث علمِه وهو معدن علمي وموضعُ سرّي وحجّتي على خلقي. جعلتُ الجنة مثواه وشفّعتُه في سبعين ألفاً مِن أهل بيته؛ كلُّهم قد استوجبوا النار، وأختمُ بالسعادةِ لابنه عليٍّ وليّي وناصري والشاهدِ في خلقي وأميني على وحيي، أُخرج منه الداعيَ إلى سبيلي والخازنَ لعِلمي الحسنَ، ثمَّ أكمِلُ ذلك بابنه رحمةً للعالمين، عليه كمالُ موسى وبهاءُ عيسى وصبرُ أيّوب، تُستذلّ أوليائي في زمانه، وتتهادى رؤوسُهم كما تتهادى رؤوسُ التّرك والديلم فيُقتلون ويحرّقون، ويكونون خائفين وجِلين مرعوبين، تُصبغ الأرض مِن دمائهم ويفشو الويلُ والرنّة في نسائهم، أولئك أوليائي حقّاً وحقَّ عليَّ أن أرفعَ عنهم كلَّ عمياءَ حندس وبهم أكشفُ الزلازل وأرفع عنهم الآصار والأغلال، اولئِك عليهم صلواتٌ من ربهم ورحمةٌ، واولئك هم المهتدون. قال أبو بصير: لو لم تسمع في دهرك إلاّ هذا الحديث الواحد لكفاك، فصُنه إلاّ عن أهله.","22/2/4/5",""],[6,4,"وأخبرنا أحمد بن محمد بن سعيد بن عقدة الكوفي، قال: حدثنا يحيى بن زكريا بن شيبان من كتابه سنة ثلاث وسبعين ومائتين، قال: حدثنا علي بن سيف بن عميرة، قال: حدثنا أبان بن عثمان، عن زرارة، عن أبي جعفر الباقر عن آبائه  قال: قال رسول الله: إنّ مِن أهل بيتي اثنا عشر محدّثاً. فقال له رجل يقال له عبد الله بن زيد وكان أخا عليِّ بن الحسين من الرضاعة: سبحان الله محدثاً؟ - كالمنكر لذلك - قال: فأقبل عليه أبو جعفر فقال له: أما والله إنّ ابن أمّك كان كذلك - يعني عليَّ بن الحسين -.","22/2/4/6",""],[7,4,"أخبرنا محمد بن همام، قال: حدثنا أبي وعبد الله بن جعفر الحميري، قالا: حدثنا أحمد بن هلال، قال حدثني محمد بن أبي عمير سنة أربع ومائتين، قال: حدثني سعيد بن غزوان، عن أبي بصير، عن أبي عبد الله، عن آبائه قال: قال رسول الله: إن الله إختارَ مِن كلّ شيء شيئاً؛ إختار من الأرض مكةَ، واختار من مكّة المسجدَ، واختار من المسجد الموضعَ الذي فيه الكعبةُ واختار من الأنعام إناثَها ومن الغنم الضأنَ واختار من الأيام يوم الجمعة، واختار من الشهور شهرَ رمضان، ومن الليالي ليلةَ القدر، واختار من الناس بني هاشم، واختارني وعليّاً من بني هاشم، واختار مني ومن عليٍّ الحسنَ والحسين ويكمّله اثني عشر إماماً من ولد الحسين، تاسعهم باطنُهم وهو ظاهرهم وهو أفضلهم وهو قائمهم.","22/2/4/7",""],[8,4,"ومن كتاب سليم بن قيس الهلالي ما رواه أحمد بن محمد بن سعيد بن عقدة، ومحمد بن همام بن سهيل، و عبد العزيز وعبد الواحد ابنا عبد الله بن يونس الموصلي - عن رجالهم - عن عبد الرزاق بن همام، عن معمر بن راشد: عن أبان بن أبي عياش، عن سليم بن قيس. وأخبرنا به من غير هذه الطرق هارون بن محمد قال: حدثني أحمد بن عبيد الله بن جعفر بن المعلى الهمداني، قال: حدثني أبو الحسن عمرو بن جامع بن عمرو بن حرب الكندي، قال: حدثنا عبد الله بن المبارك شيخ لنا كوفي ثقة، قال: حدثنا عبد الرزاق بن همام شيخنا، عن معمر، عن أبان بن أبي عياش، عن سليم بن قيس الهلالي. وذكر أبان أنه سمعه أيضا عن عمر بن أبي سلمة. قال معمر: وذكر أبو هارون العبدي أنه سمعه أيضا عن عمر بن أبي سلمة، عن سليم: أن معاوية لما دعا أبا الدرداء وأبا هريرة ونحن مع أمير المؤمنين علي بصفين فحمّلهما الرسالة إلى أمير المؤمنين علي وأدّياه إليه، قال: قد بلغتماني ما أرسلكما به معاوية فاستمعا مني وأبلغاه عني كما بلغتماني، قالا: نعم فأجابه علي الجواب بطوله حتى إذا انتهى إلى ذكر نصب رسول الله إيّاه بغدير خم بأمر الله تعالى قال: لما نزلَ عليه إِنَّمَا وَلِيُّكُمُ اللَّهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ رَاكِعُونَ قال الناس: يا رسول الله، أخاصةٌ لبعض المؤمنين أم عامّة لجميعهم؟ فأمر الله تعالى نبيه أن يعلّمهم ولايةَ مَن أمرَهم الله بولايته، وأن يفسر لهم من الولاية ما فسر لهم من صلاتهم وزكاتهم وصومهم وحجهم. قال علي فنصبني رسول الله بغدير خم وقال: إن اللهَ أرسلني برسالةٍ ضاق بها صدري وظننتُ أنّ الناس مكذبوني، فأوعدني لأبلّغنَّها أو ليُعذبني، قُم يا عليُّ. ثمّ نادى بأعلى صوته بعد أن أمر أن يُنادى بالصلاة جامعة، فصلى بهم الظهر، ثم قال: يا أيها الناس إنّ الله مولاي، وأنا مولى المؤمنين، وأنا أولى بهم منهم بأنفسهم، مَن كنتُ مولاه فعليٌّ مولاه، اللهم والِ مَن والاه وعادِ مَن عاداه. فقام إليه سلمان الفارسي فقال: يا رسول الله ولاءُ ماذا؟ فقال: مَن كُنت أولى به من نفسه فَعَليٌّ أولى به من نفسه. فأنزل الله الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ ۙ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ فقال له سلمان: يا رسول الله، أنَزَلَت هذه الآيات في عليٍّ خاصة؟ قال: بلْ فيه وفي أوصيائي إلى يوم القيامة. فقال: يا رسول الله، بيِّنْهم لي. قال: عليٌّ أخي ووصيّي ووارثي وخليفتي في أمّتي ووليُّ كلِّ مؤمن بعدي، وأحدَ عشرَ إماماً مِن ولده، أوَّلُهُم ابني حسن ثم ابني حُسين، ثمّ تسعةٌ من ولد الحسين واحداً بعد واحدٍ؛ هُم مع القرآنِ والقرآنُ معهم لا يفارقونه ولا يفارقهم حتى يردوا عليَّ الحوضَ. فقام اثنا عشر رجلاً من البدريين فقالوا: نشهد أنا سمعنا ذلك من رسول الله كما قلتَ يا أمير المؤمنين، سواء لم تزد ولم تنقص، وقال بقية البدريين الذين شهدوا مع عليٍّ صفين: قد حفظنا جُلَّ ما قلتَ، ولم نحفظ كله، وهؤلاء الإثنا عشر خيارُنا وأفاضلُنا. فقال عليٌّ: صدقتم ليس كل الناس يحفظ، وبعضهم أفضل من بعض. وقام من الاثني عشر أربعةٌ: أبو الهيثم بن التيهان، وأبو أيوب، وعمار، وخزيمة بن ثابت ذو الشهادتين فقالوا: نشهد أنا قد حفظنا قولَ رسول الله يومئذ، والله إنه لقائمٌ وعليّ قائمٌ إلى جانبه وهو يقول: يا أيُّها الناسُ، إنّ الله أمرني أنْ أُنصّبَ لكم إماماً يكون وصيّي فيكم وخليفتي في أهل بيتي وفي أمّتي من بعدي، والذي فرض الله طاعتَه على المؤمنين في كتابه وأمرَكم فيه بولايته، فقلتُ: يا ربّ خشيتُ طعنَ أهلِ النفاق وتكذيبَهم، فأوعَدني لأبلّغنّها أو لَيعاقبني. أيّها الناس إن الله أمرَكم في كتابه بالصّلاة، وقد بيَّنتُها لكم وسننتُها لكم، والزكاةَ والصوم، فبيّنتُهُما لكم وفسّرتُهما، وقد أمركم اللهُ في كتابه بالولاية، وإني أُشهِدكم أيّها الناس إنها خاصّةٌ لهذا ولأوصيائي من ولدي وولده، أوّلُهم ابني الحسن ثم الحسينُ ثم تسعةٌ من ولد الحسين، لا يفارقون الكتابَ حتى يردوا عليَّ الحوضَ. يا أيها الناس إني قد أعلمتُكم مفزعَكُم بعدي، وإمامَكم ووليَّكم وهاديَكم وهو عَليّ بنُ ابي طالب أخي، وهو فيكم بمنْزِلتي، فقلّدوه دينَكم وأطيعوه في جميع أمورِكم، فإنَّ عنده جميعَ ما علّمني الله ، أمرني اللهُ أن أعلّمَه إيّاه وأنْ أعلِمَكم أنّه عنده، فَسَلوه وتعلَّموا منه ومِن أوصيائه، ولا تُعلّموهم ولا تتقدَّموا عليهم، ولا تتخلَّفوا عنهُم فإنَّهم مع الحقِّ والحقُّ معهم، لا يُزايلُهم ولا يزايلونه. ثمّ قال عليٌّ صلوات الله عليه لأبي الدّرداء وأبي هريرة ومَن حوله: يا أيّها الناس، أتعلمونَ أنّ الله تبارك وتعالى أنزل في كتابه وَقَرْنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَىٰ ۖ وَأَقِمْنَ الصَّلَاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُ ۚ إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا فجمعني رسول الله وفاطمة والحسن والحسين في كساء ثم قال: اللهم هؤلاء أحبّتي وعترتي وثقلي وخاصّتي وأهلُ بيتي فأذهِبْ عنهم الرجسَ وطهّرهم تطهيراً. فقالت أمُّ سلمة: وأنا، فقال لها: وأنتِ إلى خير، إنمّا أنزلت فيَّ وفي أخي عليّ وفي ابنتى فاطمة وفي ابنيَّ الحسن والحسين وفي تسعة من ولد الحسين خاصة، ليس فيها معنا أحد غيرنا. فقام جلُّ الناس فقالوا: نشهد أن أمّ سلمة حدثتنا بذلك، فسألنا رسول الله فحدّثنا كما حدثتْنا أمُّ سلمة. فقال علي: ألستم تعلمون أنّ الله أنزل في سورة الحج يَا أَيُّهَا الَّذِينَ آمَنُوا ارْكَعُوا وَاسْجُدُوا وَاعْبُدُوا رَبَّكُمْ وَافْعَلُوا الْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ ۚ هُوَ اجْتَبَاكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ ۚ مِلَّةَ أَبِيكُمْ إِبْرَاهِيمَ ۚ هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِنْ قَبْلُ وَفِي هَٰذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ ۚ فَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَاعْتَصِمُوا بِاللَّهِ هُوَ مَوْلَاكُمْ ۖ فَنِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ فقام سلمان  عند نزولها فقال: يا رسول الله، مَن هؤلاء الذين أنتَ شهيد عليهم وهم شهداءُ على الناس الذين اجتباهم الله ولم يجعل عليهم في الدين من حرج ملّةَ أبيهم إبراهيم؟ فقال رسول الله: عنيَ اللهُ تعالى بذلك ثلاثة عشر إنساناً: أنا وأخي عليّاً وأحد عشر من ولده؟ فقالوا: اللهم نعم! قد سمعنا ذلك من رسول الله . فقال عليّ: أنشد كم بالله تعلمون أن رسول الله قام خطيباً ثم لم يخطبْ بعد ذلك، فقال: أيّها الناس إني قد تركتُ فيكم أمرَين لن تضلّوا ما إنْ تمسّكتم بهما؛ كتاب الله وأهل بيتي، فإنّ اللطيف الخبير قد أخبرني وعهِد إليّ أنهما لن يفترقا حتى يردا عليَّ الحوضَ؟ فقالوا: نعم اللهم، قد شهِدنا ذلك كلَّه من رسول الله ، فقام اثنا عشر رجلاً من الجماعة فقالوا: نشهد أن رسول الله حين خطب في اليوم الذي قُبض فيه قام عمر بن الخطاب شِبه المُغضب فقال: يا رسول الله، لكلّ أهل بيتك؟ فقال: لا، ولكن لأوصيائي منهم: عليٌّ أخي ووزيري ووارثي وخليفتي في أمّتي ووليُّ كل مؤمن بعدي، وهو أوّلهم وخيرهم، ثم وصيّه بعده ابني هذا -وأشار إلى الحسنِ- ثم وصيّه ابني هذا -وأشار إلى الحسين-، ثم وصيه ابني بعده سميُّ أخي، ثم وصيّه بعده سميّي، ثم سبعة من ولده واحد بعد واحد حتى يردوا عليَّ الحوضَ، شهداء الله في أرضه وحججه على خلقه، مَن أطاعهم أطاع الله، ومَن عصاهم عصى الله. فقام السبعون البدريّون ونحوهم من المهاجرين فقالوا: ذكّرتمونا ما كنّا نسِيناه! نشهد أنّا قد كنا سمِعنا ذلك من رسول الله . فانطلق أبو الدرداء وأبو هريرة فحدّثا معاوية بكل ما قال عليٌّ وما استشهد عليه وما ردَّ عليه الناسُ وشهِدوا به.","22/2/4/8",""],[9,4,"وبهذا الإسناد عن عبد الرزاق بن همام قال: حدثنا معمر بن راشد، عن أبان بن أبى عياش، عن سليم بن قيس الهلالي قال: لما أقبلنا من صفين مع أمير المؤمنين نزل قريباً من دَير نصرانيٍّ إذ خرج علينا شيخ من الدير جميل الوجهِ حسَنُ الهيئة والسمت معه كتاب، حتى أتى أميرَ المؤمنين فسلّم عليه ثم قال: إني من نسل حواريّ عيسى بن مريم وكان أفضلَ حواريّ عيسى - الإثني عشر - وأحبَّهم إليه وآثرَهم عنده، وأنّ عيسى أوصى إليه ودفع إليه كتبه وعلَّمَه حكمتَه، فلم يزل أهلُ هذا البيت على دينه متمسّكين بملّته لم يكفروا ولم يرتدّوا ولم يغيِّروا. وتلك الكتبُ عندي إملاءَ عيسى بن مريم وخطّ أبينا بيَده، فيها كلُّ شيء يفعل الناس من بعده، واسم ملك ملك من بعده منهم، وأنّ الله تبارك وتعالى يبعث رجلاً من العرب من ولد إسماعيل بن إبراهيمَ خليلِ الله من أرضٍ يقال لها: تهامة، مِن قرية يقال لها: مكّة، يقال له: أحمد، له اثنا عشر اسماً، وذَكَر مبعثَه ومولدَه ومهاجرتَه ومَن يقاتله ومن ينصُره ومن يعاديه، وما يعيش، وما تَلقى أمّتُه بعده إلى أن ينْزلَ عيسى بنُ مريم من السماءِ. وفي ذلك الكتب ثلاثة عشر رجلاً من ولد إسماعيل بن إبراهيم خليل الله مِن خيرِ خلق الله ومِن أحبّ خلق الله إليه، واللهُ وليٌّ لمن والاهم وعدو لمَن عاداهم، من أطاعهم اهتدى ومَن عصاهم ضلَّ، طاعتُهم لله طاعةٌ ومعصيتُهم لله معصية، مكتوبةٌ أسماؤهم وأنسابهم ونعوتهم وكَم يعيش كلُّ رجلٍ منهم واحد بعد واحد وكم رجل منهم يستتر بدينه ويكتُمه من قومه، ومَن الذي يظهرُ منهم وينقاد له الناسُ حتىّ ينْزلَ عيسى بن مريم على آخرِهم فيُصلّي عيسى خلفه ويقول: إنّكم لأئمَّةٌ لا ينبغى لأحدٍ أن يتقدَّمَكم، فيتقدّمُ فيُصلي بالناس وعيسى خلفه في الصف. أولُهم وخيرُهم وأفضلهم - وله مثلُ أجورِهم وأجورِ مَن أطاعهم واهتدى بهم - رسول الله: اسمه محمّد وعبدُ الله ويۤس والفتّاح والخاتم والحاشر والعاقب والماحي والقائد ونبيُّ الله وصفيُّ الله وحبيب الله، وأنّه يُذكر إذا ذكر، مِن أكرمِ خلقِ الله على الله وأحبّهم إلى الله، لم يخلقِ الله ملَكاً مكرّماً ولا نبيّاً مرسَلاً مِن آدم فمن سِواه خيراً عند الله ولا أحبَّ إلى الله منه، يُقعده يوم القيامة على عرشه، ويشفّعُه في كلّ مَن يشفع فيه. باسمه جرى القلمُ في اللوح المحفوظ: محمّدٌ رسولُ الله، وبِصاحب اللّواء يوم الحشر الأكبرِ أخيه ووصيه ووزيره وخليفته في أمّته. ومن أحب خلق الله إلى الله بعده عليّ ابن عمّه لأمّه وأبيه، ووليّ كل مؤمن بعده، ثم أحد عشر رجلاً من ولد محمّد وولده، أوّلُهم يسمّى باسم ابنَي هارون؛ شبر وشبير، وتسعة من ولد أصغرِهما واحد بعد واحد، آخرهم الذي يصلّي عيسى بنُ مريم خلفه… وذكر باقي الحديث بطوله.","22/2/4/9",""],[10,4,"وبهذا الإسناد عن عبد الرزاق، عن معمر، عن أبان، عن سليم بن قيس الهلالي قال: قلت لعلي: إنّي سمعتُ من سلمان ومن المقداد ومن أبي ذرّ أشياء من تفسير القرآن ومن الرواية عن رسول الله غيرَ ما في أيدي الناس ثم سمعتُ منك تصديقاً لما سمعت منهم، ورأيتُ في أيدى الناس أشياء كثيرةً من تفسير القرآن ومن الأحاديثِ عن رسول الله يخالفونهم فيها ويزعُمون أن ذلك كان كلّه باطلاً، أفَتُرى أنّهم يُكذّبون على رسول الله متعمّدين ويفسّرون القرآن بآرائهم؟ قال: فأقبلَ عليٌّ وقال: قد سألتَ فافهمِ الجوابَ: إنّ في أيدي الناس حقاً وباطلاً وصِدقاً وكذباً وناسخاً ومنسوخاً وخاصّاً وعامّاً ومُحكَماً ومتَشابهاً وحِفظاً ووَهماً، وقد كُذب على رسول الله على عهده حتى قام خطيباً فقال: أيّها الناس، قد كثُرتْ عليَّ الكذابةُ، فمَن كذب عليَّ متعمّداً فلْيتبوَّءْ مقعدَه من النارِ. ثم كُذبَ عليه مِن بعده. وإنما أتاك بالحديث أربعةٌ ليس لهم خامس: رجلٌ منافق مظهر للإيمان متصنّع للإسلام باللسان، لا يتأثّم ولا يتحرّج أن يكذبَ على رسول الله متعمداً، فلو علِم الناسُ أنه منافق كاذب ما قبِلوا منه ولم يصدقوه، ولكنّهم قالوا: هذا قد صحبَ رسولَ الله وقد رآه وسمع منه، وأخذوا عنه وهُم لا يعرفون حاله وقد أخبرك الله عن المنافقين بما أخبرك ووصفهم بما وصفهم، فقال: وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِنْ يَقُولُوا تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌ مُسَنَّدَةٌ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ الْعَدُوُّ فَاحْذَرْهُمْ ۚ قَاتَلَهُمُ اللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ ﴾ ثم بقُوا بعد رسول الله وتقرّبوا إلى أئمة الضلال والدعاة إلى النار بالزور والكذب والبهتان حتى ولَّوهُم الأعمال وحملوهم على رقاب الناس وأكلوا بهم الدنيا، وإنما الناس مع الملوك والدنيا إلاّ مَن عصم اللهُ ، فهذا أحد الأربعة. ورجلٌ سمع من رسول الله شيئاً ولم يحفظْه على وجهه فتوهّم فيه ولم يتعمّد كذباً فهو في يديه ويقول به ويعمل به ويرويه ويقول: أنا سمعته من رسول الله . فلو علِم المسلمون أنّه وهم فيه لم يقبلوا منه، ولو علم هو أنه وهمٌ لرفضه. ورجل ثالث سمع من رسول الله شيئاً أمرَ به ثم نهى عنه وهو لا يعلم أو سمعه ينهى عن شيء ثم أمرَ به وهو لا يعلم، فحفظ المنسوخَ ولم يحفظ الناسخَ، ولو علم أنه منسوخ لرفضه، ولو علم الناس إذا سمعوا منه أنه منسوخ لرفضوه. ورجل رابعٌ لم يكذب على الله ولا على رسوله بُغضاً للكذب وخوفاً من الله وتعظيماً لرسول الله ولم يسْهُ، بل حفظَ الحديثَ على وجهه فجاء به كما سمعه لم يزِد فيه ولم يُنقصْ منه، وحفظ الناسخَ والمنسوخ، فعمل بالناسخ ورفض المنسوخ، وإن أمْرَ رسول الله ونهيَه مثلُ القرآن ناسخ ومنسوخ وعام وخاص ومحكم ومتشابه، قد كان يكون مِن رسول الله الكلام له وجهان: كلام عام وكلام خاص مثل القرآن، قال الله في كتابه مَا أَفَاءَ اللَّهُ عَلَىٰ رَسُولِهِ مِنْ أَهْلِ الْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنْكُمْ ۚ وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا ۚ وَاتَّقُوا اللَّهَ ۖ إِنَّ اللَّهَ شَدِيدُ الْعِقَابِ يسمعه مَن لا يعرف ولم يدرِ ما عنيَ الله ولا ما عنيَ به رسولُ الله . وليس كلُّ أصحابِ رسول الله كان يسأله عن الشيءَ فيفهم، وكان منهم مَن يسأله ولا يستفهم حتى أنهم كانوا ليُحبّون أن يجيء الأعرابيُّ أو الطاري فيسأل رسولَ الله حتى يسمعوا، وقد كنتُ أنا أدخل على رسولِ الله كل يوم دخلة وكل ليلة دخلة فيخليني فيها خلوةً أدور معه حيث دارَ وقد علِم أصحابُ رسول الله أنه لم يكن يصنع ذلك بأحدٍ من الناس غيري، فربما كان ذلك في بيتي، يأتيني رسول الله أكثر من ذلك في بيتي، وكنتُ إذا دخلت عليه بعضَ منازله أخلاني وأقام عنّي نساءَه، فلا يبقى عنده غيري. وإذا أتاني للخلوةِ معي في منْزلي لم تقُم عني فاطمةُ ولا أحدٌ من ابنيَّ وكنتُ إذا ابتدأتُ أجابني وإذا سكتُّ عنه وفنِيت مسائلي ابتدأني ودعا الله أن يحفظني ويفهمني، فما نسيتُ شيئاً قط مذ دعا لي، وإني قلتُ لرسول الله: يا نبيَّ الله إنك منذ دعوتَ الله لي بما دعوتَ لم أنْسَ ممّا علمتني شيئاً وما تُمليه عليَّ فلِم تأمرني بكتبه أتتخوف عليّ النسيان؟ فقال: يا أخي لست أتخوّف عليك النسيانَ ولا الجهل، وقد أخبرني الله أنه قد استجاب لي فيك وفي شُركائِك الذين يكونون مِن بعدك، وإنما تكتبه لهم. قلتُ: يا رسول الله ومَن شركائي؟ قال: الذين قرنهم الله بنفسه وبي، فقال: يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ ۖ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا {59} فإنْ خِفتم تنازعاً في شيء فأرجِعوه إلى الله وإلى الرسول وإلى أولي الأمر منكم، فقلت: يا نبي الله ومَن هم؟ قال: الأوصياءُ إلى أن يرِدوا عليَّ حوضي، كلُّهم هادٍ مُهتدٍ، لا يضرُّهم خذلانُ مَن خذلهم، هم مع القرآن والقرآنُ معهم لا يفارقونه ولا يفارقهم، بهم تُنصر أمّتي ويُمطرون، ويُدفع عنهم بعظائم دعواتهم. قلتُ: يا رسول الله سمِّهم لي، فقال: ابني هذا - ووضع يدَه على رأس الحسن - ثم ابني هذا - ووضع يدَه على رأس الحسين -، ثم ابنٌ له على اسمِك يا عليّ، ثم ابنٌ له محمّد بن علي. ثمّ أقبل على الحسين وقال: سيولد محمّد بن علي في حياتك فأقرِئه مني السلام، ثم تكمله اثني عشر إماماً. قلت: يا نبيّ الله سمِّهم لي، فسمّاهم رجلاً رجلاً. منهم، واللهِ يا أخا بني هلال، مهديُّ هذه الأمّةِ الذي يملأُ الأرضَ قسطاً وعدلاً كما مُلئتْ ظلماً وجوراً.","22/2/4/10",""],[11,4,"وبإسناده، عن عبد الرزاق، قال: حدثنا معمر بن راشد، عن أبان بن أبي عياش، عن سليم بن قيس: أنّ علياً قال لطلحة في حديث طويل عند ذِكر تفاخر المهاجرين والأنصار بمناقبهم وفضائلهم: يا طلحة، أليس قد شهدتَ رسولَ الله حين دعانا بالكتف ليكتبَ فيها ما لا تضِلّ الأمّةُ بعده ولا تختلف، فقال صاحبك ما قال \"إنّ رسول الله يهجرُ\" فغضبَ رسول الله وتركها؟ قال: بلى قد شهدته. قال: فإنكم لمّا خرجتُم أخبرني رسولُ الله بالذي أراد أن يكتبَ فيها ويُشهدَ عليه العامّة، وأن جبرئيل أخبره بأن الله تعالى قد علِم أن الأمةَ ستختلف وتفترق، ثم دعا بصحيفة فأملى عليَّ ما أراد أن يكتب في الكتف، وأشهَدَ على ذلك ثلاثةَ رهط: سلمان الفارسي وأبا ذر والمقداد، وسمّى مَن يكون مِن أئمة الهدى الذين أمر المؤمنين بطاعتهم إلى يوم القيامة فسمّاني أوّلَهم، ثم ابني هذا حسن، ثم ابني هذا حسين، ثم تسعة من ولد ابني هذا حسين، كذلك يا أبا ذر وأنت يا مقداد؟ قالا: نشهد بذلك على رسول الله . فقال طلحة: والله لقد سمعتُ من رسول الله يقول لأبي ذر: ما أقلّتِ الغبراءُ ولا أظلَّتِ الخضراءُ ذا لهجة أصدقَ ولا أبرَّ من أبي ذرٍ. أشهد أنهما لم يشهدا إلاّ بالحقّ، وأنت أصدقُ وأبرُّ عندي منهما.","22/2/4/11",""],[12,4,"وبإسناده، عن عبد الرزاق بن همام، عن معمر بن راشد، عن أبان ابن أبي عياش، عن سليم بن قيس قال: قال عليّ بن أبي طالب: مررتُ يوماً برجل - سمّاه لي - فقال: ما مثلُ محمّد إلاّ كمثلِ نخلةٍ نبتَتْ في كباة. فأتيتُ رسولَ الله فذكرت ذلك له، فغضب رسول الله وخرج مغضباً وأتى المنبر ففرغت الأنصارُ إلى السلاح لما رأوا من غضبِ رسول الله ، قال: فما بالُ أقوام يعيروني بقرابتي وقد سمعوني أقول فيهم ما أقول من تفضيل الله تعالى إيّاهم وما اختصّهم به من إذهاب الرجس عنهم وتطهير الله إياهم؟ وقد سمعوا ما قلتُه في فضل أهل بيتي ووصيّي وما أكرمه الله به وخصّه وفضّله من سِبقه إلى الاسلام وبلائه فيه وقرابته مني وأنه مني بمنْزلة هارون من موسى، ثم يمر به فزعم أن مثلي في أهل بيتي كمثل نخلة نبتت في أصل حُشٍّ؟ ألا إن الله خلق خلقه وفرّقهم فرقتين فجعلني في خير الفرقتين، وفرّق الفرقة ثلاث شعب، فجعلني في خيرها شعباٍ وخيرها قبيلة، ثم جعلهم بيوتاً، فجعلني في خيرها بيتاً حتى خلصت في أهل بيتي وعترتي وبني أبي أنا وأخي علي بن أبي طالب، نظر الله سبحانه إلى أهل الأرض نظرةً واختارني منهم، ثمّ نظر نظرة فاختار علياً أخي ووزيري ووارثي ووصيي وخليفتي في أمتي ووليُّ كلّ مؤمن بعدي، مَن والاه فقد والى الله ومَن عاداه فقد عادى الله ومن أحبّه أحبه اللهُ ومن أبغضه أبغضه الله، لا يحبه إلاّ كل مؤمن ولا يبغضه إلا كلّ كافر، هو زرّ الأرض بعدي وسكنها وهو كلمة التقوى وعروة الله الوثقى، يُرِيدُونَ أَنْ يُطْفِئُوا نُورَ اللَّهِ بِأَفْوَاهِهِمْ وَيَأْبَى اللَّهُ إِلَّا أَنْ يُتِمَّ نُورَهُ وَلَوْ كَرِهَ الْكَافِرُونَ {32} يريد أعداءُ الله أن يطفِئوا نور أخي ويأبى الله إلاّ أن يتمّ نوره. أيها الناس ليبلغ مقالتي شاهدُكم غائبَكم، اللهم أشهد عليهم، ثم إنّ الله نظر نظرة ثالثة فاختار أهل بيتي من بعدي، وهم خيار أمتي: أحد عشر إماماً بعد أخي واحداً بعد واحد، كلّما هلك واحد قام واحد، مثلُهم في أمتي كمثل نجوم السماء، كلّما غاب نجم طلع نجم، إنهم أئمة هداة مهديون لا يضرهم كيدُ مَن كادهم ولا خذلانُ من خذلهم، بل يضر الله بذلك من كادهم وخذلهم، هم حجج الله في أرضه وشهداؤه على خلقه، مَن أطاعهم أطاع الله، ومن عصاهم عصى الله، هم مع القرآنِ والقرآنُ معهم لا يفارقهم ولا يفارقونه حتى يردوا عليَّ حوضي، وأولُ الأئمة أخي علي خيرهم ثم ابني حسن، ثم ابني حسين، ثم تسعة من ولد الحسين - وذكر الحديث بطوله.","22/2/4/12",""],[13,4,"أخبرنا عبد الواحد بن عبد الله بن يونس الموصلي، قال: حدثنا أحمد بن محمد بن رباح الزهري، قال: حدثنا أحمد بن علي الحميري، قال: حدثنا الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن المفضل بن عمر، قال: قلت لأبي عبد الله: ما معنى قول الله: بَلْ كَذَّبُوا بِالسَّاعَةِ ۖ وَأَعْتَدْنَا لِمَنْ كَذَّبَ بِالسَّاعَةِ سَعِيرًا {11} قال لي: إن الله خلق السنة اثنَي عشر شهراً وجعل الليل اثنتي عشرة ساعة وجعل النّهار اثنتي عشرة ساعة، ومنّا اثنا عشر محدّثاً، وكان أمير المؤمنين من تلك الساعات.","22/2/4/13",""],[14,4,"وبه عن عبد الكريم بن عمرو، عن ثابت بن شريح، عن أبي بصير، قال: سمعت أبا جعفر محمد بن علي الباقر يقول: منّا اثنا عشر محدثاً.","22/2/4/14",""],[15,4,"أخبرنا عبد الواحد بن عبد الله، قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا محمد بن الحسين بن أبى الخطاب، عن عمر بن أبان الكلبي عن ابن - سنان، عن أبي السائب قال: قال أبو عبد الله جعفر بن محمد: الليلُ اثنتا عشرة ساعة، والنهار اثنتا عشرة ساعة، والشهور اثنا عشر شهراً، والأئمة اثنا عشر إماماً، والنقباء اثنا عشر نقيباً، وإن علياً ساعة من اثنتي عشرة ساعة، وهو قول الله: بَلْ كَذَّبُوا بِالسَّاعَةِ ۖ وَأَعْتَدْنَا لِمَنْ كَذَّبَ بِالسَّاعَةِ سَعِيرًا","22/2/4/15",""],[16,4,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار بقم، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، قال: حدثنا إبراهيم بن محمد بن يوسف، قال: حدثنا محمد بن عيسى، عن عبد الرزاق، عن زيد الشحام، عن أبي عبد الله ، وقال محمد بن حسان الرازي: وحدثنا به محمد بن علي الكوفي، عن محمد بن سنان، عن زيد الشحام قال: قلت لأبي عبد الله: أيهما أفضل الحسن أو الحسين؟ قال: إنّ فضلَ أوّلنا يلحق فضل آخرنا، وفضلُ آخرنا يلحق فضل أوّلنا فكلٌّ له فضل. قال: قلت له: جعلت فداك وسّع عليّ في الجواب، فإني والله ما أسألك إلاّ مرتاداً، فقال: نحن مِن شجرة برأنا اللهُ من طينة واحدة، فضلُنا من الله وعلمُنا من عند الله، ونحن أمناءُ الله على خلقه والدعاةُ إلى دينه والحجابُ فيما بينه وبين خلقه، أزيدك يا زيد؟ قلت: نعم، فقال: خلقُنا واحد وعِلمنا واحد وفضلُنا واحد، وكلنا واحد عند الله . فقلت: أخبرني بعدّتِكم، فقال: نحن اثنا عشر - هكذا - حول عرشِ ربّنا جلّ وعزَّ في مبتدء خلقِنا، أوّلنا محمد، وأوسطُنا محمد، وآخرنا محمد.","22/2/4/16",""],[17,4,"أخبرنا علي بن الحسين، قال: حدثنا محمد بن يحيى العطار قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن إبراهيم بن محمد بن يوسف، عن محمد بن عيسى، عن عبد الرزاق، عن محمد بن سنان، عن فضيل الرسان، عن أبي حمزة الثمالي قال: كنت عند أبي جعفر محمد بن علي الباقر ذات يوم فلما تفرق من كان عنده قال لي: يا أبا حمزةَ، مَن المحتوم الذي لا تبديل له عند الله قيام قائمنا، فمَن شكّ فيما أقول لقيَ اللهَ سبحانه وهو به كافر وله جاحد. ثم قال: بأبي وأمي المُسمّى باسمي والمكنّى بكُنيتي، السابعُ مِن بعدي، بأبي مَن يملأُ الأرضَ عدلاً وقِسطاً كما مُلئت ظلماً وجوراً. ثم قال: يا أبا حمزة، مَن أدركه فلمْ يسلّمْ له فما سلم لمحمد وعليّ ، وقد حرّم الله عليه الجنةَ ومأواه النارُ وبئس مثوى الظالمين. إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ مِنْهَا أَرْبَعَةٌ حُرُمٌ ۚ ذَٰلِكَ الدِّينُ الْقَيِّمُ ۚ فَلَا تَظْلِمُوا فِيهِنَّ أَنْفُسَكُمْ ۚ وَقَاتِلُوا الْمُشْرِكِينَ كَافَّةً كَمَا يُقَاتِلُونَكُمْ كَافَّةً ۚ وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ","22/2/4/17",""],[18,4,"أخبرنا سلامة بن محمد قال: حدثنا أبو الحسن علي بن عمر المعروف بالحاجي، قال: حدثنا حمزة بن القاسم العلوي العباسي الرازي، قال: حدثنا جعفر بن محمد الحسني، قال: حدثنا عبيد بن كثير، قال: حدثنا أبو أحمد بن موسى الأسدي، عن داود بن كثير الرقي، قال: دخلتُ على أبي عبد الله جعفر بن محمد بالمدينة، فقال لي: ما الذي أبطأ بك يا داود عنّا؟ فقلت: حاجة عرضت بالكوفة. فقال: مَن خلّفت بها؟ فقلت: جُعلتُ فداك، خلفتُ بها عمّك زيداً تركتُه راكباً على فرس متقلّداً سيفاً ينادي بأعلى صوته: سلوني سلوني قبل أن تفقدوني، فبين جوانحي علمٌ جمٌّ قد عرفتُ الناسخَ من المنسوخ والمثانيَ والقرآنَ العظيم، وإني العلم بين الله وبينكم. فقال لي: يا داود، لقد ذهبتْ بك المذاهبُ. ثم نادى يا سماعة بن مهران ايتني بسلّة الرطب، فأتاه بسلة فيها رطب، فتناول منها رطبة فأكلها، واستخرج النواة مِن فيه فغرسها في الأرض، ففلقت وأنبتت وأطلعت وأغدقت، فضرب بيده إلى بسرة من عذق فشقّها واستخرج منها رقاً أبيض ففضّه ودفعه إلي، وقال: اقرأه. فقرأته وإذا فيه سطران؛ السطر الأول \"لا إله إلاّ الله، محمد رسول الله\" والثاني أمير المؤمنين عليّ بن أبي طالب، الحسن بن علي، الحسين بن علي، علي بن الحسين، محمد بن علي، جعفر بن محمد، موسى بن جعفر، علي بن موسى، محمد بن علي، علي بن محمد، الحسن بن علي، الخلف الحجة. ثم قال: يا داود أتدري متى كُتب هذا في هذا؟ قلت: الله أعلم ورسوله وأنتم. فقال: قبل أن يخلق الله آدمَ بألفَي عام.","22/2/4/18",""],[19,4,"أخبرنا سلامة بن محمد قال: أخبرنا الحسن بن علي بن مهزيار، قال: حدثنا أحمد بن محمد السياري، عن أحمد بن هلال قال: وحدثنا علي بن محمد بن عبيد الله الخبائي، عن أحمد بن هلال، عن أمية بن ميمون الشعيري عن زياد القندي قال: سمعت أبا إبراهيم موسى بن جعفر بن محمد  يقول: إن الله خلق بيتاً من نور جعل قوائمه أربعة أركان كتب عليها أربعة أسماء: \"تبارك وسبحان والحمد والله\" ثم خلق من الأربعة أربعة، ومن الأربعة أربعة. ثم قال: إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ","22/2/4/19",""],[20,4,"أخبرنا علي بن الحسين، عن محمد بن يحيى، عن محمد بن حسان الرازي، عن محمد بن علي، عن محمد بن سنان، عن داود بن كثير الرقي قال: قلت لأبي عبد الله جعفر بن محمد: جعلت فداك أخبرني عن قول الله وَالسَّابِقُونَ السَّابِقُونَ أُولَٰئِكَ الْمُقَرَّبُونَ قال: نطقَ الله بها يومَ ذرأَ الخلقَ في الميثاق قبل أن يخلُق الخلقَ بألفي عام. فقلت: فسِّرْ لي ذلك، قال: إنّ الله لما أراد أن يخلق الخلق خلقَهم من طين، ورفع لهم ناراً فقال: ادخلوها، فكان أولَ مَن دخلها محمدٌ رسول الله وأمير المؤمنين والحسن والحسين وتسعةٌ من الأئمة إمام بعد إمام، ثم أتبعهم بشيعتهم، فهم والله السابقون.","22/2/4/20",""],[21,4,"حدثنا أبو علي أحمد بن محمد بن يعقوب بن عمار الكوفي قال: حدثني أبي، قال: حدثنا القاسم بن هشام اللؤلؤي، عن الحسن بن محبوب، عن إبراهيم الكرخي قال: دخلت على أبي عبد الله جعفر بن محمد فإني عنده جالس إذ دخل أبو الحسن موسى وهو غلام فقُمت إليه فقبّلتُه وجلستُ، فقال لي أبو عبد الله: يا إبراهيم أما إنه صاحبُك من بعدي، أما ليهلكنّ فيه أقوام ويسعد آخرون، فلعن الله قاتله وضاعف على روحه العذاب، أما ليخرجن الله مِن صُلبه خيرَ أهل الأرض في زمانه، سميَّ جدّه ووارث علمه وأحكامه و قضاياه ومعدن الإمامة ورأس الحكمة، يقتله جبار بني فلان بعد عجائب طريفة حسداً له، ولكنّ الله بالغُ أمره ولو كره المشركون، يُخرج الله من صلبه تكملةَ اثني عشر إماماً مهدياً اختصهم الله بكرامته وأحلهم دار قدسه، المنتظِر للثاني عشر الشاهر سيفه بين يديه كان كالشاهر سيفَه بين يدي رسول الله يذب عنه. ودخل رجل من موالي بني أمية فانقطع الكلام، فعدت إلى أبي عبد الله إحدى عشرة مرة أريد أن يستتمّ الكلام فما قدرت على ذلك، فلما كان قابل السنة الثانية دخلت عليه وهو جالس، فقال: يا إبراهيم، هو المفرّج للكرب عن شيعته بعد ضنكٍ شديد وبلاء طويل وجور وخوف، فطوبى لمَن أدرك ذلك الزمان. حسبُك يا إبراهيم. قال: فما رجعت بشيء أسرَّ إليَّ من هذا لقلبي ولا أقرَّ لعيني.","22/2/4/21",""],[22,4,"أخبرنا أحمد بن محمد بن يعقوب قال: حدثنا أبو عبد الله الحسين بن محمد قراءة عليه، قال: حدثنا محمد بن أبي قيس، عن جعفر الرماني، عن محمد بن أبي القاسم - ابن أخت خالد بن مخلد القطواني - قال: حدثنا عبد الوهاب الثقفي، عن جعفر بن محمد عن أبيه محمد بن علي أنه نظر إلى حمران فبكى، ثم قال: يا حمران، عجباً للناس كيف غفلوا أم نسوا أم تناسوا، فنسوا قول رسول الله حين مرض، فأتاه الناس يعودونه ويسلمون عليه حتى إذا غصّ بأهله البيتُ جاء عليٌّ فسلّم ولم يستطع أن يتخطّاهم إليه ولم يوسعوا له، فلما رأى رسول الله ذلك رفع مخدّته وقال: إليَّ يا عليُّ. فلما رأى الناس ذلك زحم بعضهم بعضاً وأفرجوا حتى تخطاهم وأجلسه رسول الله إلى جانبه، ثم قال: يا أيها الناس هذا أنتم تفعلون بأهل بيتي في حياتي ما أرى، فكيف بعد وفاتي؟ واللهِ لا تقربو من أهل بيتي قربة إلاّ قربتم من الله منْزلة، ولا تباعدون عنهم خطوة وتعرضون عنهم إلاّ أعرض الله عنكم. ثم قال: أيها الناس اسمعوا ما أقول لكم، ألا إنّ الرضا والرضوانَ والجنة لمَن أحب علياً وتولاّه وائتمَّ به وبفضله وبأوصيائي بعده، وحقّ على ربي أن يستجيب لي فيهم، إنهم اثنا عشر وصياً، ومن تبعه فانه مني، إني من إبراهيم، وإبراهيمُ مني، وديني دينه ودينه ديني، ونسبته نسبتي، ونسبتي نسبته وفضلي فضله، وأنا أفضل منه، ولا فخر، يصدق قولي قول ربي ذُرِّيَّةً بَعْضُهَا مِنْ بَعْضٍ ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ","22/2/4/22",""],[23,4,"أخبرنا محمد بن همام، قال: حدثنا أبو علي الحسن بن علي بن عيسى القوهستاني قال: حدثنا بدر بن إسحاق بن بدر الأنماطي في سوق الليل بمكة - وكان شيخاً نفيساً من إخواننا الفاضلين، وكان من أهل قزوين - في سنة خمس وستين ومائتين قال: حدثني أبي إسحاق بن بدر، قال حدثني جدي بدر بن عيسى، قال سألت أبي عيسى بن موسى - وكان رجلا مهيبا - فقلت له: مَن أدركتَ من التابعين؟ فقال: ما أدري ما تقول لي ولكني كنت بالكوفة، فسمعت شيخاً في جامعها يتحدث عن عبد خير، قال: سمعت أمير المؤمنين علي بن أبي طالب صلوات الله عليه يقول: قال لي رسول الله: يا عليُّ، الأئمة الراشدون المهتدون المعصومون من ولدك أحدَ عشر إماماً وأنت أولهم، وآخرُهم اسمه اسمي، يخرج فيملأُ الأرضَ عدلاً كما مُلئت جوراً وظُلماً، يأتيه الرجل والمال كدس، فيقول: يا مهدي أعطني، فيقول: خذ.","22/2/4/23",""],[24,4,"حدثنا أبو الحارث عبد الله بن عبد المك بن سهل الطبراني، قال: حدثنا محمد بن المثنى البغدادي، قال: حدثنا محمد بن إسماعيل الرقي، قال: حدثنا موسى بن عيسى بن عبد الرحمن، قال: حدثنا هشام بن عبد الله الدستوائي، قال: حدثنا علي بن محمد، عن عمرو بن شمر، عن جابر بن يزيد الجعفي، عن محمد بن علي الباقر ، عن سالم بن عبد الله بن عمر، عن أبيه عبد الله بن عمر بن الخطاب، قال: قال رسول الله: إنّ الله أوحى إليَّ ليلة أسرِي بي: يا محمد، مَن خلّفتَ في الأرض في أمّتك؟ - وهو أعلم بذلك - قلت: يا ربِّ أخي. قال: يا محمّد، عليُّ بن أبي طالب؟ قلت: نعم يا رب. قال: يا محمّد إني اطّلعتُ إلى الأرض اطلاعةً فاخترتك منها فلا أُذكَر حتى تُذكر معي؛ فأنا المحمود وأنت محمد، ثم إني اطّلعت إلى الأرض اطلاعة اخرى فاخترت منها عليّ بن أبي طالب فجعلتُه وصيّك؛ فأنت سيد الأنبياء، وعليٌّ سيد الأوصياء ثم شققتُ له اسماً من أسمائي، فأنا الأعلى وهو عليّ. يا محمد إني خلقتُ علياً وفاطمةَ والحسنَ والحسينَ والأئمّة من نور واحد، ثمّ عرضتُ ولايتهم على الملائكة، فمَن قبِلها كان من المقربين، ومن جحدها كان من الكافرين. يا محمد، لو أن عبداً من عبادي عبدني حتى ينقطع، ثم لقيني جاحداً لولايتهم أدخلتُه ناري. ثم قال: يا محمّد، أتحبُّ أن تراهم؟ فقلت: نعم. فقال: تقدَّم أمامَك، فتقدمت أمامي فإذا عليّ بن أبي طالب، والحسن، والحسين، وعلي بن الحسين، ومحمد بن علي، وجعفر بن محمد، وموسى بن جعفر، وعلي بن موسى، ومحمد بن علي، وعلي بن محمد، والحسن بن علي، والحجة القائم كأنّه الكوكب الدريّ في وسطهم. فقلت: يا رب مَن هؤلاء؟ قال: هؤلاء الأئمّة، وهذا القائم، محلّل حلالي ومحرِّم حرامي، وينتقم من أعدائي، يا محمد، أحبِبه فإني أحبّه وأحبُّ مَن يحبه.","22/2/4/24",""],[25,4,"وأخبرنا محمد بن يعقوب الكليني، قال: حدثنا علي بن إبراهيم، عن أبيه، عن ابن أبي عمير، عن سعيد بن غزوان، عن أبى بصير، عن أبي جعفر الباقر قال: يكون تسعةُ أئمة بعد الحسين بن علي، تاسعُهم قائمُهم.","22/2/4/25",""],[26,4,"أخبرنا محمد بن يعقوب، عن علي بن محمد، عن سهل بن زياد، عن محمد بن الحسين بن شمون، عن عبد الله بن عبد الرحمن الأصمّ، عن كرام قال: حلفتُ فيما بيني وبين نفسي ألاّ آكلَ طعاماً بنهار أبداً حتى يقومَ قائمُ آل محمد، فدخلتُ على أبي عبد الله فقلت له: رجل من شيعتك جعل لله عليه ألاّ يأكل طعاماً بنهار أبداً حتى يقوم قائم آل محمد. فقال: صُم يا كرام، ولا تصُم العيدَين ولا ثلاثةَ أيام التشريق، ولا إذا كنتَ مسافراً، فإن الحسين لما قُتل عجّت السماوات والأرض ومَن عليهما والملائكة، فقالوا: يا ربّنا أتأذن لنا في هلاك الخلق حتى نجذّهم من جديد الأرض بما استحلوا حرمتك وقتلوا صفوتك؟ فأوحى الله إليهم: يا ملائكتي ويا سمائي ويا أرضي اسكنوا. ثم كشف حجاباً من الحجب فإذا خلفه محمدٌ واثنا عشر وصياً له فأخذ بيد فلان مِن بينهم فقال: يا ملائكتي ويا سماواتي ويا أرضي بهذا أنتصر منهم لهذا - قالها ثلاث مرات -. وجاء في غير رواية محمد بن يعقوب الكليني: بهذا أنتصر منهم ولو بعد حين.","22/2/4/26",""],[27,4,"أخبرنا محمد بن يعقوب، قال: حدثنا علي بن إبراهيم بن هاشم، عن أبيه، عن ابن أبي عمير، عن ابن أذينة، عن أبان بن أبي عياش، عن سليم بن قيس الهلالي قال: سمعت عبد الله بن جعفر الطيار يقول: كنا عند معاوية أنا والحسن والحسين وعبد الله بن عباس وعمر بن أم سلمة واسامة بن زيد، فجَرى بيني وبين معاوية كلام، فقلت لمعاوية: سمعت رسول الله يقول: أنا أولى بالمؤمنينَ مِن أنفسهم، ثم أخي عليّ بن أبي طالب أولى بالمؤمنين من أنفسهم، فإذا استشهد عليٌّ فالحسن بن علي أولى بالمؤمنين من أنفسهم، ثم ابني الحسين مِن بعده أولى بالمؤمنين من أنفسهم، فإذا استشهد فابنه عليّ بن الحسين أولى بالمؤمنين من أنفسهم وستدركه يا علي ثم ابنه محمّد بن علي أولى بالمؤمنين من أنفسهم، وستدركه يا حسين، ثم تكمله اثني عشر إماماً تسعة من ولد الحسين. قال عبد الله بن جعفر: فاستشهدت الحسنَ والحسين وعبدَ الله بن عباس وعمر بن ام سلمة وأسامة بن زيد فشهدوا. قال سليم: وقد سمعت ذلك من سلمان الفارسي والمقداد وأبي ذر وذكروا أنهم سمعوا ذلك من رسول الله .","22/2/4/27",""],[28,4,"محمد بن عبد الله بن جعفر الحميري، عن أبيه، قال: حدثنا محمد بن عيسى بن عبيد بن يقطين، عن النضر بن سويد، عن يحيى الحلبي، عن علي بن أبي حمزة قال: كنت مع أبي بصير، ومعنا مولى لأبي جعفر الباقر ، فقال: سمعت أبا جعفر يقول: منّا اثنا عشر محدثاً، السابع من بعدي ولدي القائم. فقام إليه أبو بصير فقال: أشهد أني سمعت أبا جعفر يقوله منذ أربعين سنة. وقال أبو الحسن الشجاعي - رحمه الله -: هذان الحديثان مما استدركهما أبو عبد الله - رحمه الله - بعد فراغه، ونسخي الكتاب.","22/2/4/28",""],[29,4,"أخبرنا أبو العباس أحمد بن محمد بن سعيد بن عقدة الكوفي، قال: حدثنا محمد بن المفضل بن إبراهيم بن قيس بن رمانة الأشعري من كتابه، قال: حدثنا إبراهيم بن مهزم، قال: حدثنا خاقان بن سليمان الخزاز، عن إبراهيم بن أبي يحيى المدني، عن أبي هارون العبدي، عن عمر بن أبي سلمة ربيب رسول الله وعن أبي الطفيل عامر بن واثلة قال: قالا: شهدنا الصلاةَ على أبي بكر حين مات فبينما نحن قعود حول عمر وقد بويع إذ جاءه فتى يهوديٌّ من يهود المدينة كان أبوه عالمَ اليهود بالمدينة، يزعمون أنه من ولد هارون، فسلّم على عمر، وقال: يا أمير المؤمنين، أيّكم أعلمُ بكتابكم وسنّة نبيكم؟ فقال عمر: هذا، وأشار إلى عليّ بن أبي طالب وقال: هذا أعلمُنا بكتابنا وسنّة نبينا. فقال الفتى أخبرني أأنت كذا؟ قال: نعم سلني عن حاجتك. فقال: إنّي أسألك عن ثلاث وثلاث وواحدة. قال علي: أفلا تقول: أسألك عن سبع؟ فقال الفتى: لا! ولكن أسألك عن الثلاث، فإن أصبتَ فيهن سألتُك عن الثلاث الأخَر، فإن أصبتَ فيهنّ سألتك عن الواحدة، فإن لم تُصب في الثلاث الأُول سكتُّ ولم أسألك عن شيءٍ. قال له علي: يا يهوديّ، فإن أخبرتك بالصواب وبالحق تعلم أني أخطأتُ أو أصبت؟ قال: نعم. قال عليّ: فبالله لئن أصبتُ فيما تسألني عنه لتسلمنَّ ولتدعنّ اليهودية؟ قال: نعم، لك الله عليّ لئن أصبتَ لأسلمن ولأدَعنّ اليهودية. قال: فأسأل عن حاجتك. قال: أخبرني عن أوّل حجرٍ وُضع على وجه الأرض وأوّلِ شجرة نبتت في الأرض وأولِ عين أنبعت في الأرض؟ قال عليّ: يا يهودي، أما أول حجر وضع على وجه الأرض فإن اليهود يقولون الصخرة التي في بيت المقدس، وكذبوا ولكنه الحجرُ الأسود، نزلَ به آدمُ من الجنة فوضعه في الركن، والمؤمنون يستلمونه ليجدّدوا العهدَ والميثاق لله بالوفاء. وأما قولُك أول شجرة نبتت في الأرض فإن اليهود يقولون: الزيتونة، وكذبوا ولكنّها النخلة العجوة، نزل بها آدم من الجنة وبالفحل، فأصل الثمرة كلّها العجوة. وأما العَين فإنّ اليهود يقولون بأنها العين تحت الصخرة، وكذبوا ولكنها عين الحياة التي لا يغمس فيها ميت إلاّ حيَّ وهي عينُ موسى التي نسيَ عندها السمكةَ المملوحة فلما مسها الماء عاشت وانسربت في البحر فأتبعها موسى وفتاه حين لقيا الخضر. فقال الفتى: أشهدُ أنك قد صدقتَ وقلتَ الحق، وهذا كتاب ورثته عن آبائي إملاء موسى وخط هارون بيده وفيه هذا الخصال السبع، والله لئن أصبت في بقية السبع لأدعنّ ديني وأتبعنّ دينك. فقال علي: سل. فقال: أخبرني كم لهذه الأمّة بعد نبيها من إمامِ هدى لا يضرُّ هم خذلانُ مَن خذلهم؟ وأخبرني عن موضع محمد في الجنة أي موضع هو؟ وكم مع محمد في منْزلته؟ فقال علي: يا يهودي، لهذه الأمة اثنا عشر إماماً مهدياً كلّهم هادٍ مهدي لا يضرهم خذلان من خذلهم، وموضع محمد في أفضل منازل جنة عدن وأقربها من الله وأشرفها، وأما الذي مع محمد في منْزلته فالإثنا عشر الأئمة المهديون. قال اليهودي: وأشهدُ أنك قد صدقتَ وقلت الحق، لئن أصبتَ في الواحدة كما أصبت في الستة واللهِ لأسلمنَّ الساعة على يدك ولأدعنّ اليهودية. قال له: اسأل. قال: أخبرني عن خليفة محمد كم يعيش بعده ويموت موتاً أو يقتل قتلاً؟ قال: يعيش بعده ثلاثين سنة ويخضّب هذه من هذه - وأخذ بلحيته وأومأ إلى رأسه -. فقال الفتى: أشهد أن لا إله إلا الله وأن محمداً رسول الله وأنك خليفة رسول الله على الأمة، ومَن تقدم كان مفترياً. ثم خرج.","22/2/4/29",""],[30,4,"وأخبرنا أبو العباس أحمد بن محمد بن سعيد، قال: حدثنا حميد بن زياد من كتابه وقرأته عليه، قال: حدثني جعفر بن إسماعيل المنقري، عن عبد الرحمن بن أبي نجران، عن إسماعيل بن علي البصري عن أبي أيوب المؤدب، عن أبيه - وكان مؤدباً لبعض ولد جعفر بن محمد - قال قال: لما توفي رسول الله دخل المدينة رجلٌ من ولد داود على دين اليهودية، فرأى السكك خالية فقال لبعض أهل المدينة: ما حالكم؟ فقيل: توفي رسول الله . فقال الداودي: أما إنه توفي في اليوم الذي هو في كتابنا، ثم قال: فأين الناس؟ فقيل له: في المسجد. فأتى المسجدَ، فإذا أبو بكر وعمر وعثمان وعبد الرحمن بن عوف وأبو عبيدة بن الجراح والناس، قد غصّ المسجد بهم، فقال: أوسعوا حتى أدخلَ وأرشدوني إلى الذي خلّفه نبيكم، فأرشدوه إلى أبي بكر، فقال له: إنني من ولد داود على دين اليهودية، وقد جئتُ لأسأل عن أربعة أحرف، فإن خبرت بها أسلمتُ. فقالوا له: انتظر قليلاً. وأقبل أمير المؤمنين علي بن أبي طالب من بعض أبواب المسجد، فقالوا له: عليك بالفتى. فقام إليه، فلمّا دنا منه قال له: أنت علي بن أبي طالب؟ فقال له عليّ: أنت فلان بن فلان بن داود؟ قال: نعم. فأخذ عليٌّ يده وجاء به إلى أبي بكر، فقال له اليهودي: إني سألتُ هؤلاء عن أربعة أحرف فأرشدوني إليك لأسألك. قال: اسأل. قال: ما أوّل حرفٍ كلّم الله به نبيّكم لمّا أسري به ورجع من عند ربه؟ وخبِّرني عن الملك الذي زحم نبيكم ولم يسلم عليه، وخبرني عن الأربعة الذين كشف عنهم مالك طبقاً من النار وكلّموا نبيكم؟ وخبّرني عن منبر نبيّكم أي موضع هو من الجنة؟ قال علي: أوّل ما كلّم الله به نبيّنا قول الله تعالى آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ قال: ليس هذا أردتُ. قال: فقولُ رسول الله آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ قال: ليس هذا أردتُ. قال: اتركِ الأمرَ مستوراً. قال: لَتخبِرنّي أو لستَ أنت هو. فقال: أما إذ أبيتَ فإن رسول الله لمّا رجع من عند ربه والحجبُ ترفع له قبل أن يصير إلى موضع جبرئيل ناداه ملَك: أحمد، قال: إن الله يقرء عليك السلامَ ويقول لك: أقرأ على السيد الوليّ منّا السلامَ، فقال رسولُ الله: مَن السيد الولي؟ فقال الملَك: عليّ بن أبي طالب. قال اليهودي: صدقتَ والله إني لأجدُ ذلك في كتاب أبي. فقال علي: أما الملَك الذي زحم رسول الله فملك الموت جاء به من عند جبارٍ من أهل الدينا قد تكلم بكلام عظيم فغضب الله، فزحم رسول الله ولم يعرفه، فقال جبرئيل: يا ملك الموت، هذا رسولُ الله أحمد حبيب الله ، فرجع إليه فلصق به واعتذر وقال: يا رسول الله إني أتيت ملِكاً جباراً قد تكلّم بكلام عظيم فغضبتُ ولم أعرفكَ، فعذره. وأما الأربعة الذين كشف عنهم مالك طبقاً من النار فإن رسول الله مرّ بمالك ولم يضحك منذ خلق قط، فقال له جبرئيل: يا مالكُ، هذا نبيّ الرحمة محمدٌ، فتبسم في وجهه ولم يتبسم لأحدٍ غيره، فقال رسول الله: مُره أن يكشف طبقاً من النار، فكشف فإذا قابيل ونمرود وفرعون وهامان، فقالوا: يا محمد اسأل ربّك أن يردّنا إلى دار الدنيا حتى نعمل صالحاً، فغضب جبرئيلُ فقال بريشة من ريش جناحه فردّ عليهم طبق النار. وأما منبر رسول الله فإن مسكن رسول الله جنةُ عدن وهي جنة خلقها الله بيده ومعه فيها اثنا عشر وصياً، وفوقها قبة يقال لها: قبة الرضوان، وفوق قبة الرضوان منْزل يقال له: الوسيلة، وليس في الجنة منْزل يشبهه وهو منبر رسول الله . قال اليهودي: صدقتَ واللهِ إنه لفي كتاب أبي داود يتوارثونه واحد بعد واحد حتى صار إليّ. ثم أخرج كتاباً فيه ما ذكره مسطوراً بخط داود، ثم قال: مدَّ يدك، فأنا أشهد أن لا إله إلاّ الله وأن محمداً رسول الله، وأنه الذي بشّر به موسى ، وأشهد أنّك عالم هذه الأمة ووصيُّ رسول الله. قال: فعلّمه أمير المؤمنين شرايعَ الدين.","22/2/4/30",""],[31,4,"ما رواه محمد بن عثمان بن علان الدهني البغدادي بدمشق، قال: حدثنا أبو بكر بن أبي خيثمة قال: حدثنا علي بن الجعد، قال: حدثنا زهير بن معاوية، عن زياد بن خيثمة، عن الأسود بن سعيد الهمداني، قال: سمعت جابر بن سمرة يقول: سمعت رسول الله يقول: يكون بعدي اثنا عشر خليفة كلهم من قريش. قال: فلما رجع إلى منْزله أتته قريش فقالوا له: ثم يكون ماذا؟ قال: ثم يكون الهرج.","22/2/4/31",""],[32,4,"أخبرنا محمد بن عثمان قال: حدثنا ابن أبي خيثمة، قال: حدثني علي بن الجعد، قال: حدثنا زهير بن معاوية، عن زياد بن علاقة وسماك بن حرب وحصين بن عبد الرحمن كلهم عن جابر بن سمرة أن رسول الله قال: يكون بعدي اثنا عشر خليفة. ثم تكلم بشيء لم أفهمه فقال بعضهم: سألت القوم فقالوا قال: كلهم من قريش.","22/2/4/32",""],[33,4,"أخبرنا محمد بن عثمان قال: حدثنا أحمد قال: حدثنا عبيد الله بن عمر قال: حدثنا سليمان الأعمش، قال: حدثنا ابن عون، عن الشعبي، عن جابر بن سمرة قال: ذكر أن النبي قال: لا يزال أهل هذا الدين ينصرون على من ناواهم إلى اثني عشر خليفة. - فجعل الناس يقومون ويقعدون - وتكلم بكلمة لم أفهمها، فقلت لأبي أو آخر: أي شيء قال؟ قال: فقال: كلهم من قريش.","22/2/4/33",""],[34,4,"أخبرنا محمد بن عثمان قال: حدثنا أحمد بن أبي خيثمة، قال: حدثني يحيى بن معين، قال: حدثنا عبد الله بن صالح، قال: حدثنا الليث بن سعد، عن خالد بن يزيد، عن سعيد بن أبي هلال، عن ربيعة بن سيف، قال، كنا عند شفي الاصبحي قال: سمعت عبد الله بن عمرو يقول: سمعت رسول الله يقول: يكون خلفي اثنا عشر خليفة.","22/2/4/34",""],[35,4,"أخبرنا محمد بن عثمان قال: حدثنا أحمد، قال: حدثنا عفان ويحيى بن إسحاق السالحيني قالا: حدثنا حماد بن سلمة، قال: حدثنا عبد الله بن عثمان عن أبى الطفيل قال: قال لي عبد الله بن عمرو: يا أبا الطفيل إعدد اثني عشر من بني كعب بن لؤي ثم يكون النقف والنقاف.","22/2/4/35",""],[36,4,"أخبرنا محمد بن عثمان قال: حدثنا المقدمي عن عاصم بن عمر بن علي بن مقدام قال: حدثنا أبي، عن فطر بن خليفة، عن أبى خالد الوالبي، قال: حدثنا جابر بن سمرة قال: سمعت رسول الله يقول: لا يزال هذا الأمر ظاهراً لا يضره من ناواه حتى يكون اثنا عشر خليفة كلهم من قريش.","22/2/4/36",""],[37,4,"أخبرنا محمد بن عثمان قال: حدثنا عبد الله بن جعفر الرقي، قال: حدثنا عيسى بن يونس، عن مجالد بن سعيد، عن الشعبي، عن مسروق قال: كنا عند ابن مسعود فقال له رجل: أحدَّثكم نبيُّكم كم يكون بعده من الخلفاء؟ فقال: نعم وما سألني عنها أحد قبلك، فإنك للأحدث القوم سناً، سمعته يقول: يكون بعدي عدة نقباء موسى عليه السلام.","22/2/4/37",""],[38,4,"أخبرنا محمد بن عثمان قال: حدثنا أحمد بن أبي خيثمة، قال: حدثنا الفضل بن دكين، قال: حدثنا فطر، قال: حدثنا أبو خالد الوالبي، قال: سمعت جابر بن سمرة السوائي يقول: قال رسول الله: لا يضر هذا الدين من ناواه حتى يمضي اثنا عشر خليفة كلهم من قريش. وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ ۗ إِنَّمَا أَنْتَ مُنْذِرٌ ۖ وَلِكُلِّ قَوْمٍ هَادٍ","22/2/4/38",""],[39,4,"أخبرنا أحمد بن محمد بن سعيد بن عبد الرحمن بن عقدة قال: حدثنا محمد بن سالم بن عبد الرحمن الأزدي في شوال سنة إحدى وثمانين ومائتين، قال: حدثنا عثمان بن سعيد الطويل، عن أحمد بن سير، عن موسى بن بكر الواسطي، عن الفضيل عن أبي عبد الله في قوله وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ ۗ إِنَّمَا أَنْتَ مُنْذِرٌ ۖ وَلِكُلِّ قَوْمٍ هَادٍ قال: كلُّ إمام هادٍ للقرن الذي هو فيهم.","22/2/4/39",""],[40,4,"أخبرنا أحمد بن محمد بن سعيد بن عبد الرحمن بن عقدة قال: حدثنا محمد بن سالم بن عبد الرحمن الأزدي في شوال سنة إحدى وستين ومائتين، قال: حدثنا علي بن الحسن بن رباط، عن منصور بن حازم، عن عبد الرحيم القصير، عن أبى جعفر الباقر في قول الله تعالى وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ ۗ إِنَّمَا أَنْتَ مُنْذِرٌ ۖ وَلِكُلِّ قَوْمٍ هَادٍ قال: رسولُ الله المنذرُ، وعليٌّ الهادي. أما واللهِ ما ذهبت منا وما زالت فينا إلى الساعة.","22/2/4/40",""],[1,5,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا حميد بن زياد، قال: حدثنا جعفر بن إسماعيل المنقري، قال: أخبرني شيخ بمصر يقال له: الحسين بن أحمد المقرئ، عن يونس بن ظبيان قال: قال أبو عبد الله في قول الله وَيَوْمَ الْقِيَامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُمْ مُسْوَدَّةٌ ۚ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْمُتَكَبِّرِينَ قال: مَن زعم أنه إمام وليس بإمامٍ.","22/2/5/1",""],[2,5,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل بن إبراهيم الأشعري، قال: حدثني محمد بن عبد الله بن زرارة، عن مرزبان القمي، عن عمران الأشعري، عن جعفر بن محمد أنه قال: ثلاثةٌ لا ينظر الله إليهم يوم القيامة ولا يزكّيهم ولهم عذاب أليم: مَن زعم أنه إمامٌ وليس بإمام، ومن زعم في أمام حقٍ أنه ليس بإمام وهو إمام، ومَن زعم أن لهما في الإسلام نصيباً.","22/2/5/2",""],[3,5,"وحدثنا محمد بن يعقوب، عن الحسين بن محمد، عن معلي بن محمد، عن أبي داود المسترق، عن علي بن ميمون الصائغ، عن ابن أبي يعفور قال: سمعت أبا عبد الله يقول: ثلاثةٌ لا يكلمهم الله يوم القيامة ولا يزكيهم ولهم عذاب أليم: مَن ادعى مِن الله إمامةً ليست له، ومن جحد إماماً من الله، ومن زعم أنّ لهما في الإسلام نصيباً.","22/2/5/3",""],[4,5,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا أبو محمد القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام، قال: حدثنا عبد الله بن جبلة، عن الحكم بن أيمن، عن محمد بن تمام قال: قلت لأبي عبد الله: إن فلاناً يقرئك السلام ويقول لك: اضمن لي الشفاعةَ. فقال: أمِن موالينا؟ قلت: نعم. قال: أمرُه أرفعُ من ذلك. قال: قلت: إنه رجلٌ يوالي علياً ولم يعرف مَن بعده من الأوصياء. قال: ضالٌّ. قلت: أقرَّ بالأئمّة جميعاً وجحد الآخرَ. قال: هو كَمَنْ أقرّ بعيسى وجحد بمحمّد أو أقرّ بمحمد وجحد بعيسى، نعوذ بالله مِن جَحدِ حجّة من حججه.","22/2/5/4",""],[5,5,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن بن فضال من كتابه، قال: حدثنا العباس بن عامر بن رباح الثقفي، عن أبي المغرا عن أبي سلام، عن سورة بن كليب، عن أبي جعفر محمد بن علي الباقر أنه قال: قول الله وَيَوْمَ الْقِيَامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُمْ مُسْوَدَّةٌ ۚ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْمُتَكَبِّرِينَ قال: مَن زعم أنه إمامٌ وليس بإمام. قلت: وإن كان علوياً فاطمياً؟ قال: وإن كان علوياً فاطمياً.","22/2/5/5",""],[6,5,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام الناشري، قال: حدثنا عبد الله بن جبلة، عن عمران بن قطر، عن زيد الشحام قال: سألت أبا عبد الله هل كان رسول الله يعرف الأئمة ؟ قال: قد كان نوح يعرفهم؛ الشاهدُ على ذلك قول الله شَرَعَ لَكُمْ مِنَ الدِّينِ مَا وَصَّىٰ بِهِ نُوحًا وَالَّذِي أَوْحَيْنَا إِلَيْكَ وَمَا وَصَّيْنَا بِهِ إِبْرَاهِيمَ وَمُوسَىٰ وَعِيسَىٰ ۖ أَنْ أَقِيمُوا الدِّينَ وَلَا تَتَفَرَّقُوا فِيهِ ۚ كَبُرَ عَلَى الْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ اللَّهُ يَجْتَبِي إِلَيْهِ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ يُنِيبُ قال: شَرع لكم من الدين يا معشرَ الشيعة ما وصّى به نوحاً.","22/2/5/6",""],[7,5,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام، عن عبد الله بن جبلة، عن أبى خالد المكفوف عن بعض أصحابه قال: قال أبو عبد الله: ينبغي لمَن ادّعى هذا الأمرَ في السر أن يأتيَ عليه ببرهان في العلانية. قلت: وما هذا البرهان الذي يأتي في العلانية؟ قال: يحلّ حلالَ الله ويحرم حرام الله، ويكون له ظاهرٌ يصدق باطنه.","22/2/5/7",""],[8,5,"وأخبرنا عبد الواحد بن عبد الله بن يونس الموصلي قال: حدثني محمد بن جعفر القرشي المعروف بالرزاز الكوفي قال: حدثني محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن أبي سلام، عن سورة بن كليب، عن أبي جعفر الباقر في قوله وَيَوْمَ الْقِيَامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُمْ مُسْوَدَّةٌ ۚ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْمُتَكَبِّرِينَ قال: مَن قال إني إمام وليس بإمام. قلت: وإن كان علوياً فاطمياً؟ قال: وإن كان علوياً فاطمياً. قلت: وإن كان من ولد علي بن أبي طالب ؟ قال: وإن كان من ولد علي بن أبي طالب. وحدثنا محمد بن يعقوب، عن محمد بن يحيى، عن أحمد بن محمد، عن محمد بن سنان، عن أبي سلام، عن سورة بن كليب، عن أبي جعفر مثله سواء.","22/2/5/8",""],[9,5,"وأخبرنا عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح الزهري، قال: حدثنا محمد بن العباس بن عيسى الحسينى، عن الحسن بن علي بن أبي حمزة، عن أبيه، عن مالك بن أعين الجهني، عن أبي جعفر الباقر أنه قال: كلُّ رايةٍ تُرفع قبل رايةِ القائمِ صاحبُها طاغوتٌ.","22/2/5/9",""],[10,5,"وأخبرنا عبد الواحد، عن ابن رباح قال: حدثنا أحمد بن علي الحميري، قال: حدثني الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن أبان، عن الفضيل قال: قال أبو عبد الله جعفر: مَن ادّعى مقامَنا - يعني الإمامةَ - فهو كافرٌ (أو قال) مشركٌ.","22/2/5/10",""],[11,5,"وأخبرنا علي بن الحسين، قال: حدثنا محمد بن يحيى العطار بقم، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، عن علي بن الحسين، عن ابن مسكان، عن مالك بن أعين الجهني، قال: سمعت أبا جعفر الباقر يقول: كلُّ راية تُرفع قبل قيام القائم صاحبُها طاغوت.","22/2/5/11",""],[12,5,"وأخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن علي بن إبراهيم بن هاشم، عن أبيه، عن عبد الله بن المغيرة، عن عبد الله بن مسكان، عن مالك بن أعين الجهني قال: سمعت أبا جعفر الباقر يقول: كل راية ترفع - أو قال: تخرج - قبل قيام القائم صاحبها طاغوت.","22/2/5/12",""],[13,5,"وأخبرنا علي بن أحمد، عن عبيد الله بن موسى، عن أحمد بن محمد بن خالد، عن علي بن الحكم، عن أبان بن عثمان، عن الفضيل بن يسار قال: سمعت أبا عبد الله جعفر بن محمد يقول: مَن خرج يدعو الناس وفيهم مَن هو أفضل منه فهو ضالٌّ مبتدعٌ. ومَن ادّعى الإمامة من الله وليس بإمامٍ فهو كافر.","22/2/5/13",""],[1,6,"أخبرنا محمد بن عثمان الدهني قال: حدثنا عبد الله بن جعفر الرقي، قال: حدثنا عيسى بن يونس، عن مجالد بن سعيد، عن الشعبي، عن مسروق قال: كنا عند ابن مسعود فقال له رجل: أحدثكم نبيكم كم يكون بعده من الخلفاء؟ فقال: نعم، وما سألني أحد قبلك، وإنك لأحدث القوم سناً، سمعته يقول: يكون بعدي عدّة نقباءِ موسى .","22/2/6/1",""],[2,6,"ورواه جماعة عن عثمان بن أبي شيبة، وعبد الله بن عمر بن سعيد الأشج وأبى كريب ومحمود بن غيلان وعلي بن محمد وإبراهيم بن سعيد قالوا جميعاً حدثنا أبو أسامة، عن مجالد، عن الشعبي، عن مسروق، قال: جاء رجل إلى عبد الله بن مسعود فقال: أحدّثكم نبيُّكم عليه وآله السلام كم يكون بعده من الخلفاء؟ قال: نعم وما سألني عنها أحد قبلك، وإنك لأحدث القوم سناً، قال: يكون بعدي عدة نقباء موسى .","22/2/6/2",""],[3,6,"أبو كريب وأبو سعيد قالا: حدثنا أبو أسامة، قال: حدثنا الأشعث عن عامر، عن عمه، عن مسروق، قال: كنا جلوساً عند عبد الله بن مسعود يقرئنا القرآن، فقال رجل: يا أبا عبد الرحمن هل سألتم رسول الله كم يملك هذه الأمة من خليفة بعده؟ فقال: ما سألني عنها أحد منذ قدمت العراق! نعم سألنا رسول الله فقال: إثنا عشر عدّة نقباء بني إسرائيل.","22/2/6/3",""],[4,6,"وعن عثمان بن أبي شيبة وأبي أحمد، ويوسف بن موسى القطان وسفيان بن وكيع قالوا: حدثنا جرير عن الأشعث بن سوار، عن عامر الشعبي، عن عمه قيس بن عبد قال: جاء أعرابي فأتى عبد الله بن مسعود، وأصحابه عنده، فقال: فيكم عبد الله بن مسعود؟ فأشاروا إليه، قال له عبد الله: قد وجدته فما حاجتك؟ قال: إني أريد أن أسألك عن شيء إن كنتَ سمعته من رسول الله فنبئنا به، أحدَّثكم نبيكم كم يكون بعده من خليفة؟ قال: وما سألني عن هذا أحد منذ قدمت العراق! نعم قال: الخلفاء بعدي أثنا عشر خليفة كعدة نقباء بني إسرائيل.","22/2/6/4",""],[5,6,"وعن مسدد بن مستورد قال: حدثني حماد بن زيد، عن مجالد، عن مسروق قال: كنا جلوساً إلى ابن مسعود بعد المغرب وهو يعلّم القرآن، فسأله رجل فقال: يا أبا عبد الرحمن أسألتَ النبي كم يكون لهذه الأمة من خليفة؟ فقال: ما سألني عنها أحد منذ قدمت العراق، نعم وقال: خُلفاؤكم أثنا عشر عدّة نقباء بني إسرائيل.","22/2/6/5",""],[6,6,"ما رواه عبد السلام بن هاشم البزار قال: حدثنا عبد الله بن أبي أمية مولى بني مجاشع، عن يزيد الرقاشي، عن أنس بن مالك قال: قال رسول الله: لن يزال هذا الأمر قائماً إلى أثني عشر قيّماً من قريش. ثم ساق الحديث إلى آخره.","22/2/6/6",""],[7,6,"عمرو بن خالد بن فروخ الحراني قال: حدثنا زهير بن معاوية، قال: حدثنا زياد بن خيثمة، عن الأسود بن سعيد الهمداني، عن جابر بن سمرة قال: قال رسول الله: لا تزالُ هذه الأمّة مستقيماً أمرُها ظاهرةً على عدوها حتى يمضيَ أثنا عشر خليفة كلهم من قريش. فلما رجع إلى منْزله أتته وفودُ قريش فقالوا له: ثم يكون ماذا؟ قال: يكون الهرج. وقال: حدثنا زهير بن معاوية قال: حدثنا زياد بن خيثمة، عن ابن جريج، عن الأسود بن سعيد الهمداني، عن جابر بن سمرة قال: قال رسول الله و ذكر مثله.","22/2/6/7",""],[8,6,"عثمان بن أبي شيبة قال حدثني جرير، عن حصين بن عبد الرحمن، عن جابر بن سمرة قال: سمعت رسول الله يقول: يقوم مِن بعدي اثنا عشر أميراً. قال: ثم تكلم بشيء لم أسمعه، فسألت القوم وسألت أبي وكان أقرب إليه مني، فقال قال: كلّهم من قريش.","22/2/6/8",""],[9,6,"عثمان بن أبي شيبة قال: حدثنا حاتم بن إسماعيل، عن مهاجر بن مسمار، عن عامر بن سعد قال: كتبت مع غلامي نافع إلى جابر بن سمرة: أخبرني بشيء سمعته من رسول الله قال فكتب إلي: سمعت رسول الله يقول عشية جمعة رجم الأسلمي: لا يزال هذا الدين قائماً حتى تقوم الساعة أو يكون على الناس اثنا عشر خليفة كلهم من قريش. وذكر الحديث إلى آخره. وعن عباد بن يعقوب قال: حدثنا حاتم بن إسماعيل بإسناده مثله. وعن محمد بن عبد الله بن عبد الحكم قال: حدثنا ابن أبي فديك، عن ابن أبي - ذئب، عن مهاجر بن مسمار بإسناده مثله.","22/2/6/9",""],[10,6,"وعن غندر عن شعبة قال: حدثنا أبو عوانة، عن عبد الملك بن عمير، عن جابر بن سمرة قال: سمعت رسول الله يقول: لا يزال هذا الدين مستقيماً حتى يقوم اثنا عشر خليفة. ثم قال كلمة لم أفهمها، فسألت أبي فقال قال: كلهم من قريش.","22/2/6/10",""],[11,6,"وعن إبراهيم بن محمد بن مالك بن زيد قال: حدثنا زياد بن علاقة قال: حدثنا جابر بن سمرة السوائي قال: كنت مع أبي عند رسول الله فقال: يكون بعدي اثنا عشر أميراً. ثم أخفى صوته، فسألت أبي، فقال: قال: كلهم من قريش.","22/2/6/11",""],[12,6,"وعن خلف بن الوليد اللؤلؤي عن إسرائيل، عن سماك، قال: سمعت جابر بن سمرة يقول: سمعت رسول الله قال: يقوم بعده - أو من بعده - اثنا عشر أميراً. ثم تكلم بكلمة لم أفهمها فسألت القوم ما قال؟ فقالوا: قال: كلهم من قريش.","22/2/6/12",""],[13,6,"ومن حديث خلف بن هشام البزار قال: حدثنا حماد بن زيد، عن مجالد بن سعيد، عن الشعبي، عن جابر بن سمرة السوائي قال: خطب بنا رسول الله بعرفة فقال: لا يزال هذا الدين قوياً عزيزاً ظاهراً على مَن ناواه لا يضرّه مَن فارقه أو خالفه حتى يملك اثنا عشر. قال: وتكلم الناس فلم أفهم، فقلت لأبي: يا أبت أرأيت قول رسول الله “كلهم “ما هو؟ قال: كلهم من قريش. ومن حديث النفيلي الحراني قال حدثنا زهير بن معاوية قال حدثنا زياد بن خيثمة قال: حدثنا الأسود بن سعيد الهمداني عن جابر بن سمرة قال: قال رسول الله: لا تزال هذه الأمة مستقيماً أمرُها ظاهرة على عدوها حتى يمضي اثنا عشر خليفة، كلهم من قريش. فلما رجع إلى منْزله أتته وفودُ قريش فقالوا له: ثم يكون ماذا؟ قال: يكون الهرج.","22/2/6/13",""],[14,6,"ومن حديث علي بن الجعد قال: حدثنا زهير، عن زياد بن علاقة، وسماك وحصين كلهم، عن جابر بن سمرة أن رسول الله قال: يكون بعدي اثنا عشر أميراً. غيرَ أن حصين قال: اثنا عشر خليفة، ثم تكلم بشيء لم أفهمه - وقال بعضهم في حديثه: فسألت أبي. وقال بعضهم: فسألت القومَ، فقالوا: قال: كلّهم من قريش.","22/2/6/14",""],[15,6,"وعن عمرو بن خالد الحراني قال: حدثنا زهير بن معاوية، قال: حدثنا زياد بن خيثمة، عن الأسود بن سعيد الهمداني، عن جابر بن سمرة قال: قال رسول الله: لا تزال هذه الأمة مستقيماً أمرُها ظاهرةً على عدوها حتى يمضي منها اثنا عشر خليفة.","22/2/6/15",""],[16,6,"ومن حديث معمر بن سليمان قال: سمعت إسماعيل بن أبي خالد، يروي عن مجالد، عن الشعبي، عن جابر بن سمرة عن النبي قال: لا يزال هذا لدين ظاهراً لا يضره مَن ناواه حتى يمضي اثنا عشر خليفة. ثم قال كلمة لم أفهمها، فقلت لأبي: ما قال؟ قال: قال: كلهم من قريش.","22/2/6/16",""],[17,6,"وعن يزيد بن سنان وعثمان بن أبي شيبة قالا: حدثنا موسى بن إسماعيل، قال: حدثنا حماد بن سلمة، عن سماك بن حرب، عن جابر بن سمرة قال: سمعت النبي يقول: لا يزال هذا الإسلام عزيزاً إلى اثني عشر خليفة. ثم قال كلمة لم أفهمها، فقلت لأبي: ما قال؟ فقال: قال: كلهم من قريش.","22/2/6/17",""],[18,6,"ومن حديث يزيد بن سنان قال: حدثنا أبو الربيع الزهراني قال: حدثنا حماد بن زيد، قال: حدثنا مجالد بن سعيد، عن الشعبي، عن جابر بن سمرة قال: خطب بنا رسول الله فسمعته يقول: لا يزال هذا الأمر عزيزاً منيعاً ظاهراً على مَن ناواه حتى يملك اثنا عشر كلهم... - ثم لغط القوم وتكلموا، فلم أفهم قوله بعد “كلهم \"، فقلت لأبي يا أبتاه ما قال بعد “كلهم “؟ قال: قال: كلهم من قريش.","22/2/6/18",""],[19,6,"ومن حديث يزيد بن سنان قال: حدثنا عبد الحميد بن موسى قال: حدثنا عبيد الله بن عمرو، عن عبد الملك بن عمير، عن جابر بن سمرة قال: دخلت مع أبي علي النبي فسمعته يقول: لن تزال الأمة على هذا متمسكين حتى يقوم اثنا عشر أميراً أواثنا عشر خليفة. قال: وخافت بكلمة وكان أبي أدنى مني، فلما خرجت قلت: ما الذي خافت به؟ قال: قال: كلهم من قريش.","22/2/6/19",""],[20,6,"ومن حديث يزيد بن سنان قال: حدثنا الحسن بن عمر بن شقيق قال: حدثنا جرير بن عبد الحميد، عن حصين بن عبد الرحمن، عن جابر بن سمرة قال: سمعت رسول الله يقول: يقوم في أمّتي بعدي اثنا عشر أميراً. قال: ثم تكلم بشيء لم أسمعه، قال: فسألت القوم وسألت أبي وكان أقرب مني، فقال: قال: كلهم من قريش.","22/2/6/20",""],[21,6,"وعن ابن أبي فديك، قال: حدثني ابن أبي ذئب، عن مهاجر بن مسمار، عن عامر بن سعد أنه أرسل إلى ابن سمرة حدثنا ما سمعت من رسول الله ؟ قال: سمعت رسول الله يقول: لا يزال هذا الدين قائماً حتى يكون اثنا عشر خليفة من قريش. وساق الحديث إلى آخره.","22/2/6/21",""],[22,6,"وعن عثمان بن أبي شيبة قال: حدثنا سهل بن حماد أبو عتاب الدلال قال: حدثنا يونس بن أبي يعفور قال: حدثنا عون بن أبي جحيفة، عن أبيه قال: كنت عند رسول الله وهو يخطب وعمّي جالس بين يديه، فقال رسول الله: لا يزال أمرُ أمّتي صالحاً حتى يمضي اثنا عشر خليفة كلهم من قريش.","22/2/6/22",""],[23,6,"ومن حديث سويد بن سعيد قال: حدثنا معتمر بن سليمان، عن هشام، عن ابن سيرين، عن أبي الخير، عن عبد الله بن عمرو: لا جرمَ مكتوب في كتاب الله ، اثنا عشر يملكون الناس.","22/2/6/23",""],[24,6,"محمد بن عثمان الدهني قال: حدثنا ابن أبي خيثمة، قال: حدثنا يحيى بن معين، قال: حدثنا عبد الله بن صالح، قال: حدثنا الليث بن سعد، عن خالد بن يزيد، عن سعيد بن أبي هلال، عن ربيعة بن سيف، قال: كنا عند شفيّ الأصبحي فقال: سمعت عبد الله بن عمرو يقول: سمعت رسول الله يقول: يكون خلفي اثنا عشر خليفة.","22/2/6/24",""],[25,6,"وعن ابن أبي خيثمة قال: حدثنا عفان، ويحيى بن إسحاق السيلحيني، قالا: حدثنا حماد بن سلمة، قال: حدثنا عبد الله بن عثمان، عن أبي الطفيل، قال: قال عبد الله بن عمرو: يا أبا الطفيل اعدد اثني عشر من بنى كعب بن لؤي ثم يكون النقف والنقاف. والروايات في هذا المعنى من طرق العامة كثيرة تدل على أن رسول الله يذكر الإثني عشر وأنهم خلفاؤه.","22/2/6/25",""],[1,7,"حدثنا أحمد بن نصر بن هوذة الباهلي، قال: حدثنا إبراهيم بن إسحاق النهاوندي بنهاوند سنة ثلاث وسبعين ومائتين قال: حدثنا عبد الله بن حماد الأنصاري سنة تسع وعشرين ومائتين قال: حدثنا يحيى بن عبد الله قال: قال لي أبو عبد الله جعفر بن محمد: يا يحيى بن عبد الله، مَن بات ليلة لا يعرف فيها إمامَه مات ميتة جاهلية.","22/2/7/1",""],[2,7,"حدثنا أبو العباس أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل بن إبراهيم الأشعري وسعدان بن إسحاق بن سعيد وأحمد بن الحسين بن عبد الملك ومحمد بن أحمد بن الحسن القطواني قالوا جميعاً: حدثنا الحسن بن محبوب الزراد، عن علي بن رئاب، عن محمد بن مسلم الثقفى قال: سمعت أبا جعفر محمد بن علي الباقر يقول: كلّ مَن دان الله بعبادة يجهد فيها نفسه ولا إمامَ له من الله تعالى فسعيُه غير مقبول وهو ضالٌّ متحير، والله شانئٌ لأعماله، ومثَلُه كمثَل شاةٍ من الأنعام ضلّت عن راعيها أو قطيعها، فتاهت ذاهبة وجائية، وحارث يومها، فلما جنّها الليل بصرت بقطيع غنم مع راعيها فحنّت إليها واغترّت بها، فباتت معها في ربضتها. فلما أصبحت وساق الراعي قطيعه أنكرت راعيها وقطيعها، فهجمت متحيرة تطلب راعيَها وقطيعها فبصرت بسرح غنم آخر مع راعيها فحنت إليها واغترت بها، فصاح بها راعي القطيع: أيّتها الشاة الضالّة المتحيرة الحقي براعيك وقطيعك فإنّك تائهة متحيرة قد ضللت عن راعيك وقطيعك، فهجمت ذعرة متحيرة تائهة لا راعيَ لها يرشدها إلى مرعاها أو يردّها إلى مربضها، فبينما هي كذلك إذا اغتنم الذئب ضيعتها فأكلها. وهكذا واللهِ يا ابن مسلم! مَن أصبح مِن هذه الأمة لا إمام له من الله أصبح تائهاً متحيراً ضالاً، إن مات على هذه الحال مات ميتةَ كفر ونفاق. واعلم يا محمدُ أنّ أئمة الحق وأتباعهم هم الذين على دين الله، وإن أئمة الجور لمعزولون عن دين الله وعن الحق، فقد ضلوا وأضلوا. فأعمالُهم التي يعملونها كرمادٍ اشتدّت به الريح في يوم عاصف لا يقدرون مما كسبوا على شيء وذلك هو الضلال البعيد.","22/2/7/2",""],[3,7,"وبالإسناد الأول عن ابن محبوب، عن أبي أيوب الخزاز، عن محمد بن مسلم عن أبي جعفر قال: قلت له: أرأيتَ مَن جحد إماماً منكم ما حاله؟ فقال: مَن جحد إماماً من الله وبرئ منه ومِن دينه فهو كافر مرتدٌّ عن الإسلام، لأنّ الإمام من الله ودينه من دين الله، ومَن برئ من دين الله فدَمُه مباح في تلك الحال إلاّ أن يرجع أو يتوب إلى الله تعالى ممّا قال.","22/2/7/3",""],[4,7,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا يحيى بن زكريا بن شيبان سنة ثلاث وسبعين ومائتين قال: حدثنا علي بن سيف بن عميرة، قال: حدثنا أبان بن عثمان، عن حمران بن أعين قال: سألت أبا عبد الله عن الأئمة، فقال: مَن أنكر واحداً من الأحياء فقد أنكر الأموات.","22/2/7/4",""],[5,7,"حدثنا محمد بن يعقوب، عن الحسين بن محمد، عن المعلى، عن ابن جمهور عن صفوان، عن ابن مسكان قال: سألت أبا عبد الله عن الأئمة، فقال: مَن أنكر واحداً من الأحياء فقد أنكر الأموات.","22/2/7/5",""],[6,7,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن من كتابه قال: حدثنا العباس بن عامر، عن عبد الملك بن عتبة، عن معاوية بن وهب قال: سمعت أبا عبد الله يقول: قال رسول الله: مَن مات لا يعرف إمامَه مات ميتة جاهليّة.","22/2/7/6",""],[7,7,"حدثنا محمد بن يعقوب قال: حدثني عدة من أصحابنا، عن أحمد بن محمد، عن ابن أبي نصر، عن أبي الحسن في قوله تعالى فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ ۚ وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ ۚ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ قال: يعني مَن اتخَذ دينه رأيَه بغير إمامٍ من أئمة الهدى.","22/2/7/7",""],[8,7,"حدثنا محمد بن يعقوب قال: حدثنا محمد بن يحيى، عن محمد بن الحسين، عن محمد بن سنان، عن بعض رجاله، عن أبي عبد الله قال: مَن أشرك مع إمام إمامتُه من عند الله مَن ليست إمامته من الله كان مشركاً.","22/2/7/8",""],[9,7,"حدثنا محمد بن يعقوب، عن محمد بن يحيى، عن أحمد بن محمد، عن محمد بن إسماعيل، عن منصور بن يونس، عن محمد بن مسلم قال: قلت لأبي عبد الله: رجل قال لي: إعرف الآخرَ من الأئمة ولا يضرك ألاّ تعرف الأول، (قال) فقال: لعنَ الله هذا، فإني أبغضُه ولا أعرفه، وهل عُرف الآخرُ إلاّ بالأول.","22/2/7/9",""],[10,7,"حدثنا محمد بن يعقوب قال: حدثنا عدة من أصحابنا، عن أحمد بن محمد، عن الحسين بن سعيد، عن أبي وهب، عن محمد بن مصنور قال: سألته - يعني أبا عبد الله - عن قول الله وَإِذَا فَعَلُوا فَاحِشَةً قَالُوا وَجَدْنَا عَلَيْهَا آبَاءَنَا وَاللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ اللَّهَ لَا يَأْمُرُ بِالْفَحْشَاءِ ۖ أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ (قال) فقال: هل رأيتَ أحداً زعم أنّ الله أمره بالزنا وشربِ الخمر أو شيء من هذه المحارم؟ فقلت: لا. قال: فما هذه الفاحشةُ التي يدّعون أن الله أمرهم بها؟ قلت: الله أعلم ووليه، قال: فإن هذا في أولياء أئمّة الجور ادّعوا أنّ الله أمرَهم بالائتمام بقومٍ لم يأمرهم الله بالائتمام بهم، فردّ اللهُ ذلك عليهم وأخبر أنهم قد قالوا عليه الكذبَ وسمّى ذلك منهم فاحشة.","22/2/7/10",""],[11,7,"حدثنا محمد بن يعقوب قال: حدثنا عدة من أصحابنا، عن أحمد بن محمد، عن الحسين بن سعيد، عن أبي وهب، عن محمد بن منصور قال: سألت عبداً صالحاً سلام الله عليه عن قول الله: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ (قال) فقال: إنّ القرآن له ظاهرٌ وباطن، فجميعُ ما حرّم الله في القرآن فهو حرام على ظاهره كما هو في الظاهر، والباطن من ذلك أئمّة الجور. وجميع ما أحل الله تعالى في الكتاب فهو حلال وهو الظاهر، والباطن من ذلك أئمة الحق.","22/2/7/11",""],[12,7,"حدثنا محمد بن يعقوب، عن محمد بن يحيى، عن أحمد بن محمد بن عيسى، عن ابن محبوب عن عمرو بن ثابت، عن جابر قال: سألت أبا جعفر عن قول الله وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَادًا يُحِبُّونَهُمْ كَحُبِّ اللَّهِ ۖ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ ۗ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ اللَّهَ شَدِيدُ الْعَذَابِ قال: هُم واللهِ أولياءُ فلان وفلان؛ اتّخذوهم أئمّة دون الإمامِ الذي جعله الله للناس إماماً، ولذلك قال وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللَّهِ أَنْدَادًا يُحِبُّونَهُمْ كَحُبِّ اللَّهِ ۖ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ ۗ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ اللَّهَ شَدِيدُ الْعَذَابِ إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا وَرَأَوُا الْعَذَابَ وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ وَقَالَ الَّذِينَ اتَّبَعُوا لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ ۖ وَمَا هُمْ بِخَارِجِينَ مِنَ النَّارِ ثم قال أبو جعفر: هُم واللهِ يا جابر أئمّة الظلم وأشياعُهم.","22/2/7/12",""],[13,7,"وبه عن ابن محبوب، عن هشام بن سالم، عن حبيب السجستاني، عن أبي جعفر قال: قال الله: لأعذّبنَّ كلّ رعية في الإسلام دانت بولاية كلّ إمام جائر ليس من الله وإن كانت الرعيةُ في أعمالها برةً تقية، ولأعفُونَّ عن كلّ رعية في الإسلام دانت بولاية كلّ إمام عادل من الله وإن كانت الرعية في أعمالها ظالمةً مسيئة.","22/2/7/13",""],[14,7,"وبه عن ابن محبوب، عن عبد العزيز العبدي، عن عبد الله بن أبي يعفور قال: قلت لأبي عبد الله: إني أخالطُ الناس فيكثر عجبي من أقوام لا يتولّونكم ويتولّون فلاناً وفلاناً، لهم أمانة وصدق ووفاء، وأقوام يتولّونكم ليس لهم تلك الأمانة ولا الوفاء ولا الصدق؟ قال: فاستوى أبو عبد الله جالساً وأقبل عليَّ كالمغضِب ثم قال: لا دينَ لمن دان بولاية إمامٍ جائر ليس من الله، ولا عتبَ على مَن دان بولاية إمام عادل من الله. قلت: لا دين لأولئك، ولا عتب على هؤلاء؟ قال: نعم لا دين لأولئك، ولا عتب على هؤلاء. ثم قال: أما تسمع لقول الله اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ ۖ وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُمْ مِنَ النُّورِ إِلَى الظُّلُمَاتِ ۗ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ يعني مِن ظلمات الذنوب إلى نور التوبة والمغفرة لولايتهم كلّ إمام عادل من الله. ثم قال اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ ۖ وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُمْ مِنَ النُّورِ إِلَى الظُّلُمَاتِ ۗ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ فأيُّ نور يكون للكافر فيخرج منه؟ إنما عنيَ بهذا أنهم كانوا على نور الإسلام، فلمّا تولّوا كل إمام جائر ليس من الله خرجوا بولايتهم إياهم من نور الإسلام إلى ظلمات الكفر، فأوجب الله لهم النارَ مع الكفار، فقال اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُمْ مِنَ الظُّلُمَاتِ إِلَى النُّورِ ۖ وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُمْ مِنَ النُّورِ إِلَى الظُّلُمَاتِ ۗ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ","22/2/7/14",""],[15,7,"حدثنا محمد بن يعقوب، عن علي بن محمد، عن ابن جمهور، عن أبيه، عن صفوان، عن ابن مسكان، عن عبد الله بن سنان، عن أبي عبد الله أنه قال: إن الله لا يستحيي أن يعذب أمّة دانت بإمام ليس من الله، وإن كانت في أعمالها برّة تقية، وإن الله يستحيي أن يعذب أمة دانت بإمام من الله، وإن كانت في أعمالها ظالمة مسيئة.","22/2/7/15",""],[16,7,"أخبرنا عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح، قال: حدثنا أحمد بن علي الحميري، قال: حدثني الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن عبد الله بن أبي يعفور قال: قلت لأبي عبد الله: رجلٌ يتولاكم ويبرء من عدوكم ويحلّل حلالكم ويحرم حرامكم ويزعم أن الأمرَ فيكم لم يخرج منكم إلى غيركم، إلا أنه يقول: إنهم قد اختلفوا فيما بينهم وهم الأئمة القادة، فإذا اجتمعوا على رجل فقالوا هذا، قلنا هذا. فقال: إنْ مات على هذا فقد ماتَ ميتة جاهلية.","22/2/7/16",""],[17,7,"أخبرنا عبد الواحد بن عبد الله قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا أبو جعفر الهمداني، قال: حدثني موسى بن سعدان، عن محمد بن سنان عن عمار بن مروان عن سماعة بن مهران قال: قلت لأبي عبد الله: رجلٌ يتولّى علياً ويتبرأ من عدوه ويقول كل شيء يقول، إلاّ أنه يقول: إنهم قد اختلفوا بينهم وهم الأئمة القادة، فلست أدري أيّهم الإمام، فإذا اجتمعوا على رجل أخذت بقوله، وقد عرفت أن الأمر فيهم. قال: إنْ مات هذا على ذلك مات ميتة جاهلية. ثم قال: للقرآنِ تأويلٌ يجري كما يجري الليل والنهار وكما تجري الشمس والقمر، فإذا جاء تأويل شيء منه وقع، فمنه ما قد جاء، ومنه ما لم يجيء.","22/2/7/17",""],[18,7,"وأخبرنا سلامة بن محمد قال: حدثنا أحمد بن داود، قال: حدثنا علي بن الحسين بن بابويه، قال حدثنا سعد بن عبد الله، عن محمد بن الحسين بن أبي الخطاب، عن المفضل بن زائدة، عن المفضل بن عمر قال: قال أبو عبد الله: من دان الله بغير سماع من عالمٍ صادق ألزمه الله التيهَ إلى العناء، ومَن ادعى سماعاً من غير الباب الذي فتحه الله لخلقه فهو مشرك به، وذلك الباب هو الأمين المأمون على سر الله المكنون.","22/2/7/18",""],[19,7,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا يحيى بن زكريا بن شيبان في شعبان سنة ثلاث وسبعين ومائتين قال: حدثنا علي بن سيف بن عميرة، عن أبيه، عن حمران بن أعين أنه قال: وصفت لأبي عبد الله رجلاً يتوالى أمير المؤمنين ويتبرأ من عدوه، ويقول كل شيء يقول، إلا أنه يقول: إنهم اختلفوا فيما بينهم وهم الأئمة القادة، ولست أدري أيّهم الإمام، وإذا اجتمعوا على رجل واحد أخذنا بقوله، وقد عرفت أن الأمر فيهم - رحمهم الله جميعاً -. فقال: إنْ مات هذا مات ميتة جاهلية. وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الْإِنْسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا ۚ وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ","22/2/7/19",""],[1,8,"وأخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل وسعدان بن إسحاق وأحمد بن الحسين بن عبد الملك ومحمد بن أحمد القطواني قالوا: حدثنا الحسن بن محبوب، عن هشام بن سلام، عن أبي حمزة الثمالي، عن أبي إسحاق السبيعى قال: سمعت من يوثق به من أصحاب أمير المؤمنين يقول: قال أمير المؤمنين في خطبة خطبها بالكوفة طويلة ذكرها: اللهمّ فلا بدَّ لك من حجج في أرضك حجة بعد حجة على خلقك، يهدونهم إلى دينك، ويعلمونهم علمك لكيلا يتفرقَ أتباع أوليائك، ظاهر غير مطاع، أو مكتتم خائف يترقب، إن غاب عن الناس شخصُهم في حال هدنتهم في دولة الباطل فلن يغيب عنهم مبثوثُ علمهم، وآدابُهم في قلوب المؤمنين مثبتة، وهم بها عاملون، يأنسون بما يستوحش منه المكذبون ويأباه المسرفون بالله. كلام يكال بلا ثمنٍ لو كان مَن يسمعه بعقله فيعرفه ويؤمن به ويتبعه، وينهج نهجه فيفلح به؟ ثم يقول: فمن هذا؟ ولهذا يأرز العلم إذ لم يوجد حملةً يحفظونه ويؤدونه كما يسمعونه من العالم. اللهم وإني لأعلم أن العلم لا يأرز كله ولا ينقطع مواده فإنك لا تُخلي أرضك من حجة على خلقك إما ظاهر يطاع أو خائف مغمور ليس بمطاع لكيلا تبطل حجتك ويضل أولياؤك بعد إذ هديتهم.","22/2/8/1",""],[2,8,"حدثنا محمد بن يعقوب الكليني قال: حدثنا علي بن إبراهيم بن هاشم، عن أبيه، عن ابن أبي عمير، عن منصور بن يونس وسعدان بن مسلم، عن إسحاق بن عمار، عن أبي عبد الله قال: سمعته يقول: إن الأرض لا تخلو إلاّ وفيها عالِم كيما إن زاد المؤمنون شيئاً ردّهم، وإن نقصوا شيئا أتمّه لهم.","22/2/8/2",""],[3,8,"حدثنا محمد بن يعقوب، عن محمد بن يحيى، عن أحمد بن محمد، عن علي بن الحكم، عن الربيع بن محمد المسلي، عن عبد الله بن سليمان العامري، عن أبي عبد الله أنه قال: ما زالتِ الأرض إلاّ وللهِ فيها حجة يعرف الحلالَ والحرام ويدعو الناسَ إلى سبيل الله.","22/2/8/3",""],[4,8,"حدثنا محمد بن يعقوب، عن بعض رجاله، عن أحمد بن مهران، عن محمد بن علي، عن الحسين بن أبي العلاء، عن أبي عبد الله قال: قلت له: تبقى الأرض بغير إمام؟ قال: لا.","22/2/8/4",""],[5,8,"حدثنا محمد بن يعقوب، عن علي بن إبراهيم، عن محمد بن عيسى، عن يونس، عن ابن مسكان، عن أبي بصير، عن أبي عبد الله أنه قال: إنّ الله لم يدعِ الأرض بغير عالِم، ولولا ذلك لم يُعرف الحقّ من الباطل.","22/2/8/5",""],[6,8,"وعن علي بن إبراهيم، عن محمد بن عيسى، عن محمد بن الفضيل، عن أبي حمزة الثمالي، عن أبي جعفر الباقر أنه قال: واللهِ، ما ترك الله أرضَه منذ قبض الله آدمَ إلاّ وفيها إمامٌ يُهتدى به إلى الله، وهو حجته على عباده، ولا تبقى الأرض بغير إمام حجة لله على عباده.","22/2/8/6",""],[7,8,"وبه عن أبي حمزة قال: قلت لأبي عبد الله: أتبقى الأرض بغير إمام؟ فقال: لو بقِيتِ الأرضُ بغير إمام لَساختْ.","22/2/8/7",""],[8,8,"وبه عن محمد بن الفضيل، عن الرضا قال: قلت له: أتبقى الأرض بغير إمام؟ قال: لا. قلت: فإنا نروي عن أبي عبد الله أنها لا تبقى بغير إمام إلاّ أن يسخط الله على أهل الأرض (أو قال: على العباد). فقال: لا تبقى الأرضُ بغير إمام، ولو بقيت إذاً لساخت.","22/2/8/8",""],[9,8,"محمد بن يعقوب الكليني، عن علي بن إبراهيم، عن محمد بن عيسى، عن أبي عبد الله المؤمن، عن أبي هراسة، عن أبي جعفر الباقر أنه قال: لو أنّ الإمامَ رُفع من الأرض ساعةً لساخت بأهلها وماجتْ كما يموج البحرُ بأهله.","22/2/8/9",""],[10,8,"محمد بن يعقوب، عن الحسين بن محمد، عن معلي بن محمد، عن الوشاء قال: سألت الرضا: هل تبقى الأرض بغير إمام؟ قال: لا. قلت: إنا نروي أنها لا تبقى إلاّ أن يسخط الله على العباد. قال: لا تبقى، إذاً لَساختْ.","22/2/8/10",""],[1,9,"حدثنا عبد الواحد بن عبد الله قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا محمد بن الحسين بن أبي الخطاب، قال: حدثنا محمد بن سنان، عن أبي عمارة حمزة بن الطيار قال: سمعت أبا عبد الله يقول: لَو لَم يبقَ في الأرض إلاّ اثنانِ لكان الثاني منهما الحجّة.","22/2/9/1",""],[2,9,"حدثنا محمد بن يعقوب الكليني، عن عدة من رجاله وأحمد بن إدريس ومحمد بن يحيى جميعاً، عن أحمد بن محمد، عن محمد بن عيسى بن عبيد، عن محمد بن سنان، عن أبي عمارة حمزة بن الطيار، عن أبي عبد الله قال: لو بقيَ في الأرض اثنان لكان أحدهما الحجّة على صاحبه.","22/2/9/2",""],[3,9,"وأخبرنا محمد بن يعقوب، عن محمد بن يحيى، عمن ذكره، عن الحسن بن موسى الخشاب، عن جعفر بن محمد، عن كرام قال: قال أبو عبد الله: لو كان الناسُ رجُلَين لكان أحدهما الإمام. وقال: إنّ آخرَ من يموت الإمام لئلاّ يحتجّ أحدٌ على الله أنه تركه بغير حجة لله عليه.","22/2/9/3",""],[4,9,"محمد بن يعقوب، عن عدة من رجاله، عن أحمد بن محمد بن خالد البرقي، عن علي بن إسماعيل، عن محمد بن سنان، عن حمزة بن الطيار، قال: سمعت أبا عبد الله يقول: لَو لم يبقَ في الأرض إلا اثنان لكان أحدهما الحجّة (أو الثاني الحجّة).","22/2/9/4",""],[5,9,"محمد بن يعقوب، عن أحمد بن محمد، عن محمد بن الحسن، عن النهدي، عن أبيه، عن يونس بن يعقوب، عن أبي عبد الله أنه سمعه يقول: لَو لم يكن في الأرض إلاّ اثنان لكان أحدهما الإمام.","22/2/9/5",""],[1,10,"حدثنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك قال: حدثنا إسحاق بن سنان، قال: حدثنا عبيد بن خارجة، عن علي بن عثمان، عن فرات بن أحنف، عن أبي عبد الله جعفر بن محمد، عن آبائه ، قال: زاد الفراتُ على عهد أمير المؤمنين فركب هو وابناه الحسن والحسين فمرّ بثقيف، فقالوا قد جاء عليٌّ يرد الماء. فقال عليّ: أما والله لأقتَلنَّ أنا وابناي هذان وليبعثُنّ الله رجلاً من ولدي في آخر الزمان يطالب بدمائنا، وليغيّبنّ عنهم، تمييزاً لأهل الضلالة حتىّ يقول الجاهل: ما للهِ في آل محمد من حاجة.","22/2/10/1",""],[2,10,"أخبرنا محمد بن همام ومحمد بن الحسن بن محمد بن جمهور جميعاً، عن الحسن بن محمد بن جمهور، قال: حدثنا أبي، عن بعض رجاله، عن المفضل بن عمر قال: قال أبو عبد الله: خبرٌ تدريه خيرٌ من عشرٍ ترويه. إنّ لكل حقّ حقيقةً، ولكل صواب نوراً. ثم قال: إنّا والله لا نعُدّ الرجلَ من شيعتنا فقيهاً حتى يلحن له فيعرف اللحن. إنّ أمير المؤمنين قال على منبر الكوفة: إنّ من ورائكم فِتناً مظلمةً عمياءَ منكسفة لا ينجو منها إلا النومة. قيل: يا أمير المؤمنين وما النومة؟ قال: الذي يعرفُ الناس ولا يعرفونه. واعلموا أنّ الأرض لا تخلو من حجةٍ لله ولكن الله سيُعمي خلقَه عنها بظلمهم وجورهم وإسرافهم على أنفسهم. ولو خلَتِ الأرضُ ساعة واحدة من حجة لله لساخت بأهلها، ولكنّ الحجة يعرف الناس ولا يعرفونه كما كان يوسُف يعرف الناس وهم له منكرون. ثم تلا يَا حَسْرَةً عَلَى الْعِبَادِ ۚ مَا يَأْتِيهِمْ مِنْ رَسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ","22/2/10/2",""],[3,10,"أخبرنا أحمد بن محمد بن سعيد بن عقدة الكوفي، قال: حدثنا أحمد بن محمد الدينوري، قال: حدثنا علي بن الحسن الكوفي، عن عميرة بنت أوس قالت: حدثني جدي الحصين بن عبد الرحمن، عن أبيه، عن جده عمرو بن سعد، عن أمير المؤمنين علي بن أبي طالب أنه قال يوماً لحذيفة بن اليمان: يا حذيفة، لا تُحدّث الناس بما لا يعلمون فيطغوا ويكفروا. إنّ من العلم صعباً شديداً محملُه لو حملتْه الجبال عجزت عن حمله. إنّ عِلمنا أهل البيت سينكر ويبطل وتقتل رواتُه ويُساء إلى من يتلوه بغياً وحسداً لما فضّل الله به عترةَ الوصي وصيّ النبي . يا بن اليمان، إن النبي تفلَ في فمي وأمرّ يده على صدري وقال: اللهم أعطِ خليفتي ووصيي وقاضي ديني ومنجز وعدي وأمانتي ووليّي وناصري على عدوك وعدوي ومفرّجَ الكرب عن وجهي ما أعطيتَ آدم من العلم، وما أعطيت نوحاً من الحلم وإبراهيم من العترة الطيبة والسماحة، وما أعطيت أيوب من الصبر عند البلاء، وما أعطيت داود من الشدة عند منازلة الأقران، وما أعطيت سليمان من الفهم. اللّهم لا تُخف عن عليّ شيئاً من الدنيا حتى تجعلها كلّها بين عينيه مثل المائدة الصغيرة بين يديه. اللهم أعطه جلادة موسى، واجعل في نسله شبيهَ عيسى. اللّهم إنك خليفتي عليه وعلى عترته وذرّيته الطيبة المطهّرة التي أذهبتَ عنها الرجس والنجس وصرفتَ عنها ملامسة الشياطين. اللّهم إن بغَت قريش عليه وقدّمت غيرَه عليه فاجعله بمنْزلة هارون من موسى إذ غاب عنه موسى. ثم قال لي: يا عليُّ، كم في ولدك من ولد فاضل يُقتل والناس قيام ينظرون لا يغيّرون! فقُبّحت أمّة ترى أولاد نبيها يُقتلون ظلماً وهم لا يغيرون. إن القاتل والآمر والشاهد الذي لا يغير كلهم في الإثم واللّعان سواء مشتركون. يا ابن اليمان، إن قريشاً لا تنشرح صدورُها ولا ترضى قلوبها ولا تجري ألسنتُها ببيعة عليّ وموالاته إلاّ على الكُره والعمى والصغار. يا ابن اليمان، ستبايع قريشٌ علياً ثم تنكث عليه وتحاربه وتناضله وترميه بالعظائم، وبعد عليّ يلي الحسن وسينكث عليه، ثم يلي الحسينُ فتقتله أمّةُ جده، فلُعنت أمة تقتل ابنَ بنت نبيّها ولا تعز من أمة، ولعن القائد لها والمرتب لفاسقها، فوالذي نفسُ عليّ بيده لا تزال هذه الأمةُ بعد قتل الحسين ابني في ضلال وظلم وعسف وجور واختلافٍ في الدين وتغيير وتبديل لما أنزل الله في كتابه وإظهار البدع وإبطال السنن واختلال وقياسِ مشتبهات وتركِ محكمات حتى تنسلخ من الإسلام و تدخل في العمى والتلدد والتكسع. مالك يا بني أمية! لا هُديت يا بني أمية! ومالك يا بني العباس! لك الأتعاس، فما في بني أميّة إلا ظالم، ولا في بني العباس إلا معتدٍ متمرّد على الله بالمعاصي، قتّال لولدي، هتّاك لستري وحُرمتي، فلا تزال هذه الأمة جبارين يتكالبون على حرام الدنيا منغمسين في بحار الهلكات وفي أوديةِ الدماء، حتى إذا غاب المتغيّب من ولدي عن عيون الناس وماج الناس بفقده أو بقتله أو بموته، أطلعت الفتنة ونزلت البلية والتحمت العصبيةُ وغلا الناس في دينهم وأجمعوا على أن الحجّة ذاهبة والإمامة باطلة. ويحج حجيج الناس في تلك السنة من شيعة عليّ ونواصبه للتحسس والتجسس عن خلف الخلف، فلا يرى له أثر ولا يعرف له خبر ولا خلف، فعند ذلك سبّت شيعة عليٍّ، سبّها أعداؤها وظهرت عليها الأشرار والفساق باحتجاجِها حتى إذا بقيت الأمّة حيارى وتدلَّهت وأكثرت في قولها إن الحجة هالكة والإمامة باطلة، فوربِّ عليّ إن حجتها عليها قائمةٌ ماشيةٌ في طرقها داخلة في دورها وقصورها جوالةٌ في شرق هذه الارض وغربها، تسمع الكلام وتسلّم على الجماعة، ترى ولا ترى إلى الوقت والوعد ونداء المنادي من السماء ألا ذلك يوم فيه سرور ولدُ عليّ وشيعته.","22/2/10/3",""],[4,10,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن محمد الدينوري، قال: حدثنا علي بن الحسن الكوفي قال: حدثتنا عميرة بنت أوس، قالت: حدثني جدي الحصين بن عبد الرحمن، عن عبد الله بن ضمرة، عن كعب الأحبار أنه قال: إذا كان يوم القيامة حُشر الخلق على أربعة أصناف: صنف ركبان، وصنف على أقدامهم يمشون، وصنف مكبّون، وصنف على وجوههم صمّ بكم عمي فهم لا يعقلون ولا يُكلمون ولا يؤذن لهم فيعتذرون، أولئك الذين تلفح وجوههم النار وهم فيها كالحون. فقيل له: يا كعب، مَن هؤلاء الذين يحشرون على وجوههم وهذه الحال حالهم؟ فقال كعب: أولئك كانوا على الضلال والارتداد والنكث، فبئس ما قدمت لهم أنفسهم إذا لقوا الله بحرب خليفتهم ووصيّ نبيهم وعالمهم وسيدهم وفاضلهم وحامل اللواء وولي الحوض والمرتجى والرجا دون هذا العالم. وهو العلَم الذي لا يجهل والمحجة التي مَن زال عنها عطب وفي النار هوى، ذاك عليٌّ وربِّ كعب، أعلمُهم علماً وأقدمهم سلماً وأوفرهم حلماً. عجب كعبٌ ممّن قدم على عليٍّ غيره. ومن نسلِ عليٍّ القائمُ المهدي الذي يبدل الأرض غير الأرض، وبه يحتجّ عيسى بن مريم على نصارى الروم والصين، إن القائم المهدي من نسل عليّ أشبه الناس بعيسى بن مريم خلقاً وخلقاً وسمتاً وهيبة، يعطيه الله جلَّ وعزَّ ما أعطى الأنبياء ويزيده ويفضله. إنّ القائم من ولد علي له غيبةٌ كغيبة يوسف، ورجعة كرجعة عيسى بن مريم، ثم يظهر بعد غيبته مع طلوع النجم الأحمر وخراب الزوراء، وهي الريّ، وخسف المزورة وهي بغداد، وخروج السفياني، وحرب ولد العباس مع فتيان أرمينية وآذربيجان، تلك حرب يقتل فيها ألوف وألوف، كل يقبض على سيف محلّى، تخفق عليه رايات سود، تلك حرب يشوبها الموت الأحمر والطاعون الأغبر.","22/2/10/4",""],[5,10,"وبه عن الحصين بن عبد الرحمن، عن أبيه عن جده عمرو بن سعد قال: قال أمير المؤمنين: لا تقوم القيامةُ حتى تفقأ عين الدنيا وتظهر الحمرةُ في السماء، وتلك دموعُ حملة العرش على أهل الأرض حتى يظهر فيهم عصابة لا خَلاق لهم يدّعون لولدي وهم برآء من ولدي، تلك عصابة رديئة لا خلاق لهم، على الأشرار مسلطة، وللجبابرة مفتنة، وللملوك مبيرة، تظهر في سواد الكوفة، يقدمهم رجل أسود اللون والقلب، رثّ الدين، لا خلاق له مهجن زنيم عتل، تداولته أيدي العواهر من الأمهات مِن شرّ نسل لا سقاها الله المطر، في سنة إظهار غيبة المتغيّب من ولدي صاحب الراية الحمراء والعلَم الأخضر. أيّ يوم للمخيّبين بين الأنبار وهيت، ذلك يوم فيه صيلم الأكراد والشراة وخراب دار الفراعنة ومسكن الجبابرة، ومأوى الولاة الظلمة، وأم البلاد وأخت العاد، تلك وربّ عليّ، يا عمرو بن سعد، بغدادُ، ألا لعنة الله على العصاة من بني أمية وبني العباس الخونة الذين يقتلون الطيّبين من ولدي ولا يراقبون فيهم ذمتي ولا يخافون الله فيما يفعلونه بحرمتي. إن لبني العباس يوماً كيوم الطموح ولهم فيه صرخة كصرخة الحُبلى. الويل لشيعة ولد العباس من الحرب التي سنح بين نهاوند والدينور، تلك حرب صعاليك شيعة عليّ يقدمهم رجل من همدان اسمه على اسم النبي . منعوت موصوف باعتدال الخلق وحسن الخلُق ونضارة اللون، له في صوته ضجاج وفي أشفاره وطف وفي عنقه سطع، أفرق الشعر مفلّج الثنايا، على فرسه كبدر تمام إذا تجلّى عند الظلام، يسير بعصابة خير عصابة آوت وتقربت ودانت لله بدين تلك الأبطال من العرب الذين يلحقون حرب الكريهة، والدبَرة يومئذ على الاعداء، إنّ للعدو يوم ذاك الصليم والاستئصال.","22/2/10/5",""],[6,10,"أخبرنا سلامة بن محمد قال: حدثنا علي بن داود، قال: حدثنا أحمد بن الحسن، عن عمران بن الحجاج، عن عبد الرحمن بن أبي نجران، عن محمد بن أبي عمير، عن محمد بن إسحاق، عن أسيد بن ثعلبة، عن أم هانئ، قالت: قلت لأبي جعفر محمد بن علي الباقر: ما معنى قول الله فَلَا أُقْسِمُ بِالْخُنَّسِ فقال: يا أمّ هانئ، إمامٌ يخنس نفسه حتى ينقطع عن الناس علمه سنة ستين ومائتين ثم يبدو كالشهاب الواقد في الليلة الظلماء، فإنْ أدركتِ ذلك الزمان قرّت عينك.","22/2/10/6",""],[7,10,"محمد بن يعقوب، عن عدة من رجاله، عن سعد بن عبد الله، عن أحمد بن الحسن، عن عمر بن يزيد، عن الحسن بن أبي الربيع الهمداني، قال: حدثنا محمد ابن إسحاق، عن أسيد بن ثعلبة، عن أم هانئ قالت: لقيت أبا جعفر محمد بن علي الباقر فسألته عن هذه الآية فَلَا أُقْسِمُ بِالْخُنَّسِ {15} الْجَوَارِ الْكُنَّسِ {16} فقال: الخُنّس إمامٌ يخنس نفسه في زمانه عند انقطاعٍ من علمه عند الناس سنة ستين ومائتين، ثم يبدو كالشهاب الواقد في ظلمه الليل، فإذا أدركتِ ذلك قرّت عينُك.","22/2/10/7",""],[8,10,"محمد بن همام قال: حدثنا أحمد بن مابنداذ قال: حدثنا محمد بن مالك، قال: حدثنا محمد بن سنان، عن الكاهلي عن أبي عبد الله أنه قال: تواصَلوا وتبارّوا وتراحموا، فوالذي فلق الحبّة وبرأ النسَمة ليأتينّ عليكم وقتٌ لا يجد أحدُكم لديناره ودرهمِه موضعاً. فقلت: وأنى يكون ذلك؟ فقال: عند فقدِكم إمامَكم، فلا تزالون كذلك حتى يطلع عليكم كما تطلع الشمس آيسُ ما تكونون، فإيّاكم والشك والإرتياب، وانفوا عن أنفسكم الشكوكَ وقد حذرتُكم فاحذروا، أسأل الله توفيقَكم وإرشادكم.","22/2/10/8",""],[9,10,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أحمد بن محمد بن رباح الزهري، عن أحمد بن علي الحميري، عن الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن محمد بن عصام، قال: حدثني المفضل بن عمر قال: كنت عند أبي عبد الله في مجلسه ومعي غيري، فقال لنا: إياكم والتنويه. وكنت أراه يريد غيري، فقال لي: يا أبا عبد الله، إياكم والتنويه، واللهِ ليغيبنّ سبتاً من الدهر، وليخملنّ حتى يقال: مات أو هلك؟ بأيّ واد سلك؟ ولتفيضنّ عليه أعينُ المؤمنين وليكفأن كتكفّئ السفينة في أمواج البحر حتى لا ينجو إلاّ مَن أخذ الله ميثاقه وكتب الإيمان في قلبه وأيّده بروح منه. ولترفعنّ اثنتا عشرة راية مشتبهة لا يعرف أيّ من أيّ. قال المفضل: فبكيت، فقال لي: ما يبكيك؟ قلت: جعلت فداك، كيف لا أبكي وأنت تقول: ترفع اثنتا عشرة راية مشتبهة لا يعرف أيّ من أيّ؟ (قال) فنظرَ إلى كوّة في البيت التي تطلع فيها الشمس في مجلسه فقال: أهذه الشمس مضيئة؟ قلت: نعم؟ فقال: واللهِ لأمرُنا أضوء منها.","22/2/10/9",""],[10,10,"محمد بن همام قال: حدثنا جعفر بن محمد بن مالك وعبد الله بن جعفر الحميري جميعاً قالا: حدثنا محمد بن الحسين بن أبي الخطاب ومحمد بن عيسى وعبد الله بن عامر القصباني جميعاً، عن عبد الرحمن بن أبي نجران، عن محمد بن مساور، عن المفضل بن عمر الجعفي قال: سمعت الشيخ - يعني أبا عبد الله - يقول: إيّاكم والتنويه، أما والله ليغيبنّ سبتاً من دهركم، وليخملنّ حتى يقال: مات، هلك، بأيّ وادٍ سلك؟ ولتدمعنّ عليه عيون المؤمنين وليكفأن تكفّأ السفينة في أمواج البحر فلا ينجو إلاّ مَن أخذ الله ميثاقه وكتب في قلبه الإيمان وأيّده بروح منه، ولترفعنّ اثنتا عشرة رايةً مشتبهة لا يدرى أيّ من أيّ. (قال) فبكيت ثم قلت له: كيف نصنع؟ فقال: يا أبا عبد الله، - ثم نظر إلى شمس داخلة في الصفّة - أترى هذه الشمس؟ فقلت: نعم. فقال: لأمرُنا أبْيَنُ من هذه الشمس.","22/2/10/10",""],[11,10,"حدثنا محمد بن يعقوب الكليني - رحمه الله - عن علي بن محمد، عن الحسن بن عيسى بن محمد بن علي بن جعفر، عن أبيه، عن جده، عن علي بن جعفر، عن أخيه موسى بن جعفر أنه قال: إذا فُقد الخامسُ من ولد السابع فاللهَ اللهَ في أديانكم؛ لا يُزيلنّكم عنها، فإنه لا بُدّ لصاحب هذا الأمر من غيبةٍ حتى يرجع عن هذا الأمر مَن كان يقول به، إنما هي محنة من الله يمتحن الله بها خلقَه، ولو علم آباؤكم وأجدادكم ديناً أصحّ من هذا الدين لأتّبعوه. (قال) قلت: يا سيدي، مَن الخامس من ولد السابع؟ فقال: يا بنيّ، عقولُكم تصغر عن هذا وأحلامُكم تضيق عن حمله، ولكن إنْ تعيشوا فسوف تدرِكونه.","22/2/10/11",""],[12,10,"أخبرنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي سنة ثلاث وسبعين ومائتين قال: حدثنا عبد الله بن حماد الأنصاري سنة تسع وعشرين ومائتين، عن أبي الجارود، عن أبي جعفر قال: قال لي: يا أبا الجارود، إذا دار الفلك وقالوا: مات أو هلك، وبأيّ واد سلك، وقال الطالب له: إنّى يكون ذلك وقد بُليت عظامه فعند ذلك فارتَجوه، وإذا سمِعتم به فأتوه ولو حَبواً على الثلج.","22/2/10/12",""],[13,10,"أخبرنا محمد بن همام - رحمه الله - قال: حدثنا حميد بن زياد، عن الحسن بن محمد بن سماعة، عن أحمد بن الحسن الميثمي، عن زائدة بن قدامة، عن بعض رجاله عن أبي عبد الله قال: إنّ القائم إذا قام يقول الناس: أنّى ذلك وقد بُليت عظامه؟","22/2/10/13",""],[14,10,"حدثنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أحمد بن محمد بن رباح الزهري، عن أحمد بن علي الحميري، عن الحسن بن أيوب، عن عبد الكريم بن عمرو، عن محمد بن الفضيل عن حماد بن عبد الكريم الجلاب قال: ذكر القائم عند أبي عبد الله فقال: أما إنّه لو قد قام لقالَ الناس: أنىّ يكون هذا وقد بُليت عظامه مُذ كذا وكذا؟","22/2/10/14",""],[15,10,"حدثنا علي بن أحمد البندنيجي قال: حدثنا عبيد الله بن موسى العلوي العباسي، عن موسى بن سلام، عن أحمد بن محمد بن أبي نصر، عن عبد الرحمن، عن الخشاب، عن أبي عبد الله عن آبائه قال: قال رسول الله: مثَلُ أهل بيتي مثل نجوم السماء؛ كلما غاب نجمٌ طلع نجم حتى إذا نجم منها طلع فرمقتُموه بالأعين وأشرتُم إليه بالأصابع أتاه ملَك الموت فذهب به، ثم لبثتم في ذلك سبتاً من دهركم واستوت بنو عبد المطلب ولم يُدرَ أيّ من أيّ، فعند ذلك يبدو نجمُكم فاحمدوا الله واقبلوه.","22/2/10/15",""],[16,10,"وأخبرنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك وعبد الله بن جعفر الحميري قالا: حدثنا محمد بن الحسين بن أبي الخطاب ومحمد بن عيسى وعبد الله بن عامر القصباني جميعاً، عن عبد الرحمن بن أبي نجران، عن الخشاب عن معروف بن خربوذ، عن أبي جعفر قال: سمعته يقول: قال رسول الله: إنّما مثلُ أهل بيتي في هذه الأمة كمثل نجوم السماء كلّما غاب نجمٌ طلع نجم حتى إذا مدَدتم إليه حواجبَكم وأشرتُم إليه بالأصابع أتاه ملَك الموت فذهب به، ثم بقيتم سبتاً من دهركم لا تدرون أيّاً من أيٍّ، فاستوى في ذلك بنو عبد المطلب، فبينما أنتم كذلك إذ أطلع الله عليكم نجمَكم فاحمِدوه واقبلوه.","22/2/10/16",""],[17,10,"حدثنا محمد بن يعقوب الكليني قال: حدثنا علي بن إبراهيم بن هاشم، عن أبيه، عن حنان بن سدير، عن معروف بن خربوذ، عن أبي جعفر أنه قال: إنما نحن كنجوم السماء؛ كلّما غاب نجمٌ طلع نجم حتى إذا أشرتم بأصابعكم وملتُم بحواجبكم غيّب الله عنكم نجمَكم، فاستوت بنو عبد المطلب فلم يُعرف أيّ من أيّ، فإذا طلع نجمكم فاحمدوا ربكم.","22/2/10/17",""],[18,10,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي قال: حدثنا عيسى بن عبد الله بن محمد بن عمر بن علي بن أبي طالب، عن أبيه، عن جده، عن أبيه أمير المؤمنين أنه قال: صاحبُ هذا الأمر من ولدي هو الذي يقال: مات أو هلك، لا بل في أيّ وادٍ سلك.","22/2/10/18",""],[19,10,"وبه عن محمد بن علي الكوفي قال: حدثنا يونس بن يعقوب، عن المفضل بن عمر قال: قلت لأبي عبد الله: ما علامة القائم؟ قال: إذا استدار الفلكُ فقيل: مات أو هلك، في أيّ واد سلك؟ قلت: جعلت فداك ثم يكون ماذا؟ قال: لا يظهر إلاّ بالسيف.","22/2/10/19",""],[20,10,"حدثنا محمد بن همام قال: حدثنا حميد بن زياد الكوفي، قال: حدثنا الحسن بن محمد بن سماعة، عن أحمد بن الحسن الميثمي، عن زائدة بن قدامة، عن عبد الكريم قال: ذُكر عند أبي عبد الله القائم، فقال: أنّى يكون ذلك ولَم يستدِر الفلكُ حتى يقال: ماتَ أو هلك، في أيّ وادٍ سلك؟ فقلت: وما استدارة الفلك؟ فقال: اختلافُ الشيعة بينهم.","22/2/10/20",""],[21,10,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام الناشري، عن عبد الله بن جبلة، عن فضيل الصائغ، عن محمد بن مسلم الثقفي، عن أبي عبد الله أنه قال: إذا فقد الناس الإمامَ مكثوا سنينَ لا يدرون أيّا من أيّ، ثم يُظهر الله لهم صاحبهم.","22/2/10/21",""],[22,10,"وبه، عن عبد الله بن جبلة، عن علي بن الحارث بن المغيرة، عن أبيه قال: قلت لأبي عبد الله: يكون فترةٌ لا يعرف المسلمون فيها إمامَهم؟ فقال: يقال ذلك. قلت: فكيف نصنع؟ قال: إذا كان ذلك فتمسكوا بالأمر الأول حتى يبين لكم الآخر.","22/2/10/22",""],[23,10,"وبه، عن عبد الله بن جبلة، عن محمد بن منصور الصيقل، عن أبيه منصور قال: قال أبو عبد الله: إذا أصبحتَ وأمسيت يوماً لا ترى فيه إماماً من آل محمد فأحْبِب مَن كنت تحب وأبغض من كنت تبغض ووالِ من كنتَ توالي وانتظر الفرجَ صباحاً ومساء.","22/2/10/23",""],[24,10,"حدثنا محمد بن همام قال: حدثنا عبد الله بن جعفر الحميري، عن محمد بن عيسى والحسن بن ظريف جميعاً، عن حماد بن عيسى، عن عبد الله بن سنان قال: دخلت أنا وأبي على أبي عبد الله فقال: كيف أنتم إذا صِرتم في حال لا ترَون فيها إمامَ هدى ولا علماً يُرى؟ فلا ينجو من تلك الحَيرة إلاّ مَن دعا بدعاء الغريق. فقال أبي: هذا واللهِ البلاءُ، فكيف نصنع، جُعلتُ فداك، حينئذ؟ قال: إذا كان ذلك - ولن تدركَه - فتمسّكوا بما في أيديكم حتى يتضحَ لكم الأمر.","22/2/10/24",""],[25,10,"وبه، عن محمد بن عيسى والحسن بن ظريف، عن الحارث بن المغيرة النصري، عن أبي عبد الله قال: قلت له: إنا نروي بأنّ صاحب هذا الأمر يُفقد زماناً، فكيف نصنع عند ذلك؟ قال: تمسكوا بالأمرِ الأول الذي أنتم عليه حتى يبين لكم.","22/2/10/25",""],[26,10,"محمد بن همام بإسناده يرفعه إلى أبان بن تغلب، عن أبي عبد الله أنه قال: يأتي على الناس زمانٌ يصيبهم فيها سبطة يأرز العلم فيها كما تأرز الحيّة في جحرها، فبينما هم كذلك إذ طلع عليهم نجم. قلت: فما السبطة؟ قال: الفترة. قلت: فكيف نصنع فيما بين ذلك؟ فقال: كونوا على ما أنتم عليه حتىّ يطلع الله لكم نجمَكم.","22/2/10/26",""],[27,10,"وبه، عن أبان بن تغلب، عن أبي عبد الله أنه قال: كيف أنتم إذا وقعت السّبطة بين المسجدَين فيأرز العلم فيها كما تأرز الحيةُ في جحرها واختلفت الشيعةُ بينهم وسمّى بعضُهم بعضاً كذّابين، ويتفل بعضُهم في وجوه بعض. فقلت: ما عند ذلك مِن خير؟ قال: الخير كلّه عند ذلك - يقوله ثلاثا - يريد قرب الفرج.","22/2/10/27",""],[28,10,"حدثنا أحمد بن هوذة الباهلي أبو سليمان، قال: حدثنا إبراهيم بن إسحاق النهاوندي، قال: حدثنا عبد الله بن حماد الأنصاري، عن أبان بن تغلب، عن أبي عبد الله أنه قال: يا أبان، يصيب العلم سبطةٌ، يأرز العلم بين المسجدين كما تأرز الحية في جحرها. قلت: فما السبطة؟ قال: دون الفترة، فبينَما هم كذلك إذ طلع لهم نجمُهم. فقلت: جُعلت فداك، فكيف نصنع وكيف يكون ما بين ذلك؟ فقال لي: ما أنتم عليه حتى يأتيكم الله بصاحبها. لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا ۚ قَدْ يَعْلَمُ اللَّهُ الَّذِينَ يَتَسَلَّلُونَ مِنْكُمْ لِوَاذًا ۚ فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ ۖ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا وَأَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَاحْذَرُوا ۚ فَإِنْ تَوَلَّيْتُمْ فَاعْلَمُوا أَنَّمَا عَلَىٰ رَسُولِنَا الْبَلَاغُ الْمُبِينُ","22/2/10/28",""],[29,10,"أخبرنا محمد بن همام، عن بعض رجاله، عن أحمد بن محمد بن خالد، عن أبيه عن رجل، عن المفضل بن عمر، عن أبي عبد الله أنه قال: أقرب ما يكون هذه العصابةُ من الله وأرضى ما يكون عنهم إذا افتَقدوا حجةّ الله، فحُجب عنهم ولم يظهر لهم ولم يعلَموا بمكانه وهم في ذلك يعلمون ويوقنون أنه لم تبطل حجة ُالله ولا ميثاقه، فعندها توقّعوا الفرج صباحاً ومساءً فإنّ أشد ما يكون غضبُ الله على أعدائه إذا افتقدوا حجتَه فلم يظهر لهم. وقد علم الله أنّ أولياءه لا يرتابون، ولو علم أنهم يرتابون ما غيّب حجته طرفة عين عنهم، ولا يكون ذلك إلاّ على رأس شرار الناس.","22/2/10/29",""],[30,10,"حدثنا محمد بن يعقوب الكليني، قال: حدثنا علي بن إبراهيم بن هاشم، عن أبيه عن محمد بن خالد، عمن حدثه، عن المفضل بن عمر. قال الكليني: وحدثنا محمد بن يحيى، عن عبد الله بن محمد بن عيسى، عن أبيه، عن بعض رجاله، عن المفضل بن عمر، عن أبي عبد الله أنه قال: أقربُ ما يكون العباد من الله وأرضى ما يكون عنهم إذا افتقدوا حجة الله ولم يظهر لهم، ولم يعلموا بمكانه، وهم في ذلك يعلمون أنه لم تبطلْ حجة الله جلّ ذِكره ولا ميثاقه، فعندها فتوقّعوا الفرج صباحاً ومساء، فإنّ أشدّ ما يكون غضبُ الله على أعدائه إذا افتقدوا حجةَ الله فلم يظهر لهم، وقد علم الله أنّ أولياءه لا يرتابون ولو علِم أنهم يرتابون ما غيّب حجته عنهم طرفة عين، ولا يكون ذلك إلاّ على رأس شرارِ الناس.","22/2/10/30",""],[31,10,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل وسعدان بن إسحاق بن سعيد وأحمد بن الحسين ومحمد بن أحمد بن الحسن القطواني جميعاً، عن الحسن بن محبوب، عن هشام بن سالم الجواليقي، عن يزيد الكناسي قال: سمعت أبا جعفر الباقر يقول: إنّ صاحب هذا الأمر فيه شبهٌ من يوسف، ابن أمَة سوداء، يصلح الله له أمره في ليلة.","22/2/10/31",""],[32,10,"حدثنا علي بن أحمد قال: حدثنا عبيد الله بن موسى العلوي، عن أحمد بن الحسين، عن أحمد بن هلال، عن عبد الرحمن بن أبي نجران، عن فضالة بن أيوب، عن سدير الصيرفي قال: سمعت أبا عبد الله الصادق يقول: إنّ في صاحب هذا الأمر لشبهاً من يوسف. فقلت: فكأنك تخبّرنا بغيبة أو حَيرة. فقال: ما ينكر هذا الخلق الملعون أشباه الخنازير من ذلك؟ إنّ إخوة يوسف كانوا عقلاء ألبّاء أسباطاً أولاد انبياء، دخلوا عليه فكلّموه وخاطبوه وتاجروه وراودوه وكانوا إخوتَه وهو أخوهم لم يعرفوه حتىّ عرّفهم نفسه وقال لهم: أنا يوسف، فعرفوه حينئذ. فما تُنكر هذه الأمّة المتحيرة أن يكون الله يريد في وقت من الأوقات أن يستر حجته عنهم؟ لقد كان يوسف إليه مُلك مصر، وكان بينه وبين أبيه مسيرة ثمانية عشر يوماً، فلو أراد أن يعلمه بمكانه لقدر على ذلك، واللهِ لقد سار يعقوب وولده عند البشارة تسعة أيام من بَدوهم إلى مصر. فما تنكر هذه الأمة أن يكون الله يفعل بحجّته ما فعل بيوسف؟ وأن يكون صاحبُكم المظلوم المجحود حقّه صاحب هذا الأمر يتردّد بينهم ويمشي في أسواقهم ويطأ فرشَهم ولا يعرفونه حتى يأذن الله له أن يعرّفهم نفسه كما أذِن ليوسف حين قال له إخوته قَالُوا أَإِنَّكَ لَأَنْتَ يُوسُفُ ۖ قَالَ أَنَا يُوسُفُ وَهَٰذَا أَخِي ۖ قَدْ مَنَّ اللَّهُ عَلَيْنَا ۖ إِنَّهُ مَنْ يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ","22/2/10/32",""],[33,10,"وحدثنا علي بن أحمد، عن عبيد الله بن موسى، عن عبد الله بن جبلة، عن الحسن بن علي بن أبي حمزة، عن أبي بصير قال: سمعت أبا جعفر الباقر يقول: في صاحب هذا الأمر سننٌ من أربعة أنبياء؛ سنّةٌ من موسى وسنةٌ من عيسى وسنةٌ من يوسف وسنة من محمدٍ صلوات الله عليهم أجمعين. فقلت: ما سنة موسى؟ قال: خائف يترقب. قلت: وما سنة عيسى؟ فقال: يقال فيه ما قيل في عيسى. قلت: فما سنة يوسف؟ قال: السجن والغيبة. قلت: وما سنّة محمد ؟ قال: إذا قام سار بسيرة رسول الله إلاّ أنه يبين آثار محمّد ويضع السيفَ على عاتقه ثمانية أشهر هرجاً هرجاً حتى يرضى الله. قلت: فكيف يعلم رضا الله؟ قال: يُلقي الله في قلبه الرحمةَ. قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ إِلَّا عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَآمُرَنَّهُمْ فَلَيُبَتِّكُنَّ آذَانَ الْأَنْعَامِ وَلَآمُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ اللَّهِ ۚ وَمَنْ يَتَّخِذِ الشَّيْطَانَ وَلِيًّا مِنْ دُونِ اللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُبِينًا قَالَ فَبِمَا أَغْوَيْتَنِي لَأَقْعُدَنَّ لَهُمْ صِرَاطَكَ الْمُسْتَقِيمَ أنا حبلُ الله المتين، وأنا الصراط المستقيم، وأنا الحجة لله على خلقه أجمعين بعد رسوله الصادق الأمين. وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينَ إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ إِلَّا مَنِ اتَّبَعَكَ مِنَ الْغَاوِينَ","22/2/10/33",""],[34,10,"حدثنا محمد بن همام - رحمه الله - قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا عباد بن يعقوب، عن يحيى بن يعلى، عن زرارة قال: سمعت أبا عبد الله يقول: إنّ للقائم غيبةً قبل أن يقوم. فقلت: ولِمَ؟ قال: يخاف. -وأومأَ بيدِه إلى بطنه.- ثم قال: يا زرارةُ، وهو المنتظَر وهو الذي يُشكّ في ولادته، فمِنهم من يقول: مات أبوه بلا خلفٍ، ومنهم من يقول: حُمل، ومنهم من يقول: غائبٌ، ومنهم من يقول وُلد قبل وفاة أبيه بسنين وهو المنتظَر غير أن الله يحبّ أن يمتحن قلوبَ الشيعة، فعند ذلك يرتاب المبطلونُ يا زرارة. قال زرارة: قلت: جعلتُ فداك، إن أدركتُ ذلك الزمان أيَّ شيء أعمل؟ قال: يا زرارة، متى أدركتَ ذلك الزمان فادعُ بهذا الدعاء: اللّهمّ عرّفني نفسَك فإنّك إن لم تُعرّفني نفسك لم أعرِف نبيّك، اللّهم عرّفني رسولَك فإنّك إنْ لم تُعرّفني رسولَك لم أعرِف حجَّتَك، اللّهم عرّفني حجّتَك فإنّك إنْ لم تُعرّفني حجّتَك ضَللتُ عن ديني. ثم قال: يا زرارةُ، لا بُدّ من قتلِ غلام بالمدينة. قلت: جعلت فداك، أوَليسَ الذي يقتله جيشُ السفياني؟ قال: لا، ولكن يقتله جيشُ بني فلان يخرج حتىّ يدخل المدينة، ولا يدري الناسُ في أيّ شيء دخل، فيأخذ الغلامَ فيقتله فإذا قتله بغياً وعدواناً وظلماً لم يُمهِلهم الله، فعند ذلك يتوقع الفرج.","22/2/10/34",""],[35,10,"حدثنا محمد بن همام بإسناد له عن عبد الله بن عطاء المكي قال: قلت لأبي جعفر: إن شيعتَك بالعراق كثيرة وواللهِ ما في أهل بيتك مثلك، فكيف لا تخرج؟ فقال: يا عبد الله بن عطاء، قد أخذتَ تفرش أذُنَيك للنوكى! إي واللهِ ما أنا بصاحبكم. قلت: فمَن صاحبنا؟ فقال: انظروا مَن غُيّبتْ عن الناس ولادتُه، فذلك صاحبكم، إنه ليس منّا أحدٌ يُشار إليه بالأصابع ويمضغ بالألسن إلاّ مات غيظاً أو حتف أنفه.","22/2/10/35",""],[36,10,"حدثنا علي بن أحمد، عن عبيد الله بن موسى العلوي قال: حدثني محمد بن أحمد القلانسي بمكة سنة سبع وستين ومائتين قال: حدثنا علي بن الحسن، عن العباس بن عامر، عن موسى بن هلال، عن عبد الله بن عطاء المكي قال: خرجت حاجّاً من واسط فدخلتُ على أبي جعفر محمد بن علي فسألني عن الناس والأسعار، فقلت: تركت الناسَ مادّينَ أعناقهم إليك لو خرجت لاتَّبَعك الخلقُ. فقال: يا بن عطا، قد أخذتَ تفرش أذُنَيك للنوكى! لا والله ما أنا بصاحبكم ولا يُشار إلى رجل منّا بالأصابع ويمطّ إليه بالحواجب إلاّ مات قتيلاً أو حتف أنفه. قلت: وما حتفُ أنفه؟ قال: يموت بغيظه على فراشه، حتىّ يبعث الله مَن لا يؤبَه لولادته. قلت: ومَن لا يؤبه لولادته؟ فقال: انظر مَن لا يدري الناس أنّه وُلد أم لا، فذاك صاحبكم.","22/2/10/36",""],[37,10,"حدثنا محمد بن يعقوب قال: حدثنا عدة من أصحابنا، عن سعد بن عبد الله عن أيوب بن نوح قال: قلت لأبي الحسن الرضا:إنا نرجو أن تكون صاحبَ هذا الأمر وأن يسوقه الله إليك عفواً بغير سيف، فقد بويع لك، وقد ضُربتْ الدراهم باسمِك. فقال: ما منّا أحدٌ اختلفت الكتب إليه وأشير إليه بالأصابع وسئل عن المسائل وحملت إليه الأموال إلاّ اغتيل أو مات على فراشه حتى يبعث الله لهذا الأمر غلاماً منّا خفيَّ المولد والمنشأ، غيرَ خفيٍّ في نسبه.","22/2/10/37",""],[38,10,"وحدثنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا عباد بن يعقوب، عن يحيى بن يعلي، عن أبي مريم الأنصاري، عن عبد الله بن عطاء قال: قلت لأبي جعفر الباقر: أخبرني عن القائم . فقال: واللهِ ما هو أنا ولا الذي تمدّون إليه أعناقكم، ولا يُعرف ولادته. قلت: بما يسير. قال: بما سار به رسول الله ، هدر ما قبله واستقبل.","22/2/10/38",""],[39,10,"حدثنا محمد بن همام قال: حدثنا عبد الله بن جعفر الحميري، عن محمد بن عيسى، عن صالح بن محمد، عن يمان التمار قال: قال أبو عبد الله: إنّ لصاحب هذا الأمر غيبةً، المتمسّكُ فيها بدينه كالخارط لشَوك القتاد بيده. ثم أطرق ملياً، ثم قال: إنّ لصاحب هذا الأمر غيبةً فليتّقِ الله عبدٌ وليتمسّكْ بدينه. لا تستوحِشوا في طريق الهدى لقلّة مَن يسلكه.","22/2/10/39",""],[40,10,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن التيملي، عن عمر بن عثمان، عن الحسن بن محبوب، عن إسحاق بن عمار الصيرفي قال: سمعت أبا عبد الله يقول: للقائم غيبتان إحداهما طويلة، والأخرى قصيرة. فالأولى يعلم بمكانه فيها خاصةٌ من شيعته، والأخرى لا يعلم بمكانه فيها إلاّ خاصة مواليه في دينه.","22/2/10/40",""],[41,10,"حدثنا محمد بن يعقوب، عن محمد بن يحيى، عن محمد بن الحسين، عن الحسن بن محبوب، عن إسحاق بن عمار قال: قال أبو عبد الله: للقائم غيبتان إحداهما قصيرة، والأخرى طويلة، الغيبة الأولى لا يعلم بمكانه فيها إلاّ خاصة شيعته، والأخرى لا يعلم بمكانه فيها إلاّ خاصة مواليه في دينه.","22/2/10/41",""],[42,10,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، قال: حدثنا عبد الرحمن بن أبي نجران، عن علي بن مهزيار، عن حماد بن عيسى، عن إبراهيم بن عمر اليماني قال: سمعت أبا جعفر يقول: إنّ لصاحب هذا الأمر غيبتَين. وسمعته يقول: لا يقوم القائم ولأحد في عنقه بيعة.","22/2/10/42",""],[43,10,"حدثنا محمد بن يعقوب قال: حدثنا محمد بن يحيى، عن أحمد بن محمد، عن الحسين بن سعيد، عن ابن أبي عمير، عن هشام بن سالم، عن أبي عبد الله قال: يقوم القائم وليس لأحدٍ في عنقه عقد ولا عهد ولا بيعة.","22/2/10/43",""],[44,10,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم من كتابه قال: حدثنا عبيس بن هشام، عن عبد الله بن جبلة، عن إبراهيم بن المستنير عن المفضل بن عمر الجعفي، عن أبي عبد الله الصادق قال: إنّ لصاحب هذا الأمر غيبتين إحداهما تطول حتى يقول بعضهم: ماتَ، وبعضهم يقول: قُتل، وبعضهم يقول: ذهبَ، فلا يبقى على أمره من أصحابه إلاّ نفر يسيرٌ، لا يطلع على موضعه أحدٌ من وليّ ولا غيره إلاّ المولى الذي يلى أمره.","22/2/10/44",""],[45,10,"وبه، عن عبد الله بن جبلة، عن سلمة بن جناح، عن حازم بن حبيب قال: دخلت على أبي عبد الله فقلت له: أصلحك الله، إن أبويّ هلكا ولم يحجّا وإن الله قد رزق وأحسن فما تقول في الحج عنهما؟ فقال: افعل فإنه يبرد لهما. ثم قال لي: يا حازم، إنّ لصاحب هذا الأمر غيبتَين يظهر في الثانية، فمن جاءك يقول إنه نفضَ يده من تراب قبره فلا تصدقْه.","22/2/10/45",""],[46,10,"أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل بن إبراهيم بن قيس وسعدان بن إسحاق بن سعيد: وأحمد بن الحسين بن عبد الملك ومحمد بن أحمد بن الحسن القطواني قالوا جميعاً: حدثنا الحسن بن محبوب، عن إبراهيم بن زياد الخارقي، عن أبي بصير قال: قلت لأبي عبد الله: كان أبو جعفر يقول: لقائم آل محمّد غيبتان إحداهما أطول من الأخرى. فقال: نعم، ولا يكون ذلك حتى يختلف سيفُ بني فلان وتضيق الحلقة ويظهر السفياني ويشتد البلاء ويشمل الناسَ موت وقتل يلجأون فيه إلى حرم الله وحرم رسوله .","22/2/10/46",""],[47,10,"عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح، قال: حدثنا أحمد بن علي الحميري قال: حدثنا الحسن بن أيوب، عن عبد الكريم بن عمرو، عن العلاء بن رزين، عن محمد بن مسلم الثقفي، عن الباقر أبى جعفر أنه سمعه يقول: إنّ للقائم غيبتين يقال له في إحداهما: هلك ولا يُدرى في أيّ وادٍ سلك.","22/2/10/47",""],[48,10,"محمد بن يعقوب قال: حدثنا محمد بن يحيى وأحمد بن إدريس، عن الحسن بن علي الكوفي، عن علي بن حسان، عن عبد الرحمن بن كثير، عن المفضل بن عمر قال: سمعت أبا عبد الله يقول: إن لصاحب هذا الأمر غيبتين، يرجع في إحداهما إلى أهله والأخرى يقال: هلك، في أيّ وادٍ سلك. قلت: كيف نصنع إذا كان ذلك؟ قال: إن ادّعى مدّعٍ فاسألوه عن تلك العظائم التي يجيب فيها مثله. مَا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنْتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ ۗ وَمَا كَانَ اللَّهُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ وَلَٰكِنَّ اللَّهَ يَجْتَبِي مِنْ رُسُلِهِ مَنْ يَشَاءُ ۖ فَآمِنُوا بِاللَّهِ وَرُسُلِهِ ۚ وَإِنْ تُؤْمِنُوا وَتَتَّقُوا فَلَكُمْ أَجْرٌ عَظِيمٌ","22/2/10/48",""],[49,10,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم قال: حدثنا عبيس بن هشام، عن عبد الله بن جبلة، عن أحمد بن الحارث، عن المفضل بن عمر، عن أبي عبد الله أنه قال: إنّ لصاحب هذا الأمر غيبةً يقول فيها فَفَرَرْتُ مِنْكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِي رَبِّي حُكْمًا وَجَعَلَنِي مِنَ الْمُرْسَلِينَ","22/2/10/49",""],[50,10,"حدثنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، قال: حدثني الحسن بن محمد بن سماعة، قال: حدثني أحمد بن الحارث الأنماطي، عن المفضل بن عمر، عن أبي عبد الله أنه قال: إذا قام القائم تلا هذه الآية فَفَرَرْتُ مِنْكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِي رَبِّي حُكْمًا وَجَعَلَنِي مِنَ الْمُرْسَلِينَ","22/2/10/50",""],[51,10,"حدثنا عبد الواحد بن عبد الله بن يونس، قال: حدثنا أحمد بن محمد بن رباح، قال: حدثني أحمد بن علي الحميري، عن الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن أحمد بن الحارث، عن المفضل بن عمر قال: سمعته يقول - يعني أبا عبد الله -: قال أبو جعفر محمد بن علي الباقر: إذا قام القائم قال فَفَرَرْتُ مِنْكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِي رَبِّي حُكْمًا وَجَعَلَنِي مِنَ الْمُرْسَلِينَ","22/2/10/51",""],[52,10,"حدثنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثني الحسن بن محمد الصيرفي قال: حدثني يحيى بن المثنى العطار، عن عبد الله بن بكير، عن عبيد بن زرارة، عن أبي عبد الله أنه قال: يفتقدُ الناس إماماً يشهد المواسمَ يراهُم ولا يرونه.","22/2/10/52",""],[53,10,"حدثنا محمد بن يعقوب، عن محمد بن يحيى، عن جعفر بن محمد، عن إسحاق ابن محمد، عن يحيى بن المثني، عن عبد الله بن بكير، عن عبيد بن زرارة قال: سمعت أبا عبد الله يقول: يفقدُ الناسّ إمامهم، يشهد المواسمَ فيراهم ولا يرونه.","22/2/10/53",""],[54,10,"حدثنا عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح، قال: حدثنا أحمد بن علي الحميري، عن الحسن، عن عبد الكريم بن عمرو، عن ابن بكير ويحيى بن المثني، عن زرارة قال: سمعت أبا عبد الله يقول: إن للقائم غيبتين يرجع في إحداهما، وفي الأخرى لا يُدرى أين هو، يشهد المواسمَ يرى الناس ولا يرونه.","22/2/10/54",""],[55,10,"حدثنا محمد بن يعقوب الكليني، عن الحسين بن محمد، عن جعفر بن محمد، عن القاسم بن إسماعيل، عن يحيى بن المثنى، عن عبد الله بن بكير، عن عبيد بن زرارة، عن أبي عبد الله أنه قال: للقائم غيبتان، يشهد في إحديهما المواسمَ يرى الناس ولا يرونه فيه.","22/2/10/55",""],[56,10,"حدثنا محمد بن همام - رحمه الله - قال: حدثنا أحمد بن مابنداذ، قال: حدثنا أحمد بن هلال، عن موسى بن القاسم بن معاوية البجلي، عن علي بن جعفر، عن أخيه موسى بن جعفر قال: قلت له: ما تأويل هذه الآية قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَنْ يَأْتِيكُمْ بِمَاءٍ مَعِينٍ قال: إذا فقدتم إمامَكم فمَن يأتيكم بإمام جديد؟","22/2/10/56",""],[57,10,"حدثنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي العباسي عن محمد بن أحمد القلانسي، عن أيوب بن نوح، عن صفوان بن يحيى، عن عبد الله بن بكير، عن زرارة قال: سمعت أبا جعفر يقول: إن للقائم غيبةً، ويجحده أهله. قلت: ولم ذلك؟ قال: يخاف - وأومأ بيده إلى بطنه -.","22/2/10/57",""],[58,10,"حدثنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن أحمد بن الحسن، عن أبيه، عن ابن بكير، عن زرارة، عن عبد الملك بن أعين قال: سمعت أبا جعفر يقول: إنّ للقائم غيبة قبل أن يقوم. قلت: ولِمَ؟ قال: يخاف - وأومأ بيده إلى بطنه - يعنى القتلَ.","22/2/10/58",""],[59,10,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، عن العباس بن عامر بن رباح، عن ابن بكير، عن زرارة قال: سمعت أبا جعفر الباقر يقول: إن للغلام غيبةً قبل أن يقوم، وهو المطلوب تراثه. قلت: ولم ذلك؟ قال: يخاف - وأومأ بيده إلى بطنه - يعني القتل.","22/2/10/59",""],[60,10,"وحدثنا أحمد بن محمد بن سعيد قال: حدثنا أبو محمد عبد الله بن أحمد بن المستورد الأشجعي قال: حدثنا محمد بن عبيد الله أبو جعفر الحلبي، قال: حدثنا عبد الله بن بكير، عن زرارة، قال: سمعت أبا عبد الله جعفراً يقول: إن للقائم غيبة قبل أن يقوم. قلت: ولم ذلك؟ قال: إنه يخاف - وأوما بيده إلى بطنه - يعنى القتل.","22/2/10/60",""],[61,10,"حدثنا محمد بن همام، عن جعفر بن محمد بن مالك، قال: حدثني أحمد بن ميثم، عن عبيد الله بن موسي عن عبد الأعلى بن حصين الثعلبي، عن أبيه قال: لقيت أبا جعفر محمد بن علي في حج أو عمرة فقلت له: كبرت سنّي ودقّ عظمي فلست أدري يُقضى لي لقاؤك أم لا، فاعهد إليّ عهداً وأخبرني متى الفرج؟ فقال: إنّ الشريدَ الطريد الفريد الوحيد المفرد من أهله الموتور بوالده، المُكنّى بعمّه هو صاحبُ الرايات، واسمه اسم نبيٍّ. فقلت: أعِد عليّ. فدعا بكتاب أديم أو صحيفة فكتب لي فيها.","22/2/10/61",""],[62,10,"وحدثنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، قال: حدثني عباد بن يعقوب، قال: حدثني الحسن بن حماد الطائي، عن أبي الجارود عن أبي جعفر محمد بن علي أنه قال: صاحبُ هذا الأمر هو الطريدُ الشريد الموتورُ بأبيه، المكنّى بعمه، المفردُ من أهله، اسمُه اسم نبي.","22/2/10/62",""],[63,10,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا حميد بن زياد قراءة عليه من كتابه قال: حدثنا الحسن بن محمد الحضرمي، قال: حدثنا جعفر بن محمد . وعن يونس بن يعقوب عن سالم المكي، عن أبي الطفيل قال: قال لي عامر بن واثلة: إنّ الذي تطلبون وترجون إنما يخرج من مكة، وما يخرج من مكة حتى يرى الذي يحب، ولو صار أن يأكل الأغصان أغصان الشجرة.","22/2/10/63",""],[64,10,"حدثنا به محمد بن همام قال: حدثنا أحمد بن مابنداذ قال: حدثنا أحمد بن هلال، قال: حدثنا أحمد بن علي القيسي، عن أبي الهيثم الميثمي عن أبي عبد الله جعفر بن محمد أنه قال: إذا توالت ثلاثة أسماء محمد وعلي والحسن كان رابعهم قائمَهم.","22/2/10/64",""],[65,10,"محمد بن همام قال: حدثنا عبد الله بن جعفر الحميري، قال: حدثنا محمد بن عيسى بن عبيد، عن محمد بن أبي يعقوب البلخي قال: سمعت أبا الحسن الرضا يقول: إنكم ستُبتلون بما هو أشدّ وأكبر، تُبتلَون بالجنين في بطن أمّه والرضيع حتى يقال: غاب ومات، ويقولون: لا إمام، وقد غاب رسول الله وغاب وغاب وها أنا ذا أموت حتف أنفي.","22/2/10/65",""],[66,10,"وحدثنا محمد بن همام قال: حدثنا أحمد بن مابنداذ وعبد الله بن جعفر الحميري قالا: حدثنا أحمد بن هلال، قال: حدثنا الحسن بن محبوب الزراد قال: قال لي الرضا: إنه يا حسَنُ سيكون فتنة صماء صيلم يذهب فيها كلّ وليجة وبطانة. (وفي رواية: يسقط فيها كل وليجة وبطانة) وذلك عند فقدان الشيعة الثالثَ من ولدي، يحزن لفقده أهلُ الأرض والسماء. كم من مؤمن ومؤمنة متأسف متلهف حيران حزين لفقده. ثم أطرق، ثم رفع رأسه، وقال: بأبي وأمي سميّ جدي وشبيهي وشبيه موسى بن عمران، عليه جيوب النور يتوقد من شعاع ضياء القدس، كأني به آيس ما كانوا، قد نودوا نداء يسمعه مَن بالبعد كما يسمعه من بالقرب، يكون رحمة على المؤمنين، وعذاباً على الكافرين. فقلت: بأبي وأمي أنت، وما ذلك النداء؟ قال: ثلاثة أصوات في رجب، أولها: ألا لعنة الله على الظالمين. والثاني: أزفت الآزفة يا معشر المؤمنين. والثالث يرَون يداً بارزاً مع قرن الشمس ينادي: ألا إن الله قد بعث فلاناً على هلاك الظالمين. فعند ذلك يأتي المؤمنين الفرج، ويشفي الله صدورهم، ويذهب غيظ قلوبهم.","22/2/10/66",""],[67,10,"محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا محمد بن أحمد المديني، قال: حدثنا علي بن أسباط، عن محمد بن سنان، عن داود بن كثير الرقي قال: قلت لأبي عبد الله: جعلت فداك، قد طال هذا الأمر علينا حتى ضاقت قلوبنا ومتنا كمداً. فقال: إن هذا الأمر آيس ما يكون منه وأشدّه غمّاً ينادى منادٍ من السماء باسم القائم واسم أبيه. فقلت له: جعلت فداك ما اسمه؟ فقال: إسمه اسم نبيّ، واسم أبيه اسمُ وصي.","22/2/10/67",""],[68,10,"وحدثنا أحمد بن محمد بن سعيد قال: حدثني محمد بن علي التيملي، عن محمد بن إسماعيل بن بزيع وحدثني غير واحد، عن منصور بن يونس بزرج، عن إسماعيل بن جابر، عن أبي جعفر محمد بن علي أنه قال: يكون لصاحب هذا الأمر غيبةٌ في بعض هذه الشعابِ - وأومأ بيده إلى ناحية ذي طوى - حتى إذا كان قبل خروجه أتى المولى الذي كان معه حتىّ يلقى بعض أصحابه، فيقول: كم أنتم ههنا؟ فيقولون: نحو من أربعين رجلاً، فيقول: كيف أنتم لو رأيتم صاحبكم؟ فيقولون: واللهِ لو ناوى بنا الجبال لناويناها معه. ثم يأتيهم من القابلة ويقول: أشيروا إلى رؤسائكم أو خياركم عشرة، فيشيرون له إليهم، فينطلق بهم حتى يلقوا صاحبهم، ويعِدهم الليلة التي تليها. ثم قال أبو جعفر: والله لكأني أنظر إليه وقد أسند ظهره إلى الحجر فينشد الله حقه ثم يقول: يا أيها الناس مَن يحاجني في الله فأنا أولى الناس بالله، أيها الناس من يحاجني في آدم فأنا أولى الناس بآدم، أيها الناس من يحاجني في نوح فأنا أولى الناس بنوح، أيها الناس من يحاجني في إبراهيم فأنا أولى الناس بإبراهيم، أيها الناس من يحاجني في موسى فأنا أولى الناس بموسى، أيها الناس من يحاجني في عيسى فأنا أولى الناس بعيسى، أيها الناس من يحاجني في محمد فأنا أولى الناس بمحمد ، أيها الناس من يحاجني في كتاب الله فأنا أولى الناس بكتاب الله. ثم ينتهي إلى المقام فيصلي عنده ركعتين وينشد الله حقه. ثم قال أبو جعفر: وهو والله المضطر الذي يقول الله فيه أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ وَيَجْعَلُكُمْ خُلَفَاءَ الْأَرْضِ ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ قَلِيلًا مَا تَذَكَّرُونَ فيه نزلت وله.","22/2/10/68",""],[69,10,"حدثنا علي بن أحمد، عن عبيد الله بن موسى العلوي، قال: حدثنا محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن أبي الجارود، قال: سمعت أبا جعفر يقول: لا يزالون ولا تزال حتى يبعث الله لهذا الأمر مَن لا يدرون خُلق أم لم يخلق.","22/2/10/69",""],[70,10,"حدثنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، عن محمد بن الحسين بن أبي الخطاب وقد حدثني عبد الله بن جعفر الحميري، عن أحمد بن محمد بن عيسى قإلاّ جميعاً: حدثنا محمد بن سنان، عن أبي الجارود عن أبي جعفر الباقر قال: لا تزالون تمدّون أعناقكم إلى الرجل منا تقولون: هو هذا فيذهب الله به حتى يبعث الله لهذا الأمر من لا تدرون وُلد أم لم يولد، خُلق أم لم يخلق.","22/2/10/70",""],[71,10,"حدثنا علي بن أحمد، عن عبيد الله بن موسى، عن محمد بن أحمد القلانسي، عن محمد بن علي، عن محمد بن سنان، عن أبي الجارود قال: سمعت أبا جعفر يقول: لا يزال ولا تزالون تمدون أعينكم إلى رجل تقولون: هو هذا إلاّ ذهب حتى يبعث الله من لا تدرون خلق بعد أم لم يخلق.","22/2/10/71",""],[72,10,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي قال: حدثنا محمد بن علي، عن محمد بن سنان، عن رجل، عن ابي جعفر أنه قال: لا تزالون ولا تزال حتى يبعث الله لهذا الأمر من لا تدرون خلق أم لم يخلق.","22/2/10/72",""],[73,10,"أخبرنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا عباد بن يعقوب، قال: حدثنا يحيى بن سالم، عن أبي جعفر الباقر أنه قال: صاحب هذا الأمر أصغرنا سناً وأخملُنا شخصاً. قلت: متى يكون ذاك؟ قال: إذا سارت الركبان ببَيعة الغلام، فعند ذلك يرفع كل ذي صيصية لواء، فانتظروا الفرج.","22/2/10/73",""],[74,10,"حدثنا محمد بن همام قال: حدثنا أحمد بن ما بنداذ قال: حدثنا أحمد بن هلال، عن أمية بن علي القيسي قال: قلت لأبي جعفر محمد بن علي الرضا: مَن الخلف بعدك؟ فقال: ابني عليّ وابنا عليّ. ثم أطرق ملياً ثم رفع رأسه ثم قال: إنها ستكون حيرة. قلت: فإذا كان ذلك فإلى أين؟ فسكت ثم قال: لا أين - حتى قالها ثلاثا. فأعدتُ عليه، فقال: إلى المدينة. فقلت: أي المدن؟ فقال: مدينتنا هذه، وهل مدينة غيرها؟","22/2/10/74",""],[75,10,"حدثنا محمد بن همام قال: حدثني أبو عبد الله محمد بن عصام قال: حدثنا أبو سعيد سهل بن زياد الآدمي، قال: حدثنا عبد العظيم بن عبد الله الحسني، عن أبي جعفر محمد بن علي الرضا أنه سمعه يقول: إذا مات ابني عليّ بدا سراج بعده ثم خفيَ، فويل للمرتاب وطوبى للغريب الفارّ بدينه، ثم يكون بعد ذلك أحداث تشيب فيها النواصي ويسير الصم الصلاب.","22/2/10/75",""],[76,10,"حدثنا محمد بن يعقوب الكليني قال: حدثنا محمد بن يحيى، عن أحمد بن إدريس، عن محمد بن أحمد، عن جعفر بن القاسم، عن محمد بن الوليد الخزاز، عن الوليد بن عقبة، عن الحارث بن زياد، عن شعيب، عن أبي حمزة قال: دخلت على أبي عبد الله فقلت له: أنت صاحب هذا الأمر؟ فقال: لا. فقلت: فولدك؟ فقال: لا. فقلت: فولد ولدك؟ فقال: لا. قلت: فولد ولد ولدك؟ قال: لا. قلت: فمن هو؟ قال: الذي يملأها عدلاً كما مُلئت ظلماً وجوراً، لعلى فترة من الأئمة يأتي كما أن النبي بعث على فترة من الرسل.","22/2/10/76",""],[77,10,"حدثنا محمد بن يعقوب قال: حدثنا علي بن محمد، عن بعض رجاله، عن أيوب بن نوح، عن أبي الحسن الثالث أنه قال: إذا رفع علمكم من بين أظهرِكم فتوقعوا الفرج من تحت أقدامكم.","22/2/10/77",""],[78,10,"محمد بن يعقوب قال: حدثنا أبو علي الأشعري، عن محمد بن حسان، عن محمد بن علي، عن عبد الله بن القاسم، عن المفضل بن عمر، عن أبي عبد الله أنه سئل عن قول الله فَإِذَا نُقِرَ فِي النَّاقُورِ قال: إنّ منّا إماماً مستتراً، فإذا أراد الله عزَّ ذِكره إظهارَ أمرِه نكت في قلبه نكتةً فظهر فقامَ بأمر الله .","22/2/10/78",""],[79,10,"حدثنا محمد بن يعقوب قال: حدثنا عدة من أصحابنا، عن أحمد بن محمد عن الحسن بن علي الوشاء، عن علي بن أبي حمزة، عن أبي بصير عن أبي عبد الله أنه قال: لا بُدّ لصاحب هذا الأمر من غيبة ولا بدّ له في غيبته من عزلة، ونعم المنْزل طيبة، وما بثلاثين من وحشة.","22/2/10/79",""],[80,10,"وأخبرنا محمد بن يعقوب، عن عدة من رجاله، عن أحمد بن محمد، عن علي بن الحكم، عن أبي أيوب الخزاز، عن محمد بن مسلم قال: سمعت أبا عبد الله يقول: إنْ بلغَكم عن صاحبكم غيبةٌ فلا تنكروها.","22/2/10/80",""],[81,10,"حدثنا علي بن الحسين المسعودي قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن الحسن بن محبوب، عن عبد الله بن جبلة، عن علي بن أبي حمزة، عن أبي عبد الله أنه قال: لو قد قام القائم لأنكَرَه الناس لأنّه يرجع إليهم شاباً موفقاً، لا يثبت عليه إلاّ مَن قد أخذ الله ميثاقَه في الذرّ الأول. وإنّ مِن أعظم البلية أن يخرج إليهم صاحبُهم شاباً وهم يحسبونه شيخاً كبيراً.","22/2/10/81",""],[82,10,"محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثني عمر بن طرخان، قال: حدثنا محمد بن إسماعيل، عن علي بن عمر بن علي بن الحسين عن أبي عبد الله جعفر بن محمد أنه قال: القائم من ولدي يعمّر عمرَ الخليل عشرين ومِائة سنة يدرى به، ثم يغيب غيبة في الدهر ويظهر في صورة شاب موفق ابن اثنتين وثلاثين سنة، حتى ترجع عنه طائفة من الناس، يملأُ الأرضَ قسطاً وعدلاً كما ملئت ظلماً وجوراً.","22/2/10/82",""],[83,10,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، عن إبراهيم بن هاشم، عن حماد بن عيسى، عن إبراهيم بن عمر اليماني، عن أبي عبد الله أنه قال: يقوم القائم وليس في عنقه بيعة لأحد.","22/2/10/83",""],[84,10,"حدثنا محمد بن يعقوب قال: حدثنا محمد بن يحيى، عن أحمد بن محمد، عن الحسين بن سعيد، عن ابن أبي عمير، عن هشام بن سالم، عن أبي عبد الله أنه قال: يقوم القائم وليس لأحد في عنقه عقد ولا عهد ولا بيعة.","22/2/10/84",""],[85,10,"حدثنا به علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن محمد بن سنان، عن أبي الجارود، عن مزاحم العبدي، عن عكرمة بن صعصعة، عن أبيه قال: كان علي يقول: لا تنفكّ هذه الشيعة حتى تكون بمنْزلة المعز لا يدري الخابس على أيّها يضع يده فليس لهم شرف يشرفونه، ولا سناد يستندون إليه في أمورهم.","22/2/10/85",""],[86,10,"وأخبرنا علي بن الحسين بإسناده، عن محمد بن سنان، عن أبي الجارود، قال: حدثنا أبو بدر، عن عليم، عن سلمان الفارسي أنه قال: لا ينفكّ المؤمنون حتى يكونوا كمواة المعز، لا يدري الخابس على أيّها يضع يده، ليس فيهم شرف يشرفونه ولاسناد يسندون إليه أمرهم.","22/2/10/86",""],[87,10,"وبه عن أبي الجارود، عن عبد الله الشاعر - يعنى ابن عقبة - قال: سمعت علياً يقول: كأني بكم تجولون جولان الإبل تبتغون مرعي، ولا تجدونها يا معشر الشيعة.","22/2/10/87",""],[88,10,"وبه عن ابن سنان، عن يحيى بن المثنى العطار، عن عبد الله بن بكير؛ ورواه الحكم عن أبي جعفر أنه قال: كيف بكم إذا صعدتم فلم تجدوا أحداً، ورجعتم فلم تجدوا أحداً!","22/2/10/88",""],[89,10,"حدثنا عبد الواحد بن عبد الله قال: حدثنا محمد بن جعفر القرشي، قال: حدثني محمد بن الحسين بن أبي الخطاب قال: حدثني محمد بن سنان، عن أبي الجارود، عن أبي جعفر أنه سمعه يقول: لا تزالون تنتظرون حتى تكونوا كالمعز المهولة التي لا يبالي الجازر أين يضع يدَه منها، ليس لكم شرف تشرفونه، ولا سند تسندون إليه أموركم.","22/2/10/89",""],[1,11,"حدثنا أحمد بن محمد بن سعيد بن عقدة الكوفي قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي أبو الحسن، قال: حدثنا إسماعيل بن مهران قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب بن حفص، عن أبي بصير، عن أبي عبد الله قال: إنه قال لي أبي: لا بدّ لنارٍ من آذربيجان، لا يقوم لها شيء، وإذا كان ذلك فكونوا أحلاسَ بيوتكم وألبدوا ما ألبدنا، فإذا تحرك متحركُنا فاسعوا إليه ولو حبواً، والله لكأني أنظر إليه بين الركن والمقام يبايع الناس على كتاب جديد، على العرب شديد. وقال: ويلٌ لطغاة العرب من شرّ قد اقترب.","22/2/11/1",""],[2,11,"حدثنا أحمد بن محمد بن سعيد، عن بعض رجاله، عن علي بن عمارة الكناني، قال: حدثنا محمد بن سنان، عن أبي الجارود، عن أبي جعفر قال: قلت له: أو صني، فقال: أوصيكَ بتقوى الله، وأن تلزمَ بيتك وتقعد في دهماء هؤلاء الناس، وإيّاك والخوارج منّا فإنهم ليسوا على شيء ولا إلى شيء، واعلم أن لبني أميّة مُلكاً لا يستطيع الناس أن تردعَه، وأن لأهل الحق دولةً إذا جاءت ولاّها الله لمن يشاء منا أهل البيت، فمَن أدركها منكم كان عندنا في السنام الأعلى، وإنْ قبضه الله قبل ذلك خار له، واعلم أنه لا تقوم عصابة تدفع ضيماً أو تُعزّ ديناً إلاّ صرعتهم المنيّة والبلية حتى تقوم عصابة شهدوا بدراً مع رسول الله لا يواري قتيلهم ولا يرفع صريعهم ولا يُداوى جريحهم. قلت: مَن هم؟ قال: الملائكة.","22/2/11/2",""],[3,11,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثني علي بن الحسن التيملي قال: حدثنا الحسن ومحمد ابنا علي بن يوسف، عن أبيهما، عن أحمد بن علي الحلبي، عن صالح بن أبي الأسود، عن أبي الجارود قال: سمعت أبا جعفر يقول: ليس منّا أهل البيت أحد يدفع ضيماً ولا يدعو إلى حق إلاّ صرعته البليةُ حتى تقوم عصابة شهدت بدراً، لا يُوارى قتيلها ولا يُداوى جريحها. قلت: مَن عنيَ أبو جعفر بذلك؟ قال: الملائكة.","22/2/11/3",""],[4,11,"حدثنا محمد بن همام ومحمد بن الحسن بن محمد بن جمهور جميعاً، عن الحسن بن محمد بن جمهور، عن أبيه، عن سماعة بن مهران، عن أبي الجارود، عن القاسم بن الوليد الهمداني، عن الحارث الأعور الهمداني قال: قال أمير المؤمنين على المنبر: إذا هلك الخاطب وزاغ صاحب العصر وبقيت قلوب تتقلب فمِن مخصب ومجدب، هلك المتمنّون واضمحل المضمحلّون، وبقي المؤمنون، وقليل ما يكونون ثلاثمائة أو يزيدون، تُجاهد معهم عصابةٌ جاهدت مع رسول الله يوم بدر، لم تُقتل ولم تمُت.","22/2/11/4",""],[5,11,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا حميد بن زياد الكوفي، قال: حدثنا علي بن الصباح بن الضحاك، عن جعفر بن محمد بن سماعة، عن سيف التمار، عن أبي المرهف قال: قال أبو عبد الله: هلكت المحاضير. قال: قلت: وما المحاضير؟ قال: المستعجلون، ونجا المقربون، وثبت الحصن على أوتادها. كونوا أحلاس بيوتكم، فإن الغبرة على مَن أثارها، وإنهم لا يريدونكم بجائحة إلاّ أتاهم الله بشاغل إلاّ من تعرض لهم.","22/2/11/5",""],[6,11,"حدثنا أحمد بن محمد بن سعيد قال: حدثني يحيى بن زكريا بن شيبان، قال: حدثنا يوسف بن كليب المسعودي، قال: حدثنا الحكم بن سليمان، عن محمد بن كثير، عن أبي بكر الحضرمي قال: دخلت أنا وأبان على أبي عبد الله وذلك حين ظهرت الرايات السود بخراسان، فقلنا: ما ترى؟ فقال: إجلسوا في بيوتكم، فإذا رأيتمونا قد اجتمعنا على رجل فانهدوا إلينا بالسلاح.","22/2/11/6",""],[7,11,"وحدثنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك الفزاري، قال: حدثني محمد بن أحمد، عن علي بن أسباط، عن بعض أصحابه، عن أبي عبد الله أنه قال: كفّوا ألسنتكم والزموا بيوتكم، فإنه لا يصيبكم أمرٌ تُخصّون به أبداً ويصيب العامةَ ولا تزال الزيدية وقاء لكم أبداً.","22/2/11/7",""],[8,11,"وحدثنا علي بن أحمد قال: حدثنا عبيد الله بن موسى العلوي، عن محمد بن موسى، عن أحمد بن أبي أحمد، عن محمد بن علي، عن علي بن حسان، عن عبد الرحمن بن كثير قال: كنت عند أبي عبد الله يوماً وعنده مهزم الأسدي، فقال: جعلني الله فداك، متى هذا الأمر الذي تنتظرونه؟ فقد طال علينا. فقال: يا مهزم، كذب المتمنّون، وهلك المستعجلون، ونجا المسلمون، وإلينا يصيرون.","22/2/11/8",""],[9,11,"علي بن أحمد، عن عبيد الله بن موسى العلوي، قال: حدثنا علي بن الحسن، عن علي بن حسان، عن عبد الرحمن بن كثير، عن أبي عبد الله في قول الله أَتَىٰ أَمْرُ اللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ قال: هو أمرُنا، أمرَ الله أن لا تستعجل به حتى يؤيده الله بثلاثة أجناد: الملائكة، والمؤمنين، والرعب. وخروجه كخروج رسول الله ، وذلك قوله تعالى كَمَا أَخْرَجَكَ رَبُّكَ مِنْ بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيقًا مِنَ الْمُؤْمِنِينَ لَكَارِهُونَ","22/2/11/9",""],[10,11,"أخبرنا محمد بن همام ومحمد بن الحسن بن محمد بن جمهور جميعاً، عن الحسن بن محمد بن جمهور، عن أبيه، عن سماعة بن مهران، عن صالح بن ميثم ويحيى بن سابق جميعاً عن أبي جعفر الباقر أنه قال: هلك أصحاب المحاضير، ونجا المقربون، وثبت الحصن على أوتادها. إنّ بعد الغمّ فتحاً عجيباً.","22/2/11/10",""],[11,11,"وحدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن الحكم بن أيمن، عن ضريس الكناسي، عن أبي خالد الكابلي، قال: قال علي بن الحسين: لَوَددتُ إني تركت فكلّمت الناس ثلاثاً، ثم قضى الله فيَّ ما أحبّ، ولكن عزمةً من الله أن نصبر. ثم تلا هذه الآية وَلَتَعْلَمُنَّ نَبَأَهُ بَعْدَ حِينٍ ثم تلا أيضا قولَه تعالى لَتُبْلَوُنَّ فِي أَمْوَالِكُمْ وَأَنْفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ وَمِنَ الَّذِينَ أَشْرَكُوا أَذًى كَثِيرًا ۚ وَإِنْ تَصْبِرُوا وَتَتَّقُوا فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ الْأُمُورِ","22/2/11/11",""],[12,11,"علي بن أحمد قال: حدثنا عبيد الله بن موسى العلوي، عن علي بن إبراهيم بن هاشم، عن علي بن إسماعيل، عن حماد بن عيسى، عن إبراهيم بن عمر اليماني، عن أبي الطفيل، عن أبي جعفر محمد بن علي، عن أبيه علي بن الحسين : أن ابن عباس بعث إليه مَن يسأله عن هذه الآية يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ فغضب عليّ بن الحسين وقال للسائل: ودِدتُ أن الذي أمرك بهذا واجهني به. ثم قال: نزَلَت في أبي وفينا ولم يكن الرباط الذي أمرَنا به بعد وسيكون ذلك ذريّة من نسلنا المرابط. ثم قال: أما إنّ في صلبه (يعني ابن عباس ) وديعةً ذرئت لنارِ جهنم، سيخرجون أقواماً من دين الله أفواجاً وستصبغ الأرض بدماء فراخ من فراخ آل محمّد تنهض تلك الفراخ في غير وقت، وتطلب غير مدرك، ويرابط الذين آمنو ويصبرون ويصابرون حتى يحكم الله، وهو خير الحاكمين.","22/2/11/12",""],[13,11,"حدثنا علي بن أحمد، عن عبيد الله بن موسى، عن هارون بن مسلم، عن القاسم بن عروة، عن بريد بن معاوية العجلي، عن أبي جعفر محمد بن علي الباقر في قوله يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ فقال: اصبروا على أداء الفرائض، وصابروا عدوكم، ورابطوا إمامَكم المنتظرَ.","22/2/11/13",""],[14,11,"حدثنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك قال: حدثني أحمد بن علي الجعفي، عن محمد بن المثني الحضرمي، عن أبيه، عن عثمان بن زيد عن جابر، عن أبي جعفر محمد بن علي الباقر قال: مثلُ خروج القائم منّا أهل البيت كخروج رسول الله ، ومثل مَن خرج منا أهل البيت قبل قيام القائم مثل فرخ طار فوقع مِن وكره فتلاعَبت به الصبيان.","22/2/11/14",""],[15,11,"حدثنا علي بن أحمد، عن عبيد الله بن موسى، عن أحمد بن الحسين، عن علي بن عقبة، عن موسى بن أكيل النميري، عن العلاء بن سيابة، عن أبي عبد الله جعفر بن محمد أنه قال: مَن مات منكم على هذا الأمر منتظراً كان كمَن هو في الفسطاط الذي للقائم .","22/2/11/15",""],[16,11,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي أبو الحسن، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب بن حفص، عن أبي بصير، عن أبي عبد الله أنه قال ذات يوم: ألا أخبركم بما لا يقبل الله من العباد عملاً إلاّ به؟ فقلت: بلى، فقال: شهادةُ أن لا إله إلاّ الله، وأن محمداً عبده ورسوله والإقرار بما أمر الله، والولاية لنا، والبراءة من أعدائنا (يعني الأئمة خاصة) والتسليم لهم، والورع والاجتهاد والطمأنينة، والانتظار للقائم . ثم قال: إن لنا دولة يجيء الله بها إذا شاء. ثم قال: مَن سرّه أن يكون من أصحاب القائم فلينتظرْ وليعمل بالورع ومحاسن الأخلاق وهو منتظر، فإن مات وقام القائم بعده كان له من الأجر مثل أجر مَن أدركه، فجدّوا وانتظروا هنيئاً لكم أيتها العصابة المرحومة.","22/2/11/16",""],[17,11,"علي بن أحمد، عن عبيد الله بن موسى العلوي، عن محمد بن الحسين، عن محمد بن سنان، عن عمار بن مروان، عن منخل بن جميل، عن جابر بن يزيد، عن أبي جعفر الباقر أنه قال: اسكنوا ما سكنت السماوات والأرض (أي لا تخرجوا على أحد) فإنّ أمرَكم ليس به خفاء، ألا إنها آية من الله ليست من الناس إلاّ إنها أضوءُ من الشمس لا تخفى على بر ولا فاجر، أتعرفون الصبح؟ فإنها كالصبح ليس به خفاء.","22/2/11/17",""],[1,12,"حدثنا محمد بن يعقوب قال: حدثنا علي بن إبراهيم، عن أبيه، عن بن محبوب، عن يعقوب السراج وعن علي بن رئاب، عن أبي عبد الله أنه قال: لما بويع لأمير المؤمنين بعد مقتل عثمان صعد المنبر وخطب خطبة ذكرها يقول فيها: ألا إنّ بليّتكم قد عادت كهيئتِها يوم بعث الله نبيه . والذي بعثه بالحق لتبلبلُنّ بلبلةً ولتغربلُنَّ غربلة حتى يعود أسفلُكم أعلاكم وأعلاكم أسفلكم، وليسبقنّ سابقون كانوا قصّروا، وليقصرنّ سبّاقون كانوا سبقوا، والله ما كتمت وسمة ولا كذبت كذبة، ولقد نُبّئت بهذا المقام وهذا اليوم.","22/2/12/1",""],[2,12,"حدثنا محمد بن يعقوب الكليني قال: حدثني عدة من أصحابنا، عن أحمد بن محمد، عن معمر بن خلاد، قال: سمعت أبا الحسن يقول الم أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ ثم قال لي: ما الفتنة؟ فقلت: جعلت فداك، الذي عندنا أن الفتنة في الدين. فقال: يفتنون كما يفتن الذهب. ثم قال: يخلصون كما يخلص الذهب.","22/2/12/2",""],[3,12,"حدثنا محمد بن يعقوب قال: حدثنا علي بن إبراهيم، عن محمد بن عيسى، عن يونس، عن سليمان بن صالح رفعه إلى أبي جعفر محمد بن علي الباقر قال: قال: إنّ حديثكم هذا لتشمئز منه قلوب الرجال فانبذوه إليهم نبذاً فمَن أقرّ به فزيدوه، ومَن أنكر فذروه، إنه لا بدّ من أن تكون فتنةٌ يسقط فيها كلّ بطانة ووليجة حتى يسقط فيها مَن يشق الشعرة بشعرتين حتى لا يبقى إلاّ نحن وشيعتنا.","22/2/12/3",""],[4,12,"حدثنا أبو سليمان أحمد بن هوذة الباهلي، قال: حدثنا أبو إسحاق إبراهيم بن إسحاق النهاوندي سنة ثلاث وسبعين ومائتين قال: حدثنا عبد الله بن حماد الأنصاري سنة تسع وعشرين ومائتين، عن رجل، عن أبي عبد الله: أنه دخل عليه بعض أصحابه فقال له: جعلت فداك، إني والله أحبك وأحب من يحبك، يا سيدي ما أكثر شيعتكم، فقال له: أذكرهم، فقال: كثير، فقال: تحصيهم؟ فقال: هم أكثر من ذلك. فقال أبو عبد الله: أما لو كمُلت العدّة الموصوفة ثلاثمائة وبضعة عشر كان الذي تريدون، ولكنّ شيعتنا مَن لا يعدو صوته سمعه ولا شحناؤه بدنه ولا يمدح بنا معلناً ولا يخاصم بنا قالياً ولا يجالس لنا عايباً ولا يحدث لنا ثالباً ولا يحب لنا مبغضاً ولا يبغض لنا محباً. فقلت: فكيف أصنع بهذه الشيعة المختلفة الذين يقولون إنهم يتشيعون؟ فقال: فيهم التمييز وفيهم التمحيص وفيهم التبديل، يأتي عليهم سنون تفنيهم، وسيف يقتلهم، واختلافٌ يبددهم. إنما شيعتنا من لا يهرّ هرير الكلب ولا يطمع طمع الغراب، ولا يسأل الناس بكفّه وإن مات جوعاً. قلت: جعلت فداك، فأين أطلب هؤلاء الموصوفين بهذه الصفة؟ فقال: أطلبهم في أطراف الأرض، أولئك الخفيض عيشهم، المنتقلة دارهم، الذين إن شهدوا لم يعرفوا، وإن غابوا لم يفتقدوا، وإن مرضوا لم يعادوا، وإن خطبوا لم يزوّجوا، وإن ماتوا لم يشهَدوا، أولئك الذين في أموالهم يتواسون، وفي قبورهم يتزاورون، ولا تختلف أهواؤهم وإن اختلفت بهم البلدان. وإنْ رأوا مؤمناً أكرموه، وإن رأوا منافقاً هجروه، وعند الموت لا يجزعون، وفي قبورهم يتزاورون…","22/2/12/4",""],[5,12,"أخبرنا أحمد بن محمد بن سعيد قال: حدثني أحمد بن يوسف الجعفي، أبو الحسن من كتابه، قال: حدثنا إسماعيل بن مهران، عن الحسن بن علي بن أبي حمزة، عن أبيه ووهيب بن حفص عن أبي بصير، عن أبي عبد الله أنه قال: مع القائم من العرب شيءٌ يسير. فقيل له: إن من يصف هذا الأمر منهم لكثيراً. قال: لا بد للناس من أن يمحصوا ويميزوا، ويغربلوا، وسيخرج من الغربال خلقٌ كثير.","22/2/12/5",""],[6,12,"وأخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، عن الحسن بن محبوب الزراد، عن أبي المغرا، عن عبد الله بن أبي يعفور، عن أبي عبد الله أنه سمعه يقول: ويلٌ لطغاة العرب من شرٍّ قد اقترب. قلت: جعلت فداك، كم مع القائم من العرب؟ قال: شيء يسير. فقلت: واللهِ إن من يصف هذا الأمر منهم لكثير. فقال: لا بد للناس من أن يمحصوا ويميزوا ويغربلوا ويخرج من الغربال خلق كثير.","22/2/12/6",""],[7,12,"وأخبرنا علي بن أحمد، قال: حدثنا عبيد الله بن موسى العلوي العباسي، عن أحمد بن محمد عن الحسن بن علي بن زياد، عن علي بن أبي حمزة، عن أبي بصير قال: سمعت أبا جعفر محمد بن علي يقول: والله لتميّزنّ، والله لتمحّصنّ، والله لتغربلنّ كما يغربل الزؤان من القمح.","22/2/12/7",""],[8,12,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام، عن عبد الله بن جبلة، عن مسكين الرحال عن علي بن أبي المغيرة، عن عميرة بنت نفيل قالت: سمعت الحسين بن علي يقول: لا يكون الأمر الذي تنتظرونه حتى يبرأ بعضكم من بعض ويتفل بعضكم في وجوه بعض ويشهد بعضكم على بعض بالكفر، ويلعن بعضكم بعضاً. فقلت له: ما في ذلك الزمان من خير. فقال الحسين: الخير كله في ذلك الزمان، يقوم قائمنا، ويدفع ذلك كله.","22/2/12/8",""],[9,12,"أخبرنا علي بن أحمد قال: أخبرنا عبيد الله بن موسى العلوي، عن الحسن بن علي، عن عبد الله بن جبله، عن بعض رجاله، عن أبي عبد الله أنه قال: لا يكون ذلك الأمر حتى يتفل بعضكم في وجوه بعض، وحتى يلعن بعضكم بعضاً، وحتى يسمي بعضكم بعضا كذابين.","22/2/12/9",""],[10,12,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، قال: حدثنا محمد وأحمد بنا الحسن عن أبيهما، عن ثعلبة بن ميمون، عن أبي كهمس، عن عمران بن ميثم، عن مالك بن ضمرة قال: قال أمير المؤمنين: يا مالك بن ضمرة، كيف أنت إذا اختلفت الشيعة هكذا؟ (وشبك أصابعه وأدخل بعضها في بعض) فقلت: يا أمير المؤمنين ما عند ذلك من خير. قال: الخير كله عند ذلك، يا مالك، عند ذلك يقوم قائمنا فيقدم سبعين رجلاً يكذبون على الله وعلى رسوله ، فيقتلهم، ثم يجمعهم الله على أمر واحد.","22/2/12/10",""],[11,12,"وأخبرنا علي بن أحمد، قال: أخبرنا عبيد الله بن موسى العلوي، عن علي بن إسماعيل الأشعري، عن حماد بن عيسى، عن إبراهيم بن عمر اليماني، عن رجل، عن أبي جعفر أنه قال: لتمحصُنّ يا شيعة آل محمد تمحيصَ الكُحل في العين، وإنّ صاحب العين يدري متى يقع الكحل في عينه ولا يعلم متى يخرج منها، وكذلك يصبح الرجل على شريعةٍ من أمرنا ويمسي وقد خرج منها، ويمسي على شريعة من أمرنا ويصبح وقد خرج منها.","22/2/12/11",""],[12,12,"وأخبرنا علي بن أحمد قال: أخبرنا عبيد الله بن موسى، عن رجل، عن العباس بن عامر، عن الربيع بن محمد المسلي من بني مسلية عن مهزم بن أبي بردة الأسدي وغيره، عن أبي عبد الله أنه قال: والله لتُكسرنّ تكسّر الزجاج، وإن الزجاج ليُعاد فيعود كما كان، والله لتكسرنّ تكسّر الفخار، فإن الفخار ليتكسر فلا يعود كما كان، ووالله لتغربلُنّ ووالله لتميّزنّ وواللهِ لتمحصنّ حتى لا يبقى منكم إلاّ الأقلّ، وصعر كفه.","22/2/12/12",""],[13,12,"أخبرنا علي بن أحمد قال: حدثنا عبيد الله بن موسى، قال: حدثنا محمد بن موسى، عن أحمد بن أبي أحمد، عن إبراهيم بن هلال قال: قلت لأبي الحسن: جعلت فداك، مات أبي على هذا الأمر، وقد بلغت من السنين ما قد ترى أموت ولا تخبرني بشيء. فقال: يا أبا إسحاق، أنت تعجل؟ فقلت: إي والله أعجل وما ليَ لا أعجل وقد كبر سني وبلغت أنا من السن ما قد ترى. فقال: أما والله يا أبا إسحاق، ما يكون ذلك حتى تميزوا وتمحصوا، وحتى لا يبقى منكم إلاّ الأقلّ، ثم صعر كفه.","22/2/12/13",""],[14,12,"وأخبرنا علي بن أحمد قال: حدثنا عبيد الله بن موسى، قال: حدثنا محمد بن الحسين، عن صفوان بن يحيى قال: قال أبو الحسن الرضا: والله لا يكون ما تمدّون إليه أعينكم حتى تمحصوا وتميزوا، وحتى لا يبقى منكم إلاّ الأندر فالأندر.","22/2/12/14",""],[15,12,"وأخبرنا أحمد بن محمد بن سعيد قال: حدثنا أبو عبد الله جعفر بن عبد الله المحمدي من كتابه في سنة ثمان وستين ومائتين، قال: حدثنا محمد بن منصور الصيقل، عن أبيه، قال: دخلت على أبي جعفر الباقر وعنده جماعة فبينا نحن نتحدث وهو على بعض أصحابه مقبل إذ التفت إلينا وقال: في أيّ شيء أنتم؟ هيهات هيهاتَ! لا يكون الذي تمدّون إليه أعناقَكم حتى تمحصوا. هيهات! ولا يكون الذي تمدّون إليه أعناقَكم حتى تميزوا، ولا يكون الذي تمدون إليه أعناقكم حتى تغربلوا، ولا يكون الذي تمدون إليه أعناقكم إلاّ بعد إياسٍ، ولا يكون الذي تمدّون إليه أعناقكم حتى يشقى مَن شقيَ ويسعد من سعد.","22/2/12/15",""],[16,12,"أخبرنا أبو سليمان أحمد بن هوذة بن أبي هراسة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي، قال: حدثنا عبد الله بن حماد الأنصاري، عن صباح المزني، عن الحارث بن حصيرة، عن الأصبغ بن نباتة، عن أمير المؤمنين أنه قال: كونوا كالنّحل في الطير، ليس شيءٌ من الطير إلاّ وهو يستضعفها، ولو علِِمت الطير ما في أجوافها من البركة لم تفعل بها ذلك. خالطوا الناسَ بألسنتكم وأبدانكم وزايلوهم بقلوبكم وأعمالكم، فوَالذي نفسي بيده ما ترَون ما تحبّون حتى يتفلَ بعضُكم في وجوه بعض وحتى يسمّي بعضكم بعضاً كذابين، وحتى لا يبقى منكم (أو قال من شيعتي) إلاّ كالكحل في العين، والملح في الطعام وسأضرب لكم مثلاً، وهو مثل رجل كان له طعام فنقّاه وطيّبه، ثم أدخله بيتاً وتركه فيه ما شاء الله، ثم عاد إليه فإذا هو قد أصابه السوس، فأخرجه ونقّاه وطيّبه، ثم أعاده إلى البيت فتركه ما شاء الله، ثم عاد إليه فإذا هو قد أصابته طائفة من السوس فأخرجه ونقاه وطيبه وأعاده، ولم يزل كذلك حتى بقيت منه رزمة كرزمة الأندر لا يضره السوس شيئاً، وكذلك أنتم تميزون حتى لا يبقى منكم إلاّ عصابة لا تضرّها الفتنة شيئاً.","22/2/12/16",""],[17,12,"حدثنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أحمد بن محمد بن رباح الزهري الكوفي، قال: حدثنا محمد بن العباس بن عيسى الحسني، عن الحسن بن علي البطائني، عن أبيه، عن أبي بصير قال: قال أبو جعفر محمد بن علي الباقر: إنمّا مثل شيعتنا مثل أندر (يعني بيدراً فيه طعام) فأصابه آكلٌ فنقي ثم أصابه آكل فنقي حتى بقي منه ما لا يضرّه الآكل، وكذلك شيعتنا يميزون ويمحصون حتى تبقى منهم عصابة لا تضرّها الفتنة.","22/2/12/17",""],[18,12,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا جعفر بن عبد الله المحمدي، قال: حدثني شريف بن سابق التفليسي، عن الفضل بن أبي قرة التفليسي عن جعفر بن محمد، عن أبيه أنه قال: المؤمنون يُبتلون ثم يميّزهم الله عنده. إنّ الله لم يؤمِن المؤمنين من بلاء الدنيا ومرائرها ولكن أمنَهم فيها من العمى والشقاء في الآخرة. ثم قال: كان علي بن الحسين بن علي يضع قتلاه بعضَهم إلى بعض ثم يقول: قتلانا قتلى النبيّين.","22/2/12/18",""],[19,12,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن الحسن بن محبوب، قال: حدثنا عبد الله بن جبلة، عن علي بن أبي حمزة، عن أبي عبد الله أنه قال: لو قد قام القائم لأنكَره الناس لأنّه يرجع إليهم شاباً موفقاً لا يثبت عليه إلاّ مؤمن قد أخذ الله ميثاقه في الذر الأول.","22/2/12/19",""],[1,13,"حدثنا علي بن أحمد قال: حدثني عبيد الله بن موسى العلوي، عن أبي محمد موسى بن هارون بن عيسى المعبدي قال: حدثنا عبد الله بن مسلمة بن قعنب قال حدثنا سليمان بن بلال قال: حدثنا جعفر بن محمد ، عن أبيه، عن جده عن الحسين بن علي قال: جاء رجل إلى أمير المؤمنين ، فقال له: يا أمير المؤمنين نبّئنا بمهديكم هذا؟ فقال: إذا درج الدارجون وقلّ المؤمنين وذهب المجلبون فهناك هناك. فقال: يا أمير المؤمنين ممّن الرجل؟ فقال: من بني هاشم، مِن ذروة طود العرب وبحر مغيضها إذا وردت، ومخفر أهلها إذا اتيت، ومعدن صفوتها إذا اكتدرت، لا يجبُن إذا المنايا هكعت، ولا يخور إذا المنون اكتنعت، ولا ينكل إذا الكماة اصطرعت، مشمّر مغلولب ظفر ضرغامة حصد مخدش ذكر، سيفٌ من سيوف الله، رأس، قثم، نشؤ رأسه في باذخ السؤدد وعارز مجده في أكرم المحتد. فلا يصرفنّك عن بيعته صارف عارض ينوص إلى الفتنة كل مناص؛ إن قال فشرّ قائل، وإن سكت فذو دعاير. ثم رجع إلى صفة المهدى فقال: أوسعُكم كهفاً، وأكثرُكم علماً، وأوصلُكم رحماً. اللهم فاجعل بعثه خروجاً من الغمة، واجمع به شمل الأمة. فإنْ خارَ الله لك فاعزم ولا تنثنِ عنه إن وفّقتَ له، ولا تجوزنّ عنه إنْ هُديتَ إليه، هاه - وأومأ بيده إلى صدره - شوقا إلى رؤيته.","22/2/13/1",""],[2,13,"أخبرنا علي بن أحمد قال: حدثنا عبيد الله بن موسى العلوي، عن بعض رجاله، عن إبراهيم بن الحكم بن ظهير، عن إسماعيل بن عياش، عن الأعمش عن أبي وائل، قال: نظر أمير المؤمنين علي إلى الحسين فقال: إن ابني هذا سيّد كما سماه رسول الله سيداً، وسيُخرج الله من صلبه رجلاً باسم نبيّكم، يشبهه في الخَلق والخُلق، يخرج على حين غفلة من الناس وإماتةٍ للحق وإظهارٍ للجور. والله لو لم يخرج لضربت عنقه، يفرح بخروجه أهل السماوات وسكانها، وهو رجل أجلى الجبين، أقنى الأنف، ضخم البطن، أزيل الفخذين، بفخذه اليمنى شامة، أفلج الثنايا ويملأُ الأرض عدلاً كما ملئت ظلماً وجوراً.","22/2/13/2",""],[3,13,"حدثنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، قال: حدثنا عبد الله بن بكير، عن حمران بن أعين قال: قلت لأبي جعفر الباقر: جعلت فداك، إني قد دخلت المدينة وفي حقوي هميان فيه ألف دينار، وقد أعطيت الله عهداً أنني أنفقها ببابِك ديناراً ديناراً أو تجيبني فيما أسألك عنه. فقال: يا حمران سلْ تُجب، ولا تنفقنّ دنانيرك. فقلت: سألتُك بقرابتك من رسول الله ؛ أنت صاحب هذا الأمر والقائم به؟ قال: لا. قلت: فمَن هو بأبي أنت وأمي. فقال: ذاك المشربّ حمرة، الغائر العينين، المشرف الحاجبين، العريض ما بين المنكبين، برأسه حزاز، بوجهه أثر، رحم الله موسى!","22/2/13/3",""],[4,13,"حدثنا عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح الزهري قال: حدثنا أحمد بن علي الحميري، قال: حدثني الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن إسحاق بن جرير، عن حجر بن زائدة عن حمران بن أعين، قال: سألت أبا جعفر فقلت له: أنت القائم؟ فقال: قد ولدني رسولُ الله وإنّي المطالب بالدم، ويفعل الله ما يشاء. ثم أعدت عليه، فقال: قد عرفت حيث تذهب، صاحبك المُبدِح البطن، ثم الحزاز برأسه، ابن الأرواع، رحم الله فلانا.","22/2/13/4",""],[5,13,"حدثنا عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح الزهري قال: حدثنا أحمد بن علي الحميري، قال: حدثنا الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، قال: حدثني محمد بن عصام، قال: حدثني وهيب بن حفص، عن أبي بصير، قال: قال أبو جعفر (أو أبو عبد الله - الشك من ابن عصام) يا أبا محمد، بالقائم علامتان: شامةٌ في رأسه وداء الحزاز برأسه، وشامة بين كتفيه، من جانبه الأيسر تحت كتفه الأيسر ورقة مثل ورقة الآس.","22/2/13/5",""],[6,13,"أخبرنا محمد بن يعقوب قال: حدثنا أبو القاسم بن العلاء الهمداني رفعه عن عبد العزيز بن مسلم قال: كنا مع مولانا الرضا بمرو، فاجتمعنا وأصحابنا في الجامع يوم الجمعة في بدء مقدمنا، فأداروا أمر الإمامة، وذكروا كثرة الاختلاف فيها فدخلت على سيدي الرضا فأعلمته خوض الناس في ذلك فتبسم ، ثم قال: يا عبد العزيز، جهل القوم وخدعوا عن آرائهم، إن الله تبارك أسمه لم يقبض رسوله حتى أكمل له الدين فأنزل عليه القرآن فيه تفصيل كل شيء، بيّن فيه الحلال والحرام، والحدود والأحكام وجميع ما يحتاج الناس إليه كملاً فقال وَمَا مِنْ دَابَّةٍ فِي الْأَرْضِ وَلَا طَائِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّا أُمَمٌ أَمْثَالُكُمْ ۚ مَا فَرَّطْنَا فِي الْكِتَابِ مِنْ شَيْءٍ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ وأنزل عليه في حجة الوداع وهي آخر عمره حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنْزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَنْ تَسْتَقْسِمُوا بِالْأَزْلَامِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِنْ دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ ۚ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ ۙ فَإِنَّ اللَّهَ غَفُورٌ رَحِيمٌ وأمر الإمامة من تمام الدين، لم يمض حتى بيّن لأمّته معالم دينهم، وأوضح لهم سبيلهم، وتركهم على قول الحق وأقام لهم علياً علماً وإماماً، وما ترك شيئاً يحتاج إليه الأمة إلاّ بيّنه، فمن زعم أن الله لكم يكمل دينه فقد ردّ كتاب الله، وهو كافر به. هل يعرفون قدر الإمامة ومحلّها من الأمة فيجوز فيها اختيارهم؟ إنّ الإمامة أجل قدراً وأعظم شأناً وأعلى مكاناً وأمنع جانباً وأبعد غوراً مِن أن يبلغَها الناس بعقولهم أو ينالوها بآرائهم أو يقيموا إماماً باختيارهم. إن الإمامة منْزلة خصّ الله بها إبراهيمَ الخليل بعد النبوة والخلّة مرتبةً ثالثة وفضيلةً شرّفه بها وأشاد بها ذكره فقال وَإِذِ ابْتَلَىٰ إِبْرَاهِيمَ رَبُّهُ بِكَلِمَاتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِنْ ذُرِّيَّتِي ۖ قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ فقال الخليل سروراً بها قَالَ وَمِنْ ذُرِّيَّتِي قال الله تعالى لَا يَنَالُ عَهْدِي الظَّالِمِينَ ، فأبطلت هذه الآية إمامةَ كلّ ظالم إلى يوم القيامة وصارت في الصفوة. ثم أكرمه الله بأن جعلها في ذريته أهل الصفوة والطهارة فقال وَوَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ نَافِلَةً ۖ وَكُلًّا جَعَلْنَا صَالِحِينَ وَجَعَلْنَاهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَا إِلَيْهِمْ فِعْلَ الْخَيْرَاتِ وَإِقَامَ الصَّلَاةِ وَإِيتَاءَ الزَّكَاةِ ۖ وَكَانُوا لَنَا عَابِدِينَ فلم تزل في ذريته يرثها بعضٌ عن بعض قرناً فقرناً حتى ورثها النبي فقال إِنَّ أَوْلَى النَّاسِ بِإِبْرَاهِيمَ لَلَّذِينَ اتَّبَعُوهُ وَهَٰذَا النَّبِيُّ وَالَّذِينَ آمَنُوا ۗ وَاللَّهُ وَلِيُّ الْمُؤْمِنِينَ فكانت له خاصّة، فقلّدها علياً بأمر الله عزّ اسمُه على رسم ما فرضه الله، فصارت في ذريته الأصفياء الذين آتاهم الله العلم والإيمان بقوله وَقَالَ الَّذِينَ أُوتُوا الْعِلْمَ وَالْإِيمَانَ لَقَدْ لَبِثْتُمْ فِي كِتَابِ اللَّهِ إِلَىٰ يَوْمِ الْبَعْثِ ۖ فَهَٰذَا يَوْمُ الْبَعْثِ وَلَٰكِنَّكُمْ كُنْتُمْ لَا تَعْلَمُونَ فهي في ولْد علي خاصة إلى يوم القيامة إذ لا نبيّ بعد محمد ، فمِن أين يختار هؤلاء الجهالُ الإمامَ. إنّ الإمامة هي منْزلة الأنبياء وإرث الأوصياء. إن الإمامة خلافة الله وخلافة الرسول ومقام أمير المؤمنين وميراث الحسن والحسين إن الإمامة زمام الدين ونظام أمور المسلمين وصلاح الدنيا وعزّ المؤمنين. إن الإمامة هي أس الإسلام النامي وفرعه السامي. بالإمام تمام الصلاة والزكاة والصيام والحج والجهاد، وتوفير الفيء والصدقات وإمضاء الحدود والاحكام ومنع الثغور والأطراف. الإمام يحل حلال الله ويحرم حرام الله ويقيم حدود الله ويذب عن دين الله ويدعو إلى سبيل ربه بالحكمة والموعظة الحسنة والحجة البالغة. الإمام الشمس الطالعة المجللة بنورها للعالم وهي في الأفق بحيث لا تنالها الأيدي والأبصار. الإمام البدر المنير والسراج الزاهر والنور الساطع والنجم الهادي في غياهب الدجى وأجواز البلدان والقفار ولجج البحار. الإمام الماء العذب على الظماء والنور الدالّ على الهدى والمنجي من الردى. الإمام النار على اليفاع الحار لمن اصطلى به والدليل في المهالك، مَن فارقه فهالكٌ. الإمام السحاب الماطر والغيث الهاطل والشمس المضيئة والسماء الظليلة والأرض البسيطة والعين الغزيرة والغدير والروضة. الإمام الأنيس الرفيق والوالد الشفيق والأخ الشقيق والأم البرة بالوالد الصغير ومفزع العباد في الداهية الناد. الإمام أمين الله في خلقه وحجته على عباده وخليفته في بلاده والداعي إلى الله والذابّ عن حرم الله. الإمام المطهر من الذنوب والمبرء عن العيوب المخصوص بالعلم الموسوم بالحلم، نظام الدين وعزّ المسلمين وغيظ المنافقين وبوار الكافرين. الإمام واحد دهره لا يدانيه أحدٌ ولا يعادله عالم ولا يوجد منه بدل ولا له مثل ولا نظير، مخصوص بالفضل كله من غير طلب منه له ولا اكتساب، بل اختصاص من المفضل الوهاب. فمَن ذا الذي يبلغ معرفة الإمام أو يمكنه اختياره؟ هيهات هيهات! ضلّت العقول وتاهت الحلوم وحارت الألباب وخسئت العيون وتصاغرت العظماء وتحيّرت الحكماء وتقاصرت الحلماء وحصرت الخطباء وجهلت الألبّاء وكلّت الشعراء وعجزت الأدباء وعييت البلغاء عن وصف شأنٍ من شأنه أو فضيلة من فضائله، فأقرّت بالعجز والتقصير. وكيف يوصف بكلّه أو ينعت بكنهه أو يفهم شيء من أمره أو يوجد مَن يقوم مقامه ويغني غناه؟ لا كيف وأنى وهو بحيث النجم من يد المتناولين ووصف الواصفين، فأين الاختيار من هذا؟ وأين العقول عن هذا، وأين يوجد مثل هذا؟ أتظنون أن ذلك يوجد في غير آل الرسول محمد ؟ كذّبتهم واللهِ أنفسُهم ومنّتهم الأباطيل فارتقوا مرتقاً صعباً دحضاً تزلّ عنه إلى الحضيض أقدامُهم. راموا إقامةَ الإمام بعقول حائرة بائرة ناقصة وآراء مضلة فلم يزدادوا منه إلاّ بعداً، لقد رامو صعباً وقالوا إفكاً وضلوا ضلالاً بعيداً ووقعوا في الحيرة إذ تركوا الإمام عن بصيرة، وزيّن لهم الشيطانُ أعمالهم فصدّهم عن السبيل وكانوا مستبصرين. رغبوا عن اختيار الله واختيار رسول الله وأهل بيته إلى اختيارهم، والقرآنُ يناديهم وَرَبُّكَ يَخْلُقُ مَا يَشَاءُ وَيَخْتَارُ ۗ مَا كَانَ لَهُمُ الْخِيَرَةُ ۚ سُبْحَانَ اللَّهِ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ ويقول وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ ۗ وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَقَدْ ضَلَّ ضَلَالًا مُبِينًا {36} وقال أَمْ لَكُمْ كِتَابٌ فِيهِ تَدْرُسُونَ {37} إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ {38} أَمْ لَكُمْ أَيْمَانٌ عَلَيْنَا بَالِغَةٌ إِلَىٰ يَوْمِ الْقِيَامَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ {39} سَلْهُمْ أَيُّهُمْ بِذَٰلِكَ زَعِيمٌ {40} أَمْ لَهُمْ شُرَكَاءُ فَلْيَأْتُوا بِشُرَكَائِهِمْ إِنْ كَانُوا صَادِقِينَ {41} وقال أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَا {24} أم رَضُوا بِأَنْ يَكُونُوا مَعَ الْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ {87} أم وَلَا تَكُونُوا كَالَّذِينَ قَالُوا سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ {21} إِنَّ شَرَّ الدَّوَابِّ عِنْدَ اللَّهِ الصُّمُّ الْبُكْمُ الَّذِينَ لَا يَعْقِلُونَ {22} وَلَوْ عَلِمَ اللَّهُ فِيهِمْ خَيْرًا لَأَسْمَعَهُمْ ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوْا وَهُمْ مُعْرِضُونَ {23} أم وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُمْ بِقُوَّةٍ وَاسْمَعُوا ۖ قَالُوا سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُمْ بِهِ إِيمَانُكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ {93} بل هو فكيف لهم باختيار الإمام؟ والإمام عالم لا يجهل وراعٍ لا ينكل، معدن القدس والطهارة والنسك والزهادة والعلم والعبادة، مخصوصٌ بدعوة الرسول ونسل المطهرة البتول، لا مغمز فيه في نسب ولا يدانيه ذو حسب، فالبيت من قريش، والذروة من هاشم، والعترة من الرسول والرضى من الله ، شرف الأشراف، والفرع عن عبد مناف، نامي العلم، كامل الحلم، مضطلع بالإمامة، عالم بالسياسة، مفروض الطاعة، قائم بأمر الله ، ناصح لعباد الله، حافظ لدين الله. إنّ الأنبياء والأئمة صلوات الله عليهم يوفقهم الله ويؤتيهم من مخزون علمه وحكمه ما لا يؤتيه غيرهم، فيكون علمهم فوق علم أهل الزمان في قوله تعالى قُلْ هَلْ مِنْ شُرَكَائِكُمْ مَنْ يَهْدِي إِلَى الْحَقِّ ۚ قُلِ اللَّهُ يَهْدِي لِلْحَقِّ ۗ أَفَمَنْ يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَنْ يُتَّبَعَ أَمَّنْ لَا يَهِدِّي إِلَّا أَنْ يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ {35} يُؤْتِي الْحِكْمَةَ مَنْ يَشَاءُ ۚ وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا ۗ وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ {269} وقوله في طالوت وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا ۚ قَالُوا أَنَّىٰ يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمَالِ ۚ قَالَ إِنَّ اللَّهَ اصْطَفَاهُ عَلَيْكُمْ وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ ۖ وَاللَّهُ يُؤْتِي مُلْكَهُ مَنْ يَشَاءُ ۚ وَاللَّهُ وَاسِعٌ عَلِيمٌ {247} وقال لنبيه وَلَوْلَا فَضْلُ اللَّهِ عَلَيْكَ وَرَحْمَتُهُ لَهَمَّتْ طَائِفَةٌ مِنْهُمْ أَنْ يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّا أَنْفُسَهُمْ ۖ وَمَا يَضُرُّونَكَ مِنْ شَيْءٍ ۚ وَأَنْزَلَ اللَّهُ عَلَيْكَ الْكِتَابَ وَالْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُ ۚ وَكَانَ فَضْلُ اللَّهِ عَلَيْكَ عَظِيمًا {113} وقال في الأئمة من أهل بيت نبيه وعترته وذريته صلوات الله عليهم أجمعين أَمْ يَحْسُدُونَ النَّاسَ عَلَىٰ مَا آتَاهُمُ اللَّهُ مِنْ فَضْلِهِ ۖ فَقَدْ آتَيْنَا آلَ إِبْرَاهِيمَ الْكِتَابَ وَالْحِكْمَةَ وَآتَيْنَاهُمْ مُلْكًا عَظِيمًا {54} فَمِنْهُمْ مَنْ آمَنَ بِهِ وَمِنْهُمْ مَنْ صَدَّ عَنْهُ ۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا {55} وإنّ العبد إذا اختاره الله لأمور عباده شرح صدره لذلك وأودع قلبه ينابيع الحكمة وألهمه العلم إلهاماً، فلم يعِ بعده بجواب ولا يحير فيه عن صواب، فهو معصوم مؤيد، موفق مسدد، قد أمِن من الخطايا والزلل والعثار، يخصه الله بذلك ليكون حجته على عباده وشاهده على خلقه سَابِقُوا إِلَىٰ مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ۚ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ ۚ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ {21} فهل يقدرون على مثل هذا فيختارونه؟ أو يكون مختارهم بهذه الصفة فيقدمونه؟ تعدّوا وبيتِ الله الحقَّ، ونبذوا كتابَ الله وراء ظهورهم كأنهم لا يعلمون، وفي كتاب الله الهدى والشفاء، فنبذوه واتبعوا أهواءهم، فذمّهم الله تعالى ومقَتَهم وأتعَسَهم فقال فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ ۚ وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ ۚ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ {50} وقال وَالَّذِينَ كَفَرُوا فَتَعْسًا لَهُمْ وَأَضَلَّ أَعْمَالَهُمْ {8} وقال الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ ۖ كَبُرَ مَقْتًا عِنْدَ اللَّهِ وَعِنْدَ الَّذِينَ آمَنُوا ۚ كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ","22/2/13/6",""],[7,13,"وعن محمد بن يحيى، عن أحمد بن محمد بن عيسى، عن الحسن بن محبوب عن إسحاق بن غالب، عن أبي عبد الله جعفر بن محمد في خطبة له يذكر فيها حال الأئمة وصفاتهم فقال: إن الله تعالى أوضح بأئمة الهدى من أهل بيت نبيه عن دينه، وأبلج بهم عن سبيل منهاجه، وفتح لهم عن باطن ينابيع علمه، فمَن عرف من أمة محمد واجبَ حقّ إمامه وجد طعمَ حلاوةِ إيمانه وعلم فضل طلاوة إسلامه لأن الله تعالى نصب الإمام علماً لخلقه، وجعله حجة على أهل طاعته، ألبسه الله تاج الوقار وغشّاه من نور الجبار، يمد بسبب إلى السماء، لا ينقطع عنه مواده، ولا ينال ما عند الله إلاّ بجهة أسبابه، ولا يقبل الله الأعمال للعباد إلاّ بمعرفته. فهو عالم بما يرد عليه من مشكلات الدجى ومعميات السنن ومشتبهات الفتن، فلم يزل الله تعالى يختارهم لخلقه من ولد الحسين ، من عقب كل إمام، فيصطفيهم كذلك ويجتبيهم ويرضى بهم لخلقه ويرتضيهم لنفسه، كلما مضى منهم إمام نصب لخلقه إماماً علماً بيّناً وهادياً منيراً وإماماً قيّماً وحجة عالماً. أئمة من الله يهدون بالحق وبه يعدلون، حجج الله ودعاته ورعاته على خلقه، يدين بهديهم العباد وتستهل بنورهم البلاد وينمو ببركتهم التلاد، جعلهم الله حياة للأنام ومصابيح للظلام ومفاتيح للكلام ودعائم للاسلام، جرت بذلك فيهم مقادير الله على محتومها. فالإمام هو المنتجب المرتضى والهادي المجتبى والقائم المرتجى، اصطفاه الله بذلك واصطنعه على عينه في الذر حين ذرأه، وفي البرية حين برأه ظلاً قبل خلقه نسمة عن يمين عرشه، محبوّاً بالحكمة في علم الغيب عنده، اختاره بعلمه وانتجبه لطهره بقية من آدم، وخيرة من ذرية نوح، ومصطفى من آل إبراهيم، وسلالة من إسماعيل، وصفوة من عترة محمد . لم يزل مرعياً بعين الله يحفظه بملائكته، مدفوعاً عنه وقوب الغواسق، ونفوث كل فاسق، مصروفاً عنه قوارف السوء، مبرءاً من العاهات محجوباً عن الآفات معصوماً من الزلات مصوناً من الفواحش كلها، معروفا بالحلم والبر في يفاعه منسوباً إلى العفاف والعلم والفضل عند انتهائه، مسنداً إليه أمر والده، صامتاً عن المنطق في حياته. فإذا انقضت مدة والده وانتهت به مقادير الله إلى مشيته، وجاءت الإرادة من عند الله فيه إلى محبته وبلغ منتهى مدة والده فمضى، صار أمر الله إليه من بعده وقلّده الله دينه، وجعله الحجة على عباده وقيمه في بلاده وأيده بروحه وأعطاه علمه واستودعه سره وانتدبه لعظيم أمره وأنبأه فصل بيان علمه ونصبه علما لخلقه وجعله حجة على أهل عالمه وضياءً لأهل دينه والقيم على عباده. رضيَ الله به إماماً لهم؛ استحفظه علمه واستخبأه حكمته واسترعاه لدينه وأحيا به مناهج سبيله وفرائضه وحدوده، فقام بالعدل عند تحيّر أهل الجهل وتحيير أهل الجدل بالنور الساطع والشفاء البالغ بالحق الأبلج والبيان اللائح مِن كل مخرج على طريق المنهج الذي مضى عليه الصادقون من آبائه  فليس يجهل حق هذا العالم إلاّ شقيّ ولا يجحده إلاّ غويّ ولا يدعه إلاّ جريّ على الله.","22/2/13/7",""],[8,13,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل بن قيس بن رمانة الأشعري وسعدان بن إسحاق بن سعيد وأحمد بن الحسين بن عبد الملك ومحمد بن الحسن القطواني قالوا جميعاً: حدثنا الحسن بن محبوب الزراد عن هشام بن سالم، عن يزيد الكناسي قال: سمعت أبا جعفر محمد بن علي الباقر يقول: إنّ صاحب هذا الأمر فيه شبه من يوسف؛ ابن أمة سوداء، يصلح الله له أمره في ليلة واحدة.","22/2/13/8",""],[9,13,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أحمد بن محمد بن رباح الزهري، قال: حدثنا أحمد بن علي الحميري، قال: حدثنا الحكم أخو مشمعل الأسدي قال: حدثني عبد الرحيم القصير قال: قلت لأبي جعفر: قول أمير المؤمنين \"بأبي ابن خيرة الإماء\" أهي فاطمة ؟ فقال: إن فاطمة خيرة الحرائر. ذاك المبدح بطنه، المشربّ حمرة، رحم الله فلاناً.","22/2/13/9",""],[10,13,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام، عن عبد الله بن جبلة، عن علي بن أبي المغيرة، عن أبي الصباح قال: دخلت على أبي عبد الله فقال لي: ما وراءك؟ فقلت: سرور من عمك زيد؛ خرج يزعم أنه ابن سبيّة وهو قائم هذه الأمة وأنه ابن خيرة الإماء. فقال: كذب ليس هو كما قال، إن خرج قتل.","22/2/13/10",""],[11,13,"حدثنا محمد بن همام ومحمد بن الحسن بن جمهور جميعاً، عن الحسن بن محمد بن جمهور، عن أبيه، عن سليمان بن سماعة، عن أبي الجارود، عن القاسم بن الوليد الهمداني، عن الحارث الاعور الهمداني قال: قال أمير المؤمنين: بأبي ابن خيرة الإماء (يعنى القائم من ولده ) يسومهم خسفا، ويسقيهم بكأس مصبرة، ولا يعطيهم إلاّ السيف هرجاً فعند ذلك تتمنى فجرة قريش لو أن لها مفاداة من الدنيا وما فيها ليغفر لها، لا نكف عنهم حتى يرضى الله.","22/2/13/11",""],[12,13,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملى قال: حدثنا محمد وأحمد ابنا الحسن عن أبيهما، عن ثعلبة بن ميمون، عن يزيد بن أبي حازم قال: خرجت من الكوفة، فلما قدمت المدينة دخلت على أبي عبد الله فسلمت عليه، فسألني هل صاحبك أحد؟ فقلت: نعم. فقال: أكنتم تتكلمون؟ قلت: نعم، صحبني رجل من المغيرية. قال: فما كان يقول؟ قلت: كان يزعم أن محمد بن عبد الله بن الحسن هو القائم، والدليل على ذلك أن اسمه اسم النبي واسم أبيه اسم أبي النبي، فقلت له في الجواب: إن كنت تأخذ بالأسماء فهو ذا في ولد الحسين محمد بن عبد الله بن علي. فقال لي: إنّ هذا ابن أمَة –(يعني محمد بن عبد الله بن علي) وهذا ابن مهيرة (يعني محمد بن عبد الله بن الحسن بن الحسن). فقال أبو عبد الله: فما رددت عليه؟ فقلت: ما كان عندي شيء أرد عليه. فقال: أوَلم تعلموا أنه ابن سبية (يعني القائم )؟ 13- أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أحمد بن محمد بن رباح، قال: حدثنا أحمد بن علي الحميري قال: حدثني الحسن بن أيوب، عن عبد الكريم بن عمرو قال: حدثنا أحمد بن الحسن بن أبان قال: حدثنا عبد الله بن عطاء المكي، عن شيخ من الفقهاء (يعني أبا عبد الله ) قال: سألته عن سيرة المهدي كيف سيرته؟ فقال: يصنع كما صنع رسول الله ، يهدم ما كان قبله كما هدم رسول الله أمر الجاهلية، ويستأنف الإسلام جديداً.","22/2/13/12",""],[13,13,"أخبرنا علي بن الحسين قال: حدثني محمد بن يحيى العطار، عن محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن أحمد بن محمد بن أبي نصر، عن عبد الله بن بكير، عن أبيه، عن زرارة، عن أبي جعفر قال: قلت له: صالح من الصالحين سمّه لي (أريد القائم ) فقال: اسمه اسمي. قلت: أيسير بسيرة محمد ؟ قال: هيهات هيهات يا زرارة، ما يسير بسيرته. قلت: جعلت فداك لِمَ؟ قال: إنّ رسول الله سار في أمّته بالمنّ؛ كان يتألّف الناس، والقائم يسير بالقتل؛ بذاك أُمِر في الكتاب الذي معه أن يسير بالقتل ولا يستتيب أحداً. ويل لمَن ناواه.","22/2/13/13",""],[14,13,"أخبرنا علي بن الحسين بهذا الإسناد، عن محمد بن علي الكوفي، عن عبد الرحمن بن أبي هاشم، عن أبي خديجة، عن أبي عبد الله أنه قال: إن علياً قال: كان لي أن أقتل المولي وأجهز على الجريح ولكني تركت ذلك للعاقبة من أصحابي؛ إن جرحوا لم يقتلوا، والقائم له أن يقتل المولي ويجهز على الجريح.","22/2/13/14",""],[15,13,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن، عن محمد بن خالد، عن ثعلبة بن ميمون، عن الحسن بن هارون بياع الانماط قال: كنت عند أبي عبد الله جالسا، فسأله المعلي بن خنيس: أيسير القائم إذا قام بخلاف سيرة علي ؟ فقال: نعم، وذاك أن علياً سار بالمنّ والكفّ لأنه علم أن شيعته سيظهر عليهم من بعده، وأن القائم إذا قام سار فيهم بالسيف والسبي، وذلك أنه يعلم أن شيعته لم يظهر عليهم من بعده أبداً.","22/2/13/15",""],[16,13,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن أبيه، عن رفاعة بن موسى، عن عبد الله بن عطاء قال: سألت أبا جعفر الباقر فقلت: إذا قام القائم بأي سيرة يسير في الناس؟ فقال: يهدم ما قبله، كما صنع رسول الله ، ويستأنف الإسلام جديداً.","22/2/13/16",""],[17,13,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، عن محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن أحمد بن محمد بن أبي نصر، عن العلاء عن محمد بن مسلم قال: سمعت أبا جعفر يقول: لو يعلم الناس مايصنع القائم إذا خرج لأحبّ أكثرُهم إلاّ يروه مما يقتل من الناس، أما إنه لا يبدأ إلاّ بقريش فلا يأخذ منها إلاّ السيف، ولا يعطيها إلاّ السيف حتى يقول كثير من الناس: ليس هذا من آل محمد، ولو كان من آل محمد لرحم.","22/2/13/17",""],[18,13,"وأخبرنا علي بن الحسين بإسناده عن أحمد بن محمد بن أبي نصر، عن عاصم ابن حميد الحناط، عن أبي بصير قال: قال أبو جعفر: يقوم القائم بأمر جديد، وكتاب جديد، وقضاء جديد، على العرب شديد، ليس شأنه إلاّ السيف، لا يستتيب أحداً، ولا يأخذه في الله لومة لائم.","22/2/13/18",""],[19,13,"أخبرنا علي بن الحسين بإسناده عن محمد بن علي الكوفي، عن الحسن بن محبوب، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله أنه قال: ما تستعجلون بخروج القائم؟ فوالله ما لباسه إلاّ الغليظ، ولا طعامه إلاّ الجشب، وما هو إلاّ السيف، والموت تحت ظل السيف.","22/2/13/19",""],[20,13,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا أحمد بن يوسف بن يعقوب أبو الحسن الجعفي، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب، عن أبي بصير، عن أبي عبد الله أنه قال: إذا خرج القائم لم يكن بينه وبين العرب وقريش إلاّ السيف، ما يأخذ منها إلاّ السيف، وما يستعجلون بخروج القائم؟ والله ما لباسه إلاّ الغليظ، ما طعامه إلاّ الشعير الجشب، وما هو إلاّ السيف، والموت تحت ظل السيف.","22/2/13/20",""],[21,13,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا يحيى بن زكريا بن شيبان قال: حدثنا يوسف بن كليب، قال: حدثنا الحسن بن علي بن أبي حمزة، عن عاصم ابن حميد الحناط، عن أبي حمزة الثمالي قال: سمعت أبا جعفر محمد بن علي يقول: لو قد خرج قائم آل محمد  لنصره الله بالملائكة المسومين والمردفين والمنـزلين والكروبيين، يكون جبرئيل أمامه، وميكائيل عن يمينه، وإسرافيل عن يساره، والرعب يسير مسيرة شهر أمامه وخلفه وعن يمينه وعن شماله، والملائكة المقربون حذاه. أول من يتبعه محمد وعلي الثاني، ومعه سيف مخترط، يفتح الله له الروم والديلم والسند والهند وكابل شاه والخزر. يا أبا حمزة، لا يقوم القائم إلاّ على خوف شديد وزلازل وفتنة وبلاء يصيب الناس وطاعون قبل ذلك، وسيف قاطع بين العرب، واختلاف شديد بين الناس، وتشتت في دينهم، وتغير من حالهم حتى يتمنى المتمني الموت صباحاً ومساءً مِن عِظم ما يرى من كلَب الناس، وأكل بعضهم بعضاً، وخروجه إذا خرج عند الأياس والقنوط. فيا طوبى لمن أدركه وكان من أنصاره، والويل كل الويل لمن خالفه وخالف أمره وكان من أعدائه. ثم قال: يقوم بأمر جديد، وسنة جديدة، وقضاء جديد على العرب شديد، ليس شأنه إلاّ القتل ولا يستتيب أحدا، ولا تأخذه في الله لومة لائم.","22/2/13/21",""],[22,13,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام، عن عبد الله بن جبله، عن علي بن أبي المغيرة، قال: حدثنا عبد الله بن شريك العامري، عن بشر بن غالب الأسدي قال: قال لي الحسين بن علي: يا بِشر، ما بقاء قريش إذا قدم القائم المهدي منهم خمسمائة رجل فضرب أعناقهم صبراً، ثم قدم خمسمائة فضرب أعناقهم صبراً، ثم خمسمائة فضرب أعناقهم صبراً. (قال) فقلت له: أصلحك الله، أيبلغون ذلك؟ فقال الحسين بن علي: إن مولى القوم منهم. (قال) فقال لي بشير بن غالب أخو بشر بن غالب: أشهد أن الحسين بن علي عدَّ على أخي ست عدات - أو قال ست عددات - على اختلاف الرواية.","22/2/13/22",""],[23,13,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل بن إبراهيم قال: حدثني محمد بن عبد الله بن زرارة، عن الحارث بن المغيرة وذريح المحاربي قالا: قال أبو عبد الله: ما بقي بيننا وبين العرب إلاّ الذبح - وأومأ بيده إلى حلقه.","22/2/13/23",""],[24,13,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الصيرفي، عن محمد بن سنان، عن محمد بن علي الحلبي، عن سدير الصيرفي، عن رجل من أهل الجزيرة كان قد جعل على نفسه نذراً في جارية وجاء بها إلى مكة، قال: فلقيت الحجبة فأخبرتهم بخبرها وجعلت لا أذكر لأحد منهم أمرها إلاّ قال لي: جئني بها وقد وفى الله نذرك فدخلني من ذلك وحشة شديدة، فذكرت ذلك لرجل من أصحابنا من أهل مكة، فقال لي: تأخذ عني؟ فقلت: نعم، فقال: انظر الرجل الذي يجلس بحذاء الحجر الأسود وحوله الناس وهو أبو جعفر محمد بن علي بن الحسين  فأتِه فأخبره بهذا الأمر فانظر ما يقول لك فاعمل به. قال: فأتيته فقلت: رحمك الله إني رجل من أهل الجزيرة ومعي جارية جعلتها عليَّ نذراً لبيت الله في يمين كانت عليّ وقد أتيت بها، وذكرت ذلك للحجبة، وأقبلت لا ألقى منهم أحدا إلاّ قال جئني بها وقد وفى الله نذرك، فدخلني من ذلك وحشة شديدة. فقال: يا عبد الله، إن البيت لا يأكل ولا يشرب، فبِع جاريتك واستقصِ وانظر أهل بلادك ممّن حجّ هذا البيت فمَن عجز منهم عن نفقته فأعطِه حتى يقوى على العود إلى بلادهم. ففعلت ذلك. ثم أقبلت لا ألقى أحداً من الحجبة إلاّ قال ما فعلتَ بالجارية؟ فأخبرتهم بالذي قال أبو جعفر فيقولون: هو كذابٌ جاهل لا يدري ما يقول. فذكرت مقالتهم لأبي جعفر ، فقال: قد بلغتني، تبلغ عني؟ فقلت: نعم. فقال: قل لهم: قال لكم أبو جعفر: كيف بكم لو قد قطعت أيديكم وأرجلكم وعلقت في الكعبة، ثم يقال لكم: نادوا نحن سرّاق الكعبة. فلمّا ذهبت لأقوم قال: إنني لست أنا أفعل ذلك، وإنما يفعله رجل مني.","22/2/13/24",""],[25,13,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى، قال: حدثنا محمد بن حسان الرازي قال: حدثنا محمد بن علي الصيرفي، عن الحسن بن محبوب، عن عمرو بن شمر، عن جابر قال: دخل رجل على أبي جعفر الباقر فقال له: عافاك الله، اقبض مني هذه الخمسمائة درهم فإنها زكاة مالي. فقال له أبو جعفر: خذها أنت فضعها في جيرانك من أهل الإسلام والمساكين من إخوانك المؤمنين. ثم قال: إذا قام قائم أهل البيت قسم بالسوية وعدل في الرعية، فمن أطاعه فقد أطاع الله ومن عصاه فقد عصى الله، وإنما سمي المهدي مهدياً لأنه يهدي إلى أمر خفي، ويستخرج التوراة وسائر كتب الله من غار بأنطاكية ويحكم بين أهل التوراة بالتوراة وبين أهل الإنجيل بالإنجيل، وبين أهل الزبور بالزبور، وبين أهل القرآن بالقرآن وتجمع إليه أموال الدنيا من بطن الأرض وظهرها، فيقول للناس: تعالوا إلى ما قطعتم فيه الأرحام وسفكتم فيه الدماء الحرام وركبتم فيه ما حرم الله ، فيعطي شيئاً لم يعطه أحد كان قبله، ويملأ الأرض عدلاً وقسطاً ونوراً كما ملئت ظلماً وجوراً وشراً.","22/2/13/25",""],[26,13,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل بن إبراهيم وسعدان بن إسحاق بن سعيد وأحمد بن الحسين بن عبد الملك ومحمد بن أحمد بن الحسن القطواني قالوا جميعاً: حدثنا الحسن بن محبوب، عن عبد الله بن سنان قال: سمعت أبا عبد الله يقول: عصا موسى قضيب آس من غرس الجنة أتاه بها جبرئيل لما توجه تلقاء مدين، وهي وتابوت آدم في بحيرة طبرية، ولن يبليا ولن يتغيرا حتى يخرجهما القائم إذا قام.","22/2/13/26",""],[27,13,"أخبرنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، قال: حدثنا أبو الجارود زياد بن المنذر، قال: قال أبو جعفر محمد بن علي: إذا ظهر القائم ظهر براية رسول الله ، وخاتم سليمان، وحجر موسى وعصاه، ثم يأمر مناديه فينادي إلاّ لا يحملن رجل منكم طعاماً ولا شراباً ولا علفاً، فيقول أصحابه: إنه يريد أن يقتلنا ويقتل دوابنا من الجوع والعطش، فيسير ويسيرون معه، فأول منـزل ينـزله يضرب الحجر فينبع منه طعام وشراب وعلف، فيأكلون ويشربون، ودوابهم حتى ينـزلوا النجف بظهر الكوفة.","22/2/13/27",""],[28,13,"أخبرنا محمد بن همام ومحمد بن الحسن بن محمد بن الجمهور العمي، عن الحسن بن محمد بن الجمهور، عن أبيه، عن سليمان بن سماعة، عن أبي الجارود، عن أبي جعفر محمد بن علي أنه قال: إذا خرج القائم من مكة ينادي مناديه إلاّ لا يحملن أحد طعاماً ولا شراباً، ويحمل معه حجر موسى بن عمران، وهو وقر بعير، فلا ينـزل منـزلاً إلاّ نبعت منه عيون، فمن كان جائعا شبع، ومن كان ظمآنا روي، ورويت دوابهم حتى ينـزلوا النجف من ظهر الكوفة.","22/2/13/28",""],[29,13,"أخبرنا أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، عن عبد الله بن بكير، عن حمران بن أعين عن أبي جعفر أنه قال: كأنني بدينكم هذا لا يزال متخضخضاً يفحص بدمه ثم لا يردّه عليكم إلاّ رجل منا أهل البيت، فيعطيكم في السنة عطاءين ويرزقكم في الشهر رزقين، وتؤتون الحكمة في زمانه حتى أن المرأة لتقضي في بيتها بكتاب الله تعالى وسنة رسول الله .","22/2/13/29",""],[30,13,"أخبر نا عبد الواحد بن عبد الله، قال: حدثنا أحمد بن محمد بن رباح، قال: حدثنا محمد بن العباس بن عيسى، قال: حدثنا الحسن بن علي البطائني، عن أبيه عن المفضل، قال: سمعت أبا عبد الله يقول: إن لصاحب هذا الأمر بيتاً يقال له: بيت الحمد، فيه سراج يزهر منذ يوم ولد إلى يوم يقوم بالسيف لا يطفأ.","22/2/13/30",""],[31,13,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملى، عن أبيه، عن الحسن بن علي بن يوسف ومحمد بن علي الكوفي عن سعدان بن مسلم عن بعض رجاله، عن أبي عبد الله أنه قال: بينا الرجل على رأس القائم يأمره وينهاه إذ قال: أديروه، فيديرونه إلى قدامه، فيأمر بضرب عنقه، فلا يبقى في الخافقين شيء إلاّ خافه.","22/2/13/31",""],[32,13,"حدثنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن أحمد بن محمد بن خالد، عن أبيه، عن سعدان بن مسلم، عن هشام بن سالم، عن أبي عبد الله أنه قال: بينا الرجل على رأس القائم يأمر وينهى إذا أمر بضرب عنقه، فلا يبقى بين الخافقين شيء إلاّ خافه.","22/2/13/32",""],[33,13,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن التيملي في صفر سنة أربع وسبعين ومائتين قال: حدثني محمد بن علي، عن محمد بن إسماعيل بن بزيع، عن منصور بن يونس بزرج، عن حمزة بن حمران، عن سالم الاشل قال: سمعت أبا جعفر محمد بن علي الباقر يقول: نظر موسى بن عمران في السفر الأول إلى ما يعطى قائم آل محمد من التمكين والفضل، فقال موسى: رب اجعلني قائم آل محمد، فقيل له: إنّ ذاك من ذرية أحمد، ثم نظر في السفر الثاني فوجد فيه مثل ذلك، فقال مثله، فقيل له مثل ذلك، ثم نظر في السفر الثالث فرأى مثله، فقال مثله، فقيل له مثله.","22/2/13/33",""],[34,13,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي أبو الحسن من كتابه قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب، عن أبي بصير، عن أبي عبد الله في معنى قوله وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا ۚ يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا ۚ وَمَنْ كَفَرَ بَعْدَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ قال: نزلت في القائم وأصحابه.","22/2/13/34",""],[35,13,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا حميد بن زياد، قال: حدثنا علي بن الصباح قال: حدثنا أبو علي الحسن بن محمد الحضرمي قال حدثنا جعفر بن محمد عن إبراهيم بن عبد الحميد، عن إسحاق بن عبد العزيز، عن أبي عبد الله في قوله تعالى وَلَئِنْ أَخَّرْنَا عَنْهُمُ الْعَذَابَ إِلَىٰ أُمَّةٍ مَعْدُودَةٍ لَيَقُولُنَّ مَا يَحْبِسُهُ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ قال: العذاب خروج القائم ، والأمّة المعدودة عدة أهل بدر وأصحابه.","22/2/13/35",""],[36,13,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف، قال: حدثنا إسماعيل بن مهران، عن الحسن بن علي، عن أبيه ووهيب، عن أبي بصير، عن أبي عبد الله في قوله وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَاسْتَبِقُوا الْخَيْرَاتِ ۚ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ قال: نزلت في القائم وأصحابه، يجتمعون على غير ميعاد.","22/2/13/36",""],[37,13,"أخبر نا علي بن الحسين المسعودي، قال: حدثنا محمد بن يحيى العطار القمي، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي قال: حدثنا عبد الرحمن بن أبي نجران، عن القاسم، عن أبي بصير، عن أبي عبد الله في قول الله أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا ۚ وَإِنَّ اللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ قال: هي في القائم وأصحابه.","22/2/13/37",""],[38,13,"حدثنا علي بن أحمد قال: حدثنا عبيد الله بن موسى، عن أحمد بن محمد بن خالد، عن أبيه، عن محمد بن سليمان الديلمي، عن أبي بصير، عن أبي عبد الله في قوله تعالى يُعْرَفُ الْمُجْرِمُونَ بِسِيمَاهُمْ فَيُؤْخَذُ بِالنَّوَاصِي وَالْأَقْدَامِ قال: الله يعرفهم، ولكن نزلت في القائم يعرفهم بسيماهم فيخطبهم بالسيف هو وأصحابه خبطاً.","22/2/13/38",""],[39,13,"حدثنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن محمد بن عبد الجبار عن صفوان بن يحيى، عن أبي سعيد المكاري، عن الحارث بن المغيرة النصري، قال: قلت لأبي عبد الله بأي شيء يعرف الإمام؟ قال: بالسكينة والوقار. قلت: وبأي شيء؟ قال: وتعرفه بالحلال والحرام، وبحاجة الناس إليه، ولا يحتاج إلى أحد، ويكون عنده سلاح رسول الله . قلت: أيكون إلاّ وصياً ابن وصي؟ قال: لا يكون إلاّ وصياً وابن وصي.","22/2/13/39",""],[40,13,"حدثنا محمد بن همام ومحمد بن الحسن بن محمد بن جمهور، جميعاً عن الحسن بن محمد بن جمهور، عن أبيه، عن سليمان بن سماعة، عن أبي الجارود قال: قالت لأبي جعفر: إذا مضى الإمام القائم من أهل البيت فبأي شيء يعرف من يجيء بعده؟ قال: بالهدى والإطراق، وإقرار آل محمد له بالفضل، ولا يسأل عن شيء بين صدفيها إلاّ أجاب.","22/2/13/40",""],[41,13,"حدثنا محمد بن همام، قال: حدثنا حميد بن زياد الكوفي، قال: حدثنا الحسن بن محمد بن سماعة، قال: حدثنا أحمد بن الحسن الميثمي، عن عمه الحسين بن إسماعيل، عن يعقوب بن شعيب، عن أبي عبد الله أنه قال: ألا أريك قميص القائم الذي يقوم عليه؟ فقلت: بلى. قال: فدعا بقمطر ففتحه، وأخرج منه قميص كرابيس فنشره فإذا في كمه الأيسر دم، فقال: هذا قميص رسول الله الذي عليه يوم ضربت رباعيته، وفيه يقوم القائم. فقبّلت الدم ووضعته على وجهي، ثم طواه أبو عبد الله ورفعه.","22/2/13/41",""],[42,13,"حدثنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن علي بن الحسن عن علي بن حسان، عن عبد الرحمن بن كثير، عن أبي عبد الله في قول الله أَتَىٰ أَمْرُ اللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ قال: هو أمرُنا، أمرَ الله أن لا تستعجل به حتى يؤيده الله بثلاثة أجناد: الملائكة، والمؤمنين، والرعب. وخروجه كخروج رسول الله ، وذلك قوله تعالى كَمَا أَخْرَجَكَ رَبُّكَ مِنْ بَيْتِكَ بِالْحَقِّ وَإِنَّ فَرِيقًا مِنَ الْمُؤْمِنِينَ لَكَارِهُونَ","22/2/13/42",""],[43,13,"حدثنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، عن علي بن أبي حمزة، قال: قال أبو عبد الله: إذا قام القائم صلوات الله عليه نزلت ملائكة بدر وهم خمسة آلاف ثلث على خيول شهب، وثلث على خيول بلق، وثلث على خيول حو. قلت: وما الحو؟ قال: هي الحمر.","22/2/13/43",""],[44,13,"وبه عن عبد الله بن حماد، عن ابن أبي حمزة، عن أبي عبد الله قال: إذا قام القائم ن��لت سيوف القتال، على كل سيف اسم الرجل واسم أبيه.","22/2/13/44",""],[45,13,"علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن الحسن بن معاوية عن الحسن بن محبوب، عن خلاد بن الصفار، قال: سئل أبو عبد الله: هل ولد القائم ؟ فقال: لا، ولو أدركته لخدمته أيام حياتي.","22/2/13/45",""],[1,14,"حدثنا أبو سليمان أحمد بن هوذة الباهلي، قال: حدثنا أبو إسحاق إبراهيم بن إسحاق النهاوندي بنهاوند سنة ثلاث وتسعين ومائتين، قال: حدثنا عبد الله بن حماد الأنصاري في شهر رمضان سنة تسع وعشرين ومائتين، عن أبان بن عثمان قال: قال أبو عبد الله جعفر بن محمد: بينا رسول الله ذات يوم في البقيع حتى أقبل علي فسأل عن رسول الله فقيل إنه بالبقيع، فأتاه علي فسلم عليه فقال رسول الله: اجلس، فأجلسه عن يمينه، ثم جاء جعفر بن أبي طالب فسأل عن رسول الله فقيل له: هو بالبقيع فأتاه فسلم عليه فأجلسه عن يساره، ثم جاء العباس فسأل عن رسول الله فقيل له: هو بالبقيع فأتاه فسلم عليه فأجلسه أمامه. ثم التفت رسول الله إلى علي فقال: ألا أبشرك؟ ألا أخبرك يا علي؟ فقال: بلى يا رسول الله. فقال: كان جبرئيل عندي آنفاً وأخبرني أنّ القائم الذي يخرج في آخر الزمان فيملأ الأرض عدلاً كما ملئت ظلماً وجوراً من ذريتك من ولد الحسين. فقال علي: يا رسول الله، ما أصابنا خير قط من الله إلاّ على يديك. ثم التفت رسول الله إلى جعفر بن أبي طالب فقال: يا جعفر ألا أبشرك؟ ألا أخبرك؟ قال: بلى يا رسول الله. فقال: كان جبرئيل عندي آنفاً فأخبرني أن الذي يدفعها إلى القائم هو من ذريتك، أتدري من هو؟ قال: لا. قال: ذاك الذي وجهه كالدينار، وأسنانه كالمنشار، وسيفه كحريق النار، يدخل الجند ذليلاً، ويخرج منه عزيزاً، يكتنفه جبرئيل وميكائيل. ثم التفت إلى العباس فقال: يا عمّ النبي، ألا أخبرك بما أخبرني به جبرئيل ؟ فقال: بلي يا رسول الله قال: قال لي جبرئيل: ويلٌ لذريتك من ولد العباس. فقال: يا رسول الله أفلا أجتنب النساء؟ فقال له: قد فرغ الله مما هو كائن.","22/2/14/1",""],[2,14,"أخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن أحمد بن محمد بن خالد، عن إبراهيم بن محمد بن المستنير، عن عبد الرحمن بن القاسم، عن أبيه عن عبد الله بن عباس قال: قال رسول الله لأبي: يا عباس، ويل لذريتي من ولدك، وويل لولدك من ولدي. فقال: يا رسول الله أفلا أجتنب النساء؟ (أو قال: أفلا أجب نفسي؟) قال: إنّ علم الله قد مضى والأمور بيده، وإن الأمر سيكون في ولدي.","22/2/14/2",""],[3,14,"أخبرنا أحمد بن محمد بن سعيد بن عقدة، قال: حدثنا حميد بن زياد الكوفي قال: حدثني علي بن الصباح المعروف بابن الضحاك، قال: حدثنا أبو علي الحسن بن محمد الحضرمي، قال: حدثنا جعفر بن محمد، عن إبراهيم بن عبد الحميد، عن سعد بن طريف، عن الاصبغ بن نباتة، عن علي أنه قال: يأتيكم بعد الخمسين والمائة أمراء كفرة، وأمناء خونة، وعرفاء فسقة، فتكثر التجار وتقل الأرباح، ويفشو الربا، وتكثر أولاد الزنا، وتغمر السفاح، وتتناكر المعارف، وتعظم الأهلة، وتكتفي النساء بالنساء، والرجال بالرجال. فحدث رجل عن علي بن أبي طالب أنه قام إليه رجل حين تحدث بهذا الحديث فقال له: يا أمير المؤمنين وكيف نصنع في ذلك الزمان؟ فقال: الهرب الهرب، فإنه لا يزال عدل الله مبسوطاً على هذه الأمة ما لم يمِل قراؤهم إلى أمرائهم وما لم يزل أبرارهم ينهى فجارهم، فإن لم يفعلوا ثم استنفروا فقالوا: لا إله إلاّ الله، قال الله في عرشه: كذبتم لستم بها صادقين.","22/2/14/3",""],[4,14,"حدثنا محمد بن همام في منـزله ببغداد في شهر رمضان سنة سبع وعشرين وثلاثمائة قال: حدثني أحمد بن مابنداذ سنة سبع وثمانين ومائتين، قال: حدثنا أحمد بن هلال، قال: حدثني الحسن بن علي بن فضال، قال: حدثنا سفيان بن إبراهيم الجريري، عن أبيه، عن أبي صادق، عن أمير المؤمنين أنه قال: ملك بني العباس يسر لا عسر فيه، لو أجتمع عليهم الترك والديلم والسند والهند والبربر والطيلسان لن يزيلوه، ولا يزالون في غضارة من ملكهم حتى يشذ عنهم مواليهم وأصحاب دولتهم ويسلط الله عليهم علجاً يخرج من حيث بدأ ملكهم، لا يمرّ بمدينة إلاّ فتحها، ولا ترفع له راية إلاّ هدها، ولا نعمة إلاّ أزالها، الويل لمن ناواه، فلا يزال كذلك حتى يظفر ويدفع بظفره إلى رجل من عترتي، يقول بالحق ويعمل به.","22/2/14/4",""],[5,14,"حدثنا محمد بن همام قال: حدثنا عبد الله بن جعفر الحميري، قال: حدثنا الحسن بن محبوب، عن علي بن رئاب، عن محمد بن مسلم، عن أبي عبد الله جعفر بن محمد أنه قال: إنّ قدّام قيام القائم علامات: بلوى من الله تعالى لعباده المؤمنين. قلت: وما هي؟ قال: ذلك قول الله وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوَالِ وَالْأَنْفُسِ وَالثَّمَرَاتِ ۗ وَبَشِّرِ الصَّابِرِينَ قال: (لنبلونكم) يعني المؤمنين، (بشيء من الخوف) من ملوك بني فلان في آخر سلطانهم، (والجوع) بغلاء أسعارهم، (ونقص من الأموال) فساد التجارات وقلة الفضل فيها، (والأنفس) موت ذريع (والثمرات) قلة ريع ما يزرع وقلة بركة الثمار، (وبشر الصابرين) عند ذلك بخروج القائم . ثم قال لي: يا محمد، هذا تأويله. إن الله يقول هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ ۖ فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ ۗ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِنْ عِنْدِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ","22/2/14/5",""],[6,14,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثني أحمد بن يوسف بن يعقوب أبو الحسن الجعفي من كتابه، قال: حدثنا إسماعيل بن مهران عن الحسن بن علي بن أبي حمزة، عن أبيه، عن أبي بصير قال: قال أبو عبد الله: لا بدّ أن يكون قدام القائم سنة يجوع فيها الناس ويصيبهم خوف شديد من القتل ونقص من الأموال والأنفس والثمرات، فإن ذلك في كتاب الله لبيّن. ثم تلا هذه الآية وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوَالِ وَالْأَنْفُسِ وَالثَّمَرَاتِ ۗ وَبَشِّرِ الصَّابِرِينَ","22/2/14/6",""],[7,14,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن علي بن إبراهيم بن هاشم، عن أبيه، عن محمد بن حفص، عن عمرو بن شمر، عن جابر الجعفي قال: سألت أبا جعفر محمد بن علي عن قول الله تعالى وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوَالِ وَالْأَنْفُسِ وَالثَّمَرَاتِ ۗ وَبَشِّرِ الصَّابِرِينَ فقال: يا جابر، ذلك خاص وعام، فأما الخاص من الجوع فبالكوفة، ويخص الله به أعداء آل محمد فيهلكهم، وأما العام فبالشام يصيبهم خوف وجوع ما أصابهم مثله قط، وأما الجوع فقبل قيام القائم ، وأما الخوف فبعد قيام القائم .","22/2/14/7",""],[8,14,"أخبرنا أحمد بن محمد بن سعيد، قال: حدثنا محمد بن المفضل بن إبراهيم ابن قيس، قال: حدثنا الحسن بن علي بن فضال، قال: حدثنا ثعلبة بن ميمون عن معمر بن يحيى، عن داود الدجاجي، عن أبي جعفر محمد بن علي ، قال: سئل أمير المؤمنين عن قوله تعالى فَاخْتَلَفَ الْأَحْزَابُ مِنْ بَيْنِهِمْ ۖ فَوَيْلٌ لِلَّذِينَ كَفَرُوا مِنْ مَشْهَدِ يَوْمٍ عَظِيمٍ فقال: إنتظروا الفرج من ثلاث. فقيل: يا أمير المؤمنين وما هن؟ فقال: اختلاف أهل الشام بينهم، والرايات السود من خراسان، والفزعة في شهر رمضان. فقيل: وما الفزعة في شهر رمضان؟ فقال: أوَما سمعتم قول الله في القرآن إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ هي آية تُخرج الفتاةَ من خدرها، وتوقظ النائم، وتفزع اليقظان.","22/2/14/8",""],[9,14,"أخبرنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك الفزارى، قال: حدثني عبد الله بن خالد التميمي، قال: حدثني بعض أصحابنا، عن محمد بن أبي عمير، عن أبي أيوب الخزاز، عن عمر بن حنظلة، عن أبي عبد الله أنه قال: للقائم خمس علامات: ظهور السفياني، واليماني، والصيحة من السماء، وقتل النفس الزكية، والخسف بالبيداء.","22/2/14/9",""],[10,14,"أخبرنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك الفزاري، قال: حدثني موسى بن جعفر بن وهب، قال: حدثني الحسن بن علي الوشاء، عن عباس بن عبد الله، عن داود بن سرحان، عن أبي عبد الله أنه قال: العام الذي فيه الصيحة قبله الآية في رجب. قلت: وما هي؟ قال: وجه يطلع في القمر، ويد بارزة.","22/2/14/10",""],[11,14,"أخبرنا علي بن أحمد البندنيجي قال: حدثنا عبيد الله بن موسى العلوى، عن يعقوب بن يزيد، عن زياد بن مروان، عن عبد الله بن سنان، عن أبي عبد الله أنه قال: النداء من المحتوم، والسفياني من المحتوم، واليماني من المحتوم، وقتل النفس الزكية من المحتوم، وكف يطلع من السماء من المحتوم، (قال) وفزعة في شهر رمضان توقظ النائم، وتفزع اليقظان، وتخرج الفتاة من خدرها.","22/2/14/11",""],[12,14,"أخبرنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، قال: حدثني علي بن عاصم، عن أحمد بن محمد بن أبي نصر، عن أبي الحسن الرضا أنه قال: قبل هذا الأمر السفياني، واليماني، والمرواني، وشعيب بن صالح، فكيف يقول هذا هذا؟","22/2/14/12",""],[13,14,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثني أحمد بن يوسف بن يعقوب أبو الحسن الجعفي من كتابه، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب بن حفص، عن أبي بصير، عن أبي جعفر محمد بن علي أنه قال: إذا رأيتم ناراً من قبل المشرق شبه الهُرديّ العظيم تطلع ثلاثة أيام أو سبعة فتوقعوا فرج آل محمد  إن شاء الله ، إن الله عزيز حكيم. ثم قال: الصيحة لا تكون إلاّ في شهر رمضان لأن شهر رمضان شهر الله، والصيحة فيه هي صيحة جبرئيل إلى هذا الخلق. ثم قال: ينادي منادٍ من السماء باسم القائم فيسمع من بالمشرق ومن بالمغرب، لا يبقى راقد إلاّ إستيقظ، ولا قائم إلاّ قعد، ولا قاعد إلاّ قام على رجليه فزعاً من ذلك الصوت، فرحم الله من اعتبر بذلك الصوت فأجاب، فإن الصوت الأول هو صوت جبرئيل الروح الامين . ثم قال: يكون الصوت في شهر رمضان في ليلة جمعة ليلة ثلاث وعشرين، فلا تشكوا في ذلك، واسمعوا وأطيعوا، وفي آخر النهار صوت الملعون إبليس ينادي إلاّ إن فلاناً قتل مظلوماً، ليشكّك الناس ويفتنهم، فكم في ذلك اليوم من شاكٍّ متحير قد هوى في النار، فإذا سمعتم الصوت في شهر رمضان فلا تشكّوا فيه إنه صوت جبرئيل، وعلامة ذلك أنه ينادي باسم القائم واسم أبيه حتى تسمعه العذراء في خدرها فتحرض أباها وأخاها على الخروج. وقال: لا بد من هذين الصوتين قبل خروج القائم: صوت من السماء وهو صوت جبرئيل باسم صاحب هذا الأمر واسم أبيه، والصوت الثاني من الأرض وهو صوت إبليس اللعين ينادي باسم فلان أنه قتل مظلوماً يريد بذلك الفتنة، فاتبعوا الصوت الأول، وإياكم والأخير أن تفتنوا به. وقال: لا يقوم القائم إلاّ على خوف شديد من الناس، زلازل وفتنة وبلاء يصيب الناس، وطاعون قبل ذلك، وسيف قاطع بين العرب، واختلاف شديد في الناس، وتشتت في دينهم وتغير من حالهم حتى يتمنى المتمني الموت صباحاً ومساءً من عظم ما يرى من كلَب الناس وأكل بعضهم بعضاً، فخروجه إذا خرج عند اليأس والقنوط من أن يروا فرجاً، فيا طوبى لمن أدركه وكان من أنصاره، والويل كل الويل لمن ناواه وخالفه، وخالف أمره، وكان من أعدائه. وقال: إذا خرج يقوم بأمر جديد، وكتاب جديد، وسنة جديدة وقضاء جديد، على العرب شديد، وليس شأنه إلاّ القتل، لا يستبقي أحدا، ولا تأخذه في الله لومة لائم. ثم قال: إذا اختلفت بنو فلان فيما بينهم، فعند ذلك فانتظروا الفرج، وليس فرجكم إلاّ في اختلاف بني فلان، فإذا اختلفوا فتوقعوا الصيحة في شهر رمضان وخروج القائم ، إن الله يفعل ما يشاء، ولن يخرج القائم ولا ترون ما تحبون حتى يختلف بنو فلان فيما بينهم، فإذا كان كذلك طمع الناس فيهم واختلفت الكلمة، وخرج السفياني. وقال: لا بُدّ لبني فلان من أن يملكوا، فإذا ملكوا ثم اختلفوا تفرق ملكهم وتشتت أمرهم حتى يخرج عليهم الخراساني والسفياني هذا من المشرق، وهذا من المغرب يستبقان إلى الكوفة كفرسي رهان، هذا من هنا، وهذا من هنا حتى يكون هلاك بني فلان على أيديهما، أما إنهم لا يبقون منهم أحداً. ثم قال: خروج السفياني واليماني والخراساني في سنة واحدة، في شهر واحد، في يوم واحد، نظام كنظام الخرز يتبع بعضه بعضاً فيكون البأس من كل وجه، ويل لمن ناواهم، وليس في الرايات راية أهدى من راية اليماني، هي راية هدى لأنه يدعو إلى صاحبكم فإذا خرج اليماني حرم بيع السلاح على الناس وكل مسلم، وإذا خرج اليماني فانهض إليه، فإنّ رايته راية هدى، ولا يحل لمسلم أن يلتوي عليه، فمن فعل ذلك فهو من أهل النار، لأنه يدعو إلى الحق وإلى طريق مستقيم. ثم قال لي: إن ذهاب ملك بني فلان كقصع الفخار، وكرجل كانت في يده فخارة وهو يمشي إذ سقطت من يده وهو ساه عنها فانكسرت، فقال حين سقطت: هاه! (شبه الفزع) فذهاب ملكهم هكذا أغفل ما كانوا عن ذهابه. وقال أمير المؤمنين على منبر الكوفة: إن الله قدر فيما قدر وقضى وحتم بأنه كائن لا بد منه أنه يأخذ بني أمية بالسيف جهرة، وأنه يأخذ بنى فلان بغتة. وقال: لا بدّ من رحى تطحن، فإذا قامت على قطبها وثبتت على ساقها بعث الله عليها عبداً عنيفاً خاملاً أصله، يكون النصر معه، أصحابه الطويلة شعورهم، أصحاب السبال، سود ثيابهم، أصحاب رايات سود، ويل لمن ناواهم، يقتلونهم هرجاً، والله لكأني أنظر إليهم وإلى أفعالهم وما يلقى الفجار منهم والأعراب الجفاة يسلطهم الله عليهم بلا رحمة، فيقتلونهم هرجاً على مدينتهم بشاطئ الفرات البرية والبحرية، جزاء بما عملوا، وما ربك بظلام للعبيد.","22/2/14/13",""],[14,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف بن يعقوب، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه، عن شرحبيل قال: قال أبو جعفر (وقد سألته عن القائم ) فقال: إنه لا يكون حتى ينادي مناد من السماء يسمع أهل المشرق والمغرب حتى تسمعه الفتاة في خدرها.","22/2/14/14",""],[15,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن يعقوب بن يزيد، عن زياد القندي، عن غير واحد من أصحابه، عن أبي عبد الله أنه قال: قلنا له: السفياني من المحتوم؟ فقال: نعم، وقتل النفس الزكية من المحتوم، والقائم من المحتوم، وخسف البيداء من المحتوم، وكف تطلع من السماء من المحتوم، والنداء من السماء من المحتوم. فقلت: وأي شيء يكون النداء؟ فقال: منادٍ ينادي باسم القائم واسم أبيه .","22/2/14/15",""],[16,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثني علي بن الحسن، عن علي بن مهزيار، عن حماد بن عيسى، عن الحسين بن المختار، قال: حدثني ابن أبي يعفور، قال: قال لي أبو عبد الله: أمسك بيدك هلاك الفلاني (اسم رجل من بني العباس) وخروج السفياني، وقتل النفس، وجيش الخسف، والصوت. قلت: وما الصوت؟ أهو المنادي؟ فقال: نعم، وبه يعرف صاحب هذا الأمر. ثم قال: الفرج كله هلاك الفلاني من بني العباس.","22/2/14/16",""],[17,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثني علي بن الحسن، عن علي بن مهزيار، عن حماد بن عيسى، عن الحسين بن المختار، عن عبد الرحمن بن سيابة عن عمران بن ميثم، عن عباية بن ربعي الأسدي قال: دخلت على أمير المؤمنين علي وأنا خامس خمسة وأصغر القوم سناً، فسمعته يقول: حدثني أخي رسول الله أنه قال: إني خاتم ألف نبي وإنك خاتم ألف وصي وكلفت ما لم يكلفوا. فقلت: ما أنصفك القوم يا أمير المؤمنين. فقال: ليس حيث تذهب بك المذاهب يا ابن أخي، والله إني لأعلم ألف كلمة لا يعلمها غيري وغير محمد وإنهم ليقرؤون منها آية في كتاب الله ، وهي وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَابَّةً مِنَ الْأَرْضِ تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بِآيَاتِنَا لَا يُوقِنُونَ وما يتدبرونها حق تدبرها. ألا أخبركم بآخر ملك بني فلان؟ قلنا: بلى يا أمير المؤمنين. قال: قتل نفس حرام في يوم حرام في بلد حرام عن قوم من قريش. والذي فلق الحبة وبرأ النسمة ما لهم ملك بعده غير خمس عشرة ليلة. قلنا: هل قبل هذا أو بعده من شيء؟ فقال: صيحة في شهر رمضان تفزع اليقظان، وتوقظ النائم، وتخرج الفتاة من خدرها.","22/2/14/17",""],[18,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا أبو عبد الله يحيى بن زكريا بن شيبان قال: حدثنا أبو سليمان يوسف بن كليب، قال: حدثنا الحسن بن علي بن أبي حمزة، عن سيف بن عميرة، عن أبي بكر الحضرمي، عن أبي جعفر الباقر أنه سمعه يقول: لا بد أن يملك بنو العباس، فإذا ملكوا واختلفوا وتشتت أمرهم خرج عليهم الخراساني والسفياني هذا من المشرق، وهذا من المغرب يستبقان إلى الكوفة كفرسي رهان، هذا من ههنا وهذا من ههنا حتى يكون هلاكهم على أيديهما، أما إنهما لا يبقون منهم أحداً أبداً.","22/2/14/18",""],[19,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، قال: حدثنا عمرو بن عثمان عن الحسن بن محبوب، عن عبد الله بن سنان قال: كنت عند أبي عبد الله فسمعت رجلاً من همدان يقول له: إنّ هؤلاء العامة يعيرونا ويقولون لنا: إنكم تزعمون أن منادياً ينادي من السماء باسم صاحب هذا الأمر. وكان متكئاً فغضب وجلس ثم قال: لا ترووه عني وارووه عن أبي ولا حرج عليكم في ذلك. أشهد أني قد سمعت أبي يقول: والله إن ذلك في كتاب الله لبيّن حيث يقول إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ فلا يبقى في الأرض يومئذ أحد إلاّ خضع وذلت رقبته لها، فيؤمن أهل الأرض إذا سمعوا الصوت من السماء ألا إنّ الحق في علي بن أبي طالب وشيعته. قال: فإذا كان من الغد صعد إبليس في الهواء حتى يتوارى عن أهل الأرض، ثم ينادي ألا إن الحق في عثمان بن عفان وشيعته فإنه قتل مظلوماً فاطلبوا بدمه.قال: فيثبت الله الذين آمنوا بالقول الثابت على الحق وهو النداء الأول، ويرتاب يومئذ الذين في قلوبهم مرض. والمرض واللهِ عداوتنا، فعند ذلك يتبرؤون منا ويتناولونا فيقولون: إن المنادي الأول سحر من سحر أهل هذا البيت. وَإِنْ يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُسْتَمِرٌّ","22/2/14/19",""],[20,14,"قال: وحدثنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام الناشري، عن عبد الله بن جبلة، عن عبد الصمد بن بشير، عن أبي عبد الله جعفر بن محمد وقد سأله عمارة الهمداني فقال له: أصلحك الله إن ناساً يعيرونا ويقولون إنكم تزعمون أنه سيكون صوت من السماء. فقال له: لا تروِ عني واروِه عن أبي. كان أبي يقول: هو في كتاب الله إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ {4} فيؤمن أهل الأرض جميعاً للصوت الأول، فإذا كان من الغد صعد إبليس اللعين حتى يتوارى من الأرض في جو السماء، ثم ينادي \"ألا إن عثمان قتل مظلوما فاطلبوا بدمه\" فيرجع من أراد الله به سوءاً، ويقولون: هذا سحر الشيعة، وحتى يتناولونا ويقولون: هو من سحرهم، وهو قول الله وَإِنْ يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُسْتَمِرٌّ {2}","22/2/14/20",""],[21,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد قال: حدثنا عبيس بن هشام، قال: حدثنا عبد الله بن جبلة، عن أبيه، عن محمد بن الصامت، عن أبي عبد الله قال: قلت له: ما من علامة بين يدي هذا الأمر؟ فقال: بلى. قلت: وما هي؟ قال: هلاك العباسي، وخروج السفياني، وقتل النفس الزكية، والخسف بالبيداء، والصوت من السماء. فقلت: جعلت فداك، أخاف أن يطول هذا الأمر؟ فقال: لا إنما هو كنظام الخرز يتبع بعضه بعضاً.","22/2/14/21",""],[22,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثني أحمد بن يوسف بن يعقوب أبو الحسن الجعفي، قال: حدثني إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب، عن أبي بصير، عن أبي جعفر قال: يقوم القائم في وتر من السنين: تسع، واحدة، ثلاث، خمس. وقال: إذا اختلفت بنو أمية وذهب ملكهم، ثم يملك بنو العباس، فلا يزالون في عنفوان من الملك وغضارة من العيش حتى يختلفوا فيما بينهم، فإذا اختلفوا ذهب ملكهم، واختلف أهل المشرق وأهل المغرب، نعم وأهل القبلة ويلقى الناس جهد شديد مما يمر بهم من الخوف، فلا يزالون بتلك الحال حتى ينادي مناد من السماء، فإذا نادى فالنفير النفير، فوالله لكأني أنظر إليه بين الركن والمقام يبايع الناس بأمر جديد، وكتاب جديد، وسلطان جديد من السماء، أما إنه لا يرد له راية أبداً حتى يموت.","22/2/14/22",""],[23,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن أبيه، عن أحمد بن عمر الحلبي، عن الحسين بن موسى، عن فضيل بن محمد مولى محمد بن راشد البجلي، عن أبي عبد الله أنه قال: أما إن النداء من السماء باسم القائم في كتاب الله لبيّن. فقلت: فأين هو أصلحك الله؟ فقال: في إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ {4} قال: إذا سمعوا الصوت أصبحوا وكأنما على رؤوسهم الطير.","22/2/14/23",""],[24,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه، عن أبي بصير، عن أبي عبد الله أنه قال: إذا صعد العباسي أعواد منبر مروان أدرج ملك بني العباس. وقال: قال لي أبي (يعني الباقر ) لا بدّ لنار من آذربيجان لا يقوم لها شيء، فإذا كان ذلك فكونوا أحلاس بيوتكم، وألبدوا ما ألبدنا، فإذا تحرك متحركنا فاسعوا إليه ولو حبواً، والله لكأني أنظر إليه بين الركن والمقام يبايع الناس على كتاب جديد على العرب شديد. قال: وويل للعرب من شر قد اقترب.","22/2/14/24",""],[25,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثني علي بن الحسن التيملي، قال: حدثنا محمد وأحمد بنا الحسن، عن علي بن يعقوب الهاشمي، عن هارون بن مسلم، عن عبيد بن زرارة، عن أبي عبد الله أنه قال: ينادى باسم القائم، فيؤتى وهو خلف المقام فيقال له: قد نودي باسمك فما تنتظر؟ ثم يؤخذ بيده فيبايع. (قال) قال لي زرارة: الحمد لله قد كنا نسمع أن القائم يبايع مستكرهاً فلم نكن نعلم وجه استكراهه، فعلمنا أنه استكراه لا إثم فيه.","22/2/14/25",""],[26,14,"أخبرنا أحمد بن محمد بن سعيد بإسناده عن هارون بن مسلم، عن أبي خالد القماط، عن حمران بن أعين، عن أبي عبد الله أنه قال: من المحتوم الذي لا بد أن يكون من قبل قيام القائم خروج السفياني، وخسف بالبيداء، وقتل النفس الزكية، والمنادي من السماء.","22/2/14/26",""],[27,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثني أحمد بن يوسف بن يعقوب، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي، عن أبيه ووهيب ابن حفص، عن ناجية القطان أنه سمع أبا جعفر يقول: إن المنادي ينادي: إن المهدي من آل محمد؛ فلان بن فلان (باسمه واسم أبيه)، فينادي الشيطان: إن فلاناً وشيعته على الحق. (يعني رجلاً من بني أمية)","22/2/14/27",""],[28,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن العباس ابن عامر بن رباح الثقفي، عن عبد الله بن بكير، عن زرارة بن أعين، قال: سمعت أبا عبد الله يقول: ينادي منادٍ من السماء: إن فلاناً هو الأمير. وينادي منادٍ: إن علياً وشيعته هم الفائزون. قلت: فمن يقاتل المهدي بعد هذا؟ فقال: إن الشيطان ينادي: إن فلاناً وشيعته هم الفائزون. (لرجل من بني أمية) قلت: فمن يعرف الصادق من الكاذب؟ قال: يعرفه الذين كانوا يروون حديثنا ويقولون إنه يكون قبل أن يكون، ويعلمون أنهم هم المحقون الصادقون.","22/2/14/28",""],[29,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، عن الحسن بن علي بن يوسف، عن المثني، عن زرارة بن أعين قال: قال: قلت لأبي عبد الله: عجبت، أصلحك الله، وإني لأعجب من القائم؛ كيف يقاتَل مع ما يرون من العجائب من خسف البيداء بالجيش، ومن النداء الذي يكون من السماء؟ فقال: إن الشيطان لا يدعهم حتى ينادي كما نادى برسول الله يوم العقبة.","22/2/14/29",""],[30,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، قال: حدثنا محمد بن عبد الله، عن محمد بن أبي عمير، عن هشام بن سالم قال: قلت لأبي عبد الله إن الجريري أخا إسحاق يقول لنا: إنكم تقولون: هما نداءان فأيهما الصادق من الكاذب؟ فقال أبو عبد الله: قولوا له: إن الذي أخبرنا بذلك، وأنت تنكر أن هذا يكون، هو الصادق.","22/2/14/30",""],[31,14,"أخبرنا أحمد بن محمد بن سعيد بهذا الإسناد عن هشام بن سالم، قال: سمعت أبا عبد الله يقول: هما صيحتان صيحة في أول الليل، وصيحة في آخر اللية الثانية. قال: فقلت: كيف ذلك؟ فقال: واحدة من السماء، وواحدة من إبليس. فقلت: وكيف تعرف هذه من هذه؟ فقال: يعرفها من كان سمع بها قبل أن تكون.","22/2/14/31",""],[32,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، عن أبيه، عن محمد بن خالد، عن ثعلبة بن ميمون، عن عبد الرحمن بن مسلمة الجريري قال: قلت لأبي عبد الله: إن الناس يوبخونا ويقولون: من أين يعرف المحق من المبطل إذا كانتا؟ فقال: ما تردون عليهم؟ قلت: فما نرد عليهم شيئاً. فقال: قولوا لهم يصدّق بها إذا كانت من كان مؤمناً يؤمن بها قبل أن تكون. (قال) إن الله يقول قُلْ هَلْ مِنْ شُرَكَائِكُمْ مَنْ يَهْدِي إِلَى الْحَقِّ ۚ قُلِ اللَّهُ يَهْدِي لِلْحَقِّ ۗ أَفَمَنْ يَهْدِي إِلَى الْحَقِّ أَحَقُّ أَنْ يُتَّبَعَ أَمَّنْ لَا يَهِدِّي إِلَّا أَنْ يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ","22/2/14/32",""],[33,14,"حدثنا أحمد قال: حدثنا علي بن الحسن التيملي من كتابه في رجب سنة سبع وسبعين ومائتين، قال: حدثنا محمد بن عمر بن يزيد بياع السابري ومحمد بن الوليد بن خالد الخزاز جميعاً، عن حماد بن عثمان عن عبد الله بن سنان قال: سمعت أبا عبد الله يقول: إنه ينادي باسم صاحب هذا الأمر مناد من السماء: ألا إن الأمر لفلان بن فلان، ففيمَ القتال؟","22/2/14/33",""],[34,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا أبو سليمان أحمد بن هوذة الباهلي، قال: حدثنا إبراهيم بن إسحاق النهاوندي بنهاوند سنة ثلاث وسبعين ومائتين، قال: حدثنا عبد الله بن حماد الأنصاري في شهر رمضان سنة تسع وعشرين ومائتين، عن عبد الله بن سنان، قال: سمعت أبا عبد الله يقول: لا يكون هذا الأمر الذي تمدون إليه أعناقكم حتى ينادي مناد من السماء: ألا إن فلاناً صاحب الأمر، فعلى مَ القتال؟","22/2/14/34",""],[35,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل بن إبراهيم وسعدان بن إسحاق بن سعيد وأحمد بن الحسين بن عبد الملك ومحمد بن أحمد بن الحسن القطواني قالوا جميعاً: حدثنا الحسن بن محبوب الزراد، قال: حدثنا عبد الله بن سنان، قال: سمعت أبا عبد الله يقول: يشمل الناس موت وقتل حتى يلجأ الناس عند ذلك إلى الحرم فينادي مناد صادق من شدة القتال: فيم القتل والقتال؟ صاحبكم فلان.","22/2/14/35",""],[36,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام، عن عبد الله بن جبلة، عن محمد بن سليمان، عن العلاء، عن محمد بن مسلم، عن أبي جعفر محمد بن علي أنه قال: السفياني والقائم في سنة واحدة.","22/2/14/36",""],[37,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف بن يعقوب الجعفي أبو الحسن، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب بن حفص، عن أبي بصير، عن أبي عبد الله قال: بينا الناس وقوف بعرفات إذا أتاهم راكب على ناقة ذعلبة يخبرهم بموت خليفة يكون عند موته فرج آل محمد وفرج الناس جميعاً. وقال: إذا رأيتم علامة في السماء ناراً عظيمة من قبل المشرق تطلع ليالي، فعندها فرج الناس وهي قدام القائم بقليل.","22/2/14/37",""],[38,14,"حدثنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، قال: حدثنا محمد بن موسى، عن أحمد بن أبي أحمد الوراق الجرجاني، عن محمد بن علي، عن علي بن الحكم، عن عمرو بن شمر، عن جابر، عن أبي الطفيل، قال: سأل ابن الكواء أمير المؤمنين علي بن أبي طالب عن الغضب، فقال: هيهات الغضب هيهات! موتات بينهن موتات! وراكب الذعلبة، وما راكب الذعلبة؟ مختلط جوفها بوضينها، يخبرهم بخبر فيقتلونه، ثم الغضب عند ذلك.","22/2/14/38",""],[39,14,"حدثنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي، قال: حدثنا عبد الله بن حماد الأنصاري، عن أبي مالك الحضرمي، عن محمد بن أبي الحكم، عن عبد الله بن عثمان، عن أسلم المكي، عن أبي الطفيل، عن حذيفة بن اليمان، قال: يقتل خليفة ما له في السماء عاذر، ولا في الأرض ناصر، ويخلع خليفة حتى يمشي على وجه الأرض ليس له من الأرض شيء، ويستخلف ابن السبية. قال: فقال أبو الطفيل: يا ابن أختي، ليتني أنا وأنت من كورة. قال: قلت: ولم تتمنى يا خال ذلك؟ قال: لأن حذيفة حدثني أن الملك يرجع في أهل النبوة.","22/2/14/39",""],[40,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف بن يعقوب من كتابه، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب، عن أبي بصير قال: سئل أبو جعفر الباقر عن تفسير قول الله سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنْفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ {53} فقال: يريهم في أنفسهم المسخ، ويريهم في الآفاق انتقاص الآفاق عليهم، فيرون قدرة الله في أنفسهم وفي الآفاق. وقوله: سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنْفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ {53} يعني بذلك خروج القائم. هو الحق من الله يراه هذا الخلق، لا بد منه.","22/2/14/40",""],[41,14,"حدثنا أحمد بن محمد بن سعيد، قال: حدثنا علي بن الحسن التيملي، عن علي بن مهزيار، عن حماد بن عيسى، عن الحسين بن المختار، عن أبي بصير، قال: قلت لأبي عبد الله قول الله فَلَوْلَا كَانَتْ قَرْيَةٌ آمَنَتْ فَنَفَعَهَا إِيمَانُهَا إِلَّا قَوْمَ يُونُسَ لَمَّا آمَنُوا كَشَفْنَا عَنْهُمْ عَذَابَ الْخِزْيِ فِي الْحَيَاةِ الدُّنْيَا وَمَتَّعْنَاهُمْ إِلَىٰ حِينٍ {98} ما هو عذاب خزي الدنيا؟ فقال: وأيّ خزي أخزى، يا أبا بصير، من أن يكون الرجل في بيته وحجاله وعلى إخوانه وسط عياله إذ شق أهله الجيوب عليه وصرخوا، فيقول الناس: ما هذا؟ فيقال مُسخ فلان الساعة! فقلت: قبل قيام القائم أو بعده؟ قال: لا، بل قبله.","22/2/14/41",""],[42,14,"أخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن محمد بن موسى، عن أحمد بن أبي أحمد الوراق، عن يعقوب بن السراج، قال: قلت لأبي عبد الله: متى فرج شيعتكم؟ قال: إذا اختلف ولد العباس ووهى سلطانهم، وطمع فيهم من لم يكن يطمع وخلعت العرب أعنتها، ورفع كل ذى صيصية صيصيته، وظهر السفياني، وأقبل اليماني، وتحرك الحسني، خرج صاحب هذا الأمر من المدينة (إي مكة) بتراث رسول الله . قلت: وما تراث رسول الله ؟ فقال: سيفه، ودرعه، وعمامته، وبرده، ورايته، وقضيبه، وفرسه، ولامته وسرجه.","22/2/14/42",""],[43,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل وسعدان بن إسحاق بن سعيد وأحمد بن الحسين بن عبد الملك، ومحمد بن أحمد بن الحسن القطواني قالوا جميعاً: حدثنا الحسن بن محبوب، عن يعقوب السراج، قال: قلت لأبي عبد الله: متى فرج شيعتكم؟ فقال: إذا اختلف ولد العباس، ووهى سلطانهم… (فذكر الحديث بعينه حتى انتهى إلى ذكر اللامة والسرج وزاد فيه) حتى ينـزل بأعلى مكة فيخرج السيف من غمده، ويلبس الدرع، وينشر الراية والبردة، ويعتم بالعمامة، ويتناول القضيب بيده، ويستأذن الله في ظهوره، فيطلع على ذلك بعض مواليه، فيأتي الحسني فيخبره الخبر، فيبتدره الحسني إلى الخروج فيثب عليه أهل مكة فيقتلونه ويبعثون برأسه إلى الشامي فيظهر عند ذلك صاحب هذا الأمر فيبايعه الناس ويتبعونه، ويبعث عند ذلك الشامي جيشاً إلى المدينة فيهلكهم الله دونها، ويهرب من المدينة يومئذ من كان بالمدينة من ولد علي إلى مكة فيلحقون بصاحب الأمر، ويقبل صاحب الأمر نحو العراق، ويبعث جيشا إلى المدينة، فيأمر أهلها فيرجعون إليها.","22/2/14/43",""],[44,14,"حدثنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا معاوية بن حكيم، قال: حدثنا أحمد بن محمد بن أبي نصر، قال: سمعت الرضا يقول: قبل هذا الأمر بيوح. فلم أدرِ ما البيوح، فحججت فسمعت أعرابياُ يقول: هذا يوم بيوح، فقلت له: ما البيوح، فقال: الشديد الحر.","22/2/14/44",""],[45,14,"أخبرني أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، عن أحمد ومحمد بني الحسن، عن أبيهما، عن ثعلبة بن ميمون، عن بدر بن الخليل الأسدي قال: كنت عند أبي جعفر محمد بن علي الباقر فذكر آيتين تكونان قبل قيام القائم لم تكونا منذ أهبط الله آدم صلوات الله عليه أبداً، وذلك أن الشمس تنكسف في النصف من شهر رمضان والقمر في آخره. فقال له رجل: يا بن رسول الله، لا بل الشمس في آخر الشهر والقمر في النصف. فقال له أبو جعفر: إني لأعلم بالذي أقول. إنهما آيتان لم تكونا منذ هبط آدم.","22/2/14/45",""],[46,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم، قال: حدثنا عبيس بن هشام الناشري، عن عبد الله بن جبلة، عن الحكم بن أيمن، عن ورد (أخي الكميت)، عن أبي جعفر محمد بن علي أنه قال: إن بين يدي هذا الأمر انكساف القمر لخمس تبقى، والشمس لخمس عشرة وذلك في شهر رمضان، وعنده يسقط حساب المنجمين.","22/2/14/46",""],[47,14,"وعن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله أنه قال: علامة خروج المهدي كسوف الشمس في شهر رمضان في ثلاث عشرة وأربع عشرة منه.","22/2/14/47",""],[48,14,"حدثنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا محمد بن الحسين بن أبي الخطاب، عن الحسن بن علي، عن صالح بن سهل، عن أبي عبد الله جعفر بن محمد في قوله تعالى إِنَّا أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ أَنْ أَنْذِرْ قَوْمَكَ مِنْ قَبْلِ أَنْ يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ {1} قال: تأويلها فيما يأتي في عذاب يقع في الثوية (يعني نار) حتى ينتهى إلى الكناسة، كناسة بني أسد حتى تمر بثقيف، لا تدع وتراً لآل محمد إلاّ أحرقته، وذلك قبل خروج القائم .","22/2/14/48",""],[49,14,"حدثنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي، عن عبد الله بن حماد الأنصاري، عن عمرو بن شمر، عن جابر قال: قال أبو جعفر: كيف تقرؤون هذه السورة؟ قلت: وأية سورة؟ قال: سورة إِنَّا أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ أَنْ أَنْذِرْ قَوْمَكَ مِنْ قَبْلِ أَنْ يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ {1} فقال: ليس هو \"سأل سائل بعذاب واقع،\" إنما هو سال سيلٌ، وهي نار تقع في الثوية، ثم تمضي إلى كناسة بني أسد، ثم تمضي إلى ثقيف، فلا تدع وتراً لآل محمد إلاّ أحرقته.","22/2/14/49",""],[50,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثني علي بن الحسن، عن أخيه محمد بن الحسن، عن أبيه، عن أحمد بن عمر الحلبي، عن الحسين بن موسى، عن معمر بن يحيى بن سام، عن أبي خالد الكابلي، عن أبي جعفر أنه قال: كأني بقوم قد خرجوا بالمشرق يطلبون الحق فلا يعطونه، ثم يطلبونه فلا يعطونه، فإذا رأوا ذلك وضعوا سيوفهم على عواتقهم فيعطون ما سألوه فلا يقبلونه حتى يقوموا، ولا يدفعونها إلاّ إلى صاحبكم، قتلاهم شهداء، أما إني لو أدركت ذلك لاستبقيت نفسي لصاحب هذا الأمر.","22/2/14/50",""],[51,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن يعقوب بن يزيد، عن زياد القندي، عن ابن اذينة، عن معروف بن خربوذ، قال: ما دخلنا على أبي جعفر الباقر قط إلاّ قال: خراسان خراسان، سجستان سجستان، كأنه يبشرنا بذلك.","22/2/14/51",""],[52,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، قال: حدثنا الحسن ومحمد بنا علي بن يوسف، عن أبيهما، عن أحمد بن عمر الحلبي، عن صالح بن أبي الأسود عن أبي الجارود قال: سمعت أبا جعفر يقول: إذا ظهرت بيعة الصبي قام كل ذي صيصية بصيصيته.","22/2/14/52",""],[53,14,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، قال: حدثنا محمد بن عبد الله، عن محمد بن أبي عمير، عن هشام بن سالم، عن أبي عبد الله أنه قال: ما يكون هذا الأمر حتى لا يبقى صنف من الناس إلاّ وقد ولوا على الناس حتى لا يقول قائل \"إنا لو ولينا لعدلنا\" ثم يقوم القائم بالحق والعدل.","22/2/14/53",""],[54,14,"أخبرنا أحمد بن محمد بن سعيد بهذا الإسناد، عن هشام بن سالم، عن زرارة قال: قلت لأبي عبد الله النداء حق؟ قال: إي والله حتى يسمعه كل قوم بلسانهم. وقال: لا يكون هذا الأمر حتى يذهب تسعة أعشار الناس.","22/2/14/54",""],[55,14,"أخبرنا علي بن أحمد قال: حدثنا عبيد الله بن موسى العلوي، قال: حدثنا عبد الله بن حماد الأنصاري، قال: حدثنا إبراهيم بن عبيد الله بن العلاء، قال: حدثني أبي، عن أبي عبد الله جعفر بن محمد: أن أمير المؤمنين حدث عن أشياء تكون بعده إلى قيام القائم. فقال الحسين: يا أمير المؤمنين، متى يطهر الله الأرض من الظالمين؟ فقال أمير المؤمنين: لا يطهر الله الأرض من الظالمين حتى يسفك الدم الحرام. (ثم ذكر أمر بني أمية وبني العباس في حديث طويل) ثم قال: إذا قام القائم بخراسان وغلب على أرض كوفان وملتان، وجاز جزيرة بني كاوان، وقام منا قائم بجيلان وأجابته الآبر والديلمان، وظهرت لولدي رايات الترك متفرقات في الأقطار والجنبات، وكانوا بين هنات وهنات إذا خربت البصرة، وقام أمير الأمرة بمصر (فحكى حكاية طويلة) ثم قال: إذا جهزت الألوف، وصفت الصفوف، وقتل الكبش الخروف، هناك يقوم الآخر ويثور الثائر، ويهلك الكافر، ثم يقوم القائم المأمول، والإمام المجهول، له الشرف والفضل وهو من ولدك يا حسين، لا ابن مثله يظهر بين الركنين، في دريسين باليين يظهر على الثقلين، ولا يترك في الأرض دمين، طوبى لمن أدرك زمانه، لحق أوانه، وشهد أيامه.","22/2/14/55",""],[56,14,"محمد بن همام قال: حدثنا جعفر بن محمد بن مالك الفزاري الكوفي، قال: حدثني محمد بن أحمد، عن محمد بن سنان، عن يونس بن ظبيان، عن أبي عبد الله قال: إذا كان ليلة الجمعة أهبط الرب تعالى ملكاً إلى السماء الدنيا، فإذا طلع الفجر جلس ذلك الملك على العرش فوق البيت المعمور، ونصب لمحمد وعلي والحسن والحسين  منابر من نور، فيصعدون عليها وتجمع لهم الملائكة والنبيون والمؤمنون، وتفتح أبواب السماء، فإذا زالت الشمس قال رسول الله: يا رب ميعادك الذي وعدت به في كتابك. هو هذه الآية وَعَدَ اللَّهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصَّالِحَاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا ۚ يَعْبُدُونَنِي لَا يُشْرِكُونَ بِي شَيْئًا ۚ وَمَنْ كَفَرَ بَعْدَ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ {55} ثم يقول الملائكة والنبيون مثل ذلك، ثم يخر محمد وعلي والحسن والحسين سجداً، ثم يقولون: يا رب أغضب فإنه قد هتك حريمك وقتل أصفياؤك وأذل عبادك الصالحون، فيفعل الله ما يشاء، وذلك يوم معلوم.","22/2/14/56",""],[57,14,"حدثنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي، قال: حدثني محمد بن الحسين بن أبي الخطاب، قال: حدثنا محمد بن سنان، عن الحسين بن المختار، عن خالد القلانسي، عن أبي عبد الله أنه قال: إذا هدم حائط مسجد الكوفة من مؤخره مما يلي دار ابن مسعود، فعند ذلك زوال ملك بني فلان، أما إن هادمه لا يبنيه.","22/2/14/57",""],[58,14,"حدثنا عبد الواحد بن عبد الله قال: حدثنا أحمد بن محمد بن رباح الزهري، قال: حدثنا أحمد بن علي الحميري، عن الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن رجل، عن أبي عبد الله أنه قال: لا يقوم القائم حتى يقوم أثنا عشر رجلاً كلهم يجمع على قول أنهم قد رأوه فيكذبهم.","22/2/14/58",""],[59,14,"أخبرنا محمد بن همام قال: حدثنا حميد بن زياد، قال: حدثنا الحسن بن محمد بن سماعة، قال: حدثنا أحمد بن الحسن الميثمي، عن أبي الحسن علي بن محمد، عن معاذ بن مطر، عن رجل (قال: ولا أعلمه إلاّ مسمعا أبا سيار) قال: قال أبو عبد الله: قبل قيام القائم تحرك حرب قيس.","22/2/14/59",""],[60,14,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي، قال: حدثنا محمد بن سنان، عن عبيد بن زرارة، قال: ذُكر عند أبي عبد الله السفياني فقال: أنى يخرج ذلك؟ ولما يخرج كاسر عينيه بصنعاء.","22/2/14/60",""],[61,14,"أخبرنا علي بن الحسين قال: أخبرنا محمد بن يحيى، عن محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن إبراهيم بن أبي البلاد، عن علي بن محمد بن الاعلم الازدي، عن أبيه، عن جده قال: قال أمير المؤمنين: بين يدي القائم موت أحمر، وموت أبيض، وجراد في حينه، وجراد في غير حينه أحمر كالدم، فأما الموت الأحمر فبالسيف، وأما الموت الأبيض فالطاعون.","22/2/14/61",""],[62,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي من كتابه في رجب سنة سبع وسبعين ومائتين قال: حدثنا محمد بن عمربن يزيد بياع السابري ومحمد بن الوليد بن خالد الخزاز جميعاً قالا: حدثنا حماد بن عثمان، عن عبد الله بن سنان قال: حدثني محمد بن إبراهيم بن أبي البلاد وقال: حدثنا أبي، عن أبيه، عن الاصبغ بن نباتة قال: سمعت علياً يقول: إن بين يدي القائم سنين خداعة، يكذب فيها الصادق، ويصدق فيها الكاذب، ويقرب فيها الماحل (وفي حديث: وينطق فيها الرويبضة.) فقلت: وما الرويبضة وما الماحل؟ قال: أوما تقرؤون القرآن، قوله قال: يريد المكر. فقلت: وما الماحل؟ قال: يريد المكّار.","22/2/14/62",""],[63,14,"حدثنا عبد الواحد بن عبد الله قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا محمد بن الحسين بن أبي الخطاب، قال: حدثني محمد بن سنان، عن حذيفة بن المنصور، عن أبي عبد الله أنه قال: إن لله مائدة (وفي غير هذه الرواية: مأدبة) بقرقيسياء يطلع مطلع من السماء فينادي يا طير السماء ويا سباع الأرض هلموا إلى الشبع من لحوم الجبارين.","22/2/14/63",""],[64,14,"حدثنا أبو سليمان أحمد بن هوذة الباهلي، قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبد الله بن حماد الأنصاري، عن أبي بصير، قال: حدثنا أبو عبد الله وقال: ينادى باسم القائم يا فلان بن فلان قم.","22/2/14/64",""],[65,14,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل وسعدان بن إسحاق بن سعيد وأحمد بن الحسين بن عبد الملك ومحمد بن أحمد بن الحسن جميعاً، عن الحسن بن محبوب، عن يعقوب السراج، عن جابر، عن أبي جعفر أنه قال: يا جابر، لا يظهر القائم حتى يشمل الناس بالشام فتنة يطلبون المخرج منها فلا يجدونه، ويكون قتل بين الكوفة والحيرة، قتلاهم على سواء، وينادى مناد من السماء.","22/2/14/65",""],[66,14,"أخبرنا أحمد بن محمد بن سعيد، عن هؤلاء الرجال الأربعة، عن الحسن بن محبوب، عن العلاء بن رزين، عن محمد بن مسلم، عن أبي جعفر أنه قال: توقعوا الصوت يأتيكم بغتة من قبل دمشق، فيه لكم فرج عظيم.","22/2/14/66",""],[67,14,"أخبرنا أحمد بن محمد بن سعيد، عن هؤلاء الرجال الأربعة عن بن محبوب. وأخبرنا محمد بن يعقوب الكليني أبو جعفر قال: حدثني علي بن إبراهيم بن هاشم، عن أبيه قال: وحدثني محمد بن عمران قال: حدثنا أحمد بن محمد بن عيسى، قال: وحدثني علي بن محمد وغيره، عن سهل بن زياد جميعاً، عن الحسن بن محبوب قال وحدثنا عبد الواحد بن عبد الله الموصلي، عن أبي علي أحمد بن محمد بن أبي ناشر عن أحمد بن هلال، عن الحسن بن محبوب، عن عمرو بن أبي المقدام، عن جابر بن يزيد الجعفي قال: قال أبو جعفر محمد بن علي الباقر: يا جابر، إلزم الأرض ولا تحرك يداً ولا رجلاً حتى ترى علامات أذكرها لك إن أدركتها: أولها اختلاف بني العباس، وما أراك تدرك ذلك، ولكن حدّث به من بعدي عني، ومناد ينادي من السماء، ويجيئكم الصوت من ناحية دمشق بالفتح، وتخسف قرية من قرى الشام تسمى الجابية، وتسقط طائفة من مسجد دمشق الأيمن، ومارقة تمرق من ناحية الترك، ويعقبها هرج الروم. وسيقبل إخوان الترك حتى ينـزلوا الجزيرة، وسيقبل مارقة الروم حتى ينـزلوا الرملة. فتلك السنة يا جابر فيها اختلاف كثير في كل أرض من ناحية المغرب، فأول أرض تخرب أرض الشام، ثم يختلفون عند ذلك على ثلاث رايات: راية الأصهب، وراية الأبقع، وراية السفياني، فيلتقي السفياني بالأبقع فيقتتلون، فيقتله السفياني ومن تبعه، ثم يقتل الأصهب. ثم لا يكون له همة إلاّ الإقبال نحو العراق، ويمر جيشه بقرقيسياء، فيقتتلون بها، فيقتل بها من الجبارين مائة ألف، ويبعث السفياني جيشاً إلى الكوفة، وعدتهم سبعون ألفاً، فيصيبون من أهل الكوفة قتلاً وصلباً وسبياً، فبيناهم كذلك إذ أقبلت رايات من قبل خراسان وتطوي المنازل طياً حثيثاً، ومعهم نفر من أصحاب القائم. ثم يخرج رجل من موالي أهل الكوفة في ضعفاء فيقتله أمير جيش السفياني بين الحيرة والكوفة، ويبعث السفياني بعثاً إلى المدينة فينفر المهدي منها إلى مكة، فيبلغ أمير جيش السفياني أن المهدي قد خرج إلى مكة، فيبعث جيشاً على أثره فلا يدركه حتى يدخل مكة خائفاً يترقب على سنة موسى بن عمران . قال: فينـزل أمير جيش السفياني البيداء، فينادي مناد من السماء \"يا بيداء أبيدي القوم\" فيخسف بهم فلا يفلت منهم إلاّ ثلاثة نفر يحول الله وجوههم إلى أقفيتهم وهم من كلب، وفيهم نزلت هذه الآية يَا أَيُّهَا الَّذِينَ أُوتُوا الْكِتَابَ آمِنُوا بِمَا نَزَّلْنَا مُصَدِّقًا لِمَا مَعَكُمْ مِنْ قَبْلِ أَنْ نَطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَىٰ أَدْبَارِهَا أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّا أَصْحَابَ السَّبْتِ ۚ وَكَانَ أَمْرُ اللَّهِ مَفْعُولًا {47} قال: والقائم يومئذ بمكة، قد أسند ظهره إلى البيت الحرام مستجيرا به، فينادي: يا أيها الناس إنا نستنصر الله، فمن أجابنا من الناس؟ فإنا أهل بيت نبيكم محمد، ونحن أولى الناس بالله وبمحمد ، فمن حاجني في آدم فأنا أولى الناس بآدم، ومن حاجني في نوح فأنا أولى الناس بنوح، ومن حاجني في إبراهيم فأنا أولى الناس بإبراهيم، ومن حاجني في محمد فأنا أولى الناس بمحمد ، ومن حاجني في النبيين فأنا أولى الناس بالنبيين. أليس الله يقول في محكم كتابه إِنَّ اللَّهَ اصْطَفَىٰ آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ عَلَى الْعَالَمِينَ {33} ذُرِّيَّةً بَعْضُهَا مِنْ بَعْضٍ ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ {34} فأنا بقية من آدم وذخيرة من نوح، ومصطفى من إبراهيم، وصفوة من محمد صلى الله عليهم أجمعين. ألا فمن حاجني في كتاب الله فأنا أولى الناس بكتاب الله، ألا ومن حاجني في سنة رسول الله فأنا أولى الناس بسنة رسول الله . فأنشد الله من سمع كلامي اليوم لما أبلغ الشاهد منكم الغائب، وأسألكم بحق الله، وحق رسوله وبحقي، فإن لي عليكم حق القربى من رسول الله إلاّ أعنتمونا ومنعتمونا ممن يظلمنا، فقد أُخفنا وظُلمنا، وطردنا من ديارنا أبنائنا، وبُغي علينا، ودفعنا عن حقنا، وافترى أهل الباطل علينا، فالله الله فينا، لا تخذلونا، وانصرونا ينصركم الله تعالى. قال: فيجمع الله عليه أصحابه ثلاثمائة وثلاثة عشر رجلاً، ويجمعهم الله له على غير ميعاد قزعاً كقزع الخريف، وهي يا جابر الآية التي ذكرها الله في كتابه وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَاسْتَبِقُوا الْخَيْرَاتِ ۚ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ {148} فيبايعونه بين الركن والمقام، ومعه عهد من رسول الله قد توارثته الأبناء عن الآباء. والقائم، يا جابر، رجل من ولد الحسين يصلح الله له أمره في ليلة، فما أشكل على الناس من ذلك، يا جابر، فلا يشكلن عليهم ولادته من رسول الله ووراثته العلماء عالماً بعد عالم، فإن أشكل هذا كله عليهم، فإن الصوت من السماء لا يشكل عليهم إذا نودي باسمه واسم أبيه وأمه.","22/2/14/67",""],[68,14,"حدثنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، عن أبي بصير، عن أبي عبد الله أنه قال: يقوم القائم يوم عاشوراء.","22/2/14/68",""],[1,15,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن التيملي من كتابه في صفر سنة أربع وسبعين ومائتين، قال: حدثنا العباس بن عامر بن رباح الثقفي، عن موسى بن بكر، عن بشير النبال وأخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن أيوب بن نوح، عن صفوان بن يحيى، عن بشير بن أبي أراكة النبال (ولفظ الحديث على رواية ابن عقده) قال: لما قدمتُ المدينة انتهيت إلى منـزل أبي جعفر الباقر فإذا أنا ببغلته مسرجة بالباب، فجلست حيال الدار، فخرج فسلمتُ عليه فنَزل عن البغلة وأقبل نحوي فقال: ممن الرجل؟ فقلت: من أهل العراق. قال: من أيها؟ قلت: من أهل الكوفة. فقال: مَن صحبك في هذا الطريق؟ قلت: قوم من المحدثة. فقال: وما المحدثة؟ قلت: المرجئة. فقال: ويح هذه المرجئة، إلى من يلجؤون غداً إذا قام قائمنا؟ قلت: إنهم يقولون: لو قد كان ذلك كنا وأنتم في العدل سواء. فقال: من تاب تاب الله عليه، ومن أسرّ نفاقاً فلا يبعد الله غيره، ومن أظهر شيئاً أهرق الله دمه، ثم قال: يذبحهم، والذي نفسي بيده، كما يذبح القصاب شاته - وأو مأ بيده إلى حلقه -. قلت: إنهم يقولون: إنه إذا كان ذلك استقامت له الأمور فلا يهريق محجمة دم. فقال: كلا والذي نفسي بيده حتى نمسح وأنتم العرق والعلق - وأو مأ بيده إلى جبهته -.","22/2/15/1",""],[2,15,"أخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوى العباسي، عن الحسن بن معاوية، عن الحسن بن محبوب، عن عيسى بن سليمان، عن المفضل بن عمر، قال: سمعت أبا عبد الله وقد ذكر القائم ، فقلت: إني لأرجو أن يكون أمره في سهولة. فقال: لا يكون ذلك حتى تمسحوا العلق والعرق.","22/2/15/2",""],[3,15,"أخبرنا عبد الواحد بن عبد الله يونس قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن يونس بن رباط، قال: سمعت أبا عبد الله يقول: إن أهل الحق لم يزالوا منذ كانوا في شدة، أما إن ذاك إلى مدة قريبة وعافية طويلة. وأخبرنا أبو العباس أحمد بن محمد بن سعيد بن عقدة، عن بعض رجاله، قال: حدثني علي بن إسحاق الكندي، قال: حدثنا محمد بن سنان، عن يونس بن رباط، قال: سمعت أبا عبد الله (عليه السلام) يقول \"، وذكر مثله .","22/2/15/3",""],[4,15,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار بقم قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، عن معمر بن خلاد قال: ذُكر القائم عند أبي الحسن الرضا فقال: أنتم اليوم أرخى بالاً منكم يومئذ. قالوا: وكيف؟ قال: لو قد خرج قائمنا لم يكن إلاّ العلق والعرق والنوم على السروج، وما لباس القائم إلاّ الغليظ، وما طعامه إلاّ الجشب.","22/2/15/4",""],[5,15,"أخبرنا سلامة بن محمد قال: أخبرنا أحمد بن علي بن داود القمي، قال: حدثنا محمد بن الحسن الصفار، عن أحمد بن محمد بن عيسى، عن بعض رجاله، عن أبي عبد الله قال: سأل نوح ربه أن ينْزل على قومه العذاب، فأوحى الله إليه أن يغرس نواة من النخل فإذا بلغت فأثمرت وأكل منها، أهلك قومه وأنزل عليهم العذاب. فغرس نوح النواة وأخبر أصحابه بذلك، فلما بلغت النخلة وأثمرت واجتنى نوح منها وأكل وأطعم أصحابه، قالوا له: يا نبيّ الله، الوعدَ الذي وعدتنا. فدعا نوح ربه وسأل الوعد الذي وعده، فأوحى إليه أن يعيد الغرس ثانية حتى إذا بلغ النخل وأثمر وأكل منه أنزل عليهم العذاب. فأخبر نوح أصحابه بذلك، فصاروا ثلاث فرق: فرقة ارتدت، وفرقة نافقت، وفرقة ثبتت مع نوح، ففعل نوح ذلك حتى إذا بلغت النخلة وأثمرت وأكل منها نوح وأطعم أصحابه، قالوا: يا نبيّ الله، الوعد الذي وعدتنا، فدعا نوح ربه، فأوحى إليه أن يغرس الغرسة الثالثة فإذا بلغ وأثمر أهلك قومه، فأخبر أصحابه فافترق الفرقتان ثلاث فرق: فرقة ارتدت، وفرقة نافقت، وفرقة ثبتت معه. حتى فعل نوح ذلك عشر مرات، وفعل الله ذلك بأصحابه الذين يبقون معه فيفترقون كل فرقة ثلاث فرق على ذلك، فلما كان في العاشرة جاء إليه رجال من أصحابه الخاصة المؤمنين، فقالوا: يا نبيّ الله، فعلت بنا ما وعدت أو لم تفعل فأنت صادق نبيٌّ مرسل لا نشكّ فيك ولو فعلت ذلك بنا، قال: فعند ذلك من قولهم أهلكهم الله لقول نوح، وأدخل الخاص معه في السفينة، فنجاهم الله تعالى، ونجى نوحا معهم بعد ما صفوا وهذبوا وذهب الكدر منهم.","22/2/15/5",""],[6,15,"حدثنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أبو سليمان أحمد بن هوذة الباهلي، قال: حدثنا إبراهيم بن إسحاق النهاوندي، قال: حدثنا عبد الله ابن حماد الأنصاري، عن المفضل بن عمر، قال: كنت عند أبي عبد الله يالطواف فنظر إليّ وقال لي: يا مفضل، ما لي أراك مهموماً متغير اللون؟ (قال) فقلت له: جعلت فداك، نظري إلى بني العباس وما في أيديهم من هذا الملك والسلطان والجبروت، فلو كان ذلك لكم لكنا فيه معكم. فقال: يا مفضل، أما لو كان ذلك لم يكن إلاّ سياسة الليل وسباحة النهار وأكل الجشب ولبس الخشن شبه أمير المؤمنين وإلاّ فالنار، فزوي ذلك عنا، فصرنا نأكل ونشر ب، وهل رأيت ظلامة جعلها الله نعمة مثل هذا؟","22/2/15/6",""],[7,15,"أخبرنا أبو سليمان قال: حدثنا إبراهيم بن إسحاق، قال: حدثنا عبد الله بن حماد، عن عمرو بن شمر قال: كنت عند أبي عبد الله في بيته والبيت غاص بأهله، فأقبل الناس يسألونه، فلا يسأل عن شيء إلاّ أجاب فيه، فبكيت من ناحية البيت، فقال: ما يبكيك يا عمرو! قلت: جعلت فداك، وكيف لا أبكي! وهل في هذه الأمة مثلك والباب مغلق عليك والستر مرخى عليك. فقال: لا تبك يا عمرو، نأكل أكثر الطيب ونلبس اللين، ولو كان الذي تقول لم يكن إلاّ أكل الجشب ولبس الخشن مثل أمير المؤمنين علي بن أبي طالب ، وإلاّ فمعالجة الأغلال في النار.","22/2/15/7",""],[1,16,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، قال: حدثنا الحسن بن علي بن يوسف ومحمد بن علي، عن سعدان بن مسلم، عن أبي بصير، عن أبي عبد الله قال: قلت له: ما لهذا الأمر أمد ينتهي إليه ويريح أبداننا؟ قال: بلى، ولكنكم أذعتم، فأخره الله.","22/2/16/1",""],[2,16,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي قال: حدثني محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن محمد بن يحيى الخثعمي، قال: حدثني الضريس، عن أبي خالد الكابلي، قال: لما مضى علي بن الحسين دخلت على محمد بن علي الباقر ، فقلت له: جعلت فداك، قد عرفت انقطاعي إلى أبيك وأنسي به، ووحشتي من الناس. قال: صدقت يا أبا خالد، فتريد ماذا؟ قلت: جعلت فداك، لقد وصف لي أبوك صاحب هذا الأمر بصفة لو رأيته في بعض الطريق لأخذت بيده. قال: فتريد ماذا يا أبا خالد؟ قلت: أريد أن تسميه لي حتى أعرفه باسمه. فقال: سألتني، والله، يا أبا خالد، عن سؤال مجهد، ولقد سألتني عن أمر ما كنت محدثاً به أحداً، و لو كنت محدثاً به أحداً لحدّثتك، ولقد سألتني عن أمر لو أن بني فاطمة عرفوه حرصوا على أن يقطعوه بضعة بضعة.","22/2/16/2",""],[3,16,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى العباسي، عن يعقوب بن يزيد، عن محمد بن أبي عمير، عن عبد الله بن بكير، عن محمد بن مسلم قال: قال أبو عبد الله: يا محمد! من أخبرك عنا توقيتاً فلا تهابن أن تُكذبه، فإنا لا نوقّت لأحد وقتاً.","22/2/16/3",""],[4,16,"أخبرنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي بنهاوند سنة ثلاث وسبعين ومائتين، قال: حدثنا عبد الله بن حماد الأنصاري في شهر رمضان سنة تسع وعشرين ومائتين، قال: حدثنا عبد الله بن سنان، عن أبي عبد الله جعفر بن محمد أنه قال: أبى الله إلاّ أن يخلف وقت الموقتين.","22/2/16/4",""],[5,16,"حدثنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن محمد بن أحمد القلانسي، عن محمد بن علي، عن أبي جميلة، عن أبي بكر الحضرمي، قال: سمعت أبا عبد الله يقول: إنا لا نوقت هذا الأمر.","22/2/16/5",""],[6,16,"أخبرنا علي بن الحسين، قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، قال: حدثنا عبد الله بن جبلة، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله قال: قلت له: جعلت فداك، متى خروج القائم ؟ فقال: يا أبا محمد، إنّا أهل بيت لا نوقت، وقد قال محمد: \"كذب الوقاتون.\" يا أبا محمد، إن قدام هذا الأمر خمس علامات: أولاهن النداء في شهر رمضان، وخروج السفياني، وخروج الخراساني، وقتل النفس الزكية، وخسف بالبيداء. ثم قال: يا أبا محمد، إنه لا بد أن يكون قدام ذلك الطاعونان: الطاعون الأبيض والطاعون الأحمر. قلت: جعلت فداك، وأي شيء هما؟ فقال: أما الطاعون الأبيض فالموت الجارف، وأما الطاعون الأحمر فالسيف، ولا يخرج القائم حتى ينادى باسمه من جوف السماء في ليلة ثلاث وعشرين في شهر رمضان ليلة جمعة. قلت: بم ينادى؟ قال: باسمه واسم أبيه: ألا إن فلان بن فلان قائم آل محمد فاسمعوا له وأطيعوه، فلا يبقى شيء خلق الله فيه الروح إلاّ يسمع الصيحة، فتوقظ النائم ويخرج إلى صحن داره، وتخرج العذراء من خدرها، ويخرج القائم مما يسمع، وهي صيحة جبرئيل .","22/2/16/6",""],[7,16,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى، عن عبد الرحمن بن القاسم قال: حدثني محمد بن عمرو بن يونس الحنفي، قال: حدثني إبراهيم بن هراسة قال: حدثنا علي بن الحزور عن محمد بن بشر، قال: سمعت محمد بن الحنفية  يقول: إن قبل راياتنا رايةً لآل جعفر وأخرى لآل مرداس. فأما راية آل جعفر فليست بشيء ولا إلى شيء. فغضبتُ - وكنت أقرب الناس إليه - فقلت: جعلت فداك، إن قبل راياتكم رايات؟ قال: إي والله، إن لبني مرداس ملكاً موطداً لا يعرفون في سلطانهم شيئاً من الخير، سلطانهم عسر ليس فيه يسر، يدنون فيه البعيد ويقصون فيه القريب، حتى إذا أمنوا مكْرَ الله وعقابه صيح بهم صيحة لم يبق لهم راعٍ يجمعهم، ولا داع يسمعهم، ولا جماعة يجتمعون إليها، وقد ضربهم الله مثلاً في كتابه إِنَّمَا مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنْزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ مِمَّا يَأْكُلُ النَّاسُ وَالْأَنْعَامُ حَتَّىٰ إِذَا أَخَذَتِ الْأَرْضُ زُخْرُفَهَا وَازَّيَّنَتْ وَظَنَّ أَهْلُهَا أَنَّهُمْ قَادِرُونَ عَلَيْهَا أَتَاهَا أَمْرُنَا لَيْلًا أَوْ نَهَارًا فَجَعَلْنَاهَا حَصِيدًا كَأَنْ لَمْ تَغْنَ بِالْأَمْسِ ۚ كَذَٰلِكَ نُفَصِّلُ الْآيَاتِ لِقَوْمٍ يَتَفَكَّرُونَ ثم حلف محمد بن الحنفية باللهِ إن هذه الآيه نزلت فيهم. فقلت: جعلت فداك، لقد حدثتني عن هؤلاء بأمر عظيم، فمتى يهلكون؟ فقال: ويحك يا محمد، إن الله خالف علمه وقت الموقتين، إن موسى وعد قومه ثلاثين يوماً وكان في علم الله زيادة عشرة أيام لم يخبر بها موسى، فكفر قومه واتخذوا العجل من بعده لمّا جاز عنهم الوقت، وإن يونس وعد قومه العذاب وكان في علم الله أن يعفو عنهم، وكان من أمره ما قد علمت، ولكن إذا رأيت الحاجة قد ظهرت، وقال الرجل: بتُّ الليلة بغير عشاء، وحتى يلقاك الرجل بوجه ثم يلقاك بوجه آخر… قلت: هذه الحاجة قد عرفتها فما الأخرى وأي شيء هي؟ قال: يلقاك بوجه طلق، فإذا جئت تستقرضه قرضاً لقيك بغير ذلك الوجه، فعند ذلك تقع الصيحة من قريب.","22/2/16/7",""],[8,16,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل بن إبراهيم بن قيس بن رمانة الأشعري وسعدان بن إسحاق بن سعيد وأحمد بن الحسين ابن عبد الملك ومحمد بن أحمد بن الحسن القطواني، قالوا جميعاً: حدثنا الحسن بن محبوب الزراد، عن إسحاق بن عمار الصيرفي، قال: سمعت أبا عبد الله يقول: قد كان لهذا الأمر وقت، وكان في سنة أربعين ومائة، فحدثتم به وأذعتموه فأخره الله .","22/2/16/8",""],[9,16,"أخبرنا أحمد بن محمد بن سعيد بهذا الإسناد، عن الحسن بن محبوب، عن إسحاق بن عمار قال: قال لي أبو عبد الله: يا أبا إسحاق، إن هذا الأمر قد أُخر مرتين.","22/2/16/9",""],[10,16,"حدثنا محمد بن يعقوب الكليني قال: حدثنا علي بن محمد ومحمد بن الحسن عن سهل بن زياد ومحمد بن يحيى، عن أحمد بن محمد جميعاً، عن الحسن بن محبوب، عن أبي حمزة الثمالي، قال: سمعت أبا جعفر الباقر يقول: يا ثابت، إن الله تعالى قد كان وقّت هذا الأمر في سنة السبعين، فلما قتل الحسين اشتد غضب الله فأخّره إلى أربعين ومائة، فحدّثناكم بذلك فأذَعتم وكشفتم قناع الستر فلم يجعل الله لهذا الأمر بعد ذلك وقتاً عندنا، ويمحو الله ما يشاء ويثبت وعنده أمّ الكتاب. قال أبو حمزة: فحدثت بذلك أبا عبد الله الصادق عليه السلام، فقال: قد كان ذلك.","22/2/16/10",""],[11,16,"وأخبرنا محمد بن يعقوب، عن محمد بن يحيى، عن سلمة بن الخطاب، عن علي بن حسان، عن عبد الرحمن بن كثير، قال: كنت عند أبي عبد الله إذ دخل عليه مهزم، فقال له: جعلت فداك أخبرني عن هذا الأمر الذي ننتظره، متى هو؟ فقال: يا مهزم، كذب الوقاتون، وهلك المستعجلون، ونجا المسلمون.","22/2/16/11",""],[12,16,"وأخبرنا محمد بن يعقوب، عن عدة من شيوخه، عن أحمد بن محمد بن خالد عن أبيه، عن القاسم بن محمد، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله قال: سألته عن القائم ، فقال: كذب الوقاتون، إنا أهل بيت لا نوقت. ثم قال: أبى الله إلاّ أن يخلف وقت الموقتين.","22/2/16/12",""],[13,16,"أخبرنا محمد بن يعقوب، عن الحسين بن محمد، عن معلي بن محمد، عن الحسن بن علي الخزاز، عن عبد الكريم بن عمرو الخثعمي، عن الفضيل بن يسار، عن أبي جعفر قال: قلت له: لهذا الأمر وقت؟ فقال: كذب الوقاتون، كذب الوقاتون، إن موسى لما خرج وافداً إلى ربه واعدهم ثلاثين يوماً، فلما زاده الله على الثلاثين عشراً قال قومه: قد أخلفنا موسى، فصنعوا ما صنعوا. فإذا حدثناكم بحديث فجاء على ما حدثناكم به، فقولوا: صدق الله، وإذا حدثناكم بحديث فجاء على خلاف ما حدثناكم به، فقولوا: صدق الله؛ تؤجروا مرتين.","22/2/16/13",""],[14,16,"وأخبرنا محمد بن يعقوب، عن محمد بن يحيى وأحمد بن إدريس، عن محمد بن أحمد، عن السياري، عن الحسن بن علي بن يقطين، عن أخيه الحسين، عن أبيه علي بن يقطين قال: قال لي أبو الحسن موسى بن جعفر: يا علي، الشيعة تربّى بالأماني منذ مائتي سنة. (قال) وقال يقطين لابنه علي بن يقطين: ما بالنا قيل لنا فكان، وقيل لكم فلم يكن؟ (يعني أمر بني العباس) فقال له علي: إن الذي قيل لكم ولنا كان من مخرج واحد، غير أن أمركم حضر وقته فأعطيتم محضه فكان كما قيل لكم وإن أمرنا لم يحضر فعلّلنا بالأمانيّ، فلو قيل لنا: إن هذا الأمر لا يكون إلاّ إلى مائتي سنة أو ثلاثمائة سنة لقست القلوب ولرجع عامة الناس عن الإيمان إلى الإسلام، ولكن قالوا: ما أسرعه وما أقربه، تألفاً لقلوب الناس وتقريباً للفرج.","22/2/16/14",""],[15,16,"أخبرنا محمد بن يعقوب قال: حدثني الحسين بن محمد، عن جعفر بن محمد، عن القاسم بن إسماعيل الانباري، عن الحسن بن علي، عن إبراهيم بن مهزم، عن أبيه، عن أبي عبد الله قال: ذكرنا عنده ملوك آل فلان، فقال: إنما هلك الناس من استعجالهم لهذا الأمر، إن الله لا يعجل لعجلة العباد، إن لهذا الأمر غاية ينتهي إليها، فلو قد بلغوها لم يستقدموا ساعة ولم يستأخروا.","22/2/16/15",""],[1,17,"أخبرنا أبو العباس أحمد بن محمد بن سعيد بن عقدة قال: حدثنا محمد بن المفضل بن إبراهيم، قال: حدثني محمد بن عبد الله بن زرارة، عن محمد بن مروان، عن الفضيل بن يسار، قال: سمعت أبا عبد الله يقول: إن قائمنا إذا قام استقبل من جهل الناس أشد مما استقبله رسول الله من جهال الجاهلية. قلت: وكيف ذاك؟ قال: إن رسول الله أتى الناس وهم يعبدون الحجارة والصخور والعيدان والخشب المنحوتة، وإن قائمنا إذا قام أتى الناس وكلّهم يتأول عليه كتاب الله، يحتج عليه به. ثم قال: أما والله ليدخلن عليهم عدله جوف بيوتهم كما يدخل الحر والقر.","22/2/17/1",""],[2,17,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن الحسين بن المختار عن أبي حمزة الثمالي قال: سمعت أبا جعفر يقول: إن صاحب هذا الأمر لو قد ظهر لقي من الناس مثل ما لقي رسول الله وأكثر.","22/2/17/2",""],[3,17,"أخبرنا محمد بن همام قال: حدثنا حميد بن زياد الكوفي، قال: حدثنا الحسن بن محمد بن سماعة، قال: حدثنا أحمد بن الحسن الميثمي، عن محمد بن أبي حمزة عن بعض أصحابه، عن أبي عبد الله ، قال: سمعته يقول: القائم يلقى في حربه ما لم يلق رسول الله . إن رسول الله أتاهم وهم يعبدون حجارة منقورة وخشباً منحوتة، وإن القائم يخرجون عليه فيتأولون عليه كتاب الله، ويقاتلونه عليه.","22/2/17/3",""],[4,17,"أخبرنا علي بن أحمد قال: أخبرنا عبيد الله بن موسى العلوي، عن محمد بن الحسين، عن محمد بن سنان، عن قتيبة الأعشى، عن أبان بن تغلب، قال: سمعت أبا عبد الله جعفر بن محمد يقول: إذا ظهرت راية الحق لعنها أهل المشرق وأهل المغرب، أتدري لم ذاك؟ قلت: لا. قال: للذي يلقى الناس من أهل بيته قبل خروجه.","22/2/17/4",""],[5,17,"أخبرنا عبد الواحد بن عبد الله قال: حدثنا محمد بن جعفر القرشي، قال: حدثني محمد بن الحسين، عن محمد بن سنان، عن قتيبة الأعشى، عن منصور بن حازم عن أبي عبد الله أنه قال: إذا رفعت راية الحق لعنها أهل المشرق والمغرب. قلت له: مم ذلك؟ قال: مما يلقون من بني هاشم.","22/2/17/5",""],[6,17,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى وأحمد بن علي الأعلم قالا: حدثنا محمد بن علي الصيرفي، عن محمد بن صدقة وابن اذينة العبدي ومحمد بن سنان جميعاً، عن يقعوب السراج، قال: سمعت أبا عبد الله يقول: ثلاث عشرة مدينة وطائفة يحارب القائم أهلها ويحاربونه: أهل مكة، وأهل المدينة، وأهل الشام، وبنو أمية، وأهل البصرة، وأهل دست ميسان، والأكراد، والأعراب وضبة، وغني، وباهلة، وأزد، وأهل الري.","22/2/17/6",""],[1,18,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثني محمد بن المفضل بن إبراهيم بن قيس بن رمانة من كتابه في رجب سنة خمس وستين ومائتين، قال: حدثنا الحسن بن علي بن فضال، قال: حدثنا ثعلبة بن ميمون أبو إسحاق، عن عيسى بن أعين، عن أبي عبد الله أنه قال: السفياني من المحتوم، وخروجه في رجب، ومن أول خروجه إلى آخره خمسة عشر شهراً، ستة أشهر يقاتل فيها، فإذا ملك الكور الخمس ملك تسعة أشهر، ولم يزد عليها يوماً.","22/2/18/1",""],[2,18,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا القاسم بن محمد بن الحسن بن حازم من كتابه، قال: حدثنا عبيس بن هشام، عن محمد بن بشر الأحول، عن عبد الله بن جبلة، عن عيسى بن أعين، عن معلي بن خنيس، قال: سمعت أبا عبد الله يقول: من الأمر محتوم ومنه ما ليس بمحتوم، ومن المحتوم خروج السفياني في رجب.","22/2/18/2",""],[3,18,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن التيملي في صفر سنة أربع وسبعين ومائتين، قال: حدثنا الحسن بن محبوب، عن أبي أيوب الخزاز، عن محمد بن مسلم قال: سمعت أبا جعفر الباقر يقول: اتقوا الله واستعينوا على ما أنتم عليه بالورع والاجتهاد في طاعة الله، فإن أشد ما يكون أحدكم أغتباطاً بما هو فيه من الدين لو قد صار في حد الآخرة وانقطعت الدنيا عنه، فإذا صار في ذلك الحدّ عرف أنه قد استقبل النعيم والكرامة من الله والبشرى بالجنة وأمن ممّا كان يخاف وأيقن أن الذي كان عليه هو الحق، وأن من خالف دينه على باطل، وأنه هالك. فأبشروا، ثم أبشروا بالذي تريدون، ألستم ترون أعداءكم يقتتلون في معاصي الله، ويقتل بعضهم بعضاً على الدنيا دونكم وأنتم في بيوتكم آمنون في عزلة عنهم، وكفى بالسفياني نقمة لكم من عدوكم، وهو من العلامات لكم، مع أن الفاسق لو قد خرج لمكثتم شهراً أو شهرين بعد خروجه لم يكن عليكم بأس حتى يقتل خلقاً كثيراً دونكم. فقال له بعض أصحابه: فكيف نصنع بالعيال إذا كان ذلك؟ قال: يتغيب الرجال منكم عنه، فإن حنقه وشرهه إنما هي على شيعتنا، وأما النساء فليس عليهن بأس إن شاء الله تعالى. قيل: فإلى أين مخرج الرجال ويهربون منه؟ فقال: مَن أراد منهم أن يخرج يخرج إلى المدينة أو إلى مكة أو إلى بعض البلدان. ثم قال: ما تصنعون بالمدينة وإنما يقصد جيش الفاسق إليها، ولكن عليكم بمكة، فأنها مجمعكم، وإنما فتنته حمل أمرأة: تسعة أشهر، ولا يجوزها إن شاء الله.","22/2/18/3",""],[4,18,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن العباس بن عامر، عن عبد الله بن بكير، عن زرارة بن أعين، عن عبد الملك بن أعين، قال: كنت عند أبي جعفر فجرى ذكر القائم ، فقلت له: أرجو أن يكون عاجلاً ولا يكون سفياني. فقال: لا والله، إنه لمن المحتوم الذي لا بد منه.","22/2/18/4",""],[5,18,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن، عن محمد بن خالد الأصم، عن عبد الله بن بكير، عن ثعلبة بن ميمون، عن زرارة، عن حمران بن أعين، عن أبي جعفر محمد بن علي في قوله تعالى هُوَ الَّذِي خَلَقَكُمْ مِنْ طِينٍ ثُمَّ قَضَىٰ أَجَلًا ۖ وَأَجَلٌ مُسَمًّى عِنْدَهُ ۖ ثُمَّ أَنْتُمْ تَمْتَرُونَ {2} فقال: إنهما أجلان: أجل محتوم، وأجل موقوف. فقال له حمران: ما المحتوم؟ قال: الذي لله فيه المشيئة. قال حمران: إني لأرجو أن يكون أجل السفياني من الموقوف. فقال أبو جعفر: لا والله، إنه لمن المحتوم.","22/2/18/5",""],[6,18,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن سالم بن عبد الرحمن الأزدي من كتابه في شوال سنة إحدى وسبعين ومائتين، قال: حدثني عثمان بن سعيد الطويل عن أحمد بن سليم، عن موسى بن بكر، عن الفضيل بن يسار، عن أبي جعفر قال: إن من الأمور أموراً موقوفة، وأموراً محتومة، وإن السفياني من المحتوم الذي لا بد منه.","22/2/18/6",""],[7,18,"حدثنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، قال: حدثني عباد بن يعقوب، قال: حدثنا خلاد الصائغ، عن أبي عبد الله أنه قال: السفياني لا بد منه، ولا يخرج إلاّ في رجب. فقال له رجل: يا أبا عبد الله، إذا خرج فما حالنا؟ قال: إذا كان ذلك فإلينا.","22/2/18/7",""],[8,18,"حدثنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي بنهاوند سنة ثلاث وسبعين ومائتين، قال: حدثنا أبو محمد عبد الله بن حماد الأنصاري سنة تسع وعشرين ومائتين، عن عمرو بن شمر، عن جابر الجعفي قال: سألت أبا جعفر الباقر عن السفياني، فقال: وأنى لكم بالسفياني حتى يخرج قبله الشيصباني، يخرج من أرض كوفان ينبع كما ينبع الماء، فيقتل وفدكم، فتو قعوا بعد ذلك السفياني، وخروج القائم .","22/2/18/8",""],[9,18,"أخبرنا محمد بن همام قال: حدثنا جعفر بن محمد بن مالك، قال: حدثنا الحسن بن علي بن يسار الثوري، قال: حدثنا الخليل بن راشد، عن علي بن أبي حمزة قال: زاملتُ أبا الحسن موسى بن جعفر بين مكة والمدينة، فقال لي يوماً: يا علي، لو أن أهل السماوات والأرض خرجوا على بني العباس لسقيت الأرض بدمائهم حتى يخرج السفياني. قلت له: يا سيدي، أمره من المحتوم؟ قال: نعم. ثم أطرق هنيئة، ثم رفع رأسه وقال: ملك بني العباس مكر وخدع، يذهب حتى يقال: لم يبق منه شيء، ثم يتجدد حتى يقال: ما مر به شيء.","22/2/18/9",""],[10,18,"أخبرنا محمد بن همام قال: حدثنا محمد بن أحمد بن عبد الله الخالنجي قال: حدثنا أبو هاشم داود بن القاسم الجعفري قال: كنا عند أبي جعفر محمد بن علي الرضا فجرى ذكر السفياني وما جاء في الرواية من أن أمره من المحتوم فقلت لأبي جعفر: هل يبدو لله في المحتوم؟ قال: نعم. قلنا له: فنخاف أن يبدو لله في القائم. فقال: إن القائم من الميعاد، والله لا يخلف الميعاد.","22/2/18/10",""],[11,18,"أخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عن محمد بن موسى، عن أحمد بن أبي أحمد، عن محمد بن علي القرشي، عن الحسن بن الجهم، قال: قلت للرضا: أصلحك الله إنهم يتحدثون أن السفياني يقوم وقد ذهب سلطان بني العباس. فقال: كذبوا، إنه ليقوم وإن سلطانهم لقائم.","22/2/18/11",""],[12,18,"أخبرنا أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي عن عبد الله بن حماد الأنصاري، عن الحسين بن أبي العلاء، عن عبد الله بن أبي يعفور قال: قال لي أبو جعفر الباقر: إن لولد العباس والمرواني لوقعة بقرقيسياء يشيب فيها الغلام الحزور، ويرفع الله عنهم النصر، ويوحي إلى طير السماء وسباع الأرض: اشبعي من لحوم الجبارين، ثم يخرج السفياني.","22/2/18/12",""],[13,18,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي من كتابه في صفر سنة أربع وسبعين ومائتين، قال: حدثنا العباس بن عامر بن رباح الثقفي قال: حدثني محمد بن الربيع الأقرع، عن هشام بن سالم، عن أبي عبد الله جعفر بن محمد أنه قال: إذا استولى السفياني على الكور الخمس فعِدّوا له تسعة أشهر. وزعم هشام أن الكور الخمس: دمشق، وفلسطين، والأردن، وحمص وحلب.","22/2/18/13",""],[14,18,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن عبد الله بن محمد، قال: حدثنا محمد بن خالد، عن الحسن بن المبارك، عن أبي إسحاق الهمداني عن الحارث الهمداني، عن أمير المؤمنين أنه قال: المهدي أقبل، جعد، بخده خال، يكون مبدؤه من قبل المشرق، وإذا كان ذلك خرج السفياني، فيملك قدر حمل أمرأة تسعة أشهر، يخرج بالشام فينقاد له أهل الشام إلاّ طوائف من المقيمين على الحق، يعصمهم الله من الخروج معه، ويأتي المدينة بجيش جرار حتى إذا انتهى إلى بيداء المدينة خسف الله به، وذلك قول الله في كتابه وَلَوْ تَرَىٰ إِذْ فَزِعُوا فَلَا فَوْتَ وَأُخِذُوا مِنْ مَكَانٍ قَرِيبٍ {51}","22/2/18/14",""],[15,18,"أخبرنا علي بن أحمد قال: حدثنا عبيد الله بن موسى، عن إبراهيم بن هاشم، عن محمد بن أبي عمير، عن هشام بن سالم، عن أبي عبد الله أنه قال: اليماني والسفياني كفَرسَي رهان.","22/2/18/15",""],[16,18,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى، عن محمد بن موسى، قال أخبرني أحمد بن أبي أحمد المعروف بأبي جعفر الوراق، عن إسماعيل بن عياش، عن مهاجر بن حكيم، عن المغيرة بن سعيد، عن أبي جعفر الباقر أنه قال: قال أمير المؤمنين: إذا أختلف الرمحان بالشام لم تنجلِ إلاّ عن آية من آيات الله. قيل: وما هي يا أمير المؤمنين؟ قال: رجفة تكون بالشام يهلك فيها أكثر من مائة ألف، يجعلها الله رحمة للمؤمنين وعذاباً على الكافرين، فإذا كان ذلك فانظروا إلى أصحاب البراذين الشهب المحذوفة والرايات الصفر، تقبل من المغرب حتى تحل بالشام، وذلك عند الجزع الأكبر والموت الأحمر، فإذا كان ذلك فانظروا خسف قرية من دمشق يقال لها حرستا، فإذا كان ذلك خرج ابن آكلة الأكباد من الوادي اليابس حتى يستوي على منبر دمشق فإذا كان ذلك فانتظروا خروج المهدي .","22/2/18/16",""],[17,18,"حدثنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، قال: حدثني الحسن بن وهب، قال: حدثني إسماعيل بن أبان، عن يونس بن أبي يعفور، قال: سمعت أبا عبد الله يقول: إذا خرج السفياني يبعث جيشاً إلينا وجيشاً إليكم، فإذا كان كذلك فأتونا على كل صعب وذلول.","22/2/18/17",""],[18,18,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا حميد بن زياد، قال حدثني علي بن الصباح بن الضحاك، قال: حدثنا أبو علي الحسن بن محمد الحضرمي، قال: حدثنا جعفر بن محمد، عن إبراهيم بن عبد الحميد، عن أبي أيوب الخزاز، عن محمد بن مسلم، عن أبي جعفر الباقر قال: السفياني أحمر أشقر أزرق، لم يعبد الله قط، ولم يرَ مكة ولا المدينة قط، يقول: يا رب ثاري والنار، يا رب ثاري والنار.","22/2/18/18",""],[1,19,"حدثنا محمد بن همام قال: حدثنا أحمد بن مابنداذ، قال: حدثنا أحمد بن هلال، عن محمد بن أبي عمير، عن أبي المغرا، عن أبي بصير قال: قال أبو عبد الله: لما التقى أمير المؤمنين وأهل البصرة نشر الراية؛ راية رسول الله ، فزلزلت أقدامهم فما أصفرت الشمس حتى قالوا: آمنا يا بن أبي طالب، فعند ذلك قال: لا تقتلوا الأسرى ولا تجهزوا الجرحى ولا تتبعوا مولياً، ومن ألقى سلاحه فهو آمن ومن أغلق بابه فهو آمن. ولما كان يوم صفين سألوه نشر الراية فأبى عليهم، فتحمّلوا عليه بالحسن والحسين وعمار بن ياسر ، فقال للحسن: يا بنيّ، إن للقوم مدة يبلغونها، وإن هذه راية لا ينشرها بعدي إلاّ القائم صلوات الله عليه.","22/2/19/1",""],[2,19,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا أبو عبد الله يحيى بن زكريا بن شيبان، عن يونس بن كليب، عن الحسن بن علي بن أبي حمزة، عن أبيه، عن أبي بصير قال: قال أبو عبد الله: لا يخرج القائم حتى يكون تكملة الحلقة. قلت: وكم تكملة الحلقة؟ قال: عشرة آلاف، جبرئيل عن يمينه، وميكائيل عن يساره. ثم يهز الراية ويسير بها، فلا يبقى أحد في المشرق ولا في المغرب إلاّ لعنها وهي راية رسول الله ، نزل بها جبرئيل يوم بدر. ثم قال: يا أبا محمد، ما هي والله قطن ولا كتان ولا قز ولا حرير. قلت: فمن أي شيء هي؟ قال: من ورق الجنة، نشرها رسول الله يوم بدر، ثم لفها ودفعها إلى علي ، فلم تزل عند علي حتى إذا كان يوم البصرة نشرها أمير المؤمنين ففتح الله عليه، ثم لفها وهي عندنا هناك، لا ينشرها أحد حتى يقوم القائم، فإذا هو قام نشرها فلم يبق أحد في المشرق والمغرب إلاّ لعنها، ويسير الرعب قدامها شهراً ووراءها شهراً وعن يمينها شهراً وعن يسارها شهراً. ثم قال: يا أبا محمد، إنه يخرج موتوراً غضبان أسفاً لغضب الله على هذا الخلق، يكون عليه قميص رسول الله الذي عليه يوم احد، وعمامته السحاب، ودرعه درع رسول الله السابغة وسيفه سيف رسول الله ذو الفقار، يجرد السيف على عاتقه ثمانية أشهر يقتل هرجاً. فأول ما يبدء ببني شيبة فيقطع أيديهم ويعلقها في الكعبة وينادى مناديه: هؤلاء سراق الله، ثم يتناول قريشاً، فلا يأخذ منها إلاّ السيف، ولا يعطيها إلاّ السيف، ولا يخرج القائم حتى يقرء كتابان كتاب بالبصرة، وكتاب بالكوفة بالبراءة من علي .","22/2/19/2",""],[3,19,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي قال: حدثنا محمد بن الحسين بن أبي الخطاب، قال: حدثنا محمد بن سنان، عن حماد بن أبي طلحة، عن أبي حمزة الثمالي، قال: قال لي أبو جعفر: يا ثابت، كأني بقائم أهل بيتي قد أشرف على نجفكم هذا، (وأومأ بيده إلى ناحية الكوفة) فإذا هو أشرف على نجفكم نشر راية رسول الله ، فإذا هو نشرها أنحطت عليه ملائكة بدر. قلت: وما راية رسول الله ؟ قال: عمودها من عمد عرش الله ورحمته وسائرها من نصر الله، لا يهوي بها إلى شيء إلاّ أهلكه الله. قلت: فمخبوة عندكم حتى يقوم القائم أم يؤتى بها؟ قال: لا بل يؤتى بها. قلت: من يأتيه بها؟ قال: جبرئيل .","22/2/19/3",""],[4,19,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، قال حدثنا الحسن ومحمد ابنا علي بن يوسف، عن سعدان بن مسلم، عن عمر بن أبان الكلبي عن أبان بن تغلب، قال: سمعت أبا عبد الله يقول: كأني أنظر إلى القائم على نجف الكوفة، عليه خوخة من استبرق، ويلبس درع رسول الله فإذا لبسها انتفضت به حتى تستدير عليه، ثم يركب فرساً له أدهم أبلق، بين عينيه شمراخ بيّن، معه راية رسول الله . قلت: مخبوة أو يؤتى بها؟ قال: بل يأتيه بها جبرئيل، عمودها من عمد عرش الله، وسائرها من نصر الله، لا يهوي بها إلى شيء إلاّ أهلكه الله، يهبط بها تسعة آلاف ملك وثلاثمائة وثلاثة عشر ملكاً. فقلت له: جعلت فداك، كل هؤلاء معه؟ قال: نعم، هم الذين كانوا مع نوح في السفينة، والذين كانوا مع إبراهيم حيث أُلقي في النار، وهم الذين كانوا مع موسى لما فلق له البحر، والذين كانوا مع عيسى لما رفعه الله إليه، وأربعة آلاف مسومين كانوا مع رسول الله ، وثلاثمائة وثلاثة عشر ملكاً كانوا معه يوم بدر، ومعهم أربعة آلاف صعدوا إلى السماء يستأذنون في القتال مع الحسين فهبطوا إلى الأرض وقد قتل، فهم عند قبره شعث غبر يبكونه إلى يوم القيامة، وهم ينتظرون خروج القائم .","22/2/19/4",""],[5,19,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي قال: حدثنا أبو جعفر الهمداني، قال: حدثنا موسى بن سعدان، عن عبد الله القاسم الحضرمي، عن عمر بن أبان الكلبي، عن أبان بن تغلب، قال: قال أبو عبد الله: كأني بالقائم، فإذا استوى على ظهر النجف لبس درع رسول الله الأبيض فينتفض هو بها فيستديرها عليه فيغشاها بخداعة من استبرق، ويركب فرسا له أدهم أبلق، بين عينيه شمراخ، فينتفض به أنتفاضه لا يبقى أهل بلد إلاّ وهم يرون أنه معهم في بلدهم، وينشر راية رسول الله ، عمودها من عمد عرش الله وسائرها من نصر الله، ما يهوي بها إلى شيء إلاّ أهلكه الله. قلت: أمخبوة هي أم يؤتى بها؟ قال: بل يأتي بها جبرئيل ، فإذا هزها لم يبق مؤمن إلاّ صار قلبه أشد من زبر الحديد، وأعطي قوة أربعين رجلاً، ولا يبقى مؤمن ميت إلاّ دخلت عليه تلك الفرحة في قبره وذلك حيث يتزاورون في قبورهم ويتباشرون بقيام القائم ، وينحط عليه ثلاثة عشر ألفاً وثلاثمائة وثلاثة عشر ملكاً. (قال) فقلت: كل هؤلاء كانوا مع أحد قبله من الأنبياء؟ قال: نعم، وهم الذين كانوا مع نوح في السفينة، والذين كانوا مع إبراهيم حيث ألقي في النار، والذين كانوا مع موسى حين فلق البحر، والذين كانوا مع عيسى حين رفعه الله إليه، وأربعة آلاف كانوا مع النبي مردفين، وثلاثمائة وثلاثة عشر ملكاً كانوا يوم بدر، وأربعة آلاف هبطوا يريدون القتال مع الحسين ، فلم يؤذن لهم فرجعوا في الاستيمار فهبطوا وقد قتل الحسين ، فهم عند قبره شعث غبر يبكونه إلى يوم القيامة، ورئيسهم ملك يقال له: منصور، فلا يزوره زائر إلاّ استقبلوه، ولا يودعه مودع إلاّ شيعوه، ولا مريض إلاّ عادوه ولا يموت ميت إلاّ صلوا عليه واستغفروا له بعد موته، فكل هؤلاء ينتظرون قيام القائم .","22/2/19/5",""],[1,20,"أخبرنا علي بن الحسين المسعودي قال: حدثنا محمد بن يحيى العطار بقم قال حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، عن عبد الرحمن بن أبي حماد، عن يعقوب بن عبد الله الأشعري، عن عتيبة بن سعدان بن يزيد، عن الأحنف بن قيس، قال: دخلت على علي في حاجة لي فجاء ابن الكواء وشبث بن ربعي فاستاذنا عليه، فقال لي علي: إن شئت فأذن لهما فإنك أنت بدأت بالحاجة. (قال) قلت: يا أمير المؤمنين، فأذن لهما. فلما دخلا قال: ما حملكما على أن خرجتما عليّ بحروراء؟ قالا: أحببنا أن نكون من جيش الغضب. قال: ويحكما، وهل في ولايتي غضب؟ أوَيكون الغضب حتى يكون من البلاء كذا وكذا؟ ثم يجتمعون قزعاً كقزع الخريف من القبائل ما بين الواحد والإثنين والثلاثة والأربعة والخمسة والستة والسبعة والثمانية والتسعة والعشرة.","22/2/20/1",""],[2,20,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسين التيملي قال: حدثنا الحسن ومحمد بنا علي بن يوسف، عن سعدان بن مسلم، عن رجل، عن المفضل بن عمر، قال: قال أبو عبد الله: إذا أذن الإمام دعا الله بأسمه العبراني فأتيحت له صحابته الثلاثمائة وثلاثة عشر قزع كقزع الخريف. فهم أصحاب الألوية منهم من يُفقد من فراشه ليلاً فيصبح بمكة، ومنهم من يُرى يسير في السحاب نهاراً يعرف بأسمه واسم أبيه وحليته ونسبه. قلت: جعلت فداك، أيّهم أعظم إيماناً. قال: الذي يسير في السحاب نهاراً، وهم المفقودون، وفيهم نزلت هذه الآية وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَاسْتَبِقُوا الْخَيْرَاتِ ۚ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ","22/2/20/2",""],[3,20,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي قال: حدثنا محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن ضريس، عن أبي خالد الكابلي، عن علي بن الحسين أو عن محمد بن علي أنه قال: الفقداء قوم يفقدون من فرشهم فيصبحون بمكة، وهو قول الله وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَاسْتَبِقُوا الْخَيْرَاتِ ۚ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ وهم أصحاب القائم .","22/2/20/3",""],[4,20,"حدثنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي بنهاوند سنة ثلاث وسبعين ومائتين، قال: حدثنا عبد الله بن حماد الأنصاري سنة تسع وعشرين ومائتين، عن عبد الله بن بكير، عن أبان بن تغلب، قال: كنت مع جعفر بن محمد في مسجد بمكة، وهو آخذ بيدي، فقال: يا أبان، سيأتي الله بثلاثمائة وثلاثة عشر رجلاً في مسجدكم هذا، يعلم أهل مكة أنه لم يخلق آباؤهم ولا أجدادهم بعد، عليهم السيوف، مكتوب على كل سيف اسم الرجل واسم أبيه وحليته ونسبه، ثم يأمر منادياً فينادي: هذا المهدي يقضي بقضاء داود وسليمان، لا يسأل على ذلك بينة.","22/2/20/4",""],[5,20,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى العلوي، عن هارون بن مسلم الكاتب الذي كان يحدث بسر من رأى عن مسعدة بن صدقة، عن عبد الحميد الطائي، عن محمد بن مسلم، عن أبي جعفر في قوله تعالى أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ وَيَجْعَلُكُمْ خُلَفَاءَ الْأَرْضِ ۗ أَإِلَٰهٌ مَعَ اللَّهِ ۚ قَلِيلًا مَا تَذَكَّرُونَ {62} قال: نزلت في القائم ، وكان جبرئيل على الميزاب في صورة طير أبيض فيكون أول خلق الله مبايعة له (أعني جبرئيل) ويبايعه الناس الثلاثمائة وثلاثة عشر، فمن كان ابتلي بالمسير وافى في تلك الساعة، ومن لم يبتلَ بالمسير فقد من فراشه، وهو قول أمير المؤمنين علي: \"المفقودون من فرشهم\" وهو قول الله وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَاسْتَبِقُوا الْخَيْرَاتِ ۚ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ {148} قال: الخيرات الولاية لنا أهل البيت.","22/2/20/5",""],[6,20,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، عن محمد بن علي الكوفي، عن إسماعيل بن مهران، عن محمد بن أبي حمزة، عن أبان بن تغلب، عن أبي عبد الله أنه قال: سيبعث الله ثلاثمائة وثلاثة عشر رجلاً إلى مسجد بمكة، يعلم أهل مكة أنهم لم يولدوا من آبائهم ولا أجدادهم، عليهم سيوف مكتوب عليها ألف كلمة، كل كلمة مفتاح ألف كلمة، ويبعث الله الريح من كل وادٍ تقول: هذا المهدي يحكم بحكم داود، ولا يريد بينة.","22/2/20/6",""],[7,20,"أخبرنا أحمد بن هوذة أبو سليمان قال: حدثني إبراهيم بن إسحاق النهاوندي عن عبد الله بن حماد الأنصاري، عن أبي الجارود، عن أبي جعفر الباقر قال: أصحاب القائم ثلاثمائة وثلاثة عشر رجلاً أولاد العجم، بعضهم يحمل في السحاب نهاراً، يعرف باسمه واسم أبيه ونسبه وحليته، وبعضهم نائم على فراشه فيوافيه في مكة على غير ميعاد.","22/2/20/7",""],[8,20,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى، عن محمد بن حسان الرازي عن محمد بن علي الكوفي، عن علي بن الحكم، عن علي بن أبي حمزة، عن أبي بصير، عن أبي جعفر الباقر: أن القائم يهبط من ثنية ذي طوى في عدة أهل بدر - ثلاثمائة وثلاثة عشر رجلاً - حتى يسند ظهره إلى الحجر الأسود، ويهز الراية الغالبة. قال علي بن أبي حمزة: فذكرت ذلك لأبي الحسن موسى بن جعفر ، فقال: كتاب منشور.","22/2/20/8",""],[9,20,"أخبرنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، عن محمد بن حسان الرازي، عن محمد بن علي الصيرفي، عن عبد الرحمن بن أبي هاشم، عن عمرو ابن أبي المقدام، عن عمران بن ظبيان، عن أبي تحيى حكيم بن سعد، قال: سمعت علياً يقول: إن أصحاب القائم شباب لا كهول فيهم إلاّ كالكحل في العين، أو كالملح في الزاد، وأقل الزاد الملح.","22/2/20/9",""],[10,20,"أخبرنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، عن علي بن أبي حمزة، قال: قال أبو عبد الله جعفر بن محمد: بينا شباب الشيعة على ظهور سطوحهم نيام إذ توافوا إلى صاحبهم في ليلة واحدة على غير معياد، فيصبحون بمكة.","22/2/20/10",""],[11,20,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا علي بن الحسن بن فضال، قال: حدثنا محمد بن حمزة ومحمد بن سعيد قالا: حدثنا حماد بن عثمان، عن سليمان ابن هارون العجلي قال: قال: سمعت أبا عبد الله يقول: إن صاحب هذا الأمر محفوظة له أصحابه، لو ذهب الناس جميعاً أتى الله له بأصحابه، وهم الذين قال الله فيهم أُولَٰئِكَ الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ ۚ فَإِنْ يَكْفُرْ بِهَا هَٰؤُلَاءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَيْسُوا بِهَا بِكَافِرِينَ {89} وهم الذين قال الله فيهم يَا أَيُّهَا الَّذِينَ آمَنُوا مَنْ يَرْتَدَّ مِنْكُمْ عَنْ دِينِهِ فَسَوْفَ يَأْتِي اللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُ أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ يُجَاهِدُونَ فِي سَبِيلِ اللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَائِمٍ ۚ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ ۚ وَاللَّهُ وَاسِعٌ عَلِيمٌ {54}","22/2/20/11",""],[12,20,"حدثنا علي بن الحسين قال: حدثنا محمد بن يحيى العطار، عن محمد بن حسان الرازي، عن محمد بن علي الكوفي، قال: حدثنا عبد الرحمن بن أبي هاشم، عن علي بن أبي حمزة، عن أبي بصير، عن أبي عبد الله قال: إن أصحاب طالوت ابتلوا بالنهر الذي قال الله تعالى سنبتليكم بنهر، وإن أصحاب القائم يبتلون بمثل ذلك.","22/2/20/12",""],[1,21,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا حميد بن زياد، عن علي بن الصباح، قال: حدثنا أبو علي الحسن بن محمد الحضرمي، قال: حدثني جعفر بن محمد، عن إبراهيم بن عبد الحميد، قال: أخبرني من سمع أبا عبد الله يقول: إذا خرج القائم خرج من هذا الأمر من كان يرى أنه من أهله ودخل فيه شبه عبدة الشمس والقمر.","22/2/21/1",""],[2,21,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف بن يعقوب أبو الحسن الجعفي، قال: حدثنا إسماعيل بن مهران، عن الحسن بن علي بن أبي حمزة، عن المفضل بن محمد الأشعري عن حريز عن أبي عبد الله ، عن أبيه، عن علي بن الحسين أنه قال: إذا قام القائم أذهب الله عن كل مؤمن العاهة ورد إليه قوته.","22/2/21/2",""],[3,21,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا علي بن الحسن التيملي، قال: حدثنا الحسن ومحمد ابنا علي بن يوسف، عن سعدان بن مسلم، عن صباح المزني، عن الحارث بن حصيرة، عن حبة العرني، قال: قال أمير المؤمنين: كأني أنظر إلى شيعتنا بمسجد الكوفة، قد ضربوا الفساطيط يعلمون الناس القرآن كما أنزل، أما إن قائمنا إذا قام كسره، وسوى قبلته.","22/2/21/3",""],[4,21,"أخبرنا علي بن الحسن قال: حدثنا محمد بن يحيى العطار، قال: حدثنا محمد بن حسان الرازي، قال: حدثنا محمد بن علي الكوفي، قال: حدثنا عبد الله بن محمد الحجال، عن علي بن عقبة بن خالد، عن أبي عبد الله أنه قال: كأني بشيعة علي في أيديهم المثاني يعلمون الناس المستأنف.","22/2/21/4",""],[5,21,"حدثنا أبو سليمان أحمد بن هوذة قال: حدثنا إبراهيم بن إسحاق النهاوندي، قال: حدثنا عبد الله بن حماد الأنصاري، عن صباح المزني، عن الحارث بن حصيرة، عن الأصبغ بن نباتة، قال: سمعت علياً يقول: كأني بالعجم فساطيطهم في مسجد الكوفة يعلمون الناس القرآن كما أنزل. قلت: يا أمير المؤمنين، أوليس هو كما أنزل؟ فقال: لا، محي منه سبعون من قريش بأسمائهم وأسماء آبائهم، وما ترك أبو لهب إلاّ إزراءً على رسول الله لأنّه عمه.","22/2/21/5",""],[6,21,"أخبرنا علي بن أحمد البندنيجي، عن عبيد الله بن موسى العلوي، عمن رواه، عن جعفر بن يحيى، عن أبيه، عن أبي عبد الله جعفر بن محمد أنه قال: كيف أنتم لو ضرب أصحاب القائم الفساطيط في مسجد كوفان، ثم يخرج إليهم المثال المستأنف، أمر جديد، على العرب شديد.","22/2/21/6",""],[7,21,"أخبرنا محمد بن همام قال: حدثني جعفر بن محمد بن مالك، قال: حدثنا أبو طاهر الوراق، قال: حدثني عثمان بن عيسى، عن أبي الصباح الكناني، قال: كنت عند أبي عبد الله فدخل عليه شيخ وقال: قد عقّني ولدي وجفاني إخواني. فقال أبو عبد الله: أوَما علمت أن للحق دولة وللباطل دولة كلاهما ذليل في دولة صاحبه، فمن أصابته رفاهية الباطل اقتص منه في دولة الحق.","22/2/21/7",""],[8,21,"حدثنا أبو سليمان أحمد بن هوذة، قال: حدثنا أبو إسحاق إبراهيم بن إسحاق النهاوندي، قال: حدثني عبد الله بن حماد الأنصاري، عن محمد بن جعفر بن محمد عن أبيه قال: إذا قام القائم بعث في أقاليم الأرض، في كل إقليم رجلاً، يقول: عهدك في كفك فإذا ورد عليك أمر لا تفهمه ولا تعرف القضاء فيه فانظر إلى كفّك واعمل بما فيها، قال: ويبعث جنداً إلى القسطنطينية، فإذا بلغوا الخليج كتبوا على أقدامهم شيئاً ومشوا على الماء، فإذا نظر إليهم الروم يمشون على الماء، قالوا: هؤلاء أصحابه يمشون على الماء، فكيف هو؟ فعند ذلك يفتحون لهم أبواب المدينة، فيدخلونها، فيحكمون فيها ما يشاؤون.","22/2/21/8",""],[9,21,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي، قال: حدثني محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن حريز، عن أبان بن تغلب، قال: سمعت أبا عبد الله جعفر بن محمد يقول: لا تذهب الدنيا حتى ينادي مناد من السماء: يا أهل الحق اجتمعوا. فيصيرون في صعيد واحد، ثم ينادي مرة أخرى: يا أهل الباطل اجتمعوا. فيصيرون في صعيد واحد. قلت: فيستطيع هؤلاء أن يدخلوا في هؤلاء؟ قال: لا والله، وذلك قول الله مَا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنْتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ ۗ وَمَا كَانَ اللَّهُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ وَلَٰكِنَّ اللَّهَ يَجْتَبِي مِنْ رُسُلِهِ مَنْ يَشَاءُ ۖ فَآمِنُوا بِاللَّهِ وَرُسُلِهِ ۚ وَإِنْ تُؤْمِنُوا وَتَتَّقُوا فَلَكُمْ أَجْرٌ عَظِيمٌ","22/2/21/9",""],[10,21,"حدثنا أحمد بن محمد بن سعيد قال: حدثنا أحمد بن يوسف بن يعقوب أبو الحسن الجعفي، قال: حدثنا إسماعيل بن مهران، قال: حدثنا الحسن بن علي بن أبي حمزة، عن أبيه ووهيب عن أبي بصير، قال: قال أبو عبد الله: ليُعدن أحدكم لخروج القائم ولو سهماً، فإن الله تعالى إذا علم ذلك من نيته رجوت لأن ينسئ في عمره حتى يدركه فيكون من أعوانه وأنصاره.","22/2/21/10",""],[1,22,"حدثنا أحمد بن محمد بن سعيد بن عقدة قال: حدثني علي بن الحسن التيملي، قال: حدثني أخواي محمد وأحمد بنا الحسن، عن أبيهما، عن ثعلبة بن ميمون، وعن جميع الكناسي جميعاً عن أبي بصير، عن كامل، عن أبي جعفر أنه قال: إن قائمنا إذا قام دعا الناس إلى أمر جديد كما دعا إليه رسول الله ، وإن الإسلام بدا غريباً وسيعود غريباً كما بدا، فطوبى للغرباء.","22/2/22/1",""],[2,22,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي، قال: حدثنا محمد بن الحسين بن أبي الخطاب، قال: حدثنا محمد بن سنان، عن ابن مسكان، عن أبي بصير، عن أبي عبد الله أنه قال: الإسلام بدا غريباً وسيعود غريباً كما بدا، فطوبى للغرباء. فقلت: اشرح لي هذا، أصلحك الله. فقال: مما يستأنف الداعي منّا دعاء جديداً كما دعا رسول الله .","22/2/22/2",""],[3,22,"وبهذا الإسناد عن ابن سنان، عن عبد الله بن مسكان، عن مالك الجهني قال: قلت لأبي جعفر: إنا نَصِف صاحب هذا الأمر بالصفة التي ليس بها أحد من الناس. فقال: لا والله، لا يكون ذلك أبداً حتى يكون هو الذي يحتج عليكم بذلك ويدعوكم إليه.","22/2/22/3",""],[4,22,"أخبرنا أحمد بن محمد بن سعيد قال: حدثنا محمد بن المفضل بن ابراهيم، قال: حدثنا محمد بن عبد الله بن زرارة، عن سعد بن أبي عمر و الجلاب، عن جعفر بن محمد أنه قال: إن الإسلام بدا غريباً وسيعود غريباً كما بدا فطوبى للغرباء.","22/2/22/4",""],[5,22,"حدثنا عبد الواحد بن عبد الله بن يونس، قال: حدثنا أحمد بن محمد بن علي بن رباح الزهري، قال: حدثنا محمد بن العباس بن عيسى الحسني، عن الحسن بن علي البطائني، عن شعيب الحداد، عن أبي بصير، قال: قلت لأبي عبد الله: أخبرني عن قول أمير المؤمنين: إن الإسلام بدا غريباً وسيعود كما بدا فطوبى للغرباء. فقال: يا أبا محمد، إذا قام القائم استأنف دعاء جديداً كما دعا رسول الله . (قال) فقمت إليه وقبلت رأسه وقلت: أشهد أنك إمامي في الدنيا والآخرة أوالى وليك وأعادي عدوك، وأنك ولي الله. فقال: رحمك الله.","22/2/22/5",""],[1,23,"أخبرنا علي بن أحمد، عن عبيد الله بن موسى، قال: حدثني محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن أبي الجارود، عن أبي جعفر الباقر أنه سمعه يقول: الأمر في أصغرنا سناً وأخملنا ذكراً.","22/2/23/1",""],[2,23,"حدثنا محمد بن همام قال: حدثنا أحمد بن مابنداذ، قال: حدثنا أحمد بن هلال، عن أبي مالك الحضرمي، عن أبي السفاتج، عن أبي بصير، قال: قلت لهما (لأبي عبد الله أو لأبي جعفر ): أيكون أن يفضي هذا الأمر إلى من لم يبلغ؟ قال: سيكون ذلك. قلت: فما يصنع؟ قال: يورثه علماً وكتباً ولا يكله إلى نفسه.","22/2/23/2",""],[3,23,"حدثنا عبد الواحد بن عبد الله بن يونس قال: حدثنا محمد بن جعفر القرشي قال: حدثنا محمد بن الحسين بن أبي الخطاب، عن محمد بن سنان، عن أبي الجارود قال: قال لي أبو جعفر: لا يكون هذا الأمر إلاّ في أخملنا ذكراً وأحدثنا سناً.","22/2/23/3",""],[4,23,"أخبرنا محمد بن همام قال: حدثنا أحمد بن مابنداذ، قال: حدثنا أحمد بن هلال، عن إسحاق بن صباح، عن أبي الحسن الرضا أنه قال: إن هذا سيفضي إلى من يكون له الحمل.","22/2/23/4",""],[1,24,"حدثنا أبو العباس أحمد بن محمد بن سعيد بن عقدة قال: حدثنا أبو عبد الله جعفر بن عبد الله المحمدي من كتابه في رجب سنة ثمان وستين ومائتين، قال: حدثني الحسن بن علي بن فضال، قال: حدثنا صفوان بن يحيى، عن إسحاق بن عمار الصيرفي قال: وصف إسماعيل بن عمار أخي لأبي عبد الله دينه واعتقاده، فقال: إني أشهد أن لا إله إلاّ الله، وأن محمداً رسول الله وأنكم (ووصفهم - يعني الأئمة - واحداً واحداً) حتى انتهى إلى أبي عبد الله ، ثم قال: وإسماعيل من بعدك. قال: أما إسماعيل فلا.","22/2/24/1",""],[2,24,"حدثنا محمد بن همام قال: حدثنا حميد بن زياد، قال: حدثني الحسن بن محمد بن سماعة، عن أحمد بن الحسن الميثمي، قال: حدثنا أبو نجيح المسمعي، عن الفيض بن المختار، قال: قلت لأبي عبد الله: جعلت فداك، ما تقول في أرض أتقبلها من السلطان ثم اؤاجرها من أكرتي على أن ما أخرج الله منها من شيء كان لي من ذلك النصف أو الثلث وأقل من ذلك أو أكثر، هل يصلح ذلك؟ قال: لا بأس به. فقال له إسماعيل ابنه: يا أبتاه لم تحفظ. قال: أوَليس كذلك أعامل أكرتي يا بني؟ أليس من أجل ذلك كثيراً ما أقول لك إلزمني فلا تفعل! فقام إسماعيل وخرج، فقلت: جعلت فداك، فما على إسماعيل أن لا يلزمك إذ كنت متى مضيت أفضيت الأشياء إليه من بعدك كما أُفضيت الأشياءُ إليك من بعد أبيك؟ فقال: يا فيض، إن إسماعيل ليس مني كأنا من أبي. قلت: جعلت فداك، فقد كنتُ لا أشك في أن الرحال تُحط إليه من بعدك، فان كان ما نخاف، وإنا نسأل الله من ذلك العافية، فإلى من؟ فأمسك عني، فقبّلت ركبته وقلت: ارحم شيبتي، فإنما هي النار، إني والله لو طمعت أن أموت قبلك ما باليت ولكني أخاف أن أبقى بعدك. فقال لي: مكانك، ثم قام إلى ستر في البيت فرفعه ودخل فمكث قليلاً، ثم صاح بي: يا فيض، أدخل. فدخلت فإذا هو بمسجده قد صلى وانحرف عن القبلة، فجلست بين يديه، فدخل عليه أبو الحسن موسى وهو يومئذ غلام في يده درة، فأقعده على فخذه وقال له: بأبي أنت وأمي، ما هذه المخفقة التي بيدك؟ فقال: مررت بعلي أخي وهي في يده وهو يضرب بها بهيمة، فانتزعتها من يده. فقال لي أبو عبد الله: يا فيض، إن رسول الله أفضيت إليه صحف إبراهيم وموسى فائتمن عليها علياً، ثم ائتمن عليها عليٌ الحسن، ثم ائتمن عليها الحسنُ الحسينَ أخاه، وائتمن الحسين عليها عليَّ بن الحسين، ثم ائتمن عليها علي بن الحسين محمد بن علي، وائتمنني عليها أبي، فكانت عندي وقد ائتمنت ابني هذا عليها على حداثته وهي عنده. فعرفتُ ما أراد فقلت: جعلت فداك، زدني. فقال: يا فيض، إن أبي كان إذا أراد أن لا ترد له دعوة أجلسني عن يمينه ودعا، فأمّنتُ، فلا ترَد له دعوة، وكذلك أصنع بابني هذا، وقد ذكرت أمس بالموقف فذكرتك بخير. (قال فيض) فبكيت سروراً، ثم قلت له: يا سيدي زدني. فقال: إن أبي كان إذا أراد سفراً وأنا معه فنعس وكان هو على راحلته أدنيت راحلتي من راحلته فوسّدته ذراعي الميل والميلين حتى يقضي وطره من النوم، وكذلك يصنع بي ولدي هذا. فقلت له: زدني جعلت فداك. فقال: يا فيض، إني لأجد بابني هذا ما كان يعقوب يجده بيوسف. فقلت: سيدي زدني. فقال: هو صاحبك الذي سألتَ عنه، قم فأقرّ له بحقه. فقمت حتى قبّلت يده ورأسه ودعوت الله له. فقال أبو عبد الله: أما إنه لم يؤذن لي في المرة الأولى منك. فقلت: جعلت فداك، أخبر به عنك؟ قال: نعم، أهلك وولدك ورفقاءك. وكان معي أهلى وولدي، وكان معي يونس بن ظبيان من رفقائي، فلما أخبرتهم حمدوا الله على ذلك، وقال يونس: لا والله، حتى أسمع ذلك منه، وكانت به عجلة، فخرج فأتبعته فلما انتهيت إلى الباب سمعتُ أبا عبد الله يقول - وقد سبقنا -: يونس! الأمر كما قال لك فيض. اسكت واقبل. فقال: سمعت وأطعت. ثم دخلت، فقال لي أبو عبد الله حين دخلت: يا فيض زرقه زرقه. قلت: قد فعلت.","22/2/24/2",""],[3,24,"أخبرنا أحمد بن محمد بن سعيد بن عقدة قال: حدثنا القاسم بن محمد بن الحسن بن حازم من كتابه قال: حدثنا عبيس بن هشام، عن درست بن أبي منصور، عن الوليد بن صبيح، قال: كان بيني وبين رجل يقال له عبد الجليل كلام في قدم فقال لي: إن أبا عبد الله أوصى إلى إسماعيل. (قال) فقلت لأبي عبد الله إن عبد الجليل حدثني بأنك أوصيت إلى إسماعيل في حياته قبل موته بثلاث سنين. فقال: يا وليد، لا والله! فإن كنتُ فعلت فإلى فلان (يعني أبا الحسن موسى ) وسمّاه.","22/2/24/3",""],[4,24,"أخبرنا عبد الواحد بن عبد الله بن يونس قال: حدثنا أحمد بن محمد بن رباح الزهري الكوفي قال: حدثنا أحمد بن علي الحميري قال: حدثني الحسن بن أيوب، عن عبد الكريم بن عمرو الخثعمي، عن جماعة الصائغ قال: سمعت المفضل بن عمر يسأل أبا عبد الله: هل يفرض الله طاعة عبد ثم يكتمه خبر السماء؟ فقال له أبو عبد الله: الله أجل وأكرم وأرأف بعباده وأرحم من أن يفرض طاعة عبد ثم يكتمه خبر السماء صباحاً ومساءً. (قال) ثم طلع أبو الحسن موسى ، فقال له أبو عبد الله: أيسرك أن تنظر إلى صاحب كتاب علي؟ فقال له المفضل: وأي شيء يسرني إذاً أعظم من ذلك. فقال: هو هذا صاحب كتاب علي؛ الكتاب المكنون الذي قال الله لَا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ","22/2/24/4",""],[5,24,"حدثنا محمد بن همام قال: حدثنا حميد بن زياد، قال: حدثنا الحسن بن محمد بن سماعة، قال: حدثنا أحمد بن الحسن الميثمي، عن محمد بن إسحاق، عن أبيه قال: دخلت علي أبي عبد الله فسألته عن صاحب الأمر من بعده فقال لي: هو صاحب البهمة. وكان موسى في ناحية الدار صبياً ومعه عناق مكية وهو يقول لها: اسجدي لله الذي خلقك.","22/2/24/5",""],[6,24,"حدثنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي، عن عبد الله بن حماد الأنصاري، عن معاوية بن وهب قال: دخلت على أبي عبد الله ، فرأيت أبا الحسن موسى وله يومئذ ثلاث سنين ومعه عناق من هذه المكية وهو آخذ بخطام عليها وهو يقول لها: اسجدي لله الذي خلقك، ففعل ذلك ثلاث مرات، فقال له غلام صغير: يا سيدي، قل لها تموت. فقال له موسى: ويحك! أنا أحيي وأميت؟ الله يحيي ويميت.","22/2/24/6",""],[7,24,"ومن مشهور كلام أبي عبد الله عند وقوفه على قبر إسماعيل: غلبني الحزن لك على الحزن عليك، اللهم إني وهبت لإسماعيل جميع ما قصر عنه ممّا افترضت عليه من حقي، فهب لي جميع ما قصّر عنه فيما افترضت عليه من حقك.","22/2/24/7",""],[8,24,"وروي عن زرارة بن أعين أنه قال: دخلت على أبي عبد الله وعن يمينه سيد ولده موسى وقدامه مرقد مغطى، فقال لي: يا زرارة، جئني بداود بن كثير الرقي وحمران وأبي بصير، ودخل عليه المفضل بن عمر، فخرجت فأحضرته من أمرني باحضاره، ولم يزل الناس يدخلون واحداً إثر واحد حتى صرنا في البيت ثلاثين رجلاً. فلما حشد المجلس قال: يا داود، إكشف لي عن وجه إسماعيل. فكشف عن وجهه فقال أبو عبد الله: يا داود، أحيٌّ هو أم ميت؟ قال داود: يا مولاي، هو ميت. فجعل يعرض ذلك على رجل رجل حتى أتى على آخر من في الملجس وانتهى عليهم بأسرهم، كلٌ يقول: هو ميت يا مولاي. فقال: اللهم اشهد. ثم أمر بغسله وحنوطه وإدراجه في أثوابه. فلما فرغ منه قال للمفضل: يا مفضل، أحسر عن وجهه. فحسر عن وجهه فقال: أحيٌّ هو أم ميت؟ فقال: ميتٌ. قال: اللهم اشهد عليهم. ثم حمل إلى قبره فلما وضع في لحده قال: يا مفضل، إكشف عن وجهه، وقال للجماعة: أحيٌّ هو أم ميت؟ قلنا له: ميت. فقال: اللهم اشهد واشهدوا فإنه سيرتاب المبطلون، يريدون إطفاء نور الله بأفواههم، - ثم أومأ إلى موسى - والله متمّ نوره ولو كره المشركون. ثم حثونا عليه التراب، ثم أعاد علينا القول فقال: الميت المحنط المكفن المدفون في هذا اللحد مَن هو؟ قلنا: إسماعيل. قال: اللهم اشهد. ثم أخذ بيد موسى وقال: هو حق والحق منه إلى أن يرث الله الأرض ومن عليها. والله ليظهرن عليكم صاحبكم وليس في عنقه لأحد بيعة. فلا يظهر صاحبكم حتى يشك فيه أهل اليقين. قُلْ هُوَ نَبَأٌ عَظِيمٌ {67} أَنْتُمْ عَنْهُ مُعْرِضُونَ {68}","22/2/24/8",""],[9,24,"حدثنا أبو سليمان أحمد بن هوذة الباهلي قال: حدثنا إبراهيم بن إسحاق النهاوندي قال: حدثنا عبد الله بن حماد الأنصاري، عن صفوان بن مهران الجمال، قال: سأل منصور بن حازم وأبو أيوب الخزاز أبا عبد الله وأنا حاضر معهما، فقالا: جعلنا الله فداك، إن الأنفس يغدى عليها ويراح، فمن لنا بعدك؟ فقال: إذا كان ذلك فهذا - فضرب يده إلى العبد الصالح موسى وهو غلام خماسي بثوبين أبيضين - وقال: هذا، وكان عبد الله بن جعفر حاضراً يومئذ البيت.","22/2/24/9",""],[1,25,"أخبرنا محمد بن يعقوب  قال: حدثنا علي بن إبراهيم، عن أبيه، عن حماد بن عيسى، عن حريز، عن زرارة، قال: قال أبو عبد الله: إعرف إمامك فإنك إذا عرفته لم يضرّك تقدم هذا الأمر أو تأخر.","22/2/25/1",""],[2,25,"أخبرنا محمد بن يعقوب قال: حدثني الحسين بن محمد بن عامر، عن معلي بن محمد، عن محمد بن جمهور، عن صفوان بن يحيى، عن محمد بن مروان، عن الفضيل بن يسار، قال: سألت أبا عبد الله عن قول الله يَوْمَ نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ ۖ فَمَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَأُولَٰئِكَ يَقْرَءُونَ كِتَابَهُمْ وَلَا يُظْلَمُونَ فَتِيلًا قال: يا فضيل، إعرف إمامك، فإنك إذا عرفت إمامك لم يضرّك تقدم هذا الأمر أو تأخر، ومن عرف إمامه ثم مات قبل أن يقوم صاحب هذا الأمر كان بمنْزلة من كان قاعداً في عسكره، لا بل بمنْزلة من قعد تحت لوائه. (قال) ورواه بعض أصحابنا \"بمنْزلة من استشهد مع رسول الله .\"","22/2/25/2",""],[3,25,"أخبرنا محمد بن يعقوب، عن علي بن محمد رفعه إلى علي بن أبي حمزة، عن أبي بصير، قال: قلت لأبي عبد الله: جعلت فداك، متى الفرج؟ فقال: يا أبا بصير، وأنت ممن يريد الدنيا؟ من عرف هذا الأمر فقد فرج عنه بانتظاره.","22/2/25/3",""],[4,25,"أخبرنا محمد بن يعقوب، عن علي بن إبراهيم، عن صالح بن السندي، عن جعفر بن بشير، عن إسماعيل بن محمد الخزاعي، قال: سأل أبو بصير أبا عبد الله وأنا أسمع، فقال: تراني أدرك القائم ؟ فقال: يا أبا بصير، ألست تعرف إمامك؟ فقال: إي والله وأنت هو - وتناول يده -. فقال: والله ما تبالي يا أبا بصير إلاّ تكون محتبياً بسيفك في ظل رواق القائم .","22/2/25/4",""],[5,25,"أخبرنا محمد بن يعقوب قال: حدثنا عدة من أصحابنا، عن أحمد بن محمد، عن علي بن النعمان، عن محمد بن مروان، عن الفضيل بن يسار، قال: سمعت أبا جعفر يقول: من مات وليس له إمام فميتته ميتة جاهيلة، ومن مات وهو عارف لإمامه لم يضرّه تقدم هذا الأمر أو تأخر، ومن مات وهو عارف لإمامه كان كمن هو قائم مع القائم في فسطاطه.","22/2/25/5",""]],"name":"الغيبة للنعماني","author":"محمد بن إبراهيم النعماني (ت نحو 360 هـ)","blurb":"من أقدم الكتب المؤلَّفة في الغيبة، ألّفه تلميذ الكليني: الأئمة الاثنا عشر، الغيبة، الانتظار، العلامات، وصفات القائم.","book":"https://thaqalayn.net/book/Kitab-al-Ghayba-Numani"};